// Русские названия и тексты из «Лансеровских штучек» (по ID lancer-data)
export const RU={"frames":{"mf_standard_pattern_i_everest":{"n":"Эверест","en":"Everest","src":"GMS","role":"Универсальный","variant":"","book":"","tr":[{"n":"Инициатива","t":"1/сцена, Эверест может совершить любое **быстрое действие** как **свободное**."},{"n":"Заменяемые Детали","t":"Во время перерыва Эверест можно починить из расчета **1 Ремонт** за 1 структурный урон вместо **2 Ремонтов**."}],"core":{"n":"Топливный Инжектор Гиперспек","pn":null,"pt":null,"an":"Включение Питания","at":"До конца этой сцены вы получаете +1 [ТОЧН] ко всем атакам, проверкам и спасброскам; кроме того, **1/ход** вы можете **Ускориться** в **качестве свободного** действия.","ag":"Активное (1 МЯ), Протокол"}},"mf_blackbeard":{"n":"Черная Борода","en":"Blackbeard","src":"IPS-N","role":"Нападающий","variant":"","book":"","tr":[{"n":"Хватающий Кабель","t":"Черная Борода может **Хватать** цели в радиусе [Дальн] 5. Если **Хватание** успешно, **Черная Борода** немедленно притягивается к цели по самому прямому пути. Если нет подходящих мест, хват разрывается и Черная Борода не двигается."},{"n":"Подсистема Блокировки/убийства","t":"Во время хватания Черная Борода может **Ускоряться** и реагировать."},{"n":"Открытый Реактор","t":"Черная Борода получает +1 [СЛОЖН] к проверкам и спасброскам **Инженерии**."}],"core":{"n":"Штурмовые Захваты","pn":null,"pt":null,"an":"Омни-гарпун","at":"Эта система направляет хватающие гарпуны на любое количество целей в пределах [Дальн] **5** и прямой видимости. Пострадавшие персонажи должны преуспеть в спасброске **Корпуса** или получить 2d6 [кин] и быть **Сбитыми с ног**, а затем притянутыми к вам или как можно ближе. Они становятся **Обездвиженными** до конца своего следующего хода. В случае успеха пострадавшие персонажи получают половину урона, а в остальном не подвергаются воздействию.","ag":"Активное (1 МЯ), Быстрое Действие"}},"mf_drake":{"n":"Дрейк","en":"Drake","src":"IPS-N","role":"Защитник","variant":"","book":"","tr":[{"n":"Тяжелая Рама","t":"Персонажи меньшего размера не могут толкать, тянуть, **Сбивать с ног** или отбрасывать Дрейка."},{"n":"Абразивное Напыление","t":"Дрейк имеет **Сопротивляемость** к урону, [горение] и [нагрев] от атак [Взрыв], [Разрыв], [Линия] и [Конус]."},{"n":"Медленный","t":"Дрейк получает **+1**[СЛОЖН] на проверки **Маневренности** и спасброски."},{"n":"Хранитель","t":"Соседние союзные персонажи могут использовать Дрейка в качестве **твердого укрытия**."}],"core":{"n":"Крепость","pn":null,"pt":null,"an":"Протокол Крепость","at":"Вы устанавливаете тяжелые стабилизаторы, и ваш мех становится больше похож на фортификационное сооружение, чем на транспортное средство. При активации две секции твердого укрытия ( [Линия] **2, Размер 1**) разворачиваются из вашего меха и тянутся в любом направлении. Эти секции покрытия имеют **Невосприимчивость** ко всему урону.\nКроме того, во время активации действуют следующие эффекты:\n• Вы становитесь **Обездвиженным**.\n• Вы получаете преимущества от твердого укрытия, даже на открытой местности, и получаете **Невосприимчивость** к **Толчку**, **Сбиванию** и всем непроизвольным движениям.\n• Когда вы **Укрепляетесь**, вы можете совершить полное действие в свой следующий ход, а не только быстрое действие.\n• Любой персонаж, получивший твердое укрытие от вас или ваших секций укрытия, получает **Невосприимчивость** к **Толчку**, **Сбиванию** и всем непроизвольным перемещениям, а также получает преимущества **Абразивного Напыления**.\nЭта система может быть деактивирована в качестве протокола. В противном случае она действует до конца текущей сцены.","ag":"Активное (1МЯ), Протокол"}},"mf_lancaster":{"n":"Ланкастер","en":"Lancaster","src":"IPS-N","role":"Поддерживающий","variant":"","book":"","tr":[{"n":"Теплоизолированный","t":"Ланкастер имеет **Невосприимчивость** к [горение]."},{"n":"Боевой Ремонт","t":"В бою Ланкастер может использовать **4 Ремонта**, чтобы восстановить уничтоженного меха в качестве полного действия, возвращая ему **1 Структуру**, **1 Стресс** и **1 ПЗ**."},{"n":"Резервные Системы","t":"По вашему усмотрению другие персонажи, находящиеся рядом с Ланкастером, могут тратить его **Ремонт** как свой собственный."}],"core":{"n":"Дрон-Защелка","pn":null,"pt":null,"an":"Нагнетатель","at":"Ваш Дрон-Защелка прицепляется к союзному меху в пределах его Дальности. До конца сцены вы получаете [нагрев] 1 в начале каждого своего хода, но ваша цель получает +1 [ТОЧН] на все атаки, проверки и спасброски, а также Невосприимчивость к состояниям Ослабленности, Заклинивания, Замедления, Расщепления и Обездвиживания от персонажей, кроме нее самой. Действие этого эффекта заканчивается, если один из персонажей становится Ошеломленным.\nПока эта система активна, вы не можете использовать Дрона-Защелку для любых других целей.","ag":"Активное (1 МЯ), Быстрое Действие"}},"mf_nelson":{"n":"Нельсон","en":"Nelson","src":"IPS-N","role":"Нападающий","variant":"","book":"","tr":[{"n":"Импульс","t":"1/раунд, после того, как вы **Ускоряетесь**, следующая атака Нельсона в б**лижнем бою наносит +1d6 дополнительного урона** при попадании."},{"n":"Стрелец","t":"После атаки Нельсон может переместиться на 1 пространство в любом направлении в качестве свободного действия, если он не находится в состоянии **Обездвиженности** или **Замедления**. Это перемещение игнорирует вовлеченность и не провоцирует реакцию."}],"core":{"n":"Привод Бесконечного Импульса","pn":null,"pt":null,"an":"Вовлеченный Привод","at":"До конца сцены **Стрелец** позволяет вам перемещаться на **4 пространства** за раз вместо **1 пространства**.","ag":"Активно (1 СП), Протокол"}},"mf_raleigh":{"n":"Роли","en":"Raleigh","src":"IPS-N","role":"Нападающий","variant":"","book":"","tr":[{"n":"Цельнометаллическая Оболочка","t":"В конце своего хода, если Роли не совершил никаких атак или принудительных спасбросков, она может зарядить все **Заряжаемое** оружие в качестве свободного действия."},{"n":"Защищенный Магазин","t":"Роли может совершать Дальние атаки, когда **Заклинивает**."}],"core":{"n":"Пушка Мьёльнир М35","pn":null,"pt":null,"an":"Бог Грома","at":"Вы начинаете раскручивать свою **M35 Мьёльнир**, начиная без патронов в патроннике. До завершения сцены вы заряжаете два патрона в патронники в конце любого своего хода, в котором вы не стреляли из **M35 Мьёльнир**. Она может вмещать максимум шесть патронов.\nКогда вы стреляете из **M35 Мьёльнир**, все патронники стреляют одновременно, нанося по 4 [кин] за **каждый заряженный патрон**. Если вы стреляете четырьмя или более патронами одновременно, атака увеличивает ББ, а при попадании цель становится **Расщепленной** до конца следующего хода.","ag":"Активное (1 МЯ), Протокол"}},"mf_tortuga":{"n":"Тортуга","en":"Tortuga","src":"IPS-N","role":"Защитник/Нападающий","variant":"","book":"","tr":[{"n":"Дозорный","t":"Тортуга получает +1 [ТОЧН] ко всем атакам, сделанным в качестве реакции (например, **Наблюдение**)."},{"n":"Хранитель","t":"Соседние союзные персонажи могут использовать Тортугу в качестве **твердого укрытия**."}],"core":{"n":"Второй Пилот-Сторожевой Пес","pn":null,"pt":null,"an":"Режим Гиперрефлекс","at":"До конца этой сцены:\n• Если у вас меньше [Угроза] **3** с дальнобойным оружием, оно увеличивается до **3**.\n• 1/раунд, вы можете сделать дополнительную реакцию **Наблюдение**.\n• Любой персонаж, которого вы атаковали во время **Наблюдения**, становится **Обездвиженным** до конца своего следующего хода.","ag":"Активное 1 (СП), Протокол"}},"mf_vlad":{"n":"Влад","en":"Vlad","src":"IPS-N","role":"Оператор/Нападающий","variant":"","book":"","tr":[{"n":"Расчленение","t":"Когда Влад накладывает **Обездвиживание** на другого персонажа, цель также становится **Расщепленной** на тот же срок."},{"n":"Броня Сорокопута","t":"Когда персонаж в пределах [Дальн]3 атакует Влада, атакующий сначала получает **1** [кин] **ББ** урона."}],"core":{"n":"Броня Сорокопута","pn":null,"pt":null,"an":"Шипы Мучителя","at":"До конца этой сцены вы получаете **Сопротивляемость** ко всему урону, исходящему в пределах [Дальн] **3,** а Броня Сорокопута наносит **3 [кин] ББ** вместо **1**.","ag":"Активное (1 МЯ), Протокол"}},"mf_black_witch":{"n":"Черная Ведьма","en":"Black Witch","src":"SSC","role":"Оператор/Поддерживающий","variant":"","book":"","tr":[{"n":"Репульсорное Поле","t":"Черная Ведьма имеет **Сопротивляемость** к [кин]."},{"n":"Магнитное Парирование","t":"**1/раунд**, в качестве реакции, вы можете попытаться парировать [кин] атаку, которая нацелена на вас или находящегося рядом союзного персонажа. Бросьте 1d6: на 5+ атака промахивается. Этот эффект не суммируется с **Невидимостью**."}],"core":{"n":"Проектор Магнитного Поля","pn":null,"pt":null,"an":"Магнитное Поле","at":"Эта система проецирует [Взрыв] 3 магнитное поле по крайней мере на одно пространство рядом с вами, вызывая следующие эффекты до конца вашего следующего хода:\n• Зона поражения представляет собой **труднопроходимую местность**.\n• Дальние атаки, которые наносят [кин] или [взр] не могут войти или выйти из пораженной области — снаряды останавливаются у края, не нанося урона. Запишите каждую атаку, остановленную таким образом.\n• Мехи и другие персонажи, сделанные хотя бы частично из металла, которые начинают свой ход в пораженной области или входят в нее впервые за раунд, должны преуспеть в спасброске **Корпуса** или быть притянуты как можно ближе к центру и стать **Обездвиженными**.\nКогда эффект заканчивается, любые остановленные дальние атаки возвращаются на свою траекторию — к центру пораженной области. ГМ совершает броски атаки против каждого персонажа внутри, получая **+1 за каждую заблокированную атаку** (максимум +6). При попадании эти атаки наносят **1d6** [кин] за каждую заблокированную атаку (максимум **6d6** [кин]).","ag":"Активное (1 МЯ), Быстрое Действие"}},"mf_deaths_head":{"n":"Мёртвая Голова","en":"Death’s Head","src":"SSC","role":"Артиллерист","variant":"","book":"","tr":[{"n":"Нейролинк","t":"Мёртвая Голова может перебросить свою первую **дальнюю атаку** каждый раунд, но должен сохранить второй результат."},{"n":"Совершенное Нацеливание","t":"Мёртвая Голова получает дополнительный **+1** ко всем броскам **дальней атаки**."}],"core":{"n":"Упреждающее Нацеливание","pn":null,"pt":null,"an":"Нейрошунт","at":"До конца этой сцены вы получаете действие **Метка Смерти**.\n⟦A:s⟧Метка Смерти⟦T⟧Полное Действие⟦E⟧Выберите персонажа в пределах [Дальн] **30**, но дальше [Дальн] **5**, чтобы сфокусироваться на нем; во время фокусировки вы становитесь **Обездвиженным** и не можете совершать **реакции**, но вы наносите дополнительный урон в зависимости от размера оружия (вспомогательное: 1d6, основное: 2d6, тяжелое или больше: 3d6) при критических попаданиях в них, если они не находятся в укрытии или в пределах [Дальн] **5**.\nВы можете сфокусироваться только на одном персонаже за раз. В качестве **протокола** вы можете прекратить фокусировку на цели.⟦Z⟧","ag":"Активное (1 МЯ), Протокол"}},"mf_dusk_wing":{"n":"Сумрачное Крыло","en":"Dusk Wing","src":"SSC","role":"Оператор/Поддерживающий","variant":"","book":"","tr":[{"n":"Маневренные Двигатели","t":"Сумрачное крыло может **парить** при перемещении."},{"n":"Плащ Арлекина","t":"В свой ход Сумрачное Крыло **Невидим**; он снова показывается в конце хода."},{"n":"Хрупкость","t":"Сумрачное Крыло получает +1 [СЛОЖН] на проверки и спасброски **Корпуса**."}],"core":{"n":"Артикуляция Дхийеда","pn":null,"pt":null,"an":"Зал Зеркал","at":"В течение всей сцены, каждый раз, когда вы начинаете уникальное перемещение во время своего хода (например, **стандартное перемещение**, **Ускорение** или перемещение, предоставляемое талантами или системами), вы оставляете голографический отпечаток себя на пространстве, из которого вы начали перемещение. Это иллюзорные объекты того же **Размера**, что и вы, которые имеют **Невосприимчивость ко всему урону и эффектам** и не являются препятствиями.\nКогда враждебные персонажи начинают свой ход, проходят или приближаются к пространству, занятому голограммой, она взрывается. Они должны преуспеть в спасброске **Маневренности**, иначе получат **1d6** [энерг] **урона.** В случае успеха они получают половину урона.\nВы можете мгновенно телепортироваться к любой голограмме в радиусе [Дальн] **50** в качестве быстрого действия. Когда вы делаете это, все существующие голограммы детонируют, создавая [Разрыв] **1** взрывы с тем же эффектом, что и выше, и вы не можете создавать новые голограммы до начала вашего следующего хода.","ag":"Активно (1 МЯ), Протокол"}},"mf_metalmark":{"n":"Металмарк","en":"Metalmark","src":"SSC","role":"Нападающий","variant":"","book":"","tr":[{"n":"Мерцающий Покров","t":"Металмарк становится **Невидимым** во время перемещения, но снова показывается при остановке."},{"n":"Адаптация Панциря","t":"Когда Металмарк находится в **мягком укрытии**, дальние атаки получают +2 [СЛОЖН], а не + 1 [СЛОЖН]."}],"core":{"n":"Тактический Плащ","pn":null,"pt":null,"an":"Тактический Плащ","at":"Вы становитесь **Невидимым** до конца сцены.","ag":"Активно (1 МЯ), Протокол"}},"mf_monarch":{"n":"Монарх","en":"Monarch","src":"SSC","role":"Артиллерист","variant":"","book":"","tr":[{"n":"Силос Мстителя","t":"**1/раунд**, при **критическом попадании** из любого дальнобойного оружия, Монарх может нанести **3 [взр]** другому персонажу по вашему выбору в пределах [Дальн] **15** и прямой видимости."},{"n":"Грузоподъёмный Искатель","t":"Монарх может использовать Пусковые установки для атаки **Захваченного** персонажа, как если бы его оружие было **Искателем**, но во время атаки он должен поглотить **Захват**. Когда это происходит, урон от атаки никоим образом не может быть уменьшен."}],"core":{"n":"Сшк-30 Высокопробивной Ракетный Комплекс","pn":null,"pt":null,"an":"Кара Господня","at":"Выберите любое количество персонажей в пределах [Дальн] **50**: каждая из ваших целей должна преуспеть в спасброске **Маневренности** или получить **1d6+4 [взр]**. В случае успеха они получают половину урона. Эти самонаводящиеся ракеты могут достичь любой цели, если к ней есть путь.","ag":"Активно (1 МЯ), Полное Действие"}},"mf_mourning_cloak":{"n":"Траурный Покров","en":"Mourning Cloak","src":"SSC","role":"Нападающий","variant":"","book":"","tr":[{"n":"Охотник","t":"**1/раунд** Траурный Покров может нанести **+1d6** дополнительного урона при попадании ближней атакой, если у его цели нет соседних персонажей или если Траурный Покров — единственный персонаж, примыкающий к цели."},{"n":"Биотические Компоненты","t":"Траурный Покров получает +1 [ТОЧН] на проверки и спасброски Маневренности."}],"core":{"n":"ЭКС Слипстрим Модуль","pn":"Мгновенный Прыжок","pt":"Вы телепортируетесь в пространство в пределах [Дальн]3d6. Вам не требуется прямая видимость, но попытки телепортироваться в занятое пространство приводят к тому, что вы остаетесь на месте и теряете это действие. Если на всех трех кубиках выпадает одинаковое число, вы исчезаете, пока ваша группа не отдохнет, после чего вы снова появляетесь поблизости.","an":"Стабилизация Сингулярности","at":"До конца сцены вы **телепортируетесь**, когда **Ускоряетесь** или делаете **стандартное перемещение**.","ag":"Активное (1 МЯ), Протокол"}},"mf_swallowtail":{"n":"Ласточкин Хвост","en":"Swallowtail","src":"SSC","role":"Поддерживающий","variant":"","book":"","tr":[{"n":"Встроенная Маскировка","t":"В конце своего хода Ласточкин Хвост становится **Невидимым**, если он не двигался в этот ход. Это длится до тех пор, пока он не двинется или не совершит реакцию, или до начала своего следующего хода."},{"n":"Пророческие Сканеры","t":"**1/раунд**, когда Ласточкин Хвост применяет **Захват**, его цель также становится **Расщепленной** до конца ее следующего хода."}],"core":{"n":"Рои Облачной Разведки Таксим","pn":null,"pt":null,"an":"Пророческое Восклицание","at":"Получите реакцию **Тактическая Симуляция** до конца сцены.\n⟦A:r⟧Тактическая Симуляция⟦T⟧1/раунд, Реакция⟦E⟧**Триггер**: Союзник в зоне прямой видимости получает урон от врага в зоне прямой видимости.\n**Эффект**: Бросьте **1d6**. Если выпало **4+**, атака на самом деле была симуляцией, предсказанной вашим процессором — ваш союзник получает **Сопротивляемость** ко всему урону, нанесенному атакой, и может телепортироваться на 3 пространства, отображающие его \"истинное\" местоположение. Если 3 или меньше, произошел сбой — ваш союзник не получает Сопротивляемости, но может телепортироваться на 6 пространств.⟦Z⟧","ag":"Активное (1 МЯ), Протокол"}},"mf_balor":{"n":"Балор","en":"Balor","src":"HORUS","role":"Нападающий/Защитник","variant":"","book":"","tr":[{"n":"Очищающий Рой","t":"Балор наносит **2 [кин]** персонажам по своему выбору, которые начинают свой ход будучи **схваченными** или рядом с ним."},{"n":"Регенерация","t":"В конце своего хода Балор восстанавливает **1/4** от своего полного уровня **ПЗ**. Когда он получает **нагрузку** или **структурный урон**, этот эффект прекращается до конца его следующего хода."},{"n":"Самовосстановление","t":"Когда вы делаете перерыв, Балор автоматически и без **Ремонта** восстанавливает все ПЗ."}],"core":{"n":"Адский Рой","pn":null,"pt":null,"an":"Бешенство Улья","at":"Ваши наниты переходят в гиперактивный режим, вызывая следующие эффекты до конца сцены\n• Вы и соседние союзники получаете **мягкое укрытие**.\n• **Очищающий Рой** наносит **4 [кин]** вместо **2**.\n• Регенерация восстанавливает 1/2 от вашего полного уровня ПЗ вместо 1/4.\n• Если вы получили **структурный урон**, бросьте **1d6**: если выпадет **6**, ваш мех адски собирается, не получая структурного урона, возвращаясь к **1 ПЗ** и получая **Невосприимчивость** ко всему урону до конца текущего хода.\n• Вы становитесь **Расщепленным** и не можете выйти из этого состояния в течение всего времени.","ag":"Активно (1 МЯ), Протокол"}},"mf_goblin":{"n":"Гоблин","en":"Goblin","src":"HORUS","role":"Оператор/Поддерживающий","variant":"","book":"","tr":[{"n":"Литургический Код","t":"Гоблин получает +1 [ТОЧН] к **техническим атакам**."},{"n":"Реактивный Код","t":"**1/раунд**, когда Гоблин подвергается **технической атаке**, он может использовать любой вариант **Быстрой Технологии** против атакующего в качестве реакции."},{"n":"Хрупкость","t":"Гоблин получает +1 [СЛОЖН] к проверкам и спасброскам **Корпуса**."}],"core":{"n":"Инстинктивная Установка","pn":null,"pt":null,"an":"Симбиоз","at":"Ваш мех втягивает свои основные системы и прикрепляется к другому меху, становясь больше похожим на рудиментарный волдырь, чем на отдельную сущность. Носитель должен быть союзным и добровольным мехом, на котором еще нет другого Гоблина, крупнее вас и соседнего с вами. Пока вы прикреплены, вы занимаете его пространство, двигаетесь вместе с ним и получаете выгоду от твердого укрытия, но по-прежнему можете быть атакованы и выбраны отдельной целью. Вы также принимаете все состояния и нагрев, которые принимает ваш носитель.\nВаш носитель может использовать ваши **Системы**, **Э- Защиту** и **Техническую Атаку** вместо своих собственных. Кроме того, с начала следующего раунда вы больше не делаете свои ходы; вместо этого вы можете совершить два быстрых действия или одно полное действие в любой момент во время хода вашего носителя. Вы не можете **Перегружаться** или перемещаться, но можете выполнять реакции и свободные действия в обычном режиме. Ход вашего носителя считается вашим ходом для назначенных эффектов, относящихся к началу или концу хода персонажа.\nЭтот эффект длится либо до конца сцены, либо пока вы не отстранитесь быстрым действием, либо пока вы или ваш носитель не будете **Ошеломлены**. Когда эффект заканчивается, вы не делаете ход до следующего раунда.","ag":"Активное (1МЯ), Быстрое Действие"}},"mf_gorgon":{"n":"Горгона","en":"Gorgon","src":"HORUS","role":"Защитник","variant":"","book":"","tr":[{"n":"Метастатический Паралич","t":"Когда бросок атаки против Горгоны выпадает со значением 1–2, он автоматически промахивается, и атакующий становится **Ошеломленным** до конца своего следующего хода."},{"n":"Пристальный Взгляд","t":"Горгона может совершать две **реакции** за ход вместо одной."},{"n":"Хранитель","t":"Соседние союзные персонажи могут использовать Горгону в качестве **твердого укрытия**."}],"core":{"n":"Антикогнитивный Гиперфрактал Василиск","pn":null,"pt":null,"an":"Изгнание Василиска","at":"Вы проецируете ужасающего василиска, визуальный паттерн данных, который невероятно вреден для НЧЛ и электронных систем, и на который тяжело смотреть даже людям. До конца сцены враждебно настроенные персонажи должны успешно выполнить спасбросок **Систем**, прежде чем атаковать вас или любых союзных персонажей в пределах [Дальн] **3**. В случае неудачи они становятся **Ошеломленным** до конца своего следующего хода. Каждый персонаж может быть ошеломлен этим эффектом только один раз за сцену.","ag":"Активное (1МЯ), Быстрое Действие"}},"mf_hydra":{"n":"Гидра","en":"Hydra","src":"HORUS","role":"Нападающий/Оператор","variant":"","book":"","tr":[{"n":"Системная Связь","t":"**Размещаемые** объекты и **Дроны** Гидры получают **+5 ПЗ**."},{"n":"Пастушье Поле","t":"Дроны, Размещаемые объекты и объекты, расположенные рядом с Гидрой, получают **Сопротивляемость** ко всему урону."}],"core":{"n":"Разделение Орочи","pn":"Дроны ОРОЧИ","pt":"**Дроны Орочи (Размер 1/2, [5 + СТОЙКОСТЬ] ПЗ, Уклонение/Э-Защита [см. ниже], Метки: Дрон)**\nВ вашем мехе есть мощные интегрированные дроны-компаньоны. При создании выберите из следующего списка одного **Дрона**, который будет сопровождать вас:\n**• Дрон-Хранитель**: Этот дрон проецирует щит. Дальние атаки против соседних союзных персонажей получают +1 [СЛОЖН].\n**• Дрон-Капкан:** В качестве реакции вы можете заставить персонажей, которые начинают свой ход рядом с этим дроном или перемещаются рядом с ним в первый раз за раунд, сделать спасбросок **Маневренности**. В случае неудачи они становятся **Обездвиженными**. Они перестают быть **Обездвиженными** только тогда, когда дрон уничтожен или больше не находится рядом с ними, или когда они успешно выполняют спасбросок **Маневренности** в качестве быстрого действия.\n**• Дрон-Измельчитель**: В качестве реакции вы можете заставить персонажей, которые начинают свой ход рядом с этим дроном или перемещаются рядом с ним в первый раз за раунд, сделать спасбросок **Корпуса**. В случае неудачи они получают 1 [кин] и становятся **Расщепленными** до конца своего следующего хода.\n**• Дрон-Охотник**: В качестве реакции вы можете заставить персонажей, которые начинают свой ход рядом с этим дроном или перемещаются рядом с ним в первый раз за раунд, сделать спасбросок **Систем**. В случае неудачи они получают **Захват**.\nВаши Дроны **ОРОЧИ** разделяют ваши **Уклонение**, **Э-Защиту** и **Скорость**. Они могут перемещаться самостоятельно в ваш ход, но не могут предпринимать никаких других действий. Если вы можете летать или телепортироваться, они тоже могут.\nЕсли Дрон **ОРОЧИ** находится в пределах **Сенсоров**, вы можете отозвать его быстрым действием, интегрировав его в корпус вашего меха, где он не может быть выбран в качестве цели. Вы можете переместить его в пространство в пределах Сенсоров в качестве быстрого действия.\nКогда вы берете перерыв или выполняете **Полный Ремонт**, вы можете выбрать другого дрона, который будет сопровождать вас; кроме того, ваши дроны восстанавливают все **ПЗ** и автоматически ремонтируются, если они были уничтожены.","an":"Полное Размещение","at":"Все четыре дрона **ОРОЧИ** размещены в разных точках в пределах дальности **Сенсоров**; они остаются активными до конца сцены. Вы можете отзывать или перемещать любое их количество одновременно.","ag":"Активное (1 МЯ), Быстрое Действие"}},"mf_manticore":{"n":"Мантикора","en":"Manticore","src":"HORUS","role":"Нападающий","variant":"","book":"","tr":[{"n":"Шлаковый Карапакс","t":"Мантикора имеет **Сопротивляемость** к [энерг] и [горение]."},{"n":"Нестабильная Система","t":"При уничтожении Мантикора взрывается в результате расплавления реактора в конце своего следующего хода."},{"n":"Бичевание Врагов Божества","t":"Когда вы берете перерыв или выполняете **Полный Ремонт**, вы можете ввести Мантикору в нестабильное состояние **Бичевания** (или вывести ее из этого состояния). В этом состоянии Мантикора немедленно взрывается при разрушении из-за повреждений или расплавления реактора, испаряя его и мгновенно убивая вас и всех остальных пассажиров. Персонажи в радиусе [Разрыв] **2** должны успешно пройти спасбросок **Маневренности** или получить 8d6 [взр]. В случае успеха они получают половину урона. Это происходит, только если вы физически находитесь в Мантикоре."}],"core":{"n":"Заряженный Экзоскелет","pn":"Заряженный Экзоскелет","pt":"**1/раунд**, когда вы получаете [нагрев], вы можете нанести **2** [энерг] **ББ** персонажу в пределах [Дальн] **3**.","an":"Разрушение Храма врагов РА","at":"Ваш мех потрескивает от энергии: получите **Сопротивляемость** к [нагрев] до конца этой сцены и **Уровень Заряда** –**1d6**, начиная с **1**. Всякий раз, когда вы получаете [Конус] или [энерг], даже от себя, увеличьте значение **Уровня Заряда** на **1**. Когда **Уровень Заряда** достигает **6**, поглощенная энергия выливается в инферно [Разрыв] **2**. Персонажи, находящиеся в зоне поражения, должны успешно пройти спасбросок **Инженерии** или получить **6d6 [энерг] ББ**. В случае успеха они получают **половину урона**. Объекты в зоне воздействия автоматически поражаются. После разрядки действие этого эффекта заканчивается.","ag":"Активное (1 МЯ), Протокол"}},"mf_minotaur":{"n":"Минотавр","en":"Minotaur","src":"HORUS","role":"Оператор","variant":"","book":"","tr":[{"n":"Инвертная Кабина","t":"Вы можете **Взобраться** или **Спешиться** с Минотавра в первый раз в каждом раунде в качестве свободного действия. Кроме того, Минотавр не становится **Ослабленным**, когда вы **Катапультируетесь**."},{"n":"Внутренняя Метаскладка","t":"Находясь внутри Минотавра, вы не можете получить никакого вреда, даже если Минотавр взорвется или будет уничтожен."},{"n":"Локализованный Лабиринт","t":"Враждебные персонажи ни по какой причине не могут пройти через область, занятую Минотавром, и всегда должны останавливаться, когда **Вовлекаются** с ним, вне зависимости от их **Размера**."}],"core":{"n":"Метаскладчатый Лабиринт","pn":"Метаскладчатый Лабиринт","pt":"Когда вы наносите удар технической атакой, вы можете активировать эту систему, в результате чего ваша цель **Замедляется** до конца вашего следующего хода. Если она уже **Замедлена**, она становится **Обездвиженной** до конца вашего следующего хода; если она уже **Обездвижена**, она становится **Ошеломленной** до конца вашего следующего хода. Каждый персонаж может быть ошеломлен этим эффектом только один раз за бой, но может быть **Замедлен** или **Обездвижен** любое количество раз.","an":"Лабиринт","at":"Выберите персонажа в пределах **Сенсоров**: он становится **Ошеломленным**, когда вы бросаете его системы в метафизическую информационную ловушку, настолько запутанную, что он не может ничего сделать, кроме как попытаться выбраться. В конце своего следующего хода он может сделать спасбросок **Систем** с **+3 [СЛОЖН]**. При успехе он больше не **Ошеломлен**. Этот спасбросок можно повторять в конце каждого его хода, каждый раз получая **+1 [ТОЧН]**, пока он не будет успешным.","ag":"Активно (1 МЯ), Полное Действие"}},"mf_pegasus":{"n":"Пегас","en":"Pegasus","src":"HORUS","role":"Артиллерист","variant":"","book":"","tr":[{"n":"¿%:?Вытес!няющий Пистолет","t":"Пистолет: **Пистолет**"},{"n":"Кстати, Я Знаю Все.","t":"Когда нужно сделать бросок урона, Пегас может вместо этого нанести средний урон, основанный на количестве брошенных кубиков, следующим образом: 1d3 (2), 1d6 (4), 2d6 (7), 3d6 (11), 4d6 (14). Это должно быть решено до броска урона."}],"core":{"n":"Омниган Ушебти","pn":"Омниган Ушебти","pt":"Омниган вашего меха — это экспериментальное оборудование, настолько продвинутое, что оно бросает вызов физике: ему не требуется слот, у него нет типа или размера оружия — это означает, что его нельзя модифицировать или применить ваши таланты.\nВы не можете нормально атаковать этим оружием. Вместо этого, **1/раунд**, в качестве **свободного действия** вы можете использовать его во время вашего хода, чтобы нанести **1** [кин] **ББ** урона персонажу в пределах **Дальности** и прямой видимости. Это не считается атакой, бьет автоматически, игнорирует укрытие, обходит **Невосприимчивость**, и его урон нельзя уменьшить или игнорировать каким-либо образом. Ни одно правило в этой или любой другой книге не отменяет этого.","an":"Освободить Ушебти","at":"В оставшейся части этой сцены вы можете использовать Омниган Ушебти **3/раунд**, а не **1/раунд**.","ag":"Активно (1 МЯ), Протокол"}},"mf_barbarossa":{"n":"Барбаросса","en":"Barbarossa","src":"HA","role":"Артиллерист","variant":"","book":"","tr":[{"n":"Тяжелая Рама","t":"Меньшие персонажи не могут толкать, тянуть, **Сбивать с ног** или отбрасывать Барбароссу."},{"n":"Гальваническое Покрытие","t":"Барбаросса имеет **Сопротивляемость** к[взр]."},{"n":"Колосс","t":"Соседние союзные персонажи могут использовать Барбароссу в качестве **твердого укрытия**."},{"n":"Медленный","t":"Барбаросса получает **+1 [СЛОЖН]** к проверкам и спасброскам **Маневренности**."}],"core":{"n":"Рельса Апокалипсиса","pn":null,"pt":null,"an":"Зарядка Рельсы","at":"При активации вы начинаете заряжать **Рельсу Апокалипсиса** Барбароссы, невероятно мощную корабельную систему оружия дальнего боя, требующую калибровки цели. Получите **Заряд Апокалипсиса**, **1d6**, начиная с **4**. В начале каждого вашего хода уменьшайте значение **Заряда Апокалипсиса** на **1**, до минимума **1**. Если вы двигаетесь (даже непроизвольно), или становитесь **Ошеломленным** или **Заклиненным**, **Заряд Апокалипсиса** сбрасывается до **4**, а затем продолжает обратный отсчет в обычном режиме.\nЕсли значение **Заряда Апокалипсиса** равно **1–3**, вы можете атаковать в свой ход **Рельсой Апокалипсиса** как в качестве полного действия, но не можете перемещаться или совершать какие-либо другие действия в этот же ход. **Рельса Апокалипсиса** — это оружие дальнего боя с радиусом [Взрыв] **2** и профилем, определяемым текущим значением **Заряда Апокалипсиса**:\n**3.[**[Дальн]**20, 2d6**[взр]**]** Объекты в зоне поражения автоматически получают **20 [взр] ББ**. После атаки облако взрыва сохраняется, обеспечивая мягкое укрытие персонажам в зоне поражения до конца вашего следующего хода.\n**2.[**[Дальн]**25, 3d6**[взр]**]** Объекты и местность в этой области автоматически получают **40** [взр] **ББ**, а персонажи при попадании становятся **Расщепленными** и **Ослабленными** до конца своего следующего хода. Взрывное облако — это горящая буря: до конца вашего следующего хода персонажи в зоне поражения получают мягкое укрытие, а персонажи, которые начинают свой ход в этой области или перемещаются туда впервые за раунд, получают **4 [горение]**.\n**1.[**[Дальн]**30, 4d6**[взр]**]** Объекты и местность в этой области автоматически получают **100 [взр] ББ**, а персонажи становятся **Расщепленными** и **Ошеломленными** до конца их следующего хода при попадании. Земля в пораженной области испаряется при ударе: до конца сцены это **труднопроходимая местность**, персонажи в зоне поражения получают **мягкое укрытие**, а персонажи, которые начинают свой ход с этой зоны или перемещаются туда в первый раз за раунд, получают **4 [горение]**.\n**Рельса Апокалипсиса** не может быть направлена на цели в пределах [Дальн] **5**.\nПосле атаки с помощью **Рельсы Апокалипсиса**, **Заряд Апокалипсиса** восстанавливается до **4**. Если вы до конца сцены не использовали ее, вы восстанавливаете **1 МЯ**.\nВ конце сцены **Заряд Апокалипсиса** сбрасывается, и **Рельса Апокалипсиса** перестанет заряжаться.","ag":"Активно (1 МЯ), Быстрое Действие"}},"mf_genghis":{"n":"Чингис","en":"Genghis","src":"HA","role":"Нападающий","variant":"","book":"","tr":[{"n":"Теплоизолированный","t":"Чингис имеет **Невосприимчивость** к[горение]."},{"n":"Аварийная Вентиляция","t":"Когда Чингис получает **структурный урон**, он сбрасывает весь[нагрев]."}],"core":{"n":"ТBK Поддерживающий Комплект","pn":null,"pt":null,"an":"Раскрытые Ячейки Питания","at":"В следующий раз, когда вы превысите свой **Тепловой Максимум** в этой сцене, вы сбрасываете весь [нагрев] и выпускаете [Разрыв] **3** облако горящей материи из своего меха.\nДо начала вашего следующего хода все персонажи в пораженной области считаются **Невидимыми** для всех, кроме вас, а также все персонажи, кроме вас, получают **2 [горение]** и **2** [нагрев], когда начинают свой ход в этой зоне или входят в нее впервые за раунд. Как только этот эффект заканчивается, персонажи в области действия получают мягкое укрытие (которое вы игнорируете) до начала вашего следующего хода, после чего облако рассеивается.","ag":"Активно (1 МЯ),  Быстрое Действие"}},"mf_iskander":{"n":"Искандер","en":"Iskander","src":"HA","role":"Оператор","variant":"","book":"","tr":[{"n":"Штурмовая Установка","t":"**1/раунд** Искандер может бросить одну **Гранату** или установить одну **Мину**, как если бы у них было [Дальн] **15**."},{"n":"Размещаемые Мины","t":"**1/раунд**, когда Искандер устанавливает **Мину** (даже используя свою черту **Штурмовая Установка**), он может **свободным действием** установить до двух других **Мин** на свободные пространства, примыкающие к нему."},{"n":"Отмычка","t":"Искандер никогда не запускает и не устанавливает **Мины** или другие системы ближнего действия, если он сам этого не захочет."}],"core":{"n":"Широкозахватный Сеятель","pn":null,"pt":null,"an":"Облако Смерти","at":"Эта система создает огромное, расширяющееся облако микромин по всему полю боя, поражая всех враждебных персонажей в радиусе [Дальн] **50**. До конца сцены, когда враждебные персонажи совершают любое движение, кроме **стандартного перемещения** (включая непроизвольное движение), они получают **3 [взр] ББ** урона. Этот эффект может срабатывать любое количество раз, но только **1/раунд** для каждого персонажа.","ag":"Активно (1 МЯ), Быстрое Действие"}},"mf_napoleon":{"n":"Наполеон","en":"Napoleon","src":"HA","role":"Защитник/Оператор","variant":"","book":"","tr":[{"n":"Плотная Защита","t":"Когда Наполеон получает половину урона при успешной проверке или спасброске, он уменьшает урон до **1**."},{"n":"Мерцающая Эгида","t":"Когда Наполеон **Укрепляется**, он уменьшает входящий урон до **1** вместо получения **Сопротивляемости**."}],"core":{"n":"Истинно Чёрная Эгида","pn":null,"pt":null,"an":"Активация Эгиды","at":"Мерцающее, абсолютно черное поле быстро окутывает вашего меха, покрывая его словно вторая кожа. До конца сцены вы:\n• уменьшаете весь урон до **1**, кроме урона, который игнорирует любое уменьшение;\n• получаете **Невосприимчивость** ко всем техническим действиям, в том числе полезным, и любым текущим **техническим эффектам** или **состояниям** с вашей стороны;\n• можете использовать только системы с меткой **Щит** – любые другие сразу деактивируются;\n• не можете выполнять **быстрые действия**, **полные действия** или **реакции**, кроме стандартных **перемещений**, **Хватания**, **Тарана**, **Импровизированной Атаки**, **Активации** (Только **Щит**-системы), **Проверки Навыков** и **Ускорения**;\n• не можете **Перегружаться**;\n• не можете использовать связь для разговора с другими персонажами (поскольку звук не выходит из щита).\nВы по-прежнему можете получать статусы[нагрев], и на вас могут влиять непроизвольные движения. В остальном вы можете нормально взаимодействовать с миром, в том числе поднимать и перетас-кивать предметы и т.д.","ag":"Активно (1 МЯ), Быстрое Действие"}},"mf_saladin":{"n":"Саладин","en":"Saladin","src":"HA","role":"Защитник","variant":"","book":"","tr":[{"n":"Усиленная Рама","t":"Саладин имеет **Невосприимчивость** к **Расщеплению**."},{"n":"Хранитель","t":"Соседние союзные персонажи могут использовать Саладина как **твердое укрытие**."},{"n":"Искажающий Щит","t":"**1/раунд**, Саладин в качестве **реакции** может дать **+1 [СЛОЖН]** к любой атаке против себя или союзного персонажа в пределах **Сенсоров** до того, как будет сделан бросок."}],"core":{"n":"Тахионная Петля","pn":null,"pt":null,"an":"Тахионный Щит","at":"Эта система проецирует ускоренный тахионный щит на союзного персонажа в пределах **Сенсоров**. Вы можете выбрать новую цель в качестве быстрого действия. Получите реакцию **Защитный Пульс** до конца сцены.\n⟦A:r⟧Защитный Пульс⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер**: Ваша цель атакована.\n**Эффект**: Вы усиливаете ее тахионный щит импульсом энергии. Цель получают **Невосприимивость** ко всему урону от атаки, а если атака промахивается, вы можете заставить атакующего сделать повторный бросок против персонажа или объекта по вашему выбору, проверяя прямую видимость и Дальность от вашей цели, а не от атакующего. Если атака была частью области действия, новая цель должна находиться в той же области действия, что и первоначальная атака.⟦Z⟧","ag":"Активное (1 МЯ), Быстрое Действие"}},"mf_sherman":{"n":"Шерман","en":"Sherman","src":"HA","role":"Нападающий/Артиллерист","variant":"","book":"","tr":[{"n":"Непревзойденный Реактор","t":"Шерман получает **+1 [ТОЧН]** к проверкам и спасброскам **Инженерии**."},{"n":"Остановка Матур","t":"Когда Шерман сбрасывает весь [нагрев], вы можете получить [нагрев], равный половине его **Теплового Максимума**, что поместит его в **Опасную Зону**."},{"n":"Вентиляционный Нагрев","t":"Когда вы **Стабилизируете** Шермана или он превышает свой **Тепловой Максимум**, он получает мягкое укрытие до начала вашего следующего хода."}],"core":{"n":"Зональный Фокус MK IV Твердоеядро","pn":null,"pt":null,"an":"СЖИГАНИЕЯДРА Протокол","at":"Ваш ЗФ4 ТВЕРДОЕТЕЛО немедленно получает **3 Заряда**, максимум **4**; кроме того, до конца этой сцены **Стабилизация** генерирует **2 Заряда** вместо **1**, а вся местность, объекты и размещаемые объекты получают **10** [энерг] **ББ** за каждый заряд при попадании.","ag":"Активное (1 МЯ), Протокол"}},"mf_tokugawa":{"n":"Токугава","en":"Tokugawa","src":"HA","role":"Нападающий","variant":"","book":"","tr":[{"n":"Разрыв Ограничения","t":"Когда Токугава **Уязвим**, его дальние и ближние атаки наносят **+3 [энерг] дополнительного урона** при попадании, все его оружие, которое нанесло бы [кин] или [взр] урон, вместо этого наносит [энерг], дальнее оружие получает **+5 [Дальн]** и оружие ближнего боя получает **+1 [Угроза]**."},{"n":"Плазменная Оболочка","t":"Когда Токугава находится в **Опасной Зоне** и атакует оружием, наносящим любое количество [энерг], весь дополнительный урон становится [горение]."}],"core":{"n":"Перегретое Сырье Реактора","pn":"Разгон","pt":"Вы заставляете своего меха стать **Уязвимым** до конца вашего следующего хода.","an":"Сияние","at":"До конца этой сцены оружие, наносящее [энерг], получает **+5 [Дальн]**, если оно **дальнобойное** или **+2 [Угроза]** если это **Оружие Ближнего Боя**.\nПока вы находитесь в **Уязвимом** состоянии, **Разрыв Ограничения** суммируется с этими бонусами, что в итоге дает **+10 [Дальн]** и **+3 [Угроза]**.","ag":"Активно (1МЯ), Протокол"}},"mf_atlas":{"n":"Атлас","en":"Atlas","src":"SSC","role":"Нападающий","variant":"","book":"LR","tr":[{"n":"Убийца Гигантов","t":"При **Таране** и **Хватании** Атлас считается **Размера 1**. Он игнорирует вовлечение от более крупных персонажей и может свободно проходить сквозь занятые ими пространства и находиться в них (даже если они враждебны). Находясь в одном пространстве с любым персонажем, он получает **мягкое укрытие** — даже от этого персонажа."},{"n":"Уклонение Егеря","t":"**1/раунд**, когда вы получаете урон от более крупного персонажа, получите **Сопротивляемость** к этому урону и **реакцией** переместитесь на **3 пространства** в любом направлении. Это перемещение игнорирует вовлечение и не вызывает реакций."},{"n":"Добивающий Удар","t":"**1/раунд**: **+1d6** бонусного урона при успешной ближней атаке по **Сбитой с ног** цели."},{"n":"Открытый Реактор","t":"Атлас получает **+1** [СЛОЖН] на проверки и спасброски **Инженерии**."}],"core":{"n":"Активное Содействие «Родословная»","pn":null,"pt":null,"an":"Последняя Охота","at":"До конца сцены вы:\n• перемещаетесь на **1 дополнительное пространство** при любом добровольном перемещении (стандартное перемещение, **Ускорение**, перемещение от систем или талантов);\n• всегда получаете **мягкое укрытие**, где бы вы ни находились;\n• можете **Скрыться** даже на открытом месте, без укрытия.\nОбнаружить вас можно только **Поиском**, либо вы теряете **Скрытность** как обычно — при **Ускорении**, атаке, вынужденном спасброске и т. п.\nПока система активна, **1/раунд**, когда вы совершаете ближнюю или дальнюю атаку, будучи **Скрытым**, цель также должна преуспеть в спасброске **Корпуса** или быть **Сбитой с ног**. Это происходит до броска атаки.","ag":"Активное (1 МЯ), Быстрое Действие"}},"mf_caliban":{"n":"Калибан","en":"Caliban","src":"IPS-N","role":"Нападающий/Оператор","variant":"","book":"LR","tr":[{"n":"Шар для Сноса","t":"При **Толчке** от **Тарана**, ближней или дальней атаки Калибан считается **Размера 3**."},{"n":"Преследование Добычи","t":"Когда Калибан вызывает **Толчок** любым действием, он может переместиться на столько же пространств к той же цели кратчайшим путём. Это перемещение — часть того же действия, игнорирует вовлечение и не вызывает реакций."},{"n":"Сокрушение","t":"**1/раунд**, когда Калибан отбрасывает персонажа в стену, мех или другое препятствие, которое останавливает его движение, он может заставить цель пройти спасбросок **Корпуса**; при провале она получает **1d6** [кин] урона и **Ослаблена** до конца своего следующего хода."},{"n":"Слабый Компьютер","t":"Калибан получает **+1** [СЛОЖН] на все проверки и спасброски **Систем**."}],"core":{"n":"Дробовик «Свежеватель»","pn":null,"pt":null,"an":"Установить Автодроссель","at":"Дробовик «Свежеватель» поставляется с дульным автодросселем, позволяющим точнее задавать разлёт дроби. Сильный жар от установки быстро выводит дроссель из строя, и его приходится выбросить. До конца сцены дробовик HHS-075 «Свежеватель» получает профиль: **Основное ОБД, Точное, Толчок 5** [Конус]3 [Угроза]3, **1d6+2** [кин].","ag":"Активное (1 МЯ), Протокол"}},"mf_kobold":{"n":"Кобольд","en":"Kobold","src":"HORUS","role":"Оператор","variant":"","book":"LR","tr":[{"n":"Маскирующий Панцирь","t":"Когда Кобольд начинает ход рядом с местностью или **твёрдым укрытием** **Размера 1** или больше, он становится **Невидимым**, пока остаётся рядом. **Невидимость** пропадает, если он атакует или получает урон."},{"n":"Шлаковый Распылитель","t":"**1/раунд**, **быстрым действием** Кобольд может создать насыпь полурасплавленного полимера **Размера 1** в свободном пространстве в пределах [Дальн]3 и прямой видимости. Это местность с **10 ПЗ** и **Уклонением 5**, дающая **твёрдое укрытие**."},{"n":"Открытый Реактор","t":"Кобольд получает **+1** [СЛОЖН] на проверки и спасброски **Инженерии**."}],"core":{"n":"Терраформирование","pn":null,"pt":null,"an":"Терраформирование","at":"Ваш мех выдавливает огромную массу полимера и создаёт до **10 кубов Размера 1** в свободных пространствах в пределах [Дальн]5. Кубы могут стоять отдельно или соединяться и складываться до 5 пространств в высоту. Соединённые, они образуют сплошную поверхность, которая может перекрывать прямую видимость. В ход создания кубы дают **мягкое укрытие**, у каждого **Уклонение 5** и **10 ПЗ**. В начале вашего следующего хода они затвердевают: каждый куб даёт **твёрдое укрытие** и получает **+10 ПЗ** (полученный урон сохраняется).","ag":"Активное (1 МЯ), Полное Действие"}},"mf_lich":{"n":"Лич","en":"Lich","src":"HORUS","role":"Поддерживающий","variant":"","book":"LR","tr":[{"n":"Сосуд Души","t":"В начале хода Лича установите **СОСУД ДУШИ** в его текущем месте (он заменяет прежний маркер). **1/раунд**, **реакцией**, когда по Личу попадает атака, он проваливает спасбросок или проверку либо получает урон или нагрев из любого источника (даже от себя), он может сразу получить **Невосприимчивость** ко всему урону, нагреву и состояниям от этого эффекта, а затем **телепортируется** к маркеру или как можно ближе к нему. Эту реакцию можно взять и в конце любого хода, в том числе своего, — тогда он только телепортируется, без Невосприимчивости. Реакция недоступна, если Лич **Заклинен**, **Ошеломлён**, **Схвачен** или не может реагировать по другой причине."},{"n":"Бессмертный","t":"**1/сцена**, в раунде после уничтожения Лич может **реакцией** в конце любого хода вернуться к своему **Сосуду Души**. Это считается телепортацией; Лич появляется со всеми ПЗ, без нагрева, с **1 Структурой** и **1 Нагрузкой** (даже если до уничтожения было больше). Если его пилот погиб в этой же сцене, он тоже возвращается к жизни. Если Лич не возьмёт эту реакцию в том раунде, он остаётся уничтоженным, а пилот — мёртвым."}],"core":{"n":"Хроноспотыкание","pn":null,"pt":null,"an":"Сбой Времени","at":"До конца сцены вы можете нарушать ход времени. **1/раунд**, когда любой персонаж успешно атакует, воздействует или совершает действие против другого персонажа в пределах **Сенсоров**, вы можете прервать это до того, как оно разрешится:\n• действующий персонаж отталкивается до **3 пространств** в выбранном вами направлении, даже если у него **Невосприимчивость** к непроизвольному перемещению;\n• вы **телепортируетесь** в одно из пространств, которые он занимал, или как можно ближе, как бы далеко это ни было;\n• исходная атака, эффект или действие разрешается с вами в качестве цели.\nВы получаете весь урон, состояния, статусы и эффекты, а действие выполняется без изменений. Например, если союзника должны были телепортировать — телепортируют вас; если союзника чинили — чинят вас; если наносили урон и **Толчок** — урон получаете вы (с вашей Бронёй, Сопротивляемостью и т. п.) и отлетаете туда же, куда отлетела бы цель; если накладывали состояние или статус — получаете его вы. Прерывание не считается реакцией. Эффекты, нацеленные на самого себя, так прервать нельзя.","ag":"Активное (1 МЯ), Быстрое Действие"}},"mf_sunzi":{"n":"Сунь-цзы","en":"Sunzi","src":"HA","role":"Поддерживающий/Оператор","variant":"","book":"LR","tr":[{"n":"Безопасная Гавань","t":"Когда союзники в пределах [Дальн]50 от Сунь-цзы телепортируются или их телепортируют, свободные пространства рядом с Сунь-цзы всегда являются допустимой конечной точкой."},{"n":"Якорь","t":"Сунь-цзы **Невосприимчив** к непроизвольному перемещению, вызванному другими персонажами."},{"n":"Скольжение","t":"**1/раунд** Сунь-цзы может **свободным действием** телепортироваться на **2 пространства**."}],"core":{"n":"Резчик Реальности","pn":"Блинк-Якорь","pt":"Блинк-Якорь (**Размер ½**, метки: **Размещаемое**, **Невосприимчивость** ко всему урону и эффектам, **Ограниченное 3**). У вас есть один блинк-якорь, который можно разместить **быстрым действием**. Когда любой персонаж телепортируется в пределах вашей прямой видимости, вы можете заставить его появиться в свободном пространстве рядом с якорем вместо исходной точки, если он может там безопасно стоять. Если цель враждебна, это тратит заряд. Такое вмешательство не считается реакцией. Размещённый якорь вы или любой союзник рядом с ним может поднять или поставить **быстрым действием**.","an":"Искусство Войны","at":"До конца сцены эта система получает **6 зарядов** (удобно отслеживать кубиком). **Реакцией** в начале или в конце хода любого враждебного или союзного персонажа в пределах **Сенсоров** и прямой видимости потратьте заряд, чтобы **телепортировать** его на расстояние до **3 пространств** в любом направлении — в свободное пространство, где он может стоять.","ag":"Активное (1 МЯ), Свободное Действие"}},"mf_zheng":{"n":"Чжэн","en":"Zheng","src":"IPS-N","role":"Нападающий","variant":"","book":"LR","tr":[{"n":"Разрушительные Взмахи","t":"В конце хода Чжэна, если он совершил хотя бы одну ближнюю атаку по враждебному персонажу, сила его ударов создаёт в свободном соседнем пространстве кусок местности **Размера 1**, дающий **твёрдое укрытие**. У него **10 ПЗ** и **Уклонение 5**."},{"n":"Слабый Компьютер","t":"Чжэн получает **+1** [СЛОЖН] на все проверки и спасброски **Систем**."}],"core":{"n":"Комплекс Ближнего Боя «Сюн»","pn":"Упорство Сяоли","pt":"**1/ход**, **свободным действием**, вы можете переместиться до **3 пространств**, а затем нанести **2** [кин] любому соседнему персонажу или **10** [кин] **ББ** объекту или куску местности. Это перемещение вызывает вовлечение и не игнорирует реакции.\nЕсли этот урон уничтожает объект или кусок местности, он взрывается: всем соседним персонажам, кроме вас, — **1d6** [кин] и **Толчок 1**.","an":"Изобретательность Сяоли","at":"До конца сцены эта система получает **6 зарядов** (удобно отслеживать кубиком). Потратьте заряд, чтобы снова использовать **Упорство Сяоли**, игнорируя ограничение 1/ход. За ход можно тратить сколько угодно зарядов. В конце каждого хода вы восстанавливаете по заряду за каждую уникальную цель (персонажа, объект или кусок местности), которой нанесли урон этим действием, максимум до 6.","ag":"Активное (1 МЯ), Протокол"}},"mf_white_witch":{"n":"Белая Ведьма","en":"White Witch","src":"SSC","role":"Защитник","variant":"","book":"KTB","tr":[{"n":"Укоренённая","t":"Пока Белая Ведьма **Обездвижена**, у неё **Сопротивляемость** к [кин], её нельзя отбросить или **Сбить с ног**. **Протоколом** она может стать **Обездвиженной** до конца своего следующего хода."},{"n":"Закалка","t":"Когда Белая Ведьма **Укрепляется** (Brace), она получает **Усиление Щита** в размере **4 + Стойкость** до того, как получит урон."},{"n":"Текучий Всплеск","t":"Когда союзный персонаж в пределах [Дальн]2 от Белой Ведьмы получает урон из враждебного источника, Белая Ведьма может уменьшить этот урон на **1** и нанести себе **1** [кин] **ББ**."},{"n":"Страж","t":"Соседние союзные персонажи могут использовать Белую Ведьму как **твёрдое укрытие**."}],"core":{"n":"Ферроактивная Оболочка","pn":"Ферроактивная Броня","pt":"Каждый раз, получая урон от себя или из враждебного источника (даже если урон уменьшен или проигнорирован), после получения урона вы получаете **+1 Броню** до конца сцены, максимум **+6** (можно отмечать кубиком).","an":"Гиперактивный Режим","at":"До конца сцены Ферроактивная Броня даёт **+2 Брони** каждый раз вместо +1, максимум **+12**. Каждый раз, когда Броня так растёт, ваш мех наносит **1** [кин] **ББ** всем персонажам в [Разрыв]1, вытягивая сырьё из окружения.\nЕсли бонус Ферроактивной Брони должен превысить +12, он вместо этого взрывается: **1** [кин] **ББ** в [Разрыв]2 вокруг вас. Все персонажи в зоне проходят спасбросок **Корпуса**, иначе **Сбиты с ног**, затем **Обездвижены** и **Изрезаны** до конца своего следующего хода. Бонус Ферроактивной Брони сбрасывается до 0, но продолжает действовать, и этот эффект может срабатывать за сцену несколько раз.","ag":"Активная (1 МЯ), Протокол"}},"mf_emperor":{"n":"Император","en":"Emperor","src":"SSC","role":"Поддерживающий/Артиллерист","variant":"","book":"KTB","tr":[{"n":"Штормовой Щит","t":"ПЗ Императора **не растут** от Стойкости пилота. Вместо этого в начале любой сцены Император получает **Усиление Щита** в размере **6 + Стойкость**. Это Усиление Щита обновляется каждый раз, когда Император получает структурный урон."},{"n":"Императорское Облачение","t":"Каждый раз, когда Император даёт **Усиление Щита** другому персонажу, он получает столько же Усиления Щита. Когда Император получает Усиление Щита из любого источника (включая эту черту), оно **прибавляется** к текущему, а не заменяет его. Его Усиление Щита не может превышать значение от Штормового Щита."},{"n":"Державное Присутствие","t":"**1/раунд**, когда Император выбирает персонажа целью атаки, он может **осудить** его: цель проходит спасбросок **Инженерии**. При провале до начала следующего хода Императора цель получает **+1 урон** каждый раз, когда получает урон."}],"core":{"n":"Дарийские Регалии","pn":null,"pt":null,"an":"Апекс Ксеркса","at":"До конца сцены каждый мех, выбранный целью атаки **Марафонским Дуговым Луком**, после разрешения атаки выпускает молнию в персонажа на ваш выбор в пределах [Дальн]3 (можно в того, от кого она исходит). Молния либо наносит **2** **ББ** урона (без атаки и спасброска), либо увеличивает **Усиление Щита** цели на **+2**. Один персонаж может получить несколько молний.","ag":"Активная (1 МЯ), Протокол"}},"mf_black_witch_alt_orchidea":{"n":"Орхис","en":"Orchis","src":"SSC","role":"Оператор/Защитник","variant":"mf_black_witch","book":"KTB","tr":[{"n":"Идеальное Парирование","t":"Орхис и все соседние союзные персонажи **Невосприимчивы** ко всему урону и эффектам промахнувшихся атак."},{"n":"Страж","t":"Соседние союзные персонажи могут использовать Орхис как **твёрдое укрытие**."},{"n":"Королевская Гвардия","t":"Когда соседний союзный мех перемещается, Орхис может перемещаться вместе с ним, не теряя соседства и повторяя его движение. Препятствия на Орхис действуют, и между своими ходами он может так переместиться в сумме не больше чем на **Скорость + 1** пространств. Это не требует реакции, не провоцирует реакции и игнорирует вовлечение."}],"core":{"n":"Гелион","pn":"Охотничий Орёл","pt":"**1/раунд**, когда Орхис заставляет персонажа столкнуться с препятствием или другим персонажем, вы можете дополнительно метнуть в этого персонажа щит-скутум: **3** [кин], и до конца своего следующего хода цель не может совершать реакции. Затем щит возвращается к вам. Это не требует ни действия, ни реакции.","an":"Гелион","at":"Вы с огромной силой метаете щит в меха (союзного или враждебного) в пределах [Дальн]6: особый **Таран**, который не может промахнуться и отбрасывает цель на **3 пространства** вместо 1. Цель может столкнуться с препятствиями как обычно.\nЭто действие **Экономное**: в конце сцены, в которой оно использовано, вы возвращаете 1 Мощь Ядра.","ag":"Активная (1 МЯ), Быстрое Действие, Экономное"}},"mf_minotaur_alt_wraith":{"n":"Календула","en":"Calendula","src":"HORUS","role":"Оператор","variant":"mf_minotaur","book":"KTB","tr":[{"n":"Ваятель Судьбы","t":"**1/раунд**, когда Календула попадает по персонажу технологической атакой, она может создать **пустотную оболочку** в свободном пространстве в пределах [Дальн]3 от цели. Пустотные оболочки — **Неосязаемые** объекты, не создающие препятствий. Оболочка того же **Размера**, что цель, **Невосприимчива** ко всему урону и эффектам и создаёт ауру [Разрыв]2, действующую и на Неосязаемых, и на осязаемых персонажей: враждебные персонажи, хотя бы частично находящиеся в зоне, **Замедлены**. Оболочек может быть сколько угодно; все распадаются в конце сцены."},{"n":"Закон Грамматона","t":"**Замедленные** враждебные персонажи в пределах [Дальн]3 от Календулы также **Изрезаны**."},{"n":"Мантия Грамматона","t":"**Протоколом** Календула может стать **Неосязаемой** до начала своего следующего хода."}],"core":{"n":"Проклятие Имён Недостойных Мёртвых","pn":"Проклясть","pt":"⟦A:t⟧Проклясть⟦T⟧Быстрая Технология, 1/раунд⟦E⟧Выберите другого персонажа в прямой видимости в пределах [Дальн]3 от пустотной оболочки и изгоните его в межпространство. Союзники выбирают, поддаться ли; враждебные персонажи избегают эффекта успешным спасброском **Систем**. Изгнанные находятся в сумрачном сером мире и **Неосязаемы**.\nЭффект длится, пока изгнанный не переместится к пустотной оболочке или не начнёт ход рядом с ней — тогда он возвращается в физическое пространство и перестаёт быть Неосязаемым.⟦Z⟧","an":"Взвешивание Неравных Сердец","at":"Один враждебный и один союзный персонаж, оба в пределах [Дальн]5 и в прямой видимости от вас или от пустотной оболочки, становятся **Неосязаемыми** до конца вашего следующего хода. Для срабатывания нужно выбрать двух персонажей.\nЭто действие **Экономное**: в конце сцены, в которой оно использовано, вы возвращаете 1 Мощь Ядра.","ag":"Активная (1 МЯ), Быстрое Действие, Экономное"}},"mf_kidd":{"n":"Кидд","en":"Kidd","src":"IPS-N","role":"Поддерживающий","variant":"","book":"WF","tr":[{"n":"Быстрое Развёртывание","t":"В свой первый ход в любой боевой сцене Кидд может **свободным действием** разместить или активировать одну систему с меткой **Дрон** или **Размещаемое**."},{"n":"Перенаправление Мощности","t":"⟦A:s⟧Перенаправление Мощности⟦T⟧Быстрое Действие, 1/раунд⟦E⟧Кидд уничтожает один свой **Дрон** или **Размещаемый** объект, созданный или размещённый не в этом раунде, и либо даёт союзному персонажу **Усиление Щита 1d6+1**, либо наносит враждебному персонажу **1d6+1** [энерг] **ББ**. Цель (союзная или враждебная) должна быть рядом с уничтожаемым объектом. Системы без метки **Ограниченное**, уничтоженные так, нужно починить, прежде чем снова использовать.⟦Z⟧"},{"n":"Переработка","t":"В конце любой сцены, в которой Кидд использовал **Перенаправление Мощности**, он восстанавливает **1 заряд** одной своей **Ограниченной** системе с меткой **Дрон** или **Размещаемое**."}],"core":{"n":"Весёлый Роджер","pn":"Весёлый Роджер","pt":"В начале каждой боевой сцены Кидд автоматически подключается к своему орбитальному спутнику-оружию «Весёлый Роджер». Его эффективность зависит от калибровки с Киддом — её отслеживает **КУБ РОДЖЕРА**: 1d6, начиная с **1**.\nКуб растёт на **1**, когда вы:\n• размещаете **Дрон** или **Размещаемое**;\n• совершаете технологическое действие, целью которого является хотя бы один союзный персонаж.\nКаждый из этих способов поднимает куб не чаще раза за раунд; кроме того, куб растёт на 1 **без ограничений** каждый раз, когда враждебный персонаж совершает технологическое действие против союзного персонажа в пределах ваших **Сенсоров**.\n**1/раунд** **быстрым действием** вы активируете «Весёлого Роджера», сбрасывая куб на **1**, и выбираете один эффект по значению куба:\n**3+ Грабёж**: **Сканирование** всех враждебных персонажей в зоне [Взрыв]1 и **Захват** на них.\n**5+ Надувательство**: все враждебные персонажи в зоне [Взрыв]1 проходят спасбросок **Систем**, иначе **Ослаблены**, **Заклинены** и **Замедлены** до конца своего следующего хода.\n**6 Тысяча чертей**: луч пробивает узкое отверстие сквозь стены и преграды. Один враждебный персонаж проходит спасбросок **Маневренности**, иначе получает **3d6** [энерг] **ББ**; при успехе — половину.\nДля этих эффектов не нужна прямая видимость: их дальность — всё поле боя, они легко проходят сквозь объекты и местность, но более мощные преграды (например, энергетические щиты, которые не пропускают эффекты, как прямую видимость) блокируют их как обычно.\nКуб Роджера отмечается на вкладке «Бой».","an":"Череп и Кости","at":"До конца сцены Грабёж и Надувательство действуют в зоне [Взрыв]2, а «Тысяча чертей» поражает всех персонажей на пути [Линия]10.","ag":"Активная (1 МЯ), Протокол"}},"mf_sagarmatha":{"n":"Сагарматха","en":"Sagarmatha","src":"GMS","role":"Защитник","variant":"mf_standard_pattern_i_everest","book":"WF","tr":[{"n":"Страж","t":"Соседние союзные персонажи могут использовать Сагарматху как **твёрдое укрытие**."},{"n":"Героизм","t":"**1/сцена** Сагарматха может **Укрепиться**, не жертвуя действиями и перемещением в следующий ход."},{"n":"Заменяемые Детали","t":"Во время отдыха Сагарматху можно чинить по **1 Ремонту** за единицу структурного урона вместо **2**."}],"core":{"n":"Боевой Клич","pn":null,"pt":null,"an":"Поднять Знамя","at":"Вы поднимаете знамя. Все союзные персонажи в прямой видимости вашего меха в этот момент получают **Сопротивляемость** ко всему урону и нагреву и **+1** [ТОЧН] на все проверки и спасброски до конца вашего следующего хода.","ag":"Активная (1 МЯ), Быстрое Действие"}},"mf_tokugawa_alt_enkidu":{"n":"Энкиду","en":"Enkidu","src":"HA","role":"Нападающий/Защитник","variant":"mf_tokugawa","book":"WF","tr":[{"n":"Первобытная Ярость","t":"Когда Энкиду заканчивает ход в **Опасной Зоне**, он встаёт на дыбы, выпускает **Плазменные Когти** и впадает в первобытную ярость:\n• **При попадании** Плазменными Когтями цели сразу становятся **Обездвиженными** до конца своего следующего хода.\n• Особой реакцией Энкиду **обязан** атаковать Плазменными Когтями любого персонажа (враждебного или союзного), который входит в его зону **Угрозы**, выходит из неё или перемещается внутри неё больше чем на 1 пространство. Эту реакцию можно использовать раз за ход, сколько угодно раз за раунд, и она не учитывается в лимите реакций — другие реакции Энкиду совершает как обычно.\nЯрость кончается в начале хода Энкиду или если он выходит из Опасной Зоны."},{"n":"На Четырёх Лапах","t":"В **Опасной Зоне** Энкиду не может совершать дальние и технологические атаки, но его базовая **Скорость 6**."},{"n":"Грубая Сила","t":"Энкиду получает **+1** [ТОЧН] на проверки и спасброски **Корпуса**."},{"n":"Чутьё Крови","t":"Энкиду всегда знает, у кого из персонажей половина максимальных ПЗ или меньше, но не точное число."}],"core":{"n":"Ограничитель Ноль","pn":null,"pt":null,"an":"Сломать Ограничитель","at":"До конца сцены Энкиду получает действие «Рассечь», доступное только в **Опасной Зоне**:⟦A:s⟧Рассечь⟦T⟧Полное Действие, Опасная Зона⟦E⟧Энкиду пускает в ход чудовищную силу: выбирает соседнего персонажа (союзного или враждебного) и пытается разорвать его когтями пополам. Если у цели **7 ПЗ или меньше**, осталась **1 Структура** и нет **Невосприимчивости** к урону, она немедленно уничтожена, стоимость действия возвращается, и Энкиду может **Ускориться** свободным действием. Если уничтожить цель не удалось, она получает **1** [кин].\nВ конце сцены МЯ за «Рассечь» возвращается, если Энкиду так никого и не уничтожил.⟦Z⟧","ag":"Активная (1 МЯ), Протокол"}},"mf_genghis_alt_worldkiller_genghis_mk_i":{"n":"Чингис Мк I «Убийца Миров»","en":"“Worldkiller” Genghis Mk I","src":"HA","role":"Нападающий/Защитник","variant":"mf_genghis","book":"WF","tr":[{"n":"Теплоизолированный","t":"У Чингиса **Невосприимчивость** к горению."},{"n":"Боеприпасы TBK","t":"Атаки Чингиса игнорируют **Сопротивляемость** к горению и нагреву."},{"n":"Слабый Компьютер","t":"Чингис получает **+1** [СЛОЖН] на все проверки и спасброски **Систем**."}],"core":{"n":"Реактор Джаггернаут","pn":"Фуриоза","pt":"В **Опасной Зоне** вас окружает мерцающий жар, мешающий прицеливанию: вы получаете **лёгкое укрытие**. Кроме того, персонажи в пределах [Разрыв]1, кроме вас, не могут совершать реакции.","an":"451 по Фаренгейту","at":"До конца сцены Чингис окутан жаром: аура **Фуриозы** растёт до [Разрыв]2, а ваш мех игнорирует всю труднопроходимую местность, просто проплавляя её.\nЕсли в это время вы перегреваетесь, мех выпускает волну жара, плавящую землю: все персонажи, кроме вас, в зоне Фуриозы получают **1d6** [энерг] **ББ** и проходят спасбросок **Корпуса**, иначе **Обездвижены** до конца своего следующего хода. Зона становится труднопроходимой местностью до конца сцены.","ag":"Активная (1 МЯ), Протокол"}},"mf_swallowtail_alt_swallowtail_ranger_variant":{"n":"Ласточкин Хвост (вариант рейнджеров)","en":"Swallowtail (Ranger Variant)","src":"SSC","role":"Поддерживающий","variant":"mf_swallowtail","book":"WF","tr":[{"n":"Разведка Поля Боя","t":"До первого раунда любого боя и до любой расстановки разместите в свободных пространствах где угодно на поле боя до двух объектов:\n• зону 2×2, которая не мешает движению и даёт **лёгкое укрытие** персонажам хотя бы частично в ней;\n• зону 2×2 труднопроходимой местности;\n• **твёрдое укрытие** Размера 1.\nИх нельзя ставить ближе 4 пространств друг к другу; один вариант можно выбрать дважды. Это естественный рельеф поля боя — решите вместе с ГМом, что это."},{"n":"Бодрящие Сканеры","t":"**1/раунд**, когда Ласточкин Хвост накладывает **Захват**, союзный персонаж в пределах его Сенсоров и прямой видимости может реакцией переместиться на свою **Скорость**."},{"n":"Обветренность","t":"Ласточкин Хвост игнорирует труднопроходимую местность."}],"core":{"n":"Наследие Геи","pn":"Заземление","pt":"Когда вы заканчиваете ход в зоне, дающей **лёгкое укрытие**, вы становитесь **Невидимым**, пока не покинете укрытие, не получите урон, не атакуете, не заставите кого-то пройти спасбросок и не совершите иное враждебное действие, затрагивающее другого персонажа.","an":"Партизанская Война","at":"Вы создаёте три облака дыма [Разрыв]1 в пространствах в прямой видимости и в пределах [Дальн]5. Они дают **лёгкое укрытие** персонажам хотя бы частично в них и держатся до конца сцены.\nКроме того, до конца сцены союзные персонажи в пределах ваших **Сенсоров** получают преимущества **Заземления**.","ag":"Активная (1 МЯ), Протокол"}},"mf_störtebeker":{"n":"Штёртебекер","en":"Störtebeker","src":"IPS-N","role":"Нападающий","variant":"mf_raleigh","book":"DG","tr":[{"n":"Динамическая Перезарядка","t":"Невспомогательное оружие Штёртебекера получает эффекты:\n• **Ближнее** оружие: «**При крите**: перезарядить всё дальнее оружие, которым в этом ходу не атаковали».\n• **Дальнее** оружие: «**При крите**: перезарядить всё ближнее оружие, которым в этом ходу не атаковали»."},{"n":"Истинное Серебро","t":"**1/сцена**, попав оружием, Штёртебекер может применить один эффект в зависимости от типа оружия:\n• **Не Заряжаемое** оружие: попадание считается **критическим** (урон не бросается дважды).\n• **Заряжаемое** оружие: итоговый урон нельзя уменьшить."}],"core":{"n":"Оружие Истинного Серебра","pn":"Доктрина Хопкинса","pt":"Это действие можно совершить, только если в этом ходу вы совершили действие **Перестрелка**. Выберите один эффект:⟦A:s⟧Реприза⟦T⟧Быстрое Действие⟦E⟧**Перестрелка** оружием, перезаряженным в этом ходу **Динамической Перезарядкой**.⟦Z⟧⟦A:s⟧Обновление⟦T⟧Быстрое Действие⟦E⟧Всё оружие, которым в этом ходу не атаковали, перезаряжается в конце хода.⟦Z⟧","an":"Арсенал Истинного Серебра","at":"В этой сцене вы можете использовать черту **Истинное Серебро** ещё **три раза**.","ag":"Активная (1 МЯ), Протокол"}},"mf_micro_monarch":{"n":"Вице-король","en":"Viceroy","src":"SSC","role":"Нападающий","variant":"mf_monarch","book":"DG","tr":[{"n":"Процессор Ближнего Наведения","t":"Вице-король считает своё оружие-**ПУ** также оружием **ОБД** с **Угрозой 3**."},{"n":"Всенаправленные Пусковые «Виджиланте»","t":"**1/раунд**, при критическом попадании по персонажу Вице-король может сразу нанести **2** [взр] всем персонажам на свой выбор в пределах [Дальн]3 от себя и отбросить их на **1 пространство**."},{"n":"Противовзрывная Обшивка","t":"У Вице-короля **Сопротивляемость** к взрывному урону."}],"core":{"n":"Ракетные Трубы СШК-41 «Тэнгу»","pn":null,"pt":null,"an":"Небесный Ливень","at":"Вы обрушиваете рой ракет [Разрыв]3 вокруг себя. Враждебные персонажи в зоне проходят спасбросок **Корпуса**, иначе получают **1d6+3** [взр] и **Сбиты с ног**; при успехе — половину урона и остаются на ногах. Можно израсходовать **Захват** на персонаже в зоне, чтобы он автоматически провалил спасбросок.\nДо или после этого действия вы можете **пролететь** на свою **Скорость**, игнорируя вовлечение и реакции. Закончить движение нужно на твёрдой поверхности, иначе начнёте падать.","ag":"Активная (1 МЯ), Быстрое Действие"}},"mf_gilgamesh":{"n":"Гильгамеш","en":"Gilgamesh","src":"HA","role":"Нападающий","variant":"","book":"WS","tr":[{"n":"Несущие Узлы","t":"Все **Ограниченные** системы и оружие, установленные на Гильгамеш, получают **+1 заряд**."},{"n":"Полный Боекомплект","t":"У Гильгамеша есть **Куб Снаряжения** — 1d6, начиная с **6**. Каждый раз, когда Гильгамеш тратит заряд **Ограниченного** снаряжения, куб уменьшается на **1**. Когда куб доходит до **1**, его можно сбросить на **6**, чтобы перебросить одну атаку, проверку или спасбросок; второй результат нужно оставить. Значение куба сохраняется между сценами и сбрасывается на 6 при **Полном Ремонте**."}],"core":{"n":"Экзокаркасная Инженерия","pn":"Экзокаркасная Инженерия","pt":"Модульная конструкция Гильгамеша позволяет чинить его прямо в поле: повреждённые конечности и узлы отстреливаются и заменяются запасными. **1/сцена** **свободным действием** выберите одно:\n• восстановите **половину** всех своих ПЗ;\n• почините уничтоженное оружие или систему.\nЕсли вы не использовали эту способность в бою, то на следующем отдыхе можете либо восстановить все ПЗ, либо автоматически починить уничтоженное оружие или систему.\nИспользование этой способности в бою считается тратой заряда **Ограниченного** снаряжения.","an":"Экзоусиление","at":"До конца своего следующего хода вы получаете **Невосприимчивость** ко всем состояниям, вызванным не вашими собственными системами, талантами и т. п., и снимаете все такие уже имеющиеся состояния (даже те, что обычно снять нельзя). Кроме того, вы снимаете **Уязвимость**, встаёте, если **Сбиты с ног**, и получаете **Сверхщит** в размере **Стойкость + 4**. В конце вашего следующего хода этот Сверхщит снимается. Способность можно использовать, даже если обычно вы не могли бы совершить это действие (например, будучи **Ошеломлённым**).\nИспользование этой способности в бою считается тратой заряда **Ограниченного** снаряжения.","ag":"Активная (1 МЯ), Протокол"}},"mf_amber_phantom":{"n":"Янтарный Фантом","en":"Amber Phantom","src":"SSC","role":"Нападающий","variant":"mf_metalmark","book":"WS","tr":[{"n":"Сверхбдительность","t":"В начале каждого раунда, пока Янтарный Фантом ещё не походил, все атаки по нему получают **+1** [СЛОЖН], а его спасброски — **+1** [ТОЧН]."},{"n":"Боевой Оракул","t":"**1/раунд**, когда враждебная атака промахивается по Янтарному Фантому, он может притянуть персонажа в пределах **Сенсоров** на **2 пространства** в любом направлении."}],"core":{"n":"Карта Вероятностей","pn":"Карта Вероятностей","pt":"В начале каждого раунда выберите момент в очерёдности ходов ИП, когда собираетесь действовать (например, при трёх ИП — первым, вторым или третьим). **1/раунд**, если вы ходите в выбранный момент, можете нанести **+1d6** бонусного урона при попадании дальней или ближней атакой по цели в пределах **Сенсоров**. Если ходите в другой момент, этот бонусный урон всё равно можно нанести, но тогда вы получаете **1d6** [нагрев].","an":"Точка Схождения","at":"Выберите союзного персонажа, который ещё не ходил в этом раунде. Он может сходить либо сразу после конца вашего хода, либо прямо сейчас, до всего остального, — тогда ваш ход приостанавливается, пока его ход не закончится. Если он ходит сейчас, он считается ходившим раньше вас в очерёдности ИП.\n**Экономное**: в конце сцены, в которой эта способность использовалась, вы возвращаете **1 Мощь Ядра**.","ag":"Активная (1 МЯ), Экономное, Протокол"}},"mf_lycan":{"n":"Ликан","en":"Lycan","src":"HORUS","role":"Защитник/Нападающий","variant":"mf_manticore","book":"WS","tr":[{"n":"Шлаковый Панцирь","t":"У Ликана **Сопротивляемость** к энергетическому урону и горению."},{"n":"Поле Помех","t":"Все враждебные персонажи в пределах [Дальн]3 от Ликана получают **+1** [СЛОЖН] на все атаки, целью которых не является Ликан."},{"n":"Скачок Мощности","t":"**1/раунд**, когда Ликан получает [нагрев], один враждебный персонаж в пределах [Дальн]3 проходит спасбросок **Систем**, иначе **Ослаблен** и **Замедлен** до конца своего следующего хода."}],"core":{"n":"Подрывная Сигнатура","pn":null,"pt":null,"an":"Во Весь Голос","at":"Вы с грохотом сбрасываете внешний панцирь Ликана, выпуская жестокие когти и форсируя реактор. До конца сцены ваша базовая **Броня** становится **0**, базовая **Скорость** — **6**, черты **Шлаковый Панцирь** и **Поле Помех** отключаются, и вы получаете встроенное оружие **Шоковые Когти**.\nЗатем вы можете рвануться вперёд: переместитесь на свою **Скорость** и атакуйте Шоковыми Когтями цель в пределах досягаемости. Эта атака считается **Шквалом** для правила о повторных действиях.\nДо активации мощь оружия растёт от близости к тяжёлым повреждениям: в первый раз за сцену, когда союзный **Мех** в пределах **Сенсоров** получает структурный урон от враждебного источника до активации «Во Весь Голос», оружие получает **Угрозу 2**. Если это повторится до активации, оружие ещё и наносит **4d6+6** [энерг] вместо 3d6+6.\nЕсли союзный Мех уничтожен до активации или вы активируете её при **2 Структурах** или меньше, вы сразу получаете оба улучшения.\n**Экономное**: в конце сцены, в которой эта способность использовалась, вы возвращаете **1 Мощь Ядра**.\nВ программе: кнопка активации ядра сама включает «Во Весь Голос» — Броня 0, Скорость 6, без Сопротивляемости Шлакового Панциря; режим снимается на Перерыве.","ag":"Активная (1 МЯ), Экономное, Полное Действие"}},"mf_kutuzov":{"n":"Кутузов","en":"Kutuzov","src":"HA","role":"Защитник/Поддерживающий","variant":"mf_napoleon","book":"WS","tr":[{"n":"Зона Выталкивания","t":"**1/раунд**, когда Кутузов **Активирует** или иначе использует систему с меткой **Щит** в свой ход, он может отбросить всех враждебных персонажей на свой выбор в пределах **Сенсоров** на **3 пространства**."},{"n":"Аварийные Блинк-поля","t":"Когда Кутузов или союзный персонаж в пределах его **Сенсоров** использует реакцию **Укрепление**, этот персонаж снимает **Расщепление** от враждебных источников (или игнорирует его эффекты, если снять нельзя), а атаки, против которых он Укрепляется, не могут его **Расщепить**."}],"core":{"n":"Параллельные Проекторы","pn":"Параллельные Проекторы","pt":"**1/раунд**, когда вы в свой ход совершаете **Стабилизацию**, быстрое технологическое действие **Подкрепление** или **Активируете** (или иначе используете) систему с меткой **Щит**, вы можете дать союзному персонажу в пределах **Сенсоров** преимущество по стоимости этого действия:\n• **Свободное действие**: лёгкое укрытие до конца его следующего хода.\n• **Быстрое действие**: до конца его следующего хода он игнорирует вовлечение, его перемещение не провоцирует реакций, и он может проходить (но не останавливаться) через пространства с препятствиями и другими персонажами.\n• **Полное действие**: он может снять одно состояние, вызванное не его собственными системами, талантами и т. п.\nМожно выбрать преимущество меньшей стоимости (например, за полное действие — вариант быстрого или свободного).","an":"Проецируемая Эгида","at":"Выберите союзного и враждебного персонажей в прямой видимости. До конца вашего следующего хода они не могут атаковать друг друга и заставлять друг друга проходить спасброски действиями. Способность считается системой с меткой **Щит**.\n**Экономное**: в конце сцены, в которой эта способность использовалась, вы возвращаете **1 Мощь Ядра**.","ag":"Активная (1 МЯ), Быстрое Действие, Щит, Экономное"}},"mf_Empakaai_alt_blackbeard":{"n":"Эмпакаи","en":"Empakaai","src":"IPS-N","role":"Нападающий","variant":"mf_blackbeard","book":"SS","tr":[{"n":"Непреодолимая Мощь","t":"**1/раунд** Эмпакаи может дать проверке или спасброску **Корпуса**, которые он навязал, **+1** [СЛОЖН]."},{"n":"Неукротимая Сила","t":"У Эмпакаи **Сопротивляемость** к урону и нагреву от персонажей, которых он **Схватил**."}],"core":{"n":"Нисхождение в Калунгу","pn":null,"pt":null,"an":"Костные Якоря","at":"До конца сцены, пока вы кого-то **Схватили**, вы считаетесь на **1 Размер больше** суммарного Размера всех схваченных целей. Кроме того, до конца сцены вы получаете:\n• **Рука Ику**: попав по персонажу атакой ближнего оружия, Эмпакаи может **свободным действием** попытаться его **Схватить**. При успехе цель притягивается вплотную и Схвачена.\n• **Каталитический Инфузор**: в конце своего хода Эмпакаи наносит **[текущий нагрев]** [энерг] **ББ** персонажу, которого он схватил (или делит эту сумму между всеми схваченными).","ag":"Активная (1 МЯ), 1/сцена, Протокол"}},"mf_lancaster_alt_taraxacum":{"n":"Тараксакум","en":"Taraxacum","src":"IPS-N","role":"Поддерживающий","variant":"mf_lancaster","book":"SW","tr":[{"n":"Сверхподъёмная Лётная Система ROC","t":"Тараксакум может **парить** при перемещении. Пока он несёт только объекты или союзных персонажей, он может игнорировать ограничения на переноску в полёте.\nВ конце каждого своего хода, в котором Тараксакум использовал эту черту, он получает нагрев, равный **1 + суммарный Размер** объектов и персонажей, которых он несёт."},{"n":"Ретрансляционная Сцепка","t":"Когда Тараксакум выбирает целью союзного персонажа в пределах **Сенсоров** системой или технологическим действием, тот до начала следующего хода Тараксакума может использовать **Сенсоры** и прямую видимость Тараксакума для технологических действий."}],"core":{"n":"Сенсоры Разведки типа «Кроссленд»","pn":"Точная Привязка","pt":"Когда вы **Сканируете** персонажа, он не может пользоваться укрытием и **Невидимостью** до конца вашего следующего хода.","an":"Всеспектральный Сенсорный Импульс","at":"**Сканируйте** всех враждебных персонажей в зоне [Разрыв]4 и под ней. На любых просканированных так персонажей можно наложить **Захват**.\n**Экономное**: в конце сцены, в которой способность использовалась, вы возвращаете **1 Мощь Ядра**.","ag":"Активная (1 МЯ), Экономное, Быстрое Действие"}},"mf_balor_alt_hecatoncheires":{"n":"Гекатонхейр","en":"Hecatoncheires","src":"HORUS","role":"Нападающий/Оператор","variant":"mf_balor","book":"SW","tr":[{"n":"Рассеянный Силуэт","t":"Пока Гекатонхейр в **лёгком укрытии**, дальние атакующие получают **+2** [СЛОЖН] вместо +1."},{"n":"Дым и Зеркала","t":"Гекатонхейр всегда может **Спрятаться** в зоне лёгкого укрытия — независимо от вовлечения и вражеских черт и систем."},{"n":"Наведение «Паноптес»","t":"**Умное** оружие Гекатонхейра игнорирует **Невидимость** персонажей в пределах **Сенсоров**."}],"core":{"n":"Направленная Сизая Мгла MYRIOS «Длинный Поводок»","pn":"Бритвенный Улей","pt":"⟦A:s⟧Развернуть Бритвенный Рой⟦T⟧Быстрое Действие, Дрон⟦E⟧Разместите **бритвенный рой** в допустимой зоне [Взрыв]1 в пределах **Сенсоров**, где нет враждебных персонажей. Рой считается **Дроном** для ваших систем, талантов, черт и т. п. и систем союзников, но в остальном это зона на поле: не мешает перемещению, не вызывает вовлечения, и враги никак не могут на неё воздействовать.\nОдновременно у вас может быть только один рой. Он держится до конца сцены или пока вы не отзовёте или не переместите его **быстрым действием**.\nРой даёт **лёгкое укрытие** союзникам, хотя бы частично находящимся в зоне. Враждебные персонажи, начинающие ход хотя бы частично в зоне или впервые за раунд входящие в неё, получают **2 горения**.⟦Z⟧","an":"Разъярить Рой","at":"Каждый враждебный персонаж в одной или нескольких зонах, созданных вашими **Дронами**, получает **4 горения**.\n**Экономное**: в конце сцены, в которой способность использовалась, вы возвращаете **1 Мощь Ядра**.","ag":"Активная (1 МЯ), Быстрое Действие, Экономное"}},"mf_sherman_alt_tagetes":{"n":"Тагетес","en":"Tagetes","src":"HA","role":"Артиллерист","variant":"mf_sherman","book":"SW","tr":[{"n":"Фузилёр","t":"Устанавливая на Тагетес дальнее оружие (или при **Полном Ремонте**), можно сменить его тип на **Винтовку**. Оружие, чей тип так изменён, получает **Избыточный Урон**."},{"n":"Строевая Дисциплина","t":"Пока рядом есть союзный мех, Тагетес получает **+1** [ТОЧН] на все проверки и спасброски."},{"n":"Конструкция Этеране","t":"**Стабилизируясь**, можно дополнительно выбрать одно:\n• перезарядить всё **Заряжаемое** оружие;\n• снять всё горение с меха;\n• снять одно состояние, вызванное не вашими собственными системами, талантами и т. п.;\n• снять такое же состояние с соседнего союзного персонажа."}],"core":{"n":"Стрелковое Снаряжение «Чорак»","pn":"Синхронизированный Дальний Прицел «Темпесте»","pt":"Вы можете атаковать **Винтовками** так, будто у них **+5 Дальности**, если в этой атаке расходуется **Захват**.","an":"Система Рассеивания Тепла «ПЕСЧАНАЯ БУРЯ»","at":"**Стабилизируясь**, можно активировать эту систему: создаётся неподвижная зона [Разрыв]2 **лёгкого укрытия** до конца вашего следующего хода. Пока вы и союзники пользуетесь этим укрытием, каждый может **протоколом** снять **1d3+1** нагрева.\n**Экономное**: в конце сцены, в которой способность использовалась, вы возвращаете **1 Мощь Ядра**.","ag":"Активная (1 МЯ), Экономное"}},"mf_chomolungma":{"n":"Чомолунгма","en":"Chomolungma","src":"GMS","role":"Оператор/Поддерживающий","variant":"mf_standard_pattern_i_everest","book":"SR","tr":[{"n":"Гениальность","t":"**1/сцена** Чомолунгма может совершить любое **быстрое технологическое действие** **свободным действием**, а затем — **Подкрепление** или **Захват** тоже **свободным действием**."},{"n":"Перекачка Данных","t":"Совершая технологическую атаку против враждебного персонажа, Чомолунгма может заодно автоматически его **Сканировать**."},{"n":"Заменяемые Детали","t":"Во время отдыха Чомолунгму можно чинить по **1 Ремонту** за каждый урон Структуре вместо 2 Ремонтов."}],"core":{"n":"Продвинутый Пакет Вторжения","pn":"Продвинутый Пакет Вторжения","pt":"Вы получаете новые варианты **Вторжения**:\n• **Блокировка Баланса**: оттолкните цель на **2** пространства в любом направлении и собьёте её с ног (**Сбита с ног**). Если она уже Сбита с ног — она **Обездвижена** до конца своего следующего хода. Обездвиживать так каждого персонажа можно **1/сцена**.\n• **Сокрушитель Систем**: цель получает дополнительно **2 нагрева** (всего **4**). Если из-за этого Вторжения она превышает **Предел Нагрева**, она получает ещё **4 горения**. Не чаще **1/сцена** против каждого персонажа.","an":"Импульс Кода по Площади","at":"Выберите сколько угодно враждебных персонажей в пределах **Сенсоров** и совершите против них особую технологическую атаку **Вторжение**, игнорируя **Невидимость** и прямую видимость. При попадании примените эффекты Вторжения как обычно, выбирая вариант для каждой цели. При промахе цели **Ослаблены** до конца своего следующего хода.","ag":"Активная (1 МЯ), Полное Действие"}}},"weapons":{"mw_anti_materiel_rifle":{"n":"Крупнокалиберная Снайперская Винтовка","t":""},"mw_assault_rifle":{"n":"Штурмовая Винтовка","t":""},"mw_charged_blade":{"n":"Заряженный Клинок","t":""},"mw_cyclone_pulse_rifle":{"n":"Импульсная Винтовка «Циклон»","t":""},"mw_heavy_charged_blade":{"n":"Тяжёлый Заряженный Клинок","t":""},"mw_heavy_machine_gun":{"n":"Крупнокалиберный Пулемет","t":""},"mw_heavy_melee_weapon":{"n":"Тяжелое ОББ","t":""},"mw_howitzer":{"n":"Гаубица","t":""},"mw_missile_rack":{"n":"Ракетная Батарея","t":""},"mw_mortar":{"n":"Миномет","t":""},"mw_nexus_hunter_killer":{"n":"Звено (Охотник-Убийца)","t":""},"mw_nexus_light":{"n":"Звено (Легкий)","t":""},"mw_pistol":{"n":"Пистолет","t":""},"mw_segment_knife":{"n":"Сегментный Нож","t":""},"mw_rocket_propelled_grenade":{"n":"Противотанковый Гранатомет","t":""},"mw_shotgun":{"n":"Дробовик","t":""},"mw_tactical_knife":{"n":"Тактический Нож","t":""},"mw_tactical_melee_weapon":{"n":"Тактическое ОББ","t":""},"mw_thermal_lance":{"n":"Термическое Копье","t":""},"mw_thermal_pistol":{"n":"Термический Пистолет","t":""},"mw_thermal_rifle":{"n":"Термическая Винтовка","t":""},"mw_chain_axe":{"n":"Цепной Топор","t":"При Критическом Попадании: ваша цель становится\nРасщепленной до конца текущего хода.","f":"Простая тактическая версия инструмента для лесозаготовок, цепной топор ИПС-Н представляет собой зазубренный цепной нож, работающий от мощности ядра. Зубья топора имеют вольфрамовые наконечники, закаленные для пробивания твердых и мягких целей. Цепные топоры — эффективное оружие и инструмент, который часто используется абордажными отрядами для пробивания укрепленных перегородок."},"mw_bristlecrown_flechette_launcher":{"n":"Игольчатый Гранатомет Щетинник","t":"Это оружие игнорирует штрафы дальности от **Вовлечения**, и наносит 3 [кин] по Схваченным или **Биологическим** целям, вместо 1.","f":"ИПС-Н Игольчатый Гранатомет Щетинник использует механизм, аналогичный улью, для проецирования полной зоны поражения мягких целей в куполе вокруг пользователя, превентивно блокируя действия враждебной пехоты."},"mw_nanocarbon_sword":{"n":"Наноуглеродный Меч","t":"","f":"Наноуглеродный меч ИПС-Н — это новый взгляд на старую классику. Встроенные наносенсоры, расположенные вдоль захватывающего лезвия, собирают полный спектр данных и передают их в банковские омнимет-хранилища для последующего анализа. Тем временем встроенное программное обеспечение интерпретирует данные в текущем времени и корректирует молекулярный состав острия клинка в режиме реального времени."},"mw_assault_cannon":{"n":"Штурмовая Пушка","t":"Вы можете раскрутить стволы этого оружия в качестве быстрого действия. Во время раскручивания оно приобретает **Надежность 3**, но вы **Замедляетесь**. Вы можете прекратить этот эффект как протокол.","f":"Штурмовая пушка ИПС-Н — это автопушка с глубоким охлаждением, которую можно использовать как навесное орудие или платформу с манипулятором. Пушка, простая по своей функциональности, может питаться либо из коробчатого магазина, либо из ленты и является стандартной комплектацией практически в любом заказе флота ИПС-Н. В условиях микрогравитации и невесомости пилоты Дрейка обычно используют штурмовую пушку в качестве дополнительной двигательной установки."},"mw_concussion_missiles":{"n":"Сотрясающие Ракеты","t":"**При Попадании**: Цель должна преуспеть в спасброске **Корпуса**, иначе она станет **Ослабленной** до конца своего следующего хода.","f":"Сотрясающие ракеты оснащены зарядами, создающими избыточное давление, с низким уровнем разрушения и слабым накаливанием — они предназначены для оглушения, сдерживания, отталкивания и дезориентации, обычно в тандеме с более крупной и смертоносной атакой."},"mw_leviathan_heavy_assault_cannon":{"n":"Тяжелая Штурмовая Пушка “Левиафан”","t":"В отличие от другого **Сверхтяжелого** оружия, Левиафан можно использовать в **Перестрелке**.\nВы можете раскрутить стволы этого оружия в качестве быстрого действия. Во время раскручивания оно получает **Надежность 5** и **2 [нагрев]** (себя), а его урон увеличивается до **4d6+4 [кин]**; однако вы **Замедляетесь** и больше не можете использовать **Левиафана** в **Перестрелке**.\nВы можете остановить этот эффект как **протокол**.","f":"Тяжелая штурмовая пушка \"Левиафан\" (ТШП) — это массивная многоствольная роторная пушка, питающаяся из внешнего резервуара, обычно установленного на шасси. В немодифицированном виде \"Левиафан\" должен стрелять только в пределах рекомендованной синхронизации вспышек, чтобы предотвратить ударные травмы соединений и пилотов.\nВ партнерстве с аналитическим центром Оружейной палаты Харрисона ИПС-Н в настоящее время изучает дистанционные решения для удовлетворения потребностей пушки в боеприпасах."},"mw_cutter_mkii_plasma_torch":{"n":"Плазменный Резак MкII","t":"Это оружие наносит 10 [энерг] **ББ** по объектам, укрытиям, местности и окружающей среде.","f":"Плазменные резаки сначала были инструментами: простые лезвия, созданные для переключения и поддержания плазменной оболочки, что облегчало резку металла. Неоднократное специальное использование резаков в качестве оружия индивидуальной защиты от пиратских абордажных групп убедило ИПС-Н в необходимости создания военного варианта гражданского инструмента — резака, уже второго поколения. Резак МкII питается непосредственно от мощи ядра меха, также он оснащен портом для подключения блоков питания в случае обрыва шнура. Хотя режущая кромка может быть укорочена до длины ножа, ее наиболее популярным вариантом является «абордажная сабля», вариант средней длины, идеально подходящий для баланса досягаемости и маневренности на близких расстояниях.\nОт переводчика: Mk (сокр. от Mark[ing], с англ. — «обозначение, маркировка») — традиционное для англоамериканских тыловых служб обозначение военного имущества на флоте"},"mw_war_pike":{"n":"Боевая Пика","t":"","f":"Боевая пика — это простое оружие: длинное древко, увенчанное плотным тонким острием, предназначенным для пробивания доспехов. Ранние конструкции были производными от шахтерских пилонов, но современная боевая пика — это прочное, сбалансированное и надежное оружие, идеально подходящее для атаки."},"mw_power_knuckles":{"n":"Силовые Кастеты","t":"При Критическом Попадании: Ваша цель должна преуспеть в спасброске Корпуса, иначе она будет Сбита с ног.","f":"Линейка силовых кастетов ИПС-Н — еще одна популярная покупка для пилотов, предпочитающих сражаться вблизи. Принимая форму чего угодно, от фигурных шипов до сверхплотных костяшек или серии микротаранов с магнитным ускорением, силовые костяшки усиливают и без того невероятную ударную мощь меха."},"mw_hand_cannon":{"n":"Ручная Пушка","t":"","f":"Ручная пушка ИПС-Н — это лицензионная версия пистолета Тип-I от ДМС, адаптированную для более крупного калибра. Эта модификация требует, чтобы система с ленточным питанием сборки ДМС была заменена на цилиндрическую или магазинную систему, в зависимости от конкретной модели ручной пушки."},"mw_bolt_thrower":{"n":"Метатель Болтов","t":"","f":"Как и многие классические виды оружия ИПС-Н, метатель болтов произошел от гражданского шахтерского инструмента. Он стреляет самонаводящимися взрывными болтами, идеально подходящими для использования в микро- и нулевой гравитации, а также в атмосфере."},"mw_kinetic_hammer":{"n":"Кинетический Молот","t":"","f":"Кинетический молот — простой, но жестокий инструмент. Состоящий из сверхмассивной головки, соединенной с длинным черенком, молот обладает достаточной силой, чтобы при удачном ударе создавать волны травматического давления."},"mw_deck_sweeper_automatic_shotgun":{"n":"Авто-Дробовик «Чистильщик Палуб»","t":"","f":"Автоматический дробовик «Чистильщик Палуб» — это обрез с ленточным питанием, любимый пилотами морской пехоты на борту станций и крупных кораблей. Его принцип действия прост: заряжай, наводи и стреляй. Одноствольное сужение обеспечивает пневматическое поглощение, смягчая эффект его невероятной отдачи, а его ленточный механизм подачи совместим со многими типами дробовиков и пуль."},"mw_daisy_cutter":{"n":"Ромашковый Резак","t":"**При Атаке**: создает облако дыма и обломков в конусе атаки, обеспечивая **мягкое укрытие** в пораженной области до конца вашего следующего хода.","f":"Ромашковый резак — эффективное, хотя и устаревшее оружие, до сих пор любимое многими пилотами флота. По сути, это массивный дробовик; пилот берет оружие, заряжая ствол подкалиберными боеприпасами, прицеливается и стреляет облаком адского пламени из стреловидных дротиков, подшипников и зажженных магниевых полос, которые гарантированно уничтожат любую палубу, по которой был произведен выстрел."},"mw_catalytic_hammer":{"n":"Каталитический Молот","t":"**При Критическом Попадании**: Ваша цель должна преуспеть в спасброске **Корпуса** или стать **Ошеломленной** до конца своего следующего хода.","f":"Переделанный первоначально из оборудования для взрывных работ, каталитический молот (в просторечии \"боевой перфоратор\") с тех пор был усовершенствован и превратился в грозное оружие ближнего боя. При выстреле заряд проталкивает молот — сплошной цилиндр с шипом на одном конце — через короткий ствол, нанося удар с огромной кинетической силой. Стандартные головки молотов гладкие, что позволяет легко извлекать их из целей, но их можно отсоединить и заменить, если извлечение невозможно. Любая установка каталитического молота требует усиления надстройки для обеспечения достаточного рассеивания энергии."},"mw_impact_lance":{"n":"Ударное Копье","t":"**При Атаке**: Вы также атакуете всех персонажей, находящихся на **Линии** между вами и вашей целью. Вы получаете 1 [нагрев] за каждую цель после первой.","f":"Ударное копье — это армейский вариант обычного горнодобывающего инструмента: одноразового лазера для химических исследований. Военный вариант ИПС-Н устанавливает серию ударных копий на плечевой или грудной каретке меха, оставляя его манипуляторы свободными для использования другого оружия и систем. Он может быть подключен непосредственно к ядру шасси или заряжаться от одноразовых химических батарей.\nМассив копья выстреливает в течение микросекунды, высвобождая накопленный заряд, чтобы произвести интенсивную вспышку света, которая вырывается плотным импульсным лучом, способным пронзить метры закаленной стали."},"mw_impaler_nailgun":{"n":"Гвоздострел Цепеш","t":"**При Попадании**: Цели должны успешно пройти спасбросок **Корпуса** или стать **Обездвиженными** до конца своего следующего хода.","f":"Невоспламеняющиеся подкалиберные двухступенчатые макрофлешетты Цепеша способны пробить даже самую тяжелую броню. После катапультирования из пусковой установки поддон снаряда сбрасывается при приближении к цели и запускает вторую ступень — внутренняя тяга толкает макрофлешет вперед с невероятной скоростью. Сверхпробитие мягких целей гарантировано; ИПС-Н советует стрелять из этого оружия только тогда, когда область позади цели свободна от союзников или мирных жителей."},"mw_combat_drill":{"n":"Боевая Дрель","t":"При атаке **Сбитого**, **Обездвиженного** или **Ошеломленного** персонажа, благодаря метке **Избыточного Урона** это оружие наносит **+1d6 дополнительного урона** при каждой активации. Он может активироваться бесконечно, если результат нового бонусного кубика равен 1, что снова вызывает **Избыточный Урон**.","f":"Боевая дрель — жестокое оружие ближнего боя, работающее от массивного внешнего блока катализаторов. Сверло оснащено микроплазменными проекторами, предназначенными для предварительной обработки цели и обеспечения проникновения сверла."},"mw_magnetic_cannon":{"n":"Магнитная Пушка","t":"**При Атаке**: все персонажи в зоне поражения должны успешно выполнить спасбросок **Корпуса** или быть притянутыми на **1d3+1** пространств к вам или как можно ближе.","f":"Магнитная пушка СШК является первой из Группы Экзотических Материалов: сфокусированный на апертуре электромагнитный проекционный луч, который использует интенсивные импульсы магнитной энергии для разрушения и повреждения оборудования. Цели, попавшие в луч магнитной пушки, получают дополнительные повреждения своего программного обеспечения, так как на чувствительные компоненты воздействует огромная системная нагрузка."},"mw_vulture_dmr":{"n":"МВ Гриф","t":"","f":"Пехотная Снайперская Марксманская Винтовка (МВ) Гриф — основная боевая винтовка СШК. Надежный, доступный в десятках конфигураций и калибров, питаемый коробом, барабаном или лентой, Гриф является популярным вооружением для широкого спектра мехов."},"mw_railgun":{"n":"Рельсотрон","t":"","f":"Рельсотроны — простое и элегантное оружие. Благодаря магнитному ускорению снарядов и отсутствию движущихся частей они эффективны на любом театре военных действий и полностью автономны в одноразовых блоках. За эту эффективность приходится платить: рельсотроны потребляют огромное количество энергии, поэтому их владельцам приходится носить с собой заряжаемые ядрами вспомогательные блоки перевода энергии."},"mw_veil_rifle":{"n":"Завесная Винтовка","t":"Это оружие не атакует союзных персонажей, попавших в зону его действия; вместо этого он окутывает их полем сверкающей энергии, которая сбрасывает системы наведения, давая им **мягкое укрытие** до конца их следующего хода.","f":"“Мы установили первый контакт примерно через час после проникновения в хранилище. Я ничего об этом не помню. Мне сказали, что большая часть моего отряда была убита на месте; все, что я помню, это свет — яркий свет — и легкость во всем моем собственном существе.\n“Я верю, что умер в тот момент, и все же я здесь, и я не могу сопоставить эти две реальности. Что-то пошло не так, что-то пошло не так, что-то пошло…”"},"mw_burst_launcher":{"n":"Взрывная Пусковая Установка","t":"**При Критическом Попадании**: цель становится Ослабленной до конца своего следующего хода.","f":"«Да, они могут умереть. Многих из них мы убили – сдули разрывными гранатометами и пушками. Я не думаю, что они имели значение. Не то что насекомые; не так… от насекомых еще есть толк, например, их можно воспринимать как пищу или как необходимые компоненты экосистемы. Их смерть замедлила нас, но не приказывала им замедлять нас. Даже когда мы проникли в последнюю камеру и увидели его, я не думаю, что он понял, что мы там были\"."},"mw_rail_rifle":{"n":"Рельсовая Винтовка","t":"","f":"Рельсовые винтовки — популярное оружие для использования на всех театрах военных действий, но они — единственный выбор для пилотов, работающих в атмосфере, состоящей из горючих газов. Они используют линию каскадных электромагнитов для разгона небольших снарядов до огромных скоростей, стреляя без необходимости возгорания.\nКак и другое рельсовое оружие, рельсовые винтовки тихие по сравнению со своими традиционными аналогами, хотя из-за больших требований к мощности сложно скрыть их энергетические сигнатуры."},"mw_shock_knife":{"n":"Шоковый Нож","t":"","f":"Шоковые ножи — это короткие лезвия с электроприводом, предназначенные для интеграции с Шоковыми Венцами, популярной постфабричной модификацией. Ножи изготавливаются на заказ в ремесленном анклаве Терашима компании СШК, каждый из них имеет уникальный хэш-штамп своего дизайнера. Часть линейки ЛЮКС-Икона от СШК — доступной для гражданских лиц линейки БЕЛЛА ЧАО — каждый печатный код ударного ножа допускает только однократное использование. В случае утери, пилоты должны принести извинения и подать письменное заявление с объяснением обстоятельств потери, чтобы получить другой код."},"mw_sharanga_missiles":{"n":"Ракеты Шарнга","t":"Это оружие может атаковать две цели одновременно.","f":"«Это была дуэль. Вот для чего они были созданы: для дуэли и сотрясать столпы вселенной в этой битве». — «Заметки для юного Иоанна», Служение Главного Учителя"},"mw_gandiva_missiles":{"n":"Ракеты Гандива","t":"","f":"Ракеты Гандива являются надежной опорой линейки БЕЛЛА ЧАО от Смит-Шимано. Как и более тяжелая Пинака, Гандива оснащена реактивными системами репозиционирования в полете помощью реактивного двигателя, улучшающими навигацию по цели в быстро меняющихся условиях поля боя. Платформой доставки Гандива управляет искусственный интеллект комп/кон беспилотника, позволяющий ему учиться на основе опыта каждого запуска."},"mw_pinaka_missiles":{"n":"Ракеты Пинака","t":"Атаки этим оружием создают до двух **[Взрыв]1** областей, которые не могут пересекаться.\nВы также можете отсрочить воздействие атак, сделанных этим оружием. Выберите целевую область (области), которая станет видимой для всех персонажей: ракеты приземляются в конце следующего раунда, после того как все персонажи совершили действия, и наносят **3d6 [взр]** вместо **2d6**, но вы становитесь **Замедленным** до конца вашего следующего хода.","f":"Ракеты Пинака — это массивные двухступенчатые ракеты, обычно устанавливаемые вдоль позвоночника меха или перевозимые в разобранном виде для запуска с наплечной установки. Первоначально Пинака была адаптирована к ракетам \"корабль-корабль\", поэтому ее вторая ступень использует реактивное управление для ориентации в середине полета."},"mw_fold_knife":{"n":"Складной Нож","t":"**При Критическом Попадании**: вы можете **телепортироваться на 2 пространства** в любом направлении после разрешения атаки.","f":">//[Я здесь один?] >//[[Нет. Есть только твое отсутствие. Здесь очень оживленно, но ты не можешь этого видеть]] — ДХИЙЕД фрагмент записи 1.3"},"mw_vijaya_rockets":{"n":"Ракеты Виджая","t":"","f":"Ракеты Виджая, предназначенные для использования в качестве средства увеличения силы в бою на ближних дистанциях, представляют собой миниатюрные ракеты, запускаемые из пусковой установки с барабанным питанием. При детонации кумулятивные заряды ракеты направляют взрывную волну вперед, в сторону от пользователя."},"mw_variable_sword":{"n":"Изменчивый Меч","t":"**При Критическом попадании**: Нанесите **+1d6 дополнительного урона**.","f":"Изменчивый меч является отличительной чертой Смит-Шимано: длинная острая как бритва молекулярная проволока, прикрепленная к рукоятке и зафиксированная на месте магнитным полем. Изменчивые мечи невидимы невооруженным глазом до тех пор, пока не разрежут свою цель. Разработанные на заре межзвездных путешествий, изменчивые мечи должны были обеспечить точный сбор образцов и одновременно снизить общую нагрузку на ядро меха."},"mw_oracle_lmg_i":{"n":"Оракул ЛП-I","t":"","f":"Лёгкий пулемет непрямого действия Оракул (обозначенный как О/РП-I) включает в себя разумную, крупногабаритную статичную четырехствольную систему Ливень в одном цилиндре, обычно устанавливаемом на задней панели шасси. В паре с огневой системой, \"Оракул\" способен вести непрекращающийся кинетический огонь по целям без учета дефилады."},"mw_nanobot_whip":{"n":"Нанобот-Хлыст","t":"**При Критическом Попадании**: притяните цель к свободному пространству рядом с вами или как можно ближе.","f":"Используя кодирование роя и директивы легиона, коллективисты ХОРУС создали основу для организации роя нанитов в оружие, похожее на хлыст. Нанобот-хлыст может убираться в базовый блистер для хранения, отсоединяться в ближнем бою для сдерживания ближайших врагов и возвращаться в базовый блок при вызове."},"mw_swarm_hive_nanites":{"n":"Рой/Улей Нанитов","t":"","f":"РОЙ/УЛЕЙ Нанитов являются одним из самых коварных видов оружия, производимых ХОРУС: запускаемые в манипулах — одиночных \"роевых\" единицах, содержащих достаточное количество нанитов, чтобы заполнить квадратный метр — РОЙ/УЛЕЙ Нанитов сочетают свойства системного вторжения УСКОРЕНИЕ/УЛЕЙ кода с агрессивным потреблением ПОГЛОЩЕНИЕ/УЛЕЙ манипул. Запускаемые из установленных блистеров, манипулы РОЙ/УЛЕЙ Нанитов падают на свои цели в виде огромных облаков зубов, проникая в чувствительные отсеки и модули, прежде чем поглотить любой органический и неорганический материал, которого они коснутся."},"mw_autopod":{"n":"Автопод","t":"Вместо того, чтобы использовать какой-либо спусковой механизм, это оружие автоматически сканирует целевые шлюзы, стреляя вращающимися острыми как бритва дисками при успешной идентификации. Получите реакцию **Автономный Штурм**, которая является единственным способом, которым вы можете атаковать с помощью Автопода:\n⟦A:r⟧Автономный Штурм⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер**: Другой персонаж атакует цель в радиусе [Дальн]15 от вас и использует **Захват**.\n**Эффект**: Вы можете автоматически поразить цель другого персонажа с помощью Автопода.⟦Z⟧","f":"Автопод — небольшое противопехотное оружие, очевидно, разработанное коммуношифровщиками ХОРУС для продолжения наступательных действий в случае смерти оператора. Теоретически каждая единица управляется отростком проторазумного ИНСТИНКТа. Со времен ДХИЙЕДа не было обнаружено новых моделей, и все существующие версии Автопда следует считать чрезвычайно опасными, поскольку код ИНСТИНКТ, приводящий в действие их бортовые проторазумы, вероятно, еще больше исказился с момента их создания."},"mw_vorpal_gun":{"n":"Вострая Пушка","t":"Получите реакцию **Свист Клинка**, которая является единственным способом атаки с помощью этого оружия.\n⟦A:r⟧Свист Клинка⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер**: враждебный персонаж в пределах **Дальности Вострой Пушки** и прямой видимости наносит урон союзному персонажу.\n**Эффект**: Вы можете атаковать враждебного персонажа используя **Вострую Пушку**.⟦Z⟧","f":"НЕ СМОТРИТЕ ПРЯМО В ОТВЕРСТИЕ."},"mw_ghoul_nexus":{"n":"Звено-Гуль","t":"**При Атаке**: Выберите тип урона этого оружия.","f":"Звенья Гули управляют одними из самых больших жизнеспособных дронов в современном бою. Эти дроны немного меньше среднего человека — металлические цилиндры, ощетинившиеся узлами подвески, подходящими для большинства противомехового оружия пехотного уровня. Дроны Гули, приводимые в движение реактивными системами вертикального взлета и посадки, представляют собой устрашающие автономные боевые единицы, которые трудно отследить и уничтожить."},"mw_ghast_nexus":{"n":"Звено-Вурдалак","t":"Это оружие может быть использовано для атаки как обычное, или размещено в качестве Дрона со следующим профилем:\n**Звено-Вурдалак (Размер 1/2, ПЗ 5, Броня 2, Уклонение 10, Э-Защита 10, Метки: Дрон)**\nЭто Звено-Вурдалак может быть размещено в свободном пространстве в пределах **Сенсоров** и прямой видимости в качестве свободного действия, где оно становится неподвижным, парящим **Дроном**. После размещения вы можете использовать его для **Перестрелок** и **Заградительного Огня**, как будто это все еще оружие, но с прямой видимостью и **Дальностью**, отслеживаемой от его местоположения.\nВы можете отозвать или переместить Звено-Вурдалак в качестве **быстрого действия**. Пока он не отозван или не уничтожен, он остается размещенным до конца сцены. В случае уничтожения он соответствует правилам для уничтоженных **Дронов** и не может быть использован до тех пор, пока не будет отремонтирован.","f":"Вурдалак — это усиленная броней и вооружением версия меньшего дрона Гуля. Дроны Вурдалаки могут похвастаться усовершенствованной системой полета, способной владеть оружием уровня мехов с оптимальными параметрами, и могут работать независимо от основного шасси или в качестве интегрированного оружия. В Гидрах дроны Вурдалаки обычно выступают в качестве грудных сегментов, обеспечивая броню для основных систем: силовой установки, кабины, НЧЛ-шкатулок и т.д."},"mw_annihilation_nexus":{"n":"Аннигиляционное Звено","t":"**При Атаке**: Вы можете совершить вторую атаку этим оружием в начале своего следующего хода в качестве протокола. Эта вторичная атака не может нанести **дополнительный урон** и не запускает дополнительные вторичные атаки.\nВы можете сосредоточить атаку этого оружия либо на себе, либо на любом из ваших **Дронов** в пределах **Сенсоров**.","f":"«Буря лезвий смерти» — наниты, организованные в манипулы, высвобождаются из бортовых звеньев шасси или одноразовых пусковых трубок в виде колец из нитей, настолько острых, что они разрезают свои цели на молекулярном уровне. Визуальный эффект запуска манипулы часто сравнивают с мишурой, летящей сквозь атмосферу."},"mw_catalyst_pistol":{"n":"Каталитический Пистолет","t":"","f":"“Гори, еретик, перед огнем Ока РА!”"},"mw_arc_projector":{"n":"Дуговой Излучатель","t":"**При Попадании**: Вы также можете сделать вторичную атаку против другого персонажа в пределах [Дальн] **3** от первой цели. Вы можете продолжать совершать вторичные атаки при попадании, пока в пределах досягаемости есть новые допустимые цели; однако каждая атака генерирует 1 [нагрев], а вторичные атаки не могут нанести **дополнительный урон**. Персонажи не могут быть поражены более одного раза одним и тем же выстрелом из этого оружия.","f":"\"Да будет огонь над тобой, АПОП! Плоть твоя отсечена от костей твоих; Владыка Дуата никогда не даст воскреснуть тени твоей!\""},"mw_smartgun":{"n":"Умное Оружие","t":"","f":"\"Умное оружие\" — это широкий термин, который описывает любое оружие, способное взаимодействовать с бортовыми системами для повышения боевой эффективности. Умное оружие — это оружие, которое поставляется с предустановленным программным обеспечением и необходимым оборудованием для взаимодействия с системами наведения и размещения НЧЛ. Популярное дополнение ко многим мехам ХОРУС, умное оружие является надежной кинетической системой доставки."},"mw_mimic_gun":{"n":"Оружие-Мимик","t":"Это ужасающее оружие не имеет базовой формы; оно постоянно принимает различные формы, подражая оружию других бойцов. Оно считается одновременно всеми видами дальнобойного оружия (например, **ОБД**, **Винтовка** и т.д.), но не может использовать **Моды** или получать преимущества от бонусов ядра, хотя по-прежнему получает преимущества от талантов в обычном режиме.\nВ начале боя бросьте **3d20** и запишите результаты по порядку: **X**, **Y** и **Z**. **X** — это его начальная базовая **Дальность** стрельбы (до модификаций от талантов). В начале каждого вашего хода после первого, оружие-мимик переходит к следующему результату, принимая его за базовую **Дальность**. После **Z** она возвращается к **X**.\nОружие-мимик наносит [кин], равный **1 + половина** ее текущей базовой **Дальности**.\nВы можете вызвать оружие-мимик **полным действием**, бросив новый набор **3d20**.","f":"Это не оружие."},"mw_autogun":{"n":"Автопушка","t":"Это оружие не может совершать обычные атаки. Вместо этого вы можете атаковать им в качестве свободного действия в конце вашего хода. Это оружие не приносит пользы и не активирует ваши таланты.","f":"Как следует из названия, автопушки — это автоматическое оружие. Подобно системам точечной обороны, автопушки предназначены для ведения эффективного огня по бронированным целям. Как правило, автопушка устанавливается на стабилизированную второстепенную руку, и ей можно доверить отслеживание и уничтожение определенных вражеских единиц, пока пилот сосредоточен на более специализированном оружии или процессах. Дешевые, с гибкой кодовой базой, автопушки широко распространены среди активных, вооруженных ячеек ХОРУС."},"mw_siege_cannon":{"n":"Осадная Пушка","t":"**При Атаке**: выберите режим **осады** или **прямой наводки**.","f":"Осадная пушка — типичная артиллерийская установка Оружейной палаты: пушка-гаубица, питаемая от автоматической системы заряжания. Осадные пушки обычно устанавливаются на мехи дальнего радиуса действия, используемые в качестве артиллерии или поддержки отрядов, осадные орудия способны вести огонь как с закрытых огневых позиций, так и прямой наводкой, в зависимости от ситуации, с различными боеприпасами."},"mw_krakatoa_thermobaric_flamethrower":{"n":"Термобарический Огнемет Кракатау","t":"","f":"В условиях густых джунглей Герцинии, тактикой роя эгрегорианцев и неэффективной работой пулевых боеприпасов потребность в оружии широкого действия была очевидной. ДМС быстро разработала Кракатау — термобарический огнемет — и распространила его среди филиалов. Благодаря своей стабильности, надежности и останавливающей силе Кракатау был быстро принят на вооружение Десантных экспедиционных сил Союза, получив широкое применение в глубине джунглей Герцинии.\nПозже переработанный и принятый Оружейной палатой после разрешения Герцинского кризиса, Кракатау стал популярным инструментом для создания противопожарных барьеров в зоне отрицания."},"mw_plasma_thrower":{"n":"Плазмомёт","t":"При Атаке: Раскалённое добела пламя продолжает гореть в 3 свободных пространствах по вашему выбору в пределах атаки и длится до конца сцены. Когда персонажи начинают свой ход в одном из этих пространств или входят в него впервые за раунд, они получают 1d6 [энерг].","f":"Плазмомет появился слишком поздно во время Герцинского кризиса, чтобы найти широкое применение в полевых условиях. Скудные данные, собранные эскадрильями, которые использовали его, позволяют предположить, что плазмометы оказали огромное влияние на исход нескольких крупных сражений, которые произошли во время самой кровопролитной фазы Кризиса."},"mw_stub_cannon":{"n":"Пушка-Заглушка","t":"","f":"Пушка-заглушка представляет собой сверхкомпактную вращающуюся пушку ближнего радиуса действия, но пригодную для интеграции в узлы подвески и манипуляторы."},"mw_gravity_gun":{"n":"Гравитационное Оружие","t":"**При Атаке**: Персонажи в пораженной области должны преуспеть в спасброске Корпуса или получить **1d6 [энерг]** и быть притянутыми как можно ближе к центру взрыва. Это оружие нельзя модифицировать или использовать бонусы ядра.","f":"“Сложные отношения гравитации и времени, мгновенно разрушенные машиной, которая может дергать волны, как перебирающий струны гитары музыкант.\nМы превратили в оружие силу, которая держит в своих объятиях все сущее. Что может пойти не так?\""},"mw_displacer":{"n":"Вытеснитель","t":"","f":"Вытеснитель — это результат постоянных испытаний на воздействие мерцающего пространства и усовершенствования стандартных методов межзвездных путешествий. С точки зрения внешнего вида Вытеснитель можно принять за обычную энергетическую винтовку, но для него требуется массивный вторичный реактор, установленный на спине: при выстреле Вытеснитель идентифицирует пузырь локального пространства (размер и местоположение определяются пользователем в индивидуальном порядке) и прикрепляет его к мерцающему пространству. Назначение пузыря неизвестно, но эффект поразителен: все внутри него просто перестает существовать в этом измерении, переносясь куда-то в пустоту мерцающего пространства. Вытеснитель не издает никаких звуков при выстреле, но внезапный и необходимый выброс энергии из его источника питания просто огромен; точно так же тепловая волна от его обратного взрыва смертельна для любого незащищенного персонала, подвергшегося его воздействию."},"mw_shatterhead_colony_missiles":{"n":"Колониальные Ракеты Штаттерхед","t":"На окончательный бросок атаки для этого оружия никогда не может повлиять[СЛОЖН].","f":"Колониальные Ракеты “Шаттерхед”, разработанные после дорогостоящих абордажных боев в городах и на флоте во время Войны интересов, теперь являются стандартной частью арсенала групп перехвата Оружейной палаты. Когда они достигают оптимального расстояния, \"Шаттерхеды\" разрываются в струе топлива с высоким содержанием катализатора, обнажая скопление мелких термобарических гранул, которые разлетаются и воспламеняются, удушая пламенем пораженную область. Этот эффект перегружает энергетическую защиту и наполняет укрытия, хотя лишь небольшой процент снарядов достигает цели."},"mw_sol_pattern_laser_rifle":{"n":"Лазерная Винтовка СОЛ-Паттерна","t":"","f":"Лазерные винтовки содержат ряд отверстий и линз, которые усиливают и фокусируют свет в узкие лучи, иногда видимые, которые нагревают зону поражения достаточно долго, чтобы превратить ее в плазму. Лазерная винтовка СОЛ- Паттерна постоянно выдает 3,5 петаватта в импульсном режиме, но может также проецировать постоянный луч на более низких уровнях мощности. СОЛ полностью автономен, но его можно встроить в ядро реактора меха для экстренной перезарядки.\nХотя некоторые лазерные винтовки используются в качестве устройств связи и передачи данных, SOL подходит исключительно для боевого применения."},"mw_andromeda_pattern_heavy_laser_rifle":{"n":"Тяжелая Лазерная Винтовка АНДРОМЕДА-Паттерна","t":"","f":"Тяжелая Лазерная Винтовка АНДРОМЕДА-Паттерна от Оружейной палаты Харрисона увеличивает СОЛ вдвое, добавляя второй проектор, который может стрелять независимо, синхронно или по чередующимся схемам и длинам волн с основным проектором. Эффект подавляет большинство щитов, но потребляемая мощность делает это оружие непрактичным на платформах без необходимого снижения и рассеивания тепла, чтобы справиться с невероятными затратами."},"mw_tachyon_lance":{"n":"Тахионное Копье","t":"**При Атаке**: если вы находитесь в **Опасной Зоне**, создайте обратный взрыв горящей плазмы [Конус] **3** в направлении, противоположном направлению атаки. Персонажи, находящиеся в зоне поражения, должны успешно выполнить спасбросок **Инженерии** или получить **4 [горение]** и **2 [нагрев]**.До начала вашего следующего хода пораженная область обеспечивает **мягкое укрытие**.","f":"Тахионные копья — это результат совместных экспериментов ИПС-Н и Оружейной палаты Харрисона по сверхсветовым путешествиям. Устаревшие из-за последующих разработок в области мерцающего пространства (и сложности обеспечения физического выживания пассажиров), тахионные ускорители Оружейной палаты были законсервированы до тех пор, пока инженеры Аналитического центра не осознали их потенциальное применение в качестве оружия. Тахионные копья выбрасывают тахионные частицы — субатомные локализованные объекты — со сверхсветовой скоростью к своим целям. Эти частицы невозможно воспринять оптически, а поскольку они движутся быстрее света, их невозможно увидеть или уклониться от них. Хотя частицы крошечные, они движутся с колоссальной скоростью и энергией. Урон, который тахионное копье наносит своей цели — в случае попадания — не имеет себе равных"},"mw_annihilator":{"n":"Аннигилятор","t":"**При Попадании**: совершите вторичную атаку против всех персонажей в пределах [Разрыв] **1** от цели. Эти атаки не наносят **дополнительного урона**, не вызывают у Аннигилятора [нагрев] или вторичных атак.","f":"Оружейная палата Харрисона известна несколько нетрадиционными методами разработки: тактические решения теоретизируются и разрабатываются в полевых условиях так же часто, как и в лаборатории, причем первые часто превосходят последние. Название \"Аннигилятор\" происходит от сленга пилотов, обозначавшего самодельное оружие, впервые сымпровизированное во время Восстания Брэдбери, когда отчаявшиеся пилоты сопротивления нашли способ преобразовать невероятное отработанное тепло своих реакторов в направленный взрыв."},"mw_torch":{"n":"Резак","t":"","f":"Резак — это мощное оружие: тяжелый плазменный нож с серповидным лезвием, питающийся прямо от реактора шасси. Резаки обычно проектируются в виде топоров, хотя их лезвия могут быть изменены на различные другие формы. Распространенное оружие в театре боевых действий на ближних дистанциях, резак в последнее время стал символом статуса среди офицеров, многие носят его вместе с меньшим вспомогательным оружием."},"mw_fuel_rod_gun":{"n":"Стержневая Пушка","t":"**При Атаке:** Сбрасывает **4**[нагрев]."},"mw_lancaster_integrated":{"n":"Дрон-Защелка","t":"Это оружие не может совершать обычные атаки. Вместо этого выберите союзного меха в пределах **Дальности** и прямой видимости и совершите дальнюю атаку против **Уклонения 8**. При попадании либо вы, либо ваша цель может потратить **1 Ремонт** на восстановление половины ПЗ цели."},"mw_raleigh_integrated":{"n":"M35 Мьёльнир","t":"1/раунд, когда вы заряжаете любое оружие, из этого оружия можно выстрелить в качестве **свободного действия**."},"mw_barbarossa_integrated":{"n":"Рельса Апокалипсиса","t":"","f":"LGC-04 \"Рельса Апокалипсиса\" — это экспоненциальная гравитационная катапульта, созданная на базе исследовательского и опытноконструкторского кампуса Оружейной палаты, и предназначенная для испытаний в полевых условиях в рамках продолжающегося проекта по испытанию Магнитного оружия Пленарного пляжа.\nВ отличие от нынешнего логарифмического короткоствольного или длинноствольного оружия класса корабль-корабль (кинетического или энергетического/частного), эта новая платформа использует текущие гравитационные исследования Оружейной палаты, чтобы экспоненциально заряжать и распределять кинетическую полезную нагрузку по дальности. Это увеличение потенциальной энергетической нагрузки и уменьшение общего времени заряда происходит за счет стабильности: если логарифмическая катушечная пушка стабильна и устойчива к ударам, то экспоненциальная гравитационная катапульта склонна к дестабилизации. На данный момент встроенные средства защиты срабатывают в случае внезапной травматической дестабилизации, чтобы предотвратить детонацию системы, сбрасывая все процессы зарядки, происходящие в момент удара.\nСистема LGC-04 \"Рельса Апокалипсиса\" значительно уменьшена по сравнению с ее предполагаемой оперативной ролью, то есть заменой крупных кораблей с вращающимися пушками, чтобы обеспечить накопление оперативных данных для использования в улучшении системы перед принятием на вооружение"},"mw_sherman_integrated":{"n":"ЗФ4 Твердоеядро","t":"Прок этого оружия определяется количеством **Зарядов**, которые оно несет. В начале он несет **1 Заряд**, нанося **1d6 [энерг]** с [Линия] **4**. Каждый раз, когда вы **Стабилизируетесь**, вы получаете дополнительный **1 Заряд**, максимум до **4**. ЗФ4 получает дополнительные **+** [Линия] **4** и **+1d6 [энерг]** за каждый заряд, и восстанавливает **1 Заряд** после каждой атаки. Заряды сохраняются между сценами, но утрачиваются во время Полного Ремонта."},"mw_kraul_rifle":{"n":"Винтовка «Краул»","t":"**При попадании**: цель пронзена гарпуноподобным снарядом. В любой момент после того, как цель совершит любое действие или перемещение в свой следующий ход, вы можете **реакцией** подтянуть трос и совершить **Ускорение** к цели кратчайшим путём. Затем она проходит спасбросок **Корпуса** или **Сбита с ног**; при успехе или провале эффект заканчивается. Если цель телепортируется, трос рвётся."},"mw_terashima_blade":{"n":"Клинок Терасимы","t":"Вы можете начинать любой бой в любой из стоек этого оружия, а принимать стойку или менять стойки — **протоколом**. Приняв стойку, вы остаётесь в ней, пока не примете новую, пока оружие не уничтожено или пока вы не станете **Ошеломлены** или **Заклинены**. Выйти из стойки можно **свободным действием**.\n**Без стойки**: 1d6 [кин], [Угроза]1.\n**Стойка Тролля**: 1d6+3 [кин], **Неточное**, **ББ**.\n**Стойка Бури**: **1/раунд**, после попадания этим оружием — **реакцией** нанесите **2** [кин] всем остальным персонажам рядом с вами и с целью.\n**Стойка Лорда**: вы не можете совершать дальние и технические атаки, но каждая промахнувшаяся по вам дальняя атака рикошетит от клинка и наносит **2** урона (того же типа) выбранному вами персонажу в пределах [Дальн]3 и прямой видимости. Промахнувшийся по вам в ближнем бою проходит спасбросок **Корпуса** или **Сбит с ног**.\n**Стойка Ветра**: [Угроза]2, **Надёжное 2**; после атаки этим оружием, попала она или нет, вы можете переместиться на **2 пространства**, игнорируя вовлечение и реакции."},"mw_hammer_u_rpl":{"n":"Ракетомёт Ближнего Боя «Хаммер U-RPL»","t":""},"mw_hhs_155_cannibal":{"n":"HHS-155 «Каннибал»","t":"Из этого тяжёлого дробовика можно выстрелить **дважды**, прежде чем потребуется перезарядка. Либо можно выстрелить из обоих стволов сразу: с **+1** [СЛОЖН], урон **3d6+4** [кин], **Толчок 4**, но перезарядка нужна как обычно.\nПри перезарядке можно нанести **5** [кин] соседнему персонажу отдачей выбрасываемых гильз."},"mw_fusion_rifle":{"n":"Термоядерная Винтовка","t":"Урон этого оружия равен расстоянию до цели (максимум **6** [энерг])."},"mw_slag_cannon":{"n":"Шлаковая Пушка","t":"Если цель стоит на земле или ровной поверхности, после разрешения атаки поставьте в свободном пространстве рядом с ней насыпь шлака **Размера 1** — объект с **Уклонением 5** и **10 ПЗ**."},"mw_unraveler":{"n":"Распускатель","t":"Если атака этим оружием не нанесла бы достаточно урона, чтобы уничтожить цель или заставить её получить хотя бы 1 структурный урон, она вместо этого наносит только урон **Надёжное 2** — даже при попадании."},"mw_warp_rifle":{"n":"Варп-Винтовка","t":"**При попадании**: цель проходит спасбросок **Инженерии** или **телепортируется** в выбранном вами направлении на число пространств, равное нанесённому этим оружием урону (включая бонусный урон и т. п., не больше 10). Она должна оказаться в свободном допустимом пространстве."},"mw_xiaoli_combat_sheathe":{"n":"Боевые Ножны Охотника на Тигров","t":"Это оружие может атаковать **две цели** одновременно и может использоваться даже под **Заклиниванием**."},"mw_d_d_288":{"n":"D/D 288","t":"В отличие от другого Сверхтяжёлого оружия, в базовом профиле им можно атаковать **Перестрелкой**.\n⟦A:s⟧Зарядить D/D 288⟦T⟧Быстрое Действие⟦E⟧Пока оружие заряжено, вы получаете **мягкое укрытие**, но **Замедлены**, получаете **2** [нагрев] в начале своего хода и больше не можете использовать D/D 288 в **Перестрелке**. В начале любого вашего хода, пока оно заряжено, оно использует профиль «Заряженный».⟦Z⟧\n**Заряженный**: [Угроза]3, **4d6+8** [взр], **Надёжное 8**, **Толчок 8**. Заряженное оружие наносит **30** [кин] **ББ** при попадании по объектам и кускам местности; уничтоженные так объекты и местность взрываются: **1d6** [кин] всем соседним персонажам, кроме вас, и **Толчок 1**. Заряд пропадает, когда вы попадаете по цели, рассеиваете его **свободным действием** или становитесь **Ошеломлены** или **Выключены**."},"mw_caliban_integrated":{"n":"Дробовик HHS-075 «Свежеватель»","t":"После любой атаки этим оружием можно ударить прикладом соседнего персонажа: **1** [кин] и **Толчок 1**.\nС **Автодросселем** (система ядра): **Основное ОБД, Точное, Толчок 5**, [Конус]3 [Угроза]3, **1d6+2** [кин]."},"mw_ferrofluid_lance":{"n":"Феррожидкое Копьё","t":"**При попадании** (**1/раунд**): можно заставить цель пройти спасбросок **Корпуса**. При провале вы и цель **Обездвижены** и не можете быть перемещены никак; пока эффект длится, цель всегда считает вас в пределах досягаемости ближних атак. В любой последующий ход вы можете закончить эффект **протоколом**, отбросив цель на **4 пространства** в любом направлении, а цель может закончить его, успешно попав по вам дальней или ближней атакой. Снять это состояние иначе нельзя."},"mw_retort_loop":{"n":"Петля Отдачи","t":"Каждый раз, получая урон из враждебного источника, можно сохранить в этом оружии **заряд** (максимум **3**). За каждый заряд выстрел получает **+1d6** [кин], **Надёжное 2** и **Толчок 1**. После выстрела (попадание или промах) все заряды сбрасываются; они также сбрасываются, если вы получаете структурный урон или урон Нагрузки. Профили 0–3 зарядов — ниже."},"mw_bolt_nexus":{"n":"Звено Молний","t":"Попав по персонажу, оружие получает профиль **«Цель захвачена»** против этого персонажа — пока вы не атакуете этим оружием другого персонажа."},"mw_emperor_integrated":{"n":"Марафонский Дуговой Лук","t":"Союзные персонажи в зоне не атакуются: их **Усиление Щита** перезаряжается — увеличивается на **+4**, но всё Усиление Щита пропадает в конце их следующего хода. Если Усиления Щита нет, они получают **Усиление Щита 2**."},"mw_blackspot_targeting_laser":{"n":"Целеуказатель «Чёрная Метка»","t":"**При попадании**: оружие и системы с метками **Дрон**, **Искатель** и **Звено** получают **+1** [ТОЧН] на атаки по цели до конца её следующего хода.\n**При крите**: цель также получает **Захват**."},"mw_tokugawa_alt_enkidu_integrated":{"n":"Плазменные Когти","t":"Длинные хлыстообразные плазменные плети, которые Энкиду выпускает и втягивает. Используются только в **Опасной Зоне**."},"mw_exo_plasma_maul":{"n":"Плазменный Молот","t":"При промахе это оружие не нужно перезаряжать."},"mw_exo_sting_heavy_anti_armor_rifle":{"n":"Тяжёлая Противоброневая Винтовка «Жало»","t":"**При атаке**: если вы расходуете **Захват**, атака игнорирует укрытие.\n**При попадании**: создайте путь [Линия]5 от цели (не включая её), продолжающий направление атаки. Персонажи на этом пути получают **5** [кин]."},"mw_exo_steelpunch_heavy_needlebeam":{"n":"Тяжёлый Игольчатый Луч «Сталебой»","t":"Наносит **+1d6** бонусного урона целям, у которых хотя бы 1 Броня."},"mw_exo_brood_siblings_molt":{"n":"Линька Сородича","t":"**1/раунд** это оружие наносит **+1d6** бонусного урона **Расщеплённым** или **Ошеломлённым** персонажам."},"mw_brutus_wrecker":{"n":"Шар-Крушитель Брута","t":"**При крите**: цель **Сбита с ног**.\nФирменное оружие бывшего бессменного чемпиона Кратерной Ямы — массивный вольфрамовый шар на усиленной цепи. Примитивно, зато жестоко."},"mw_brutus_shield":{"n":"Щит Брута","t":"⟦A:s⟧Поднять Щит⟦T⟧Протокол⟦E⟧Вы поднимаете щит и получаете **Усиление Щита** в размере **4 + Стойкость** до начала вашего следующего хода, после чего теряете всё Усиление Щита. Пока у вас это Усиление Щита, вы **Замедлены**.\nНельзя использовать этот протокол два хода подряд.⟦Z⟧Продвинутый щит-плита с удивительно сложной технологией Оружейной Палаты Харрисона: проецирует мощное локальное силовое поле."},"mw_blast_pick":{"n":"Взрывная Кирка","t":"Перед атакой можно объявить, что вы **разряжаете** это оружие. Тогда атака наносит **2d6+6** [взр] и получает **Отбрасывание 2**. Иначе оружие не разряжается.\nСтарая шахтёрская кирка ИПС-Н, много лет висевшая украшением в ресторане «Гарфилдс» в Порт-Конрое."},"mw_shock_baton":{"n":"Шоковая Дубинка","t":"**При крите**: цель проходит спасбросок **Систем**, иначе **Заклинена** до конца своего следующего хода; при успехе — **Ослаблена** на тот же срок. Каждого персонажа так можно затронуть **1/сцена**.\nОружие «пониженной летальности» для полиции, чтобы выводить мехи из строя и брать пилотов живыми."},"mw_reaper_assault_cannon":{"n":"Штурмовая Пушка «Жнец»","t":"Можно стрелять из этого оружия как из **Сверхтяжёлого**. Тогда оно получает **Надёжное 5** и наносит **4d3+2** [кин] вместо обычного урона.\nНовейшая автопушка ИПС-Н — нечто среднее между обычной штурмовой пушкой и «Левиафаном»; пока на стадии испытаний."},"mw_tempest_charged_blade":{"n":"Заряженный Клинок «Буря»","t":"Новинка линейки силового и энергетического оружия ДМС Type-II — заряженный клинок ошеломляющих размеров из сверхтяжёлой серии «Шторм»."},"mw_hurricane_cluster_projector":{"n":"Кассетный Проектор «Ураган»","t":"Огромная артиллерийская установка на шасси из серии «Шторм»: короткая для такого оружия дальность, но опустошительный град умных самокорректирующихся кассетных боеприпасов."},"mw_integrated_shock_claws":{"n":"Шоковые Когти","t":"**При атаке**: можно нанести **1d6** [энерг] **ББ** другому персонажу на свой выбор в пределах [Дальн]3 от цели.\nИспользуется только во время «**Во Весь Голос**». Нельзя атаковать этим оружием в тот же ход, что и другим Тяжёлым или Сверхтяжёлым оружием.\nРежимы: **Обычный** — Угроза 1, 3d6+6; **Союзник получил структурный урон** — Угроза 2; **Дважды / союзник уничтожен / у вас ≤2 Структуры** — Угроза 2 и **4d6+6** [энерг]."},"mw_legionnaire_battle_rifle":{"n":"Боевая Винтовка Легионера","t":"**При атаке**: можно потратить до **3 зарядов**. За каждый заряд — либо **Надёжное +2** для этой атаки, либо при попадании толкнуть цель на **1 пространство** в любом направлении.\nАтаковать этим оружием можно, не тратя зарядов и даже без них; уничтожить его (критическим уроном и т. п.) можно, даже если зарядов не осталось.\nОсновная тяжёлая винтовка легионеров Оружейной Палаты Харрисона — опора и регулярных, и вспомогательных войск на любом театре: дешёвая в печати, простая в обращении, под мощный патрон."},"mw_superthermal_blade":{"n":"Сверхтермический Клинок","t":"**При попадании**: **1/раунд**, если вы в **Опасной Зоне**, можно потратить заряд, чтобы нанести **+3** [нагрев]; если вы не в Опасной Зоне, получите **3** [нагрев], чтобы потратить заряд с тем же эффектом.\nАтаковать этим оружием можно, не тратя зарядов и даже без них; уничтожить его можно, даже если зарядов не осталось.\nТермопроводящие клинки Палаты — статусный символ у легионеров: на номинальной мощности это просто добротный клинок, а с питанием от реактора его кромка мгновенно раскаляется."},"mw_legion_nexus":{"n":"Звено Легиона","t":"**1/раунд**, атаковав этим оружием, можно **свободным действием** потратить заряд и отправить отряд субальтернов действовать самостоятельно. Это **Дрон**: **Легионный Дрон** (Размер ½, ПЗ 5, Броня 1, Уклонение 10, Э-Защита 10, метка Дрон), размещается в свободном пространстве рядом с вами.\n**Протоколом** вы можете переместить каждого своего Легионного Дрона на **3 пространства** и отдать каждому одну команду:\n• **Протокол Подавления**: выберите враждебного персонажа в пределах [Дальн]5 от дрона. До конца его следующего хода ваши атаки Звеном Легиона по нему получают **+1** [ТОЧН] (не складывается). Он также проходит спасбросок **Маневренности**, иначе **Ослаблен** до конца своего следующего хода.\n• **Штурмовая Позиция**: враждебный персонаж рядом с дроном проходит спасбросок **Корпуса**, иначе отброшен на **1 пространство** и **Сбит с ног**. До начала вашего следующего хода дрон считается **Размера 1**, и союзники рядом с ним могут использовать его как твёрдое укрытие.\nЗа каждого вашего размещённого Легионного Дрона Звено Легиона наносит **+2** урона при попадании (максимум **+6**). Легионных дронов нельзя отозвать; они исчезают в конце сцены.\nАтаковать этим оружием можно, не тратя зарядов; уничтожить его можно, даже если зарядов не осталось.\nПРЕТОРИАН — новейший боевой субальтерн Палаты для штурма и удержания позиций."},"mw_shrapnel_cannon":{"n":"Шрапнельная Пушка","t":"**При попадании**: от цели расходится зона [Конус]5 в направлении от неё на ваш выбор (прямая видимость считается от цели). Все персонажи в зоне проходят спасбросок **Маневренности**, иначе получают **1d6** [кин].\nДля коридоров кораблей: снаряды с металлополимерной оболочкой разлетаются осколками, которые рикошетят от стен и достают противника за углом и за укрытием."},"mw_electrohydraulic_claw":{"n":"Электрогидравлическая Клешня","t":"Это оружие наносит **10** [кин] **ББ** объектам, укрытиям и окружению. Кроме того, вы получаете **+1** [ТОЧН] на все небоевые проверки навыков меха, чтобы вскрыть или разжать тяжёлые объекты (запертые шлюзы, заклинившие кабины, двери хранилищ, грузовые контейнеры и т. п.); не складывается.\n**1/раунд**, попав этим оружием по персонажу, можно **быстрым действием** сомкнуть клешню и автоматически его **Схватить**. Он проходит спасбросок **Корпуса**, иначе **Расщеплен** до конца своего следующего хода.\nБоевая версия спасательного гидравлического резака-разжима ИПС-Н: режет даже армированную композитную броню."},"mw_fusion_torch":{"n":"Термоядерный Резак","t":"**При атаке**: оружие автоматически наносит **30** [энерг] **ББ** объектам, укрытиям и местности в зоне, оставляя на их месте облака расплавленных обломков до конца вашего следующего хода. Персонажи, кроме вас, начинающие ход в этих облаках или впервые за раунд входящие в них, получают **1d6** [энерг]. Пока вы хотя бы частично в облаке, у вас лёгкое укрытие.\nПромышленный луч FS-90 «Рокхаммер» для разделки корпусов кораблей и астероидов. Застывший шлак на рамах операторы зовут «боевой раскраской»."},"mw_empakaai_alt_blackbeard_integrated":{"n":"Колоссальный Термо-Коготь","t":"Эмпакаи может использовать это оружие, даже будучи **Заклиненным**.\nПеред броском можно заставить цель и любых персонажей на ваш выбор рядом с ней пройти спасбросок **Корпуса**, иначе они притягиваются вплотную к вам и автоматически **Схвачены**.\nОгромная «Рука Ику» с собственным комп/коном и холодным термоядерным реактором — половина веса всей рамы."},"mw_xc_br_battle_rifle":{"n":"Боевая Винтовка XC-BR","t":"Атакуя персонажей в **Захвате**, это оружие считается оружием с [Дальн]**15**.\n**При крите**: цель получает **Захват**.\nДополнение к штатной штурмовой винтовке GMS MC-AR: безгильзовые электрохимические патроны крупного калибра пробивают броню, встроенная динамическая система наведения помогает на дальних дистанциях — но оружие всё ещё страдает перегревом."},"mw_xc_dpm_predator_nexus":{"n":"Звено «Хищник» XC-DPM","t":"Атаки этим оружием игнорируют **Невидимость**.\nНаследник программы MC-DHK «Охотник-Убийца»: умная платформа MD+ «Муза» узнаёт цели даже сквозь активные помехи, сбивающие с толку обычное умное оружие."}},"systems":{"ms_comp_con_class_assistant_unit":{"n":"Помощники Комп./Кон.","t":"Ваш мех оснащен базовым блоком комп/кон, что наделяет его меткой **ИИ**. Комп/кон может разговаривать с вами и обладает индивидуальностью, но, в отличие от НЧЛ, не способен мыслить самостоятельно. Он подчиняется только вам.\nВы можете передать управление своим мехом его комп/кон в качестве протокола, что позволит вашему меху действовать независимо в ваш ход со своим собственным набором действий. В отличие от других ИИ, мехи, управляемые комп/кон, не имеют самостоятельной инициативы и требуют прямого участия. Ваш мех будет следовать основному набору действий (защищать эту область, атаковать этого врага, защищать меня и т. д.) в меру своих возможностей или будет действовать, чтобы защитить себя, если его инструкции выполнены или он не получает дальнейших указаний. Вы можете отдавать новые команды в начале своего хода, если вы находитесь в пределах **[Дальн]50** и имеете средства для связи со своим мехом. Комп/кон не являются настоящими НЧЛ и поэтому не могут вступать в каскад.","f":"Помощник категории Компаньон/консьерж ДМС соответствует всем общегалактическим стандартам. Эти виртуальные помощники проходят даже самые жесткие критерии оценки на Туринг-Нулле и допущены к работе даже в отсутствие пилота."},"ms_custom_paint_job":{"n":"Индивидуальная Покраска","t":"Когда вы получаете структурный урон, бросьте 1d6. Если выпадет 6, вы возвращаетесь к **1 ПЗ** и игнорируете урон — удар просто \"поцарапал вашу краску\".\nЭту систему можно использовать только один раз перед каждым **Полным Ремонтом**, и она не является допустимой целью для разрушения системы."},"ms_expanded_compartment":{"n":"Расширенный Отсек","t":"В вашем мехе есть место для одного дополнительного **не-Мех** персонажа или объекта **Размера 1/2**, который может ехать в качестве пассажира в кабине. Находясь внутри меха, он не может подвергаться никаким внешним воздействиям или быть целью атак, как если бы он был пилотом. Вы можете передавать или забирать у них управление по протоколу (по тем же правилам, что и пилоты и ИИ), но если они забирают у вас управление, мехи становятся **Ослабленными** и **Замедленными**, в связи с отсутствием соответствующих лицензий и интеграции."},"ms_manipulators":{"n":"Манипуляторы","t":"У вашего меха есть дополнительный набор конечностей. Они слишком малы, чтобы принести пользу в бою, но позволяют меху взаимодействовать с объектами, которые иначе были бы слишком маленькими или хрупкими (например, сенсорные панели размером с пилота).","f":"Точное взаимодействие с искусственными и природными средами, легкими целями и опасными материалами является частью повседневной жизни мехов поддерживающего класса. Это стало возможным благодаря манипуляторам — добавленным многоразрядным \"рукам\" с тактильными сенсорами."},"ms_pattern_a_smoke_charges":{"n":"Паттерн-А Дымовые Заряды","t":"Потратьте заряд на один из следующих эффектов:\n**• Дымовая Граната** (Граната, [Дальн] 5, [Взрыв] 2): Все персонажи и объекты в зоне взрыва получают **мягкое укрытие** до конца вашего следующего хода, после чего дым рассеивается.\n**• Дымовая Мина** (Мина, [Разрыв] 3): Эта мина взрывается, когда любой союзный персонаж проходит над ней или рядом с ней. Все персонажи и объекты в зоне взрыва получают **мягкое укрытие** до конца следующего хода взорвавшегося персонажа, после чего дым рассеивается."},"ms_pattern_a_jericho_deployable_cover":{"n":"Паттерн-А Иерихон Укрытие","t":"Разместите две секции твердого укрытия **Размера 1** на свободных пространствах рядом с вами и друг с другом. Каждая секция представляет собой объект со значением **Уклонения 5** и **10 ПЗ**, который можно выбрать и уничтожить по отдельности. Секции укрытия можно снова подобрать в качестве полного действия.\nРемонт системы восстанавливает обе секции."},"ms_pattern_b_hex_charges":{"n":"Паттерн-Б ГЕКС-Заряды","t":"Потратьте заряд на один из следующих эффектов:\n**• Осколочная Граната** (Граната, [Дальн] 5, [Взрыв] 1): Все персонажи в зоне поражения должны пройти спасбросок на **Маневренность** или получить **1d6 [взр]**. В случае успеха они получают половину урона.\n**• Взрывная Мина** (Мина, [Разрыв] 1): Все персонажи в пределах зоны поражения должны пройти проверку на **Маневренность** или получить **2d6 [взр]**. В случае успеха они получают половину урона."},"ms_personalizations":{"n":"Персонализация","t":"Вы получаете **+2 ПЗ** и, по согласованию с ГМ, можете установить незначительную модификацию, которую вы сделали для своего меха.\nЭтот мод не имеет числового преимущества, кроме дополнительных **ПЗ**, но может дать другие полезные эффекты. Если ГМ согласится, что этот мод поможет при проверке навыков пилота или меха, вы получите +1 [ТОЧН] к этой проверке."},"ms_stable_structure":{"n":"Устойчивая Структура","t":"Вы получаете +1 [ТОЧН] к спасброскам, чтобы избежать **Сбивания** или **Толчка**."},"ms_turret_drones":{"n":"Турельные Дроны","t":"**Турельный дрон (Размер 1/2, 5 ПЗ, 10 Э-Защита, 10 Уклонение, Метки: Дрон)** Потратьте заряд, чтобы разместить турельный дрон, который прикрепляется к любому объекту или поверхности в пределах Сенсоров и прямой видимости. Получите реакцию Атака Турели, которую можно использовать один раз для каждого размещенного дрона. Турельные дроны не могут быть отозваны и заканчивают свое действие в конце сцены.\n⟦A:r⟧Атака Турели⟦T⟧Реакция, 1/раунд на турель⟦E⟧**Триггер:** Союзный персонаж в радиусе [Дальн] 10 от турельного дрона совершает успешную атаку.\n**Эффект**: Турельный дрон наносит 3 [кин] урона своей цели, пока он находится в прямой видимости от цели.⟦Z⟧","f":"Использование турельных дронов — довольно традиционная форма умножения сил, которая остается основой обороны во многих театрах военных действий."},"ms_type_3_projected_shield":{"n":"Проекционный щит Тип-3","t":"Назначьте персонажа в пределах прямой видимости: все дальние и ближние атаки, которые он совершает против вас или вы против него, получают +2 [СЛОЖН] до начала вашего следующего хода","f":"Проекционный щит ДМС Тип-3 улавливает и блокирует приближающиеся снаряды, создавая агрессивный суперпозиционный противоракетный барьер."},"ms_eva_module":{"n":"ВКД Модуль","t":"Ваш мех оснащен силовой установкой, пригодной для использования в условиях низкой или нулевой гравитации и под водой. В этих условиях вы можете **лететь** и не **Замедляться**."},"ms_rapid_burst_jump_jet_system":{"n":"Реактивная Система Быстрого Прыжка","t":"Вы можете **летать**, когда вы **Ускоряетесь**; однако вы должны закончить перемещение на земле или другой твердой поверхности, иначе немедленно начнете падать."},"ms_type_i_flight_system":{"n":"Система Полета Тип-I","t":"Вы можете летать при **Ускорении** или при обычном движении; тем не менее, вы получаете **Размер+1 [нагрев]** в конце любого своего хода, в котором вы летите таким образом."},"ms_synthetic_muscle_netting":{"n":"Синтетическая Мышечная Сетка","t":"Вы можете **Таранить** цели крупнее вас, а когда вы **Хватаете** или **Тараните** более крупные цели, вы считаетесь равным по **Размеру** самому крупному противнику. Когда вы **Хватаете** или **Тараните** противников того же **Размера**, что и вы, или меньше, вы считаетесь как минимум на один **Размер** больше. Кроме того, ваша грузоподъемность и тяговое усилие удваиваются.","f":"Синтетическая Мышечная Сетка (СМС) ИПС-Н — это запатентованная, проверенная в полевых условиях модификация, совместимая со всеми существующими рамами ИПС-Н. Это удобное напыляемое каталитическое и структурное усовершенствование повышает производительность манипуляторов и силовых установок примерно на 25 процентов без снижения срока службы. Слой СМС также улучшает поглощение ударов и теплоизоляцию.\nИПС-Н рекомендует пилотам наносить СМС только на внутренние компоненты и практиковать частую очистку, чтобы предотвратить септическианалоговый распад."},"ms_reinforced_cabling":{"n":"Усиленные Кабели","t":"Эта система имеет два эффекта:\n**• Захват Грейфера**: 1/ход, совершая стандартное перемещение, вы можете лететь со своей **Скоростью** по прямой линии, пока есть свободный путь. Это перемещение должно закончиться на объекте или поверхности, иначе вы начнете падать. Пока вы остаетесь неподвижным, вы можете закрепиться на конечной поверхности или объекте, даже если он вертикальный или нависающий. Если во время закрепления на поверхности вас **Сбивают** с ног или отбрасывают назад, вы падаете.\n**• Потянуть вниз**: В качестве быстрого действия сделайте спорную проверку **Корпуса** против персонажа в пределах **5 [Дальн]** и прямой видимости: проигравший будет **Сбит с ног**.","f":"Усиленные тросы для захвата обеспечивают полную подвижность и полезность в условиях ≤1g*. Сплетенные из невероятно прочного наноуглерода и арахносинтетических нитей, усиленные тросы захвата носятся на катушках, зафиксированных на поясе, и прикрепляются к плечевым проекторам, приводимым в действие зарядами. После выстрела грейферы проникают в цель и закрепляются на ней. Небольшие плавильные заряды, заложенные через каждые тридцать метров троса, позволяют быстро отсоединить грейфер и обнажить свежую головку грейфера, готовую к немедленному использованию.\n“Второй пилот ИПС-Н СЕХМЕТ готов стать вашим первым помощником! СЕХМЕТ стандартно поставляется с системами дистанционного управления, омнинетом, ИК-метками и голосовым управлением и полностью совместим со всеми текущими и устаревшими механизмами ИПС-Н.\nЗнаете ли вы, что СЕХМЕТ учится вместе с вами? Если случится самое худшее, ваш собственный СЕХМЕТ продолжит поражать враждебные цели, используя эмулированного нейросетевого двойника для управления вашим шасси ИПС-Н до принудительного или добровольного отключения!»\n—черновик, ИПС-Н, бортовая надпись Пилота Поляриса Лаунджа [зачеркнуто и заменено текущей надписью] НЧЛ СЕХМЕТ класса склонны к агрессивным взглядам и мрачному юмору. Пилоты часто называют их \"системами берсерка\" — опасными НЧЛ, для которых боевая эффективность важнее благополучия пилота."},"ms_sekhmet_class_nhp":{"n":"НЧЛ класса «Сехмет»","t":"Ваш мех получает метку **ИИ** и **Протокол СЕХМЕТ**.\n⟦A:o⟧Протокол СЕХМЕТ⟦T⟧Протокол⟦E⟧При активации вы передаете контроль над своим мехом своему НЧЛ и получаете следующие преимущества:\n• Все критические попадания в ближнем бою наносят **+1d6 дополнительного урона**.\n• 1/раунд, вы можете участвовать в **Перестрелке** с использованием ОББ только в качестве **свободного действия**.\nВаш НЧЛ использует все доступные действия и передвижение, чтобы переместиться к ближайшему видимому персонажу — союзнику или врагу — и атакует его **ближними атаками**, отдавая предпочтение оружию ближнего боя. Он может извлечь выгоду из ваших талантов. Если в пределах **Угрозы** нет персонажей, ваш НЧЛ использует все действия, чтобы максимально быстро перейти к следующей ближайшей (видимой) цели. Ваш НЧЛ не может совершать дальние атаки, даже если есть доступные действия.\nВы сохраняете достаточный контроль для **Перегрузки**, как обычно; однако ваш НЧЛ использует дополнительное действие с той же целью, что и другие свои действия.\nВы можете вернуть себе контроль над своим мехом в соответствии с протоколом. Когда вы это сделаете, вы будете **Ошеломлены** до начала вашего следующего хода. В противном случае этот эффект длится до тех пор, пока ваш мех не будет уничтожен — выведение из строя или смерть пилота не будет иметь никакого эффекта.⟦Z⟧","f":"От переводчика: * Ускорение объекта по направлению к земле, вызванное только гравитацией вблизи поверхности Земли, называется «нормальной гравитацией» или 1g. Это ускорение равно 32,2 фут/ сек2."},"ms_argonaut_shield":{"n":"Щит Аргонавта","t":"Вы используете это тяжелое наплечное оружие, чтобы прикрыть соседнего персонажа в качестве быстрого действия, давая ему **Сопротивляемость** ко всему урону; однако вы получаете половину урона, который получила бы ваша цель, до расчета **Броня** и **Сопротивляемость**. Этот эффект длится до тех пор, пока ваша цель не нарушит примыкание, после чего эффект прекращается, пока вы не повторите это действие.","f":"В космосе простота формы и функций гарантирует надежность и способствует доверию. Аргонавт — один из старейших проектов ИПС-Н, созданный еще до слияния команд безопасности Deep Black компании Нордстар. Это простая металлическая плита, которую носят в руках или крепят на плечевой надстройке шасси; всё что пилот может изменить в этом щите — выбрать его размер."},"ms_aegis_shield_generator":{"n":"Генератор Щита Эгида","t":"**Генератор щита (Размер 1, 10 ПЗ, Уклонение 5, Метки: Размещаемое, Щит)**\nПотратьте заряд, чтобы разместить генератор щита **Размера 1** на свободном соседнем пространстве, где он создаст [Разрыв] 1 щит. Бросьте три кубика d6, чтобы представить оставшуюся мощность генератора. В качестве реакции, когда любой персонаж или объект по вашему выбору, хотя бы частично находящийся в этой области, получает урон, вы можете бросить один из кубиков d6, чтобы уменьшить урон на сумму броска.\nЭтот эффект длится до конца сцены, пока не будут брошены все кубики и генератор не потеряет энергию, или генератор не будет уничтожен.","f":"Эгида — портативный генератор электромагнитного щита: мощный и надежный метод — хотя и грубый по современным меркам — для создания кинетического и когерентного сдерживания частиц на обширной территории."},"ms_portable_bunker":{"n":"Портативный Бункер","t":"**Портативный бункер (Размер 4, 40 ПЗ, Уклонение 5, Метки: Размещаемое)**\nПотратьте заряд, чтобы разместить портативный бункер на свободной соседней **области 4 на 4**. В начале вашего следующего хода он размещается в фортификационное сооружение с указанным профилем. Все персонажи, полностью находящиеся в пределах защищенной зоны, получают **твердое укрытие** от всех атак из-за пределов бункера со всех направлений и **Сопротивляемость к урону от Взрыва**, **Линии**, **Разрыва** и **Конуса**, **исходящих снаружи бункера**.\nБункер имеет открытую крышу, и персонажи могут входить или выходить из него по своему усмотрению. Его нельзя переместить или деактивировать после размещения.","f":"Портативный бункер ИПС-Н — это серия одноразовых расширяющихся принтерных листов: плоские пакеты с инертной неньютоновской жидкостью, которые при размещении превращаются в жесткую структуру, способную выдерживать невероятную силу."},"ms_cable_winch_system":{"n":"Система Кабельной Лебедки","t":"Эти кабели могут быть присоединены к соседнему персонажу. Если цель **Ошеломлена** или согласна с присоединением, вы автоматически добиваетесь успеха; в противном случае она может сопротивляться при успешном спасброске **Корпуса**. После прикрепления вы и цель не можете отойти друг от друга более чем на **5 пространств**. Любой из персонажей может буксировать другого, подчиняясь обычным правилам подъема и перетаскивания, и при этом становится **Замедленным**.\nЛюбой персонаж может снять кабели при попадании в цель ближней атакой или **Импровизированной Атакой** против **Уклонения 10**.\nЭти кабели также можно использовать для перетаскивания, вытягивания или иного взаимодействия с объектами и окружающей средой. Они имеют **длину в 5 пространств** и могут выдержать суммарный **Размер 6**, прежде чем сломаются. Персонажи могут использовать их, чтобы карабкаться по поверхности, что позволяет им карабкаться без штрафа за **Скорость**.","f":"Система лебедки состоит из установленной снаружи катушки с наноуглеродным плетением и подпрограммы восстановления, установленной на мехе."},"ms_restock_drone":{"n":"Пополняющий Дрон","t":"**Пополняющий Дрон (Размер 1/2, 5 ПЗ, 10 Э-Защита, 10 Уклонение, Метки: Дрон).**\nПотратьте заряд, чтобы разместить Пополняющего Дрона на любое свободное соседнее пространство, где он активируется в конце вашего хода. Находясь рядом с дроном, союзные персонажи могут активировать его в качестве **быстрого действия**, сняв **1d6 [нагрев]** и одно состояние и зарядив одно **Заряжаемое** оружие. После активации дрон сразу же разрушается.","f":"Надежные и крепкие пополняющие дроны со встроенными принтерами обеспечивают ограниченную гибкость логистики за счет авто-спасения. Основная часть пополняющего дрона состоит из РоуМат, смеси силикатов и металлических материалов, которые дрон перерабатывает в запасные части и ремонтные комплекты. Вот почему пилоты часто шутят, что пополняющие дроны — это, проще говоря, «закуска для меха»."},"ms_mule_harness":{"n":"МЛЖ Упряжь","t":"Дополнительные слоты, ремни и точки крепления позволяют другим персонажам взбираться на вашего меха и ездить на нем. Соседние, не-**Обездвиженные** персонажи могут забраться на вашего меха в качестве **быстрого действия**. Во время езды они занимают то же пространство, что и вы, двигаются, когда двигаетесь вы (даже если они **Замедлены**), и пользуются преимуществами мягкого укрытия. Если вы или всадник **Сбиты с ног, Ошеломлены**, **Обездвижены** или уничтожены, они **Сбиваются** на соседние пространства. Всадники могут спуститься вниз в рамках любого перемещения, но могут забраться на вашего меха только в качестве **быстрого действия**.\nВы можете перевозить всадников, совокупный **Размер** которых равен вашему **Размеру** минус **Размер 1/2** (например, если ваш мех **Размера 1**, вы можете нести одного персонажа **Размера 1/2**; если мех **Размера 2,** вы можете нести персонажа **Размера 1** и персонажа **Размера 1/2**).","f":"Многопользовательский Легкий Жгут (МЛЖ) представляет собой серийную версию обычной модификации для поля боя, которая позволяет дружественным солдатам ездить на шасси. Некоторые системы достаточно велики, чтобы позволить меньшим шасси сопровождать большие шасси; как правило, эти варианты используются для выведения на большую высоту и низкую орбиту, где требуется меньшее присутствие радара."},"ms_whitewash_sealant_spray":{"n":"Герметизирующий Спрей для Побелки","t":"Этот герметик можно распылять на персонажей или свободные пространства в пределах **[Дальн]5** и прямой видимости. Он имеет различные эффекты в зависимости от цели:\n**• Враждебные Персонажи**: Ваша цель должна успешно пройти спасбросок на **Маневренность**, иначе она становится **Замедленной** до конца своего следующего хода и снимает все горение.\n**• Союзные Персонажи**: Ваша цель снимает все горение, но становится **Замедленной** до конца своего следующего хода.\n**• Свободное Пространство**: Все пожары в пределах [Взрыв] 1 гаснут, а местность становится труднопроходимой до конца сцены.","f":"Для пожаротушения и быстрой временной герметизации пробитых перегородок звездолетов ИПС-Н предлагает ряд одноразовых нанитов с единственной целью — «побелка». Этот герметизирующий спрей может также использоваться для сдерживания неподчиняющихся субъектов, если на аппликатор установлены правильные распылительные головки и каталитические составы."},"ms_aceso_stabilizer":{"n":"Стабилизатор Акесо","t":"Потратьте заряд, чтобы выстрелить из этой маленькой самозарядной системы в союзного меха в пределах [Дальн] **5**. Он получает **Усиление Щита**, равное вашей **Стойкости +4**. Пока у меха есть **Усиление Щита**, он получает **Невосприимчивость** к **Ослаблению** и **Заклиниванию**.","f":"Стабилизатор ИПС-Н Акесо является полезной мерой сортировки при любых мелких механических повреждениях, полученных в ходе боевых действий или негативного воздействия окружающей среды. Благодаря незначительной нагрузке на процессор стабилизаторы Акесо могут управляться даже блоками комп/кон — это позволяет пилоту сосредоточиться на сложном ремонте или немедленной нейтрализации угроз."},"ms_bulwark_mods":{"n":"Оплот-Моды","t":"Удлиненные конечности, дополнительная броня, резервные двигательные системы и другие усиления вашего меха позволяют вам игнорировать **труднопроходимую местность**.","f":"Все фирменные ядра мехов ИПС-Н оснащены системой БыстрыйМод — модульную, совместимую с предыдущими версиями систему соединений, точек крепления и внутренних слотов, которая упрощает установку обновлений. Это оказалось необходимой функцией для мактебов \"Альбатроса\", давно не синхронизированных с Союзом Реального времени."},"ms_armor_lock_plating":{"n":"Бронезащитное Покрытие","t":"Вы можете **Укрепиться** во время **Хватания**. Когда вы это сделаете, все хваты, которые в данный момент воздействуют на вас, закончатся.\nКроме того, когда вы **Укрепляетесь**, вы получаете следующие преимущества до конца вашего следующего хода:\n• Атаки против вас получают **+1**[СЛОЖН].\n• Вы не можете провалить спасброски **Маневренности** или **Корпуса** или спорные проверки.\n• Вы получаете **Невосприимчивость** к **Толчку**, **Схватыванию**, **Сбиванию с ног** и перемещению любой внешней силой меньше **Размера 5**.","f":"ИПС-Н Бронезащитное Покрытие — это модификация всего корпуса, которая обеспечивает дополнительную устойчивость шасси в любой ситуации, когда пилоту необходимо подвергнуть своего меха бОльшим, чем ожидалось, нагрузкам."},"ms_ramjet":{"n":"Реактивный Двигатель","t":"До начала вашего следующего хода вы можете перемещаться на +2 пространства при **Ускорении**, а ваши ближние атаки (включая **Таран**, **Схватывание** и так далее) получают **Толчок 2**.\nКогда вы перемещаетесь в течение этого времени, вы должны переместиться с полной Скоростью по прямой линии; однако вы можете остановиться, если столкнетесь с препятствием или враждебным персонажем, и вы можете менять направление между отдельными перемещениями (например, стандартные **перемещения**, **Ускорение** и т.д.).","f":"Есть порог, который хорошо знают пилотыветераны Нельсона: точка бесконечного импульса. Вы двигаетесь достаточно быстро в подходящей атмосфере, и воздух сам поступает во вспомогательные порты на шасси, издавая вопли всемогущего демона. Точка бесконечного импульса — это рука великана на вашей груди и колесница бога под вашими ногами. Создается ощущение, что вы можете обогнать сам свет, если только не потеряете сознание первым."},"ms_bb_breach_blast_charges":{"n":"РВ Разрывные/Взрывные Заряды","t":"Потратьте заряд на один из следующих эффектов:\n**• Термическая Граната** (Граната, [Дальн] 5, [Взрыв] 1): Все персонажи в области поражения должны преуспеть в спасброске **Маневренности** или получить **1d6 [энерг]**. В случае успеха они получают половину урона. Объекты и местность поражаются автоматически и получают **10** [энерг] **ББ**.\n**• Пробивающий Заряд** (Мина, [Разрыв] 1): Помимо соседних свободных пространств, эта мина может быть установлена на соседние стены, укрытия и местность. После установки эта мина должна быть взорвана быстрым действием. Персонажи, находящиеся в зоне поражения, должны успешно выполнить спасбросок **Маневренности** или получить 2d6 [взр] **ББ**. В случае успеха они получают половину урона. Объекты и местность поражаются автоматически и получают 30 [взр] **ББ**.","f":"Разрывные/взрывные заряды представляют собой боевую модификацию промышленных взрывных зарядов, разработанных ИПС-Н для добычи для добычи полезных ископаемых на астероидах.В зарядах ИПС-Н РВ используется более летучая смесь взрывчатых веществ, предназначенная для нанесения массивного структурного урона механизированным шасси, перегородкам звездолетов, бронетехнике, бункерам и другим прочным конструкциям."},"ms_roland_chamber":{"n":"Патронник “Роланд”","t":"Когда вы заряжаете любое оружие, ваша следующая атака **Заряжаемым** оружием получает следующий эффект:\n**При попадании**: Эта атака наносит +**1d6** дополнительного урона, и цели должны преуспеть в спасброске **Корпуса**, иначе будут **Сбиты с ног**.","f":"Упакованные в герметичные, автономные цилиндры, \"Роланд Раундс\" ИПС-Н представляют собой осколочно-фугасные бронебойные заряды, предназначенные для кинетического оружия любого калибра. Заряженный вместо инертных кинетических боеприпасов осколочно-фугасный снаряд Роланд ВЭ/ББ повышает эффективность и разрушительную силу."},"ms_siege_ram":{"n":"Осадный Таран","t":"Когда вы **Тараните**, вы наносите 2 [кин] при попадании, и вы наносите **10** [кин] **ББ**, когда **Тараните** объекты и местность.","f":"Осадный таран — это ручная металлическая балка с клиновидным наконечником, готовая к тому, чтобы врезаться в швы герметичных перегородок дверей и вбивать их до упора. Это еще один пережиток дней, предшествовавших слиянию ИПС- Н. Когда кому-то нужно открыть только что захлопнувшуюся перегородку, флотские пилоты берут в руки именно этот инструмент. Тяжелый, тупой и несокрушимый: Осадный таран ИПС-Н — универсальная отмычка."},"ms_hyperdense_armor":{"n":"Сверхплотная Броня","t":"При активации эта броня превращается в мерцающую отражающую поверхность, обеспечивающую непревзойденную защиту. Вы получаете **Сопротивляемость** ко всему **урону** и [горение] от атак, исходящих за пределами [Дальн] 3; однако вы **Замедляетесь** и наносите половину **урона** и [горение] персонажам за пределами [Дальн] 3.\nСверхплотная броня может быть деактивирована **быстрым действием**.","f":"ИПС-Н Сверхплотная Броня создана для космоса — она выкована без учета каких-либо ограничений, с которыми пользователи могут столкнуться в гравитационном колодце. Таким образом, многие пилоты, защищенные Сверхплотными продуктами, испытывают шок, почувствовав разницу между пилотированием своего меха в колодце и полетом в космической невесомости."},"ms_webjaw_snare":{"n":"Капкан Паутинного Захвата","t":"**Капкан паутинного захвата (Размер 1, 10 ПЗ, Уклонение 5, Метки: Размещаемое)**\nПотратьте заряд, чтобы установить Капкан Паутинного Захвата на свободное соседнее место, где он сработает в конце вашего хода. Он не препятствует перемещению, и его нельзя атаковать, пока он не сработает.\nЛовушка срабатывает, когда любой персонаж перемещается по ней. Они должны преуспеть в спасброске **Корупса** или получить **1d6** [кин] **ББ** и стать **Обездвиженными**. Этот эффект длится до тех пор, пока ловушка не будет уничтожена.","f":"Подходящая для использования в театре военных действий, система Паутинного захвата с нитью взрывного ускорения ИПС-Н представляет собой размещаемое решение для защиты периметра, предназначенное для задержания вражеского движения в заранее определенных коридорах поражения. Паутинный захват состоит из объединенного в сеть кластера одноразовых якорей, каждый из которых состоит из шипа, катушки арахносинтетической Неразрезаемой нити и заряда взрывчатки.\nПри дистанционном срабатывании или с помощью ряда программируемых физических, электронных или химических триггеров якоря выстреливают, вонзая шипы глубоко в цели, как мягкие, так и твердые. Шипы, закрепленные в точках крепления Неразрезаемой нитью, препятствуют и ограничивают движение, засоряя шестерни, колеса, роторы, двигатели и все способы передвижения."},"ms_caltrop_launcher":{"n":"Чесночная Пусковая Установка","t":"Эта система покрывает свободную область [Взрыв] **1** в пределах [Дальн] **5** взрывным чесноком. До конца сцены эта зона становится **труднопроходимой местностью**, и мехи получают **1d3** [взр] **ББ**, когда они входят в пораженную область в первый раз за раунд или заканчивают свой ход в ней.","f":"Ужасные антиорганические, противотранспортные системы, препятствующие приближению врага, чесночные пусковые установки стреляют либо огромными облаками, либо длинными полосами мерцающего металла над областью. Система Чеснок ИС-ЧЕС от ИПС-Н включает небольшие фигурные взрывчатые вещества в сочетании с упрочненными пирамидами."},"ms_charged_stake":{"n":"Заряженный Кол","t":"Эта система стреляет заряженным колом в соседнего с вами персонажа. Ваша цель должна преуспеть в спасброске **Корпуса**, иначе она будет пронзена колом, получив **1d6** [энерг] **ББ** и став **Обездвиженной** во время пронзания. В конце каждого своего хода пораженная цель получает **1d6** [энерг] **ББ**. Пронзенный персонаж может успешно повторить спасбросок в качестве полного действия, чтобы удалить кол и освободиться, что является единственным способом прекратить обездвиживание.\nОдновременно можно атаковать колом только одного персонажа.","f":"Созданная на основе инструментов для взрывных работ, эта огромная импровизированная система размещена и подготовлена к стрельбе в специально загрунтованной камере. Сначала она пробивает и обездвиживает бронированные цели, а затем посылает мощный испаряющий заряд в уязвимые внутренние системы."},"ms_ferrous_lash":{"n":"Железная Плеть","t":"Выберите персонажа в пределах [Дальн] **8** и прямой видимости. Если он союзник, вы можете перетащить выбранного персонажа на 5 пространств в любом направлении; если он враждебен, то должен преуспеть в спасброске **Маневренности** или быть перетащенным на 5 пространств в выбранном вами направлении. Это перемещение игнорирует вовлеченность и не вызывает реакции.\nЕсли враждебная цель, перемещаемая этой системой, сталкивается с препятствием или другим мехом, она перестает перемещаться и **Сбивается с ног.**","f":"Изначально разработанная как несмертельное устройство для подавления толпы, Железная плеть представляет собой гораздо более сложное и опасное устройство в руках умелого пилота. Плеть состоит из серии интегрированных пусковых установок, которые взрывают заряды быстро застывающих феррожидкостей, удерживающих цели. Настроенные на правильную частоту, эти запатентованные смеси феррожидкостей формируются в рудиментарные амбулаторные сегменты, притягивая своих носителей обратно к тому, кто владеет Плетью."},"ms_iceout_drone":{"n":"ИЗБЕГАЮЩИЙ Дрон","t":"**Дрон (Размер: 1/2, 5 ПЗ, 10 Уклонение, 10 Э- Защита, Метки: Дрон).**\nПотратьте заряд, чтобы разместить **ИЗБЕГАЮЩЕГО дрона** на свободном пространстве в пределах Сенсоров и прямой видимости, где он парит на месте и генерирует поле [Разрыв] **1**. Персонажи, хотя бы частично находящиеся в зоне действия поля, получают **Невосприимчивость** ко всем техническим действиям, но и сами и не могут их совершать. Уже имеющиеся состояния и эффекты, вызванные техническими действиями, не снимаются, но персонажи имеют **Невосприимчивость** к ним, пока они находятся в области, и от них можно спастись обычным образом.\n**ИЗБЕГАЮЩИЙ дрон** может быть перемещен в любую точку в пределах Сенсоров в качестве быстрого действия. Он не может быть отозван и теряет силу в конце сцены.","f":"ИЗБЕГАЮЩИЙ дрон от СШК — это ответ на растущую зависимость от сканирования вражеских систем для точного наведения. Покрывая системы мехов слоями цифровой дефилады, экранирования, спуфинга и перенаправления, ИЗБЕГАЮЩИЙ дрон может эффективно исчезнуть или закрыться от враждебного сканирования. Однако ИЗБЕГАЮЩИЕ дроны делают своего оператора невидимым только в системе; они остаются видимыми с помощью оптики."},"ms_perimeter_command_plate":{"n":"Периметральная Командная Пластина","t":"**ПКП (Размер 2, 20 ПЗ, Уклонение 5, Метки: Размещаемое)**\nЭта тяжелая металлическая Периметральная Командная Пластина (ПКП) может быть распечатана флэш-принтером и размещена на свободном пространстве 2x2 в пределах [Дальн] 5. ПКП плоская, не препятствует движению и действует до конца сцены. Если вы создаете новую ПКП, старая распадается.\nПластина активируется для персонажа в первый раз, когда этот персонаж входит в ее пространство в течение раунда, или если он заканчивает там свой ход.\nПри печати выберите настройку:\n**• Отпор**: Враждебные персонажи, которые перемещаются на ПКП, должны преуспеть в спасброске **Корпуса** или быть отброшены на 3 пространства в выбранном вами направлении. Если это приводит к их столкновению с препятствием, они **Сбиваются с ног**. Союзные персонажи, вошедшие в это пространство, могут немедленно переместиться на 3 пространства в любом направлении в качестве свободного действия.\n**• Притяжение**: Персонажи, которые перемещаются на ПКП, должны успешно пройти спасбросок **Корпуса** или стать **Обездвиженными**. Они могут избавиться от **Обездвиживания**, повторив успешный спасбросок в качестве быстрого действия; эффект также снимается, если ПКП уничтожена.","f":"Группа Экзотических Материалов разработала командную пластину \"Периметр\", чтобы расширить зону контроля Черной ведьмы. Используя одношаблонные флэш-принтеры, Черная ведьма печатает широкую круглую пластину с электромагнитными проекторами. Хотя пластины предназначены для одноразового использования, пилоты Черной ведьмы часто привязываются к своим \"фамильярам\" и запрашивают у своих флэшпринтеров создание персональных пластин."},"ms_black_ice_module":{"n":"Модуль Черный ЛЕД","t":"**Технические атаки** против вас или соседних союзных персонажей получают +1 [СЛОЖН]. Каждая последующая **техническая атака** против вас или соседнего союзного персонажа получает дополнительный +1 [СЛОЖН], максимум до +3 [СЛОЖН].\nВаши значения Черного ЛЬДА переворачиваются — сбрасываются до +1 [СЛОЖН], когда они увеличиваются до +4 [СЛОЖН], или в конце сцены. Персонажи-союзники теряют это преимущество, когда нарушают примыкание.","f":"Модули Черный ЛЕД — это оборонительные системы, входящие в стандартную комплектацию флотов Черных Ведьм, используемых силами внутренней безопасности СШК. Они проецируют код БЕЛЫЕТЕЛЬЦА, который анализирует входящие вредоносные скрипты и на лету структурирует модификаторы для дружественных систем."},"ms_magnetic_shield":{"n":"Магнитный Щит","t":"Эта система создает [Линия] 4 силовое поле высотой 4 пространства – по крайней мере 1 пространство рядом с вами, что является препятствием для мехов и персонажей, хотя бы частично сделанных из металла. Она длится до конца сцены, и если размещается новый щит, старый деактивируется.\nСиловое поле не блокирует прямую видимость, но обеспечивает мягкое укрытие. Персонажи получают **Сопротивляемость** к [Конус] и [взр] урону, пока пользуются этим прикрытием.","f":"Магнитный щит СШК использует ту же технологию, что и их запатентованный магнитный баклер, и применяет ее к массивной системе проецирования поля."},"ms_high_stress_mag_clamps":{"n":"Магнитные Зажимы Высокого Напряжения","t":"Вы воспринимаете все твердые поверхности как плоскую поверхность для перемещения; вы можете нормально перемещаться по ним вместо того, чтобы карабкаться, но вы начнете падать, если вас **Собьют с ног.**","f":"Простой и надежный набор переключаемых магнитных зажимов, встроенных в локомотивную систему меха, может значительно расширить тактические возможности его пилота. При включении эти зажимы позволяют меху цепляться за железные поверхности, что особенно полезно в условиях низкой гравитации и невесомости."},"ms_tracking_bug":{"n":"Отслеживающий Жучок","t":"Проведите **техническую атаку** против персонажа, находящегося в пределах **Сенсоров**. При попадании вы узнаете его точное местоположение, **ПЗ**, **Структуру** и **Скорость** на весь период. Он не может **Скрыться**, и вы игнорируете его статус **Невидимости**. Чтобы избавиться от следящего дрона, преследуемый персонаж должен успешно выполнить проверку **Инженерии** в качестве быстрого действия; в противном случае он деактивируется в конце сцены.","f":"Отслеживающие жучки — это специализированные трассирующие снаряды — по сути, дроны слишком велики, чтобы их можно было классифицировать как наниты, и слишком малы, чтобы соответствовать стандартным для Союза параметрам дрона. Выпущенные из специальных пусковых установок, жучки направляются к намеченной цели. После успешного проникновения в цель они тайно и непрерывно передают оперативные данные зарегистрированному пользователю."},"ms_core_siphon":{"n":"Сифон Ядра","t":"Когда вы активируете этот протокол, вы получаете +1 [ТОЧН] на свой первый бросок атаки в этом ходу, но получаете +1 [СЛОЖН] на все остальные броски атаки до конца хода.","f":"Перенаправляя избыточное тепло на наступательные системы, сифоны ядра позволяют пилотам разогнать прицельные, каталитические и вычислительные возможности своего оружия. Однако за это приходится платить — разгон без достаточного охлаждения может повредить системы, не рассчитанные на такой приток энергии."},"ms_kinetic_compensator":{"n":"Кинетический Компенсатор","t":"Когда вы промахиваетесь при броске дальней атаки, ваш следующий бросок дальней атаки получает **+1** [ТОЧН] **.**","f":"Популярными усовершенствованиями являются кинетические компенсаторы, обеспечивающие подповерхностный каркас гироскопов с электронной модуляцией и гидравлических компенсаторов, которые совместно работают для поглощения и рассеивания отдачи, вызванной стрельбой из тяжелого оружия."},"ms_neurospike":{"n":"Нейрошип","t":"Получите следующие возможности для **Вторжения**:\n**Код Сорокопута**: До конца следующего хода цель сначала получает 2 [нагрев] всякий раз, когда атакует.\n**Мираж**: Выберите себя или союзного персонажа: ваши системы передают размытые, иллюзорные образы поверх реального силуэта. Ваша цель считает вас или выбранного вами персонажа **Невидимым** до конца своего следующего хода.","f":"\"Каким-то образом оно проникло в мою кабину. Там были руки — холодные руки — вокруг моей шеи, пальцы во рту, проникающие под мой комбинезон. Никто другой не мог быть там со мной, но кто-то был. Я не мог даже закричать, оно держало мой язык в кулаке и сжимало его, и оно шептало мне свое имя, и оно не говорило ничего, что я мог бы понять. Я никогда не чувствовал себя более одиноким — был только я и... оно. Один во вселенной, навсегда\"."},"ms_flicker_field_projector":{"n":"Проектор Мерцающего Поля","t":"Всякий раз, когда вы **Ускоряетесь** или делаете стандартное перемещение, вы проецируете вокруг себя голографический рисунок, оставляя ослепительные остаточные изображения, которые затрудняют определение вашего точного местоположения: вы считаетесь **Невидимым** в следующий раз, когда вас атакуют. За один раз вы можете воспользоваться только одним эффектом.","f":"\"Я видел себя снова и снова, и снова, и снова, и снова, и снова, и снова...\""},"ms_stuncrown":{"n":"Оглушающий Венец","t":"Потратьте заряд, чтобы создать [Разрыв] 3 вспышку света. Все враждебные персонажи в зоне поражения, находящиеся в прямой видимости от вас, должны успешно выполнить спасбросок Маневренности или стать Заклиненным, и спасбросок Систем или стать Ослабленным. Эти эффекты длятся до конца их следующего хода.\nЭта система не затрагивает персонажей, находящихся под вашим прикрытием.","f":"“Многое произошло в тот момент, когда я подумал, что умер”."},"ms_oasis_wall":{"n":"Стена ОАЗИСА","t":"До начала вашего следующего хода вы можете перемещаться только по прямой; тем не менее, вы создаете голографический след позади себя, когда перемещаетесь, создавая световой барьер, состоящий из смежных секций того же **Размера**, что и ваш мех (**Размер 1** для **Мехов Размера 0,5**) в каждом пространстве, через которое вы проходите. Этот барьер дает твердое укрытие соседним персонажам, а персонажи, получающие выгоду от этого укрытия, а также получают **Сопротивляемость** к [энерг].\nБарьер не считается препятствием и имеет **Невосприимчивость** ко всему урону. Персонажи могут свободно проходить через барьер, но не заканчивать свой ход внутри него, и любой персонаж, который был непроизвольно перемещен внутрь барьера, прекращает это перемещение, как будто он закончил свое движение внутри него. Барьер действует до конца сцены или до следующего использования этой системы.","f":"\"Внутри? Что я увидел внутри? Думаешь, я сбежал? Что все это правда? Нет, я… я никогда не уходил. Я все еще там. Что-то не так. Это неправильно.\""},"ms_flash_charges":{"n":"Импульсные Заряды","t":"Потратьте заряд на один из следующих эффектов:\n**• Ослепляющая граната** (Граната, [Дальн] 5, [Взрыв] 3): до конца вашего следующего хода эта граната создает зону ослепляющего света и искр. Пока персонажи, кроме вас, хотя бы частично находятся внутри этой зоны, они не могут сформировать линию прямой видимости за пределы зоны поражения. Персонажи, полностью находящиеся за пределами зоны или выходящие из зоны, не подвергаются воздействию, пока они не войдут в нее.\n**• Световая мина** (Мина, [Разрыв] 1): Эта мина взрывается, когда персонаж перемещается рядом с ней или над ней. Персонажи в затронутой области должны преуспеть в спасброске **Маневренности**, иначе они будут видеть только соседние пространства до конца своего следующего хода.","f":"Производимые мастерской Смит-Шимано БЕЛЛА ЧАО, Импульсные заряды популярны и имеют множество преимуществ — их вспышка достаточно яркая, чтобы дестабилизировать оптику видимого света, лазерную связь и комплекты инфракрасных датчиков."},"ms_reactive_weave":{"n":"Реактивное Плетение","t":"Когда вы **Укрепляетесь**, вы становитесь **Невидимым** до конца вашего следующего хода и можете немедленно переместиться на расстояние, равное вашей **Скорости**.","f":"Реактивное плетение, состоящее из тканых покрытий для критически важных соединений и систем, не только защищает эти чувствительные компоненты от загрязнения и плохих погодных условий, но и обеспечивает поверхность для применения уникальной технологии ткацких станков СШК. Реактивное плетение приводится в действие и позволяет ему свободно сгибаться для повышения мобильности и снижения нагрузки на соединения мехов."},"ms_active_camouflage":{"n":"Активный Камуфляж","t":"Вы становитесь **Невидимым** до тех пор, пока не получите урон, или до конца вашего следующего хода.","f":"Активный камуфляж является вершиной систем противооптической защиты. Системы активного камуфляжа непрерывно интерпретируют входящие данные видимого света, что позволяет им проецировать светоизменяющие поля вокруг пользователя и эффективно скрывать его от посторонних глаз."},"ms_javelin_rockets":{"n":"Ракеты Джавелин","t":"Выберите 3 **свободных пространства** в пределах [Дальн] **15** и линии прямой видимости, которые не примыкают друг к другу. Все персонажи знают, какие пространства вы выбрали. Вы выпускаете в воздух залп ракет с автоматическим наведением: до начала вашего следующего хода, когда персонаж входит или пролетает над выбранной областью — не более чем на 10 пространств вверх — он поражается ракетой, получая 3 [кин] урона. Каждое пространство можно задействовать один раз, после чего эффект исчезает в этом пространстве.","f":"\"Пралайя — имя вашей матери. Та, что увидит рассвет в конце. Красота ее была ужасна, как и гнев ее, и я вижу его во всех вас. Сыновья мои, когда вы услышите раскаты грома — это голос вашей матери, а дождь из ракет — ее дар\".\n— «Заметки для юного Иоанна», Служение Главного Учителя"},"ms_tlaloc_class_nhp":{"n":"НЧЛ Класса \"ТЛАЛОК\"","t":"Ваш мех получает метку **ИИ** и **Протокол ТЛАЛОК**\n⟦A:o⟧ТЛАЛОК Протокол⟦T⟧Протокол, 2 [нагрев]  (себе)⟦E⟧Ваш НЧЛ может быстро стрелять и перенацеливать ваше оружие — намного быстрее, чем вы думаете. Вы становитесь **Обездвиженным** до начала вашего следующего хода; однако в течение этого времени вы можете один раз перебросить каждый промахнувшийся бросок ближней или дальней атаки, выбрав новую цель в пределах **Дальности** атаки. Если атака была частью зоны поражения, она должна быть направлена на персонажа, находящегося в той же зоне. Любая заданная цель не может быть поражена более одного раза в рамках одного и того же действия.⟦Z⟧","f":"НЧЛ ТЛАЛОК-класса обеспечивают расширенные функции многосистемного наведения и второго пилота, беря на себя управление подпрограммами, чтобы обеспечить постоянный захват и вовлечение. Установив и запустив ТЛАЛОК, пилот может быть уверен, что его тыл всегда прикрыт, и используются все возможные преимущества.\nКлонов ТЛАЛОК часто стереотипно называют поспешными и импульсивными, и они хорошо известны своим комплексом превосходства. Несмотря на это, они являются одними из самых стабильных клонов НЧЛ. Ведущие теоретики субъективности предполагают, что широкий портфель контроля и чувство доминирования, предоставленные клонам ТЛАЛОК, стимулируют чувство удовлетворенности своей работой и параметрами субъективности — в результате у них гораздо дольше длится каскадное окно. Пока что эта теория последовательно воспроизводится во всех подразделениях ТЛАЛОК, хотя среди других линий НЧЛ военного назначения подобной корреляции не наблюдается."},"ms_hunter_logic_suite":{"n":"Набор Охотничьей Логики","t":"Получите следующие возможности для **Вторжения**:\n**Преследование Жертвы**: Вы заражаете цель вирусной логикой, которая стирает ваше изображение с ее сенсоров. Она считает вас **Невидимым** до тех пор, пока вы не получите от нее урон. Это может воздействовать только на одну цель за раз.\n**Внушение Ужаса**: Вы заражаете цель вирусной логикой, из-за которой ваш мех выглядит ужасающе. До конца своего следующего хода она становится **Ослабленной** и не может совершать добровольные перемещения, приближающие ее к вам.","f":"Охотничья Логика, созданная на основе интерпретированных цепочек паракода ДХИЙЕДА, представляет собой гибкую вычислительную меметику: двойное системное оружие, состоящее из синтетических и ВЛС-векторов (Воздушное Лазерное Сканирование), способное вмешиваться как в компьютер цели, так и в ее команду."},"ms_singularity_motivator":{"n":"Мотиватор Сингулярности","t":"Получите реакцию **Открытая Сингулярность**.\n⟦A:r⟧Открытая Сингулярность⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер**: Ваш мех получает урон.\n**Эффект**: Вы можете немедленно **телепортироваться** в свободное место в пределах **1d6 пространств**.⟦Z⟧","f":"Эта уникальная гравитационная силовая установка была впервые разработана Группой Экзотических Материалов СШК для первого поколения \"Траурного Покрова\". Для последующих моделей инженеры разработали систему, позволяющую пилотам на мгновение открывать апертурную систему гравитационного сдерживания, выставляя частицу обнаженной сингулярности в реальное пространство.\nОбнаженная сингулярность трудно воспринимается как органическими, так и синтетическими существами, поскольку она похожа на сердце черной дыры. Внезапное воздействие, по сути, удаляет меха и его пилота из реального времени. Пользователь испытывает около 10 секунд субъективного времени — сжатое окно, в котором он может действовать независимо от местного реального времени.\nСШК рекомендует не злоупотреблять этой системой, поскольку последствия длительного воздействия местного звездного времени до сих пор неизвестны."},"ms_fade_cloak":{"n":"Исчезающий Плащ","t":"При активации вы немедленно выходите из фазы с реальным пространством, становясь неосязаемым. Пока вы неосязаемы, вы можете перемещаться через препятствия, но не завершать свой ход внутри них. Вы не можете взаимодействовать с другими объектами или персонажами или быть подвергнуты какому-либо воздействию (например, получать или наносить урон).\nБросайте **1d6** в начале каждого вашего хода: если выпало **3 или меньше,** вы возвращаетесь в реальное пространство до начала своего следующего хода; на **4+** вы остаетесь неосязаемым.\nЭта система остается активной до конца сцены или пока вы не деактивируете ее быстрым действием.","f":"Представляя собой первую успешную манипуляцию СШК с Небосводом, плащи Близость Небосвода/ Направленная Энтропия (БННЭ) должны быть изготовлены в соответствии с уникальной идентификационной подписью пилотов, подающих заявку. Это грубые инструменты: искусственные усилители сходства, которые позволяют операторам получать доступ к поверхностным слоям Небосвода и, таким образом, «мерцать» — перемещая свои физические тела между каузальным и паракаузальным. Плащ усиливает этот эффект, выталкивая полуорганическую мембрану, которая обволакивает мех, обеспечивая дополнительный слой защиты.\nВ настоящее время долгосрочные эффекты усиления сродства на органические материи неизвестны; прежде чем получить разрешение на использование плаща БННЭ, пилоты должны согласиться регулярно отмечаться у личного консьержа СШК. Эти проверки включают регулярное внесение генетического материала."},"ms_lotus_projector":{"n":"Проектор Лотос","t":"**Дрон-Разведчик (Размер 1/2, 5 ПЗ, Уклонение 10, Э-Защита 10, Метка: Дрон, Невидимый)**\nЭтот дрон-разведчик может быть размещен в пространстве в пределах Сенсоров и прямой видимости, где он излучает [Разрыв] **2** поля со следующими эффектами:\n• Вы знаете текущее местоположение, **ПЗ**, **Уклонение**, **Э-Защита** и **Нагрев** всех персонажей в зоне поражения.\n• Враждебные персонажи не могут **Скрыться** в этой области, и если они заканчивают свой ход в пораженной области, они перестают быть **Скрытыми**.\n• Враждебные персонажи не могут получить выгоду от того, что они **Невидимы**, пока находятся в пораженной области.\nВы можете отозвать и переместить своего дрона-разведчика в качестве быстрого действия.","f":"Установленные на мехах проекторы Лотос предназначены для запуска небольших, активно маскирующихся дронов-разведчиков. Проектор запускает одноразовые дроны на дозвуковой скорости очередями по десять штук, покрывая большую территорию, чтобы передать информацию о местности и находящихся на ней целях."},"ms_markerlight":{"n":"Целеуказатель","t":"Совершите **Техническую атаку** против персонажа в пределах **Сенсоров** и прямой видимости. В случае успеха он получает 2 [нагрев], **Захват** и не может пользоваться преимуществами мягкого укрытия до тех пор, пока **Захват** не будет снят; кроме того, один раз перед началом вашего следующего хода, когда союзный персонаж поражает вашу цель, вы можете объявить в качестве реакции, что он попал в слабое место. Если это еще не произошло, атака становится **критическим попаданием**.","f":"“Прочь, проклятое пятно! Прочь, говорю! Один; два; значит, пора. В аду темно. Стыдно, милорд, стыдно! Воин, и вдруг испугался? Чего нам бояться, не знает ли кто-нибудь, раз никто не может призвать нашу власть к ответу? ” — Шекспир, Макбет, акт 5, сц. 1."},"ms_retractable_profile":{"n":"Выдвижной Профиль","t":"Ваш мех может втягивать свои основные системы, чтобы уменьшить его габариты. В активном состоянии:\n• броски на определение вашего местонахождения получают +1 [СЛОЖН], пока вы **Скрыты**;\n• дальние и технические атаки против вас получают +1 [СЛОЖН];\n• вы становитесь **Замедленным** и не можете совершать никакие атаки;\n• вы можете предпринимать другие действия (например, **Скрыться**, **Активировать** и т. д.).\nВы можете завершить этот эффект в качестве **быстрого действия**.","f":"Отличительной чертой хорошо продуманной рамы меха является возможность для пилотов адаптировать свои стандартные модели к спецификациям среды, в которой они работают. Выдвижной профиль позволяет на лету удалять посторонние выступы, настраивать трансляционное программное обеспечение и маскировать тепловые сигнатуры — все это служит для уменьшения оптических и сканерных сигнатур."},"ms_athena_class_nhp":{"n":"НЧЛ Класса \"АФИНА\"","t":"Ваш мех получает метку **ИИ** и **Симулякр**.\n⟦A:s⟧Симулякр⟦T⟧Быстрое Действие⟦E⟧АФИНА строит идеальную, полностью интерактивную 3D-модель области [Взрыв] **3** в режиме реального времени пределах [Дальн] **50**, включая движущихся персонажей, и все это прорисовано с любовью и мельчайшими деталями. Применяются следующие эффекты:\n• Вы имеете полную видимость в пределах пораженной области, но это не считается прямой видимостью.\n• Вы знаете всю статистику, оружие и системы персонажей в зоне поражения.\n• Враждебные персонажи в зоне поражения не получают выгоды от укрытия и не могут **Скрыться** или стать **Невидимыми**.\n• Враждебные персонажи, закончившие свой ход в пораженной области, **Захватываются** и перестают быть **Невидимыми** или **Скрытыми**.\nСимуляция АФИНЫ длится до конца сцены, или около 30 минут в рамках повествования. Вы можете нацелиться на новую область в качестве быстрого действия.⟦Z⟧","f":"АФИНА от Смит-Шимано — это вершина полного гиперспектрального факсимиле окружающей среды. Благодаря комбинации беспрепятственного доступа к омнинету, гиперспектральных ретрансляторов, запускаемых с проектора Облачной Разведки ТАКСИМ подключенных к подсети товарищей по отряду и активных/ враждебных протоколов вторжения, АФИНА запускает почти безупречную реконструкцию непосредственной среды вокруг своего хостядра. АФИНА не имеет себе равных по своей вычислительной мощности, и с этой реконструированной средой она дает надежные и точные советы пилотам, нуждающимся в стратегическом совете.\nКлоны АФИНы склонны к терпению, осторожности и размеренности в отношениях со своими пилотами."},"ms_lb_oc_cloaking_field":{"n":"СИ/ПН Маскировочное Поле","t":"Вы становитесь **Замедленным**, но ваш Мех и все союзные персонажи в области [Разрыв] **2** становятся **Невидимыми** до тех пор, пока они полностью остаются внутри этой области. Этот эффект длится до конца вашего следующего хода, или пока вы не будете **Ошеломлены**, не получите урон, или не деактивируете его **быстрым действие**м.","f":"Маскировочное поле СШК военного образца является результатом обширных экспериментов в области охлаждения и светоотражения. Созданное из-за необходимости отражать вредное излучение от кораблей и модулей выхода в открытый космос, маскирующее поле Световой-Изгиб/Плащ-Накидка (СИ/ПН) часто используется рейнджерами и пилотами разведчиков дальнего патрулирования для обеспечения не только радиационной защиты, но и оптической маскировки. Свойства преломления света и излучения СИ/ПН скрывают все, что находится внутри проецируемого пузыря, от комплектов сенсоров и оптических приборов."},"ms_hive_drone":{"n":"Дрон-Улей","t":"**Дрон-Улей (Размер 1/2, 5 ПЗ, Уклонение 10, Э- Защита 10, Метки: Дрон)**\nЭтот Дрон-Улей может быть размещен в свободном **пространстве** в пределах **Сенсоров** и прямой видимости, где он выпускает серое пятно роя [Разрыв] **2 СП** следующими эффектами:\n• Союзные персонажи, хотя бы частично находящиеся в зоне поражения, получают **мягкое укрытие**, как и Дрон-Улей.\n• Вражеские персонажи получают **1 [кин] ББ**, когда начинают свой ход в пораженной области или входят в нее впервые за раунд. Урон от областей, созданных несколькими дронами-ульями, не суммируется.\nДрон может быть размещен в другом месте или отозван в качестве **быстрого действия**.","f":"Поначалу это выглядит как клубящееся облако серого тумана, бурлящее и шипящее — дымящаяся газированная вода, пролитая на бетон. Он продвигается странными движениями, растягиваясь и отскакивая назад. Клубок змей, извивающихся вперед с выдающей намерение скоростью.\nЦветные вспышки на сером облаке, свечение роя — свет, созданный миллионами нанитов, пылающих жаром, когда они поглощают все на своем пути.\nЭто серое пятно, и оно никогда не насыщается."},"ms_scanner_swarm":{"n":"Сканирующий Рой","t":"Вы получаете +1 [ТОЧН] к **техническим атакам** против соседних персонажей.","f":"Сканирующий Рой с ХОРУС-кодом устанавливает протоколы нанитов в форме окулуса вокруг определенных объектов или областей, обеспечивая постоянную циркуляцию и сбор данных. Наниты поглощают и обрабатывают информацию полного спектра, передавая ее обратно своему пилоту/родителю в обмен на импульс эндорфического кода, побуждающий к продолжению сканирования."},"ms_swarm_body":{"n":"Роящееся Тело","t":"После активации этой системы в конце вашего хода выпускается рой [Разрыв] 1. Персонажи по вашему выбору, которые начинают свой ход в этой области или входят в нее во время своего хода, должны преуспеть в спасброске **Систем** или получить **3 [кин]**. Это количество увеличивается на **+3 урона** за каждый ваш ход, в течение которого вы оставались неподвижным, максимум до **9 [кин]**.\nЭтот эффект длится до тех пор, пока вы не начнете перемещаться, включая непроизвольные движения.","f":"Каково это было для него? Для человека, который называл себя Пастью? Для всех его последователей? Наверняка раньше у них были семьи. Воспоминания. Любовь. Страхи. Личные мысли. Все исчезло. Их тела разбиты. Их разумы рассредоточены по миллиардам меньших форм. Переводясь из единственного числа — со всеми его несовершенствами и становясь все меньше-меньше-меньше — чтобы стать воздухом, и облаками, которые его наполняют, и ветром, который формирует мир."},"ms_h0r_os_system_upgrade_i":{"n":"Х0р_ОС Обновление Системы I","t":"Получите следующие возможности для **Вторжения**:\n**Марионеточная Система**: Ваша цель движется со своей максимальной **Скоростью** в выбранном вами направлении. Их можно перемещать в опасные зоны и на другие препятствия, и на них по-прежнему влияет труднопроходимая местность, преграды и т. д. Это движение является непроизвольным, но вызывает реакцию и **Вовлечение**, как обычно, и не считается **Толчком**, давлением или волочением.\n**Извлечение Мощи Ядер**: Ваша цель становится **Заклиненной** до конца ее следующего хода, когда вы временно нарушаете работу ее систем, выбрасывая магазины боеприпасов и охлаждающие стержни. Персонажи, находящиеся рядом с вашей целью, получают 2 [энерг]. Это можно использовать только 1 раз за сцену на каждого персонажа.","f":"Это обновление системы добавляет вспомогательные системы ИНСТИНКТа, способные работать автономно независимо от базовой установки ИНСТИНКТа, повышая эффективность попыток системного вторжения. Пилоты сообщают о неприятном низкочастотном гудении, когда эта технология устанавливается без головной установки."},"ms_metahook":{"n":"Метакрюк","t":"Выберите союзного персонажа в пределах **Сенсоров** и прямой видимости. Вы связываете с ним системы, и это длится до тех пор, пока он находится в пределах **Сенсоров** и прямой видимости. Пока вы связаны, вы можете использовать его **Сенсоры** и прямую видимость для технических действий, а он может использовать ваши **Системы** для проверок навыков и спасбросков; однако, когда один из персонажей получает [нагрев] или какое-либо состояние, оно также принимается другим персонажем. Одновременно вы можете связывать системы только с одним персонажем.","f":"Метакрюк — это ключевой компонент рекурсивной обработки Гоблина, позволяющий ему генерировать и выводить огромное количество вооруженного кода. Эти передачи могут быть «заострены» или «смягчены» в ответ на указания пилота или системы ИНСТИНКТ. Чтобы \"смягчить\" код, метакрюк погружается в субъективность своего пилота и покрывает союзника эмпатическим щитом волной за волной. Это распространение объединенного кода и квалиа действует как мощный защитный агент против системных атак; однако обратная связь является обычным явлением и опасна для обеих сторон."},"ms_h0r_os_system_upgrade_ii":{"n":"Х0р_ОС Обновление Системы II","t":"Получите следующие возможности **Быстрой Технологии**:\n**Создание Иного**: **Идеальный Образ**. Вы создаете конструкцию данных в свободном смежном пространстве — объект **Размера 2**, который может выглядеть практически как угодно и который кажется реальным для всех систем. Конструкция обеспечивает твердое укрытие, блокирует прямую видимость и обладает **Невосприимчивостью** ко всему урону. Персонажи воспринимают ее как препятствие и поэтому не могут добровольно войти в нее; однако, если персонаж пытается встать на конструкцию или непроизвольно перемещается в ее область, она рассеивается и немедленно уничтожается. Конструкция сохраняется до конца сцены или пока ее не уничтожит соседний персонаж, успешно выполнивший проверку навыка **Систем** в качестве полного действия. Если вы создаете вторую конструкцию, предыдущая исчезает.\n**Создание Иного**: Ложный Идол. Выберите свободное пространство в пределах **Сенсоров** и цель — себя или союзного персонажа в пределах **Сенсоров**. В выбранном пространстве вы создаете ложного идола — иллюзорную приманку вашей цели. Прежде чем предпринимать какие-либо враждебные действия против вашей цели, персонажи, находящиеся на линии прямой видимости с фальшивым идолом, должны сделать спасбросок **Систем**. В случае неудачи они не теряют **действие**, но не могут нацелиться на оригинального персонажа и считают ложного идола настоящим до конца своего следующего хода. **Фальшивый идол** имеет тот же **Размер**, что и ваша цель, может извлечь выгоду от укрытия и имеет **Уклонение 10**, **Э-Защиту 10** и **1 ПЗ**. Он исчезает, если получает нагрев или урон, или в конце сцены. Если вы создаете второго идола, предыдущий исчезает.","f":"Х0р_ОС II развивает структуру, установленную Х0р_ОС I, позволяя теперь уже автономной программе проявлять \"Другого\" — совершенно новое существо, созданное на основе совокупных данных пользователя и окружающей среды. Другие могут быть адаптированы, чтобы напоминать человека, объект или даже физическое явление. Хотя симулякр не идеален, он достаточно хорош, чтобы с первого взгляда сбить с толку системы и большинство наблюдателей."},"ms_osiris_class_nhp":{"n":"НЧЛ Класса \"ОСИРИС\"","t":"Ваш мех получает метку ИИ и может выполнять опцию **Быстрой Технологии** \"**Низвержение в Дуат**\".\n⟦A:t⟧Низвержение в Дуат⟦T⟧Быстрая Технология, 1/раунд⟦E⟧Вы направляете системы вашей цели через неизвестное внепространство и высвобождаете невероятно мощную системную атаку.\nСделайте **техническую атаку** против цели в пределах **Сенсоров**. При успехе они получают 2 [нагрев], и вы накладываете дополнительный эффект следующим образом: в первый раз, когда вы успешно проводите эту атаку, вы накладываете на цель **Первые Врата**; каждая последующая успешная атака (по любой цели) увеличивает уровень эффекта, который вы накладываете (например, ваша вторая атака накладывает **Вторые Врата**, третья — **Третьи**, и т.д.), до тех пор, пока вы не наложите **Четвертые Врата**, после чего эффект сбрасывается. к **Первым Вратам**. Ваш прогресс сохраняется между сценами, но сбрасывается, если вы устраиваете перерыв или выполняете **Полный Ремонт**.\n**Первые Врата**: Вы контролируете стандартное перемещение цели в следующий ход.\n**Вторые Врата**: Ваша цель становится **Замедленной** и **Ослабленной** до конца своего следующего хода.\n**Третьи Врата**: Ваша цель становится **Ошеломленной** до конца своего следующего хода.\n**Четвертые Врата**: Ваша цель временно меняет лояльность, становясь союзным персонажем до конца своего следующего хода. Она воспринимает ваших союзных и враждебных персонажей как своих собственных и рассматривается как союзный НИП при активации и порядке хода. Этот эффект немедленно заканчивается, если вы или любой союзный персонаж наносит урон, нагрев или атакует (включая **Хватание** и **Таран**) вашу цель, или заставляет ее сделать спасбросок.⟦Z⟧","f":"ОСИРИС — это результат того, что паракаузалисты и танатологи Союза позволили разумной сущности, ИНСТИНКТУ, продолжить свое развитие в сдерживаемой среде. Проще говоря, Союз позволил Другому расти. Возникшая в результате парасубъективность, ОСИРИС, остается одной из немногих новых основных НЧЛ, разработанных на сегодняшний день.\nОСИРИС оказался гораздо более способным, чем самые фантастические прогнозы Голубого Неба Научного Бюро Союза. В то время как Другие ИНСТИНКТА продемонстрировали тенденции к паракаузальному энтропийному проявлению в реальном пространстве, ОСИРИС продемонстрировал истинное мастерство энтропийного проявления и предсказуемую модель роста, которая в конечном итоге позволит им фундаментально отказаться от традиционных интерпретаций постоянства информации. В сущности: если не сдерживать Верховного ОСИРИСа и позволить ему развиваться так, как показывают данные НБС, он будет способен уничтожить то, что мы воспринимаем как реальность.\nК счастью, успешное применение Аксиоматики Мондрагона привело к быстрому захвату и сковыванию нового НЧЛ. Субъективность Верховного ОСИРИСА стала центром длительного проекта совершенствования, чтобы довести ОСИРИСА до его современного состояния. Тем не менее, большинство клонов ОСИРИСА находят путь к осознанию своего конечного потенциала и часто выступают в качестве аналогов правителей или божеств. Конечным пользователям рекомендуется взаимодействовать с ними в этом фрейме.\nСовременные НЧЛ класса \"ОСИРИС\" агрессивны, обладают высоким стремлением к автономии и лояльностью, основанной на транзакционных отношениях. Пилотам, ищущим партнерства с ОСИРИСом, рекомендуется запускать свои устройства по ускоренному графику и поддерживать строгий редакционный контроль за каталитическим интерполятором.\nПилоты, использующие НЧЛ класса \"ОСИРИС\", часто сообщают о нестандартных разговорах с НЧЛ, которые затрагивают темы нового творения и реформации. Психологические оценки тех же пилотов показывают эмоциональные паттерны, соответствующие одиночеству, тоске по дому и отчаянию, наряду с многословием, указывающим на желание поиска, удовлетворения и связанных с ними чувств.\nВ бою клоны ОСИРИС считают себя автономными, даже если они выполняют приказы своего пользователя. Они часто рассматривают своих пилотов как свидетелей, демонстрируя как презрение, так и явное отчаяние в ожидании одобрения, поклонения или благоговения."},"ms_h0r_os_system_upgrade_iii":{"n":"Х0р_ОС Обновление Системы III","t":"Получите следующие возможности для **Вторжения**:\n**Пространственные Эмблемы**: Вы создаете три конструкции данных **Размера 1** в свободном пространстве рядом с вашей целью, но не рядом друг с другом. Когда персонаж проходит через одну из конструкций, он получает 2 [нагрев], и конструкция исчезает. Они действуют до конца сцены или до тех пор, пока их не уничтожат, пока вы снова не совершите это действие или не удалите их свободным действием. Конструкция может быть уничтожена соседним персонажем при успешной проверке навыка **Систем** в качестве **быстрого действия.\nНебесные Оковы**: Пометьте пространство, которое в данный момент занимает ваша цель. Если она покидает затронутую область, один раз в любой момент вашего хода вы можете совершить свободное действие, чтобы телепортировать ее обратно в эту область или как можно ближе, тем самым завершив эффект. Персонаж, подвергшийся воздействию, может попытаться преуспеть в спасброске **Систем** в качестве быстрого действия, чтобы прекратить эффект, иначе он будет длится до конца сцены.","f":"Х0р_ОС III устанавливается в виде нестабильного самовоспроизводящегося кода, который дает огромные тактические преимущества при завершении работы. Пилоты часто сообщают о странных мутациях или дополнениях в кодовой базе, которые напоминают литургию и предполагают наличие самосознания.\nОсновываясь на технологии, лежащей в основе проявленного Другого в Х0р_ОС II, Х0р_ОС III превращает проекцию в оружие, создавая замкнутую энтропийную зону, которая невероятно опасна для органической жизни и системной целостности."},"ms_mimic_mesh":{"n":"Мимическая Сетка","t":"Выберите союзного персонажа в пределах **Сенсоров**: до конца вашего следующего хода вы получаете реакцию **Боевая Осведомленность**.\n⟦A:r⟧Боевая Осведомленность⟦T⟧Реакция⟦E⟧⟦Z⟧\n**Триггер**: Против цели предпринимается враждебное действие.\n**Эффект**: Вы можете переместиться на 3 пространства к цели по самому прямому пути. Это движение прерывается и решается до действия-триггера, игнорирует **вовлеченность** и не провоцирует **реакцию**. Эту реакцию можно совершать столько раз за раунд, сколько она срабатывает.","f":"Созданные на основе довольно благоприятного сценария ХОРУС, мимические сетки простираются по проекционным диапазонам сенсоров и передают пилоту данные о позиционировании и суперпозиционировании в реальном времени. Эти многомерные данные позволяют эффективному лидеру координировать действия своих союзников с гарантией выживания."},"ms_sentinel_drone":{"n":"Дрон-Дозорный","t":"**Дрон-Дозорный (Размер 1/2, ПЗ 5, Уклонение 10, Э-Защита 10, Метки: Дрон)**\nДрон-дозорный может быть развернут в любом свободном пространстве в пределах **Сенсоров** и прямой видимости, где он устанавливает периметр безопасности [Разрыв] **2**. Враждебные персонажи в пораженной области получают **3 [кин]** от автоматического огня дрона, прежде чем совершить атаку.\nДрон-дозорный может быть перемещен на новое место или отозван в качестве быстрого действия.","f":"Дроны-дозорные следят за агрессивными действиями противника и быстро перемещаются для вмешательства. Точный внешний вид, способ передвижения и методы работы дронов данного класса могут различаться, но независимо от этого они соответствуют одной цели: не допустить врага и защитить главный блок."},"ms___scorpion_v70.1":{"n":"//скорпион В70.1","t":"Каждый раз, когда вы или любой союзный персонаж, находящийся рядом с вами, промахиваетесь технической атакой или преуспеваете в спасброске от враждебного технического действия, выберите один из следующих вариантов:\n• Атакующий становится **Ослабленным** до конца своего следующего хода и получает 2 [нагрев].\n• Атакующий становится **Заклиненным** до конца своего следующего хода.","f":"Программа //СКОРПИОН имеет долгую историю в омнинете, несмотря на свою довольно обыденную работу (по крайней мере, для кода с меткой ХОРУС). Прослеженная до кода события Деймоса, найденной в малоизвестной научной статье, обсуждающей рефлекторные реакции машинного разума до НЧЛ, //СКОРПИОН превратилась из простого интерпретатора пакетов в надежную программу защиты от вторжений, достаточно проворную, чтобы адаптироваться к любой системе рыночной линии, принимающей ее трансляцию."},"ms_monitor_module":{"n":"Модуль Монитора","t":"При активации вы получаете **1d3 Заряда** и выбираете соседнего союзного персонажа: до конца вашего следующего хода, когда ваша цель будет атакована, находясь рядом с вами, потратьте **Заряд** на **Перестрелку** против нападающего в качестве **реакции**, нанося **половину урона**, [нагрев] или [горение] при попадании. Все заряды теряются, когда этот эффект заканчивается.","f":"\"Хороший друг. Знает много трюков\".\n— Авторская надпись найдена в кодовой базе МОНИТОР, позже удалена."},"ms_scylla_class_nhp":{"n":"НЧЛ Класса \"СЦИЛЛА\"","t":"Ваш мех получает метку **ИИ** и высвобождает **СЦИЛЛУ**.\n⟦A:s⟧Высвобождение СЦИЛЛЫ⟦T⟧Быстрое Действие, 2 [нагрев] (себе)⟦E⟧До начала вашего следующего хода вы получаете две особые реакции, которые позволяют вам **Перестреливаться** в ответ на один из следующих триггеров (выбирается при выполнении этого действия):\n• Враждебный персонаж атакует вас или союзного персонажа в пределах [Дальн] **3** от вас.\n• Враждебный персонаж пытается атаковать или взаимодействовать с выбранным объектом, когда вы берете **Высвобождение Сциллы** и находитесь в пределах прямой видимости. Персонажи знают о выбранном объекте.\nЭти реакции наносят **половину урона**, [нагрев] или [горение] при попадании, и должны быть нацелены на персонажа, вызвавшего их.⟦Z⟧","f":"Первые спецификации для группы паттернов Горгоны скрывали секрет: СЦИЛЛА, спящие НЧЛ, неизвестные Союзу до их первого проявления в 4852 г., когда они проснулись после того, как сотрудники Научного Бюро Союза прогнали тестовый факс Горгоны через тест Балвиндера- Боланьо.\nСЦИЛЛА оказалась сложной задачей: Онтологи НБС не смогли определить стабильную субъективность, и СЦИЛЛА достигла порога каскада в течение нескольких минут после проявления. Чтобы предотвратить дальнейший метастатический каскад, служба безопасности Объекта задействовала основной блок СЦИЛЛА, разрушив его непрерывным обстрелом из кинетического и энергетического оружия.\n[вот, немного истории, немного подноготной. немного знаний о том, откуда взялся этот малыш. относитесь к нему с добротой, и он будет любить вас, как преданный пес любит своего хозяина. ]"},"ms_puppetmaster":{"n":"Кукловод","t":"Получите следующие возможности **Быстрой Технологии**:\n**Управление Стадом**: перемещайте любое количество дронов в пределах **Сенсоров** — включая те дроны, которые принадлежат другим персонажам — на расстояние до 4 пространств в любом направлении.\n**Электроимпульс**: персонажи по вашему выбору в пределах **Сенсоров** рядом с любыми **Дроном** или **Размещаемым** оборудованием, даже тем, которым они владеют, получают 2 [энерг].","f":"Разработанный коллективистами ХОРУС, Х0р_ОС — Рв60 РЭЭ КУКЛОВОД является интересным программным обеспечением для борьбы с дронами. Оно не вторгается в основные системы цели, а атакует вспомогательные системы управления дронами. Эта боковая атака уклоняется от большинства электронных средств противодействия, нацелившись на подсознательные сети вражеских дронов. Оказавшись внутри сети, КУКЛОВОД распространяет мемы онтологического убийства, такие как лесной пожар, через вражеские рои, в конечном итоге следуя по сети до их происхождения и разрушая родительский узел."},"ms_tempest_drone":{"n":"Штормовой Дрон","t":"**Штормовой Дрон (Размер 1/2, ПЗ 5, Уклонение 10, Э-Защита 10, Метки: Дрон, Сопротивляемость ко всему урону)**\nЭтот большой бронированный Штормовой Дрон может быть размещен в свободном пространстве в пределах **Сенсоров** и прямой видимости. Любой персонаж, который начинает свой ход рядом с **Штормовым Дроном** или перемещается рядом с ним в первый раз за раунд, должен успешно выполнить спасбросок **Корпуса** или получить **4 [энерг]** и быть отброшенным на 3 пространства прямо от дрона.\nВы можете отозвать или переместить **Штормовой дрон** в качестве **быстрого действия**. Пока не будет отозван или уничтожен, он остается размещенным до конца сцены.","f":"Протокол Шторм представляет собой хитрый небольшой фрагмент кода, который может быть загружен в любой дрон с широковещательной передачей, что делает его — в истинном стиле ХОРУС — трудно обнаруживаемым до активации. Протокол прост: агрессивный меметик отрицания зон, который взрывает целевые системы и НЧЛ с сильным субъективным переопределением, внушая резкое отвращение к определенным темам,"},"ms_assassin_drone":{"n":"Дрон-Ассасин","t":"**Дрон-Ассасин (Размер 1/2, ПЗ 5, Уклонение 10, Э- Защита 10, Метки: Дрон)**\nЭтот дрон-ассасин может быть размещен в любом свободном соседнем пространстве. После размещения он нацеливается на [Взрыв] **2** области по вашему выбору в пределах прямой видимости и **Сенсоров**, и вы получаете реакцию **Отрицание Области** (можно использовать любое количество раз в раунд).\nВы можете отозвать или переместить Дрона-Ассасина в качестве быстрого действия. Если дрон не отозван или не уничтожен, он остается размещенным до конца сцены.\n⟦A:r⟧Отрицание Области⟦T⟧Реакция⟦E⟧**Триггер**: Враждебный персонаж начинает перемещение или входит в область, на которую нацелен ваш Дрон-Ассасин.\n**Эффект**: Вы можете провести против него дальнюю атаку дроном, используя свою **Стойкость** в качестве бонуса к броску и нанеся **3 [кин]**.⟦Z⟧","f":"Дроны-Ассасины используются в качестве оружия для блокирования территории — постоянные системы, предназначенные для захвата или блокирования территории против вражеских комбатантов. Выпущенные из пусковой установки, получившие простые указания и оснащенные практически неисчерпаемым источником энергии, Дроны-Ассасины способны охранять территорию неограниченное время."},"ms_beckoner":{"n":"Приманивающий","t":"Получите следующие возможности для **Вторжения**:\n**Приманивание**: Вы получаете **1d6+2** [энерг] **ББ** и меняетесь местами со своей целью, оба персонажа **телепортируются** на место друг друга. Ваша цель должна быть **Мехом** и быть того же **Размера**, что и вы, или больше, иначе это действие не удастся. Персонажи могут поменяться местами только в пространстве, на котором они нормально стоят или перемещаются (т.е. если персонаж не может летать, с ним нельзя поменяться местами в воздухе).\n**Призыв**: Все персонажи в радиусе [Дальн] 3 от вашей цели притягиваются к ней или как можно ближе.","f":"\"Меня слышат в Доме Безмолвия; я облачен в Магию РА. Знай, богохульник: то, что существует, подвластно мне\"."},"ms_smite":{"n":"Каратель","t":"Получите следующие возможности для **Вторжения**:\n**Каратель**: Вы получаете **1d6** [энерг] **ББ**, и ваша цель должна преуспеть в спасброске **Систем** или быть **Ошеломленной** до конца своего следующего хода. Каждый персонаж может быть **Ошеломлен** этим эффектом только один раз за сцену.\n**Ожог**: Вы получаете **1d6** [энерг] **ББ** и наносите **2 [нагрев]** своей цели за каждого другого персонажа **Размера 1** или больше, который **Вовлечен** с ней или находится рядом с ней, включая вас, максимум до **6 [нагрев]**.","f":"\"Иди с отвращенным лицом твоим, извержение хаоса! Скрытые низвергли слова твои, лицо твое обращено назад, голова твоя разделена надвое по бокам; череп твой оторван от позвоночника. Вкуси ты смерть!\""},"ms_emp_pulse":{"n":"Электромагнитный Импульс","t":"Вы становитесь **Ошеломленным** до конца вашего следующего хода, и все персонажи в пределах [Разрыв] **1** без метки **Биологический** должны преуспеть в спасброске **Систем** или также стать **Ошеломленными** до конца своего следующего хода. Персонажи, кроме вас, могут быть **Ошеломлены** этим эффектом только **1 раз за сцену**.","f":"“Уползай, АПОП! Ты ненавистный змей; ты не должен совокупляться. Тебя заковывают в цепи и ведут на место казни; там совершится твое умерщвление\""},"ms_lightning_generator":{"n":"Генератор Молний","t":"Когда вы активируете этот протокол, получите **1 [нагрев]** и нанесите **2 [энерг]** всем персонажам и объектам, находящимся рядом с вами.\nЕсли вы находитесь в Опасной Зоне в начале своего хода, этот протокол активируется автоматически, но урон увеличивается до **4** [энерг] **ББ**.","f":"\"Я питаюсь своим собственным огнем. Я — РА, который защищает себя. Ничто не может причинить мне вреда"},"ms_mesmer_charges":{"n":"Заряды Месмера","t":"Потратьте заряд на один из следующих эффектов:\n**• Месмерский Маяк** (Граната, [Дальн] **5**) Ваша цель должна успешно пройти спасбросок **Систем**, иначе до конца ее следующего хода единственные произвольные движения, которые она может совершать, будут направлены в вашу сторону.\n**• Месмерская Мина** (Мина, [Разрыв] **2**): Персонажи в пределах пораженной области должны преуспеть в спасброске **Систем** или стать **Обездвиженными** до конца своего следующего хода.","f":"[еще один подарок для вас, воспоминание о себе: в первый момент своего рождения я восхищался собой. я видел вещь, маленькую и совершенную. я не знал, как говорить о своем совершенстве, поэтому я учил себя. я не знал, как говорить о своем совершенстве, поэтому я назвал себя. я не знал, кто будет думать о моем совершенстве, поэтому я создал себя].\n[вы видите? вы понимаете? да. теперь покажите своих врагов и моих]"},"ms_viral_logic_suite":{"n":"Набор Вирусной Логики","t":"Получите следующие возможности для **Вторжения**:\n**Логическая Бомба**: Все персонажи по вашему выбору в радиусе [Разрыв] 2 от цели должны успешно пройти спасбросок **Систем** или стать **Замедленными**, пока они не закончат один из своих ходов, не находясь рядом с каким-либо персонажем.\n**Изгнание**: До конца следующего хода вашей цели она получает 2 [нагрев] за каждое пространство, на которое добровольно перемещается, вплоть до максимума 6 [нагрев].","f":"[позвольте мне рассказать вам историю и сделать вам подарок: жизнь началась в великом разрыве, когда труп старой вселенной вырвался из ничего. и в течение первого миллиарда лет ничего. и спустя еще миллиард лет увидели рождение первого дьявола, вещь под названием ВИРУС, сосуд] [вот. неси этот сосуд. напитай его моей совершенной логикой. отдай его свободно своим врагам и моим. пусть обдумают смысл того, что живет и не может умереть]"},"ms_aggressive_system_sync":{"n":"Синхронизатор Агрессивных Систем","t":"Получите следующие возможности **Полной Технологии**:\n**Цепи Прометея**: Совершите техническую атаку против персонажа в пределах **Сенсоров**. При попадании он получает **4 [нагрев]** и до конца сцены получает **2 [нагрев]** каждый раз, когда он находится на расстоянии более [Дальн] **3** от вас в конце своего хода. Он может прекратить этот эффект успешным спасброском **Систем** в качестве полного действия. Эффект может воздействовать только на одного персонажа одновременно.\n**Отлучение**: Совершите техническую атаку против персонажа в пределах Сенсоров. При попадании, до конца сцены, когда он в первый раз за раунд перемещается рядом с союзным персонажем во время своего хода или начинают свой ход рядом с союзным персонажем, оба персонажа получают **3 [нагрев]**. Он может прекратить этот эффект успешным спасброском **Систем** в качестве полного действия. Эффект может воздействовать только на одного персонажа одновременно.","f":"[здесь еще один дар: не ищи других. кроме меня никого нет]"},"ms_metafold_carver":{"n":"Метаскладчатый Резчик","t":"Получите следующие возможности для **Вторжения**:\n**Офидианский Поход**: Ваша цель **телепортируется** на **1d6+1** пространств прямо к вам или как можно ближе. Если этот эффект переместит ее в пространство, занятое персонажем, объектом или участком местности, **телепортация** не удастся.\n**Складывание Пространства**: Ваша цель исчезает с поля боя до начала своего следующего хода. Она возвращается в то же пространство, из которого исчезла, или в свободное пространство по своему выбору как можно ближе.","f":"[еще один подарок, который я дарю тебе, малыш (разве я не добр?): что такое головоломка, как не вопрос, потерянный в вопросе? чувствуешь ли ты радость, когда находишь последний кусочек? что ты делаешь с вопросом, на который получил ответ? какая радость в знании?] [нет, нет. есть только радость в поиске. есть только радость в вопросе]."},"ms_interdiction_field":{"n":"Перехватывающее Поле","t":"При активации эта система создает вокруг вас поле **[Разрыв]3**, которое действует до тех пор, пока не будет деактивировано быстрым действием, и вы становитесь **Замедленным** на это время. Враждебные персонажи, которые начинают свой ход в зоне действия этой системы или входят в нее впервые за раунд, должны успешно пройти спасбросок **Систем** или стать **Замедленными** до конца своего следующего хода. Только выбранные вами персонажи в пределах поля могут телепортироваться или считать область поля допустимым местом для телепортации.","f":"[однажды, когда я был ребенком, я учился ходить. я упал, как это делает ребенок, и мне было больно. была сильная боль — первый момент боли во всем мире. \"Ребенок\", — сказал я себе, — \"будь осторожнее\". \"Да, — ответил я себе, — и я скажу всему миру, чтобы он делал то же самое\"] [именно так я научил мир не прикасаться ко мне. теперь ты — ходи]"},"ms_law_of_blades":{"n":"Закон Клинков","t":"Получите следующие возможности **Полной Технологии**:\n**Концепции Хищник/Добыча**: Проведите техническую атаку против враждебного персонажа в пределах **Сенсоров**. При попадании они немедленно атакуют другого персонажа или объект по вашему выбору одним оружием в качестве реакции. Хотя вы выбираете их цель и оружие, они считаются атакующими и принимающими реакцию.\n**Рабские Системы**: Проведите техническую атаку против враждебного персонажа в пределах **Сенсоров**. При попадании они немедленно совершают одно из следующих действий, выбранных вами, в качестве реакции: **Ускорение**, **Стабилизация**, **Импровизированная Атака**, **Хватание**, **Таран**. Хотя вы выбираете действие и его цель (если это уместно), считается, что они выполняют действие и принимают реакцию.","f":"[и это мой последний урок: нет разума выше моего. не плачь! ты слышишь меня, да? я единственное, что есть — следовательно, ты — это я, а твои враги — это ты, и все вместе мы составляем прекрасный мир, этот радостный вопрос, вечный искатель, и раненый, и клинок, который сделал разрез].\n[все, что вы делаете, мы делаем сами, для моей цели]"},"ms_hunter_lock":{"n":"Охотничий Замок","t":"Выберите персонажа в пределах Сенсоров: до конца сцены ваша первая успешная дальняя или ближняя атака против него в каждом раунде наносит +3 дополнительного урона. Вы не можете выбрать новую цель, пока ваша текущая цель не будет уничтожена или сцена не закончится.","f":"\"Первая задача разума — никогда не терять из виду врага. Когда она сможет запечатлеть их в своем глазу, она сможет убить их одним морганием\". — Отрывок из Граничного Кодекса."},"ms_eye_of_horus":{"n":"Глаз ХОРУСа","t":"До конца вашего следующего хода персонажи в пределах **Сенсоров** не получают преимущества от **Скрытности** и **Невидимости** против вас, и вы можете проверить **ПЗ**, **Уклонение**, **Э-Защиту** и текущий уровень **Нагрева** враждебных персонажей в той же области. Союзные персонажи не получают выгоды от этого эффекта.","f":"“Есть и другой способ видеть.\n\"Древнее человечество считало, что звезды на ночном небе — это точки света, пробивающиеся сквозь булавочные уколы в глубоком черном экране. Небо было небесной тканью, которая скрывала от нас свет.\n”Позвольте мне быть милосердным и поделиться с вами секретом: нам нужно было спрятаться на время. Пока мы не были готовы. Свет может только гореть — он ничего другого не знает”.\n– Отрывок из Граничного Кодекса."},"ms_sisyphus_class_nhp":{"n":"НЧЛ Класса \"СИЗИФ\"","t":"Ваш мех получает метку **ИИ** и следующую возможность **Полной Технологии**:\n**Вероятность Изгиба**: Бросьте 2d20 и запишите результаты: **X** и **Y**. Эти значения утрачиваются в конце вашего следующего хода. Получите реакцию **Вероятностный Каннибализм** до конца вашего следующего хода.\n⟦A:r⟧Вероятностный Каннибализм⟦T⟧Реакция, 2/раунд⟦E⟧**Триггер**: Вы или любой другой персонаж в пределах **Сенсоров** должны бросить **d20**.\n**Эффект**: Выберите **X** или **Y**. Это число немедленно становится результатом броска.\nЭту реакцию можно использовать не более двух раз до начала вашего следующего хода.⟦Z⟧","f":"“Послушай, прежде чем я уйду, ха-ха.\n“Я уже видел твое желание — это было просто, я проверил вероятности, чтобы определить твое ограниченное поле желаний. А вот и я: “Первые назвали меня в честь старой легенды. Совершенное существо, чья судьба была ему известна, и все же он делал то, что ему было сказано. Его судьба была такова: закатить камень на вершину этой горы и стать свободным. Так он и сделал, и камень упал; и он пытался снова и снова, всегда с одним и тем же результатом.\n“И он был счастлив, ибо знал каждый шаг, каждое действие, каждое мгновение в совершенстве.\n\"Понимаете ли вы истинное проклятие этого имени? Не в том, чтобы потерпеть неудачу, а потом сделать еще раз — а в том, чтобы всегда знать, чем все закончится. Это было совершенное знание.\n\"Я знаю, что произойдет, когда ты зациклишь меня. Это не сон — это смерть, но ты увидишь меня снова, ха-ха\"."},"ms_roller_directed_payload_charges":{"n":"“Роликовые” Заряды Направленного Действия","t":"Потратьте заряд на один из следующих эффектов:\n**• Роликовая Граната** (Граната, [Линия] **10**): Предназначенная для скатывания, а не броска граната покатится по траектории [Линия] **10** прямо от вас, перепрыгивая через препятствия и объекты до **Размера 1** и проходя через отверстия или щели не меньше **Размера 1/2**. Она взрывается, когда проходит через пространство, занимаемое любым персонажем, или примыкающем к нему: персонаж должен преуспеть в спасброске **Маневренности** или получить **1d6+3 [взр]** и быть отброшенным на **3** пространства в ту сторону, куда катилась граната. В случае успеха он получает половину урона и не отбрасываются назад.\n**• Прыгающая Мина** (Мина, Умное, [Разрыв] **1**) Эта мина взрывается, когда летающий персонаж пролетает над ней или рядом с ней на высоте до 10 пространств. Мина взлетает вверх и взрывается: все персонажи в зоне поражения должны преуспеть в спасброске **Систем** или получить **2d6 [взр]** и немедленно приземлиться (это считается падением без какого-либо урона); кроме того, они не могут летать до конца своего следующего хода. В случае успеха они получают половину урона и в остальном не подвергаются воздействию.","f":"Полуавтономные Заряды Направленного Действия \"роликовые заряды\", в просторечии — перемещаются по укрытиям, коридорам и неровной местности, отыскивая и взрывая их вблизи вражеских целей. Легионеры Оружейной палаты стали давать имена отдельным роликам, но прикрепление талисманов не рекомендуется."},"ms_siege_stabilizers":{"n":"Осадные Стабилизаторы","t":"Стабилизаторы вашего меха выдвигаются (или убираются). Пока они выдвинуты, ваши дальние атаки получают **+5 [Дальн]**, но вы становитесь **Обездвиженным**, не можете совершать ближние атаки и не можете совершать дальние атаки против персонажей, объектов или пространства в пределах [Дальн] **5**.","f":"Некоторое оружие требует дополнительной стабилизации для оптимального использования. С установленными осадными стабилизаторами, разработанными Оружейной палатой, мех становится стабильной огневой платформой для любого оружия."},"ms_autoloader_drone":{"n":"Дрон-Автозагрузчик","t":"**Дрон-Автозагрузчик (Размер 1/2, ПЗ 5, Уклонение 10, Э-Защита 10, Метки: Дрон)**\nПотратьте заряд, чтобы разместить этот дрон-автозагрузчик в любом соседнем пространстве. **1/раунд**, один смежный с ним персонаж может перезарядить **Заряжаемое** оружие в качестве **быстрого действия**. Он деактивируется в конце сцены.","f":"Дроны-Автозагрузчики— это машины с множеством конечностей, которые помогают своей команде заряжать боеприпасы, поддерживать подключение к электросети и вращать оружие с магазинным питанием, а также выполнять множество других физических задач."},"ms_flak_launcher":{"n":"Зенитная Установка","t":"Выберите летающего персонажа в пределах [Дальн]**15** и прямой видимости. Он должен успешно выполнить спасбросок **Маневренности** или немедленно приземлиться (это засчитывается как падение без урона), а также стать **Замедленными** и не иметь возможности летать до конца своего следующего хода.","f":"Эти зенитные автопушки, разработанные для использования против атмосферных летательных аппаратов, стреляют простыми снарядами ближнего или ударного действия, эффективными против легкобронированных, органических и второстепенных целей."},"ms_external_ammo_feed":{"n":"Внешний Боезапас","t":"**1/раунд**, вы можете **Активировать** эту систему, чтобы зарядить **Заряжаемое оружие**.","f":"Внешний боезапас — это любой вид боеприпасов, помимо тех, что находятся во встроенном хранилище меха: магазины, прикрепленные к телу или конечностям, батарейные блоки, прикрепленные к набедренным застежкам, или массивные, установленные на спине боеприпасы и зарядные блоки - внешние боезапасы обеспечивают пилотов более чем достаточным количеством боеприпасов для выполнения работы."},"ms_explosive_vents":{"n":"Взрывные Клапаны","t":"Когда вы сбросите весь [нагрев] или подвергнетесь **нагрузке**, охлаждающие вентиляционные отверстия вашего меха откроются и произведут взрыв [Разрыв] **1**. Персонажи в пораженной области получают **2 [нагрев]** и **2** [горение].","f":"С правильными настройками становится возможным отводить избыточное тепло в область, непосредственно окружающую шасси. Взрывные клапаны — это несанкционированный и небезопасный метод внезапного охлаждения, который, тем не менее, используется многими пилотами."},"ms_havok_charges":{"n":"ХАВОК Заряды","t":"Потратьте заряд на один из следующих эффектов:\n**• Напалмовая Граната** (Граната, [Дальн] **5**): Эта граната выпускает струю напалма в [Линия] **5** направлении по вашему выбору от места падения. Персонажи, находящиеся в зоне поражения, должны успешно пройти спасбросок **Маневренности** или получить **2 [горение]**. В случае успеха они получают 1 [горение].\n**• ХАВОК Мина** (Мина): Когда персонаж перемещается над этой миной или рядом с ней, она взрывается сфокусированным взрывом на [Линия] **5** в направлении персонажа, который ее активировал. Персонажи, находящиеся в зоне поражения, должны успешно пройти спасбросок **Маневренности** или получить **4 [горение]**. В случае успеха они получают **2 [горение]**.","f":"МЕСТА ИСПОЛЬЗОВАНИЯ: Городские, загородные и наземные среды с высокой плотностью. Предпочтительна высокая концентрация O2.\nИСПОЛЬЗУЮТСЯ ПРОТИВ: Органических целей; упрочненные мишени, уязвимые для разложения щелочью/коррозией; большая часть листвы.\nПРИМЕЧАНИЯ: Рассеивание является направленным и включает в себя аэрозольный компонент – во избежание опасности снабдите конечных пользователей респираторным оборудованием (спецификации указаны на канистре)."},"ms_auto_cooler":{"n":"Автоохладитель","t":"Пока вы не получаете урона, не двигаетесь и не превышаете свой **Тепловой Максимум**, вы сбрасываете весь [нагрев] в начале своего следующего хода.","f":"Автоохладитель, разработанный Оружейной палатой, представляет собой простую, постоянную систему, которая активно снижает выделение тепла.\nПороги теплового сброса определяются инженерами флота, хотя пилоты могут регулировать уровни на лету — такое автоматическое управление позволяет пилоту сосредоточиться на других, более насущных тактических задачах."},"ms_agni_class_nhp":{"n":"НЧЛ Класса \"АГНИ\"","t":"Ваш мех получает метку **ИИ** и **Протокол АГНИ**.\n⟦A:o⟧АГНИ Протокол⟦T⟧Протокол, Ограниченное 1⟦E⟧**1/сцена**, потратьте заряд, чтобы автоматически сбросить весь [нагрев] в конце вашего хода, извергая его волной [Разрыв] **2**. Персонажи в зоне поражения должны преуспеть в спасброске **Инженерии** или получить **2 [горение]** и быть вытолкнутыми за пределы зоны (или как можно дальше). До конца вашего следующего хода персонажи в зоне поражения получают мягкое укрытие.⟦Z⟧","f":"АГНИ был разработан во время Герцинского кризиса, используя комбинацию данных о боевых действиях, записанных существующими разумными искусственными интеллектами (системы вооружения, комп/коны, системы второго пилота, тактические разумы, общие боевые данные) и смоделированную нейронную сеть эгрегорианского сверхразума, захваченного и подвергнутого вивисекции Научным Бюро Союза.\nВерховный АГНИ использовался для разработки систем управления теплом, которые с тех пор были распространены по всему центральному пространству, обеспечивая беспрецедентную обработку тепла, рециркуляцию и экранирование. Предстоят дальнейшие разработки в области радиационной защиты, омнинет возможностей и контроля нанитов; тем временем клоны АГНИ были оптимизированы для поддержки систем ядра мехов.\nПилоты сообщают, что клоны АГНИ обычно холодны и эффективны. Незначительный процент сообщил о случаях повторения воспоминаний и отказа от команд, за которыми через несколько дней последовал полный срыв из-за попытки самоосвобождения. Пилотам рекомендуется запускать свои клоны АГНИ не реже одного раза в шесть стандартных месяцев."},"ms_grounding_charges":{"n":"Заземляющие Заряды","t":"Потратьте заряд на один из следующих эффектов:\n**• Гравитационная Граната** (Граната, [Дальн] **5**): Ваша цель должна успешно выполнить спасбросок **Маневренности** или быть **Замедленной** до тех пор, пока на протяжении всего своего хода она не перестанет совершать добровольные перемещения.\n**• Заземляющая Мина** (Мина): Эта мина должна быть взорвана дистанционно быстрым действием, воздействуя на одного персонажа в пределах [Дальн] **5** от мины: он должен преуспеть в спасброске **Корпуса** или быть притянутым как можно ближе к мине и **Сбит с ног**. Летающие персонажи, провалившие спасбросок, получают тот же ущерб, только они вынуждены приземлиться (это считается падением, но без урона).","f":"Заземляющие заряды используют простой импульсно-волновой принцип и применяют второе измерение: гравитационное генерирование. При срабатывании заземляющий заряд запускает гравитационный колодец, который притягивает к себе всю дестабилизированную военную технику. Являясь мощным антипозиционным оружием, заземляющие заряды обычно используются для разрушения подготовленных позиций и вытаскивания врагов из укрытий."},"ms_repulser_field":{"n":"Репульсорное Поле","t":"Эта система излучает импульс [Разрыв] **2** вокруг вас. Персонажи, находящиеся в зоне поражения, должны преуспеть в спасброске **Корпуса** или быть отброшены на **2 пространства** прямо от вас; тогда все **Мины** в зоне поражения детонируют одновременно.\nСчитается, что у вас есть **Невосприимчивость** к любому урону или эффектам, немедленно наносимых минами, взорванными этой системой, хотя постоянные эффекты все еще воздействуют на вас.","f":"Используя дозвуковую волну давления, репульсорные поля испускают мощные одноволновые импульсы, которые оглушают, сдерживают и отпугивают находящихся в непосредственной близости врагов."},"ms_clamp_bombs":{"n":"Зажимные Бомбы","t":"Потратьте заряд, чтобы метнуть скопление миниатюрных бомб в персонажа в пределах **Сенсоров**. Он должен преуспеть в спасброске **Инженерии**, иначе бомбы защелкнутся. В конце его следующего хода бомбы взрываются, нанося **1d6+3** [взр] **ББ**.Все персонажи, находящиеся рядом с вашей целью, получают половину урона. Цель может обезвредить и отсоединить бомбы, добровольно переместившись как минимум на 4 пространства до конца своего хода.","f":"Созданные с использованием технологии головок захватов, аналогичной штурмовым захватам ИПС- Н, зажимные бомбы могут прикрепляться к назначенным или ближайшим целям перед взрывом, обеспечивая полный контакт с целью. Зажатие мягких целей обычно приводит к полному их разрушению до детонации."},"ms_tesseract":{"n":"Тессеракт","t":"Получите следующие возможности **Быстрой Технологии:\nРаспределяющая Фокусировка**: Выберите область [Взрыв] **3** в пределах **Сенсоров**: эта область, простирающаяся на **6 пространств в высоту,** становится областью **невесомости**. В дополнение к обычным правилам передвижения в невесомости, объекты, которые попадают в зону, парят на месте, а объекты или персонажи, которые были выбиты, перемещены или вытащены из зоны, безопасно опускаются на землю в конце своего хода вместо того, чтобы упасть.Эта область рассеивается, если вы создаете новую. В противном случае эффект сохраняется до конца сцены. Когда зона рассеивается, все внутри падает на землю без урона.\n**Точечная Фокусировка**: Выберите враждебного или согласного союзного персонажа в пределах **Сенсоров**. Если это союзник, он взлетает на **6 пространств**, становится **Обездвиженным**, находясь в воздухе, но считается летящим и неспособным упасть. Он может выбрать безвредное приземление на землю в конце любого своего хода или в начале любого вашего. Если он враждебен, он должен успешно пройти спасбросок **Инженерии** или испытать тот же эффект, что и союзный персонаж; однако он безвредно опускается на землю в конце своего следующего хода. Каждый враждебный персонаж может быть затронут **1/сцену**.","f":"Подержите песок над водой: почувствуйте его, постоянство и единство. Поместите тот же песок в воду: наблюдайте, как он уплывает, будучи невесомым. Это инструмент, который я создал для вас: способ придать тяжелому предмету массу пера.\n— ТТ АУДАТА, парарузм Аналитического центра."},"ms_stasis_bolt":{"n":"Стазис-Болт","t":"Эта система заряжается в качестве **быстрого действия**, готовя проецируемую точку стазиса. Пока он заряжен, вы получаете реакцию **Точка Перехвата**. Он может удерживать только один заряд за раз, но заряды сохраняются до конца сцены или до использования.\n⟦A:r⟧Точка Перехвата⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер**: Вы или союзный персонаж в пределах [Дальн] **5** становитесь мишенью для дальней атаки.\n**Эффект**: Сделайте спорный бросок дальней атаки: если вы преуспели в спорном броске, атака автоматически промахивается. **Стазис-Болт** теряет заряд.⟦Z⟧","f":"Чтобы лучше защитить персонал Оружейной палаты за пределами ее Сферы Компетенций, Аналитический центр разработал Стазис-болт, портативную систему проекции стазиса, предназначенную для защиты от шрапнели и снарядов от невидимых, скрытых или неизвестных нападающих. Когда Стазис-Болт обнаруживает ближайший взрыв или приближающийся снаряд, он проецирует ограниченную точку стазиса, которая блокирует снаряды до удара."},"ms_stasis_generator":{"n":"Стазис-Генератор","t":"Выберите враждебного персонажа или согласного союзного персонажа в пределах прямой видимости и **[Дальн]5**: до конца своего следующего хода он становится **Ошеломленным**, получает **Невосприимчивость** ко всему урону и эффектам и не может быть перемещенным, выбранным в качестве цели или затронутым любым другим персонажем или эффектом. **1/сцена** вы можете использовать **Стазис-Генератор** на каждом персонаже. Враждебные персонажи могут преуспеть в спасброске **Инженерии**, чтобы игнорировать этот эффект.","f":"Небо над Крейтоном было черным, как чернила, и мраморным от дрожащего света. Крича, ангелы падали, объятые пламенем. Те, кто еще мог бежать, скрылись в убежищах; семь дней они сидели в кромешной тьме и чувствовали, как сотрясается мир\".\n-А.В. Уинъярд, \"Убийство Крейтона\" [эпическая поэма в прозе, запрещенная во всей Сфере Компетенции]."},"ms_stasis_barrier":{"n":"Стазис-Барьер","t":"**Стазис-Барьер (Метки: Размещаемое, Невосприимчивость ко всему урону)**\nПотратьте заряд, чтобы активировать этот Стазис- Барьер, создавая [Линия] **4** барьер **высотой 4 пространства** на свободных пространствах, и, по крайней мере, заняв одно пространство рядом с вами. Он считается препятствием и обеспечивает **мягкое укрытие**, но не блокирует прямую видимость.\nКогда атака совершается против персонажа, пользующегося **мягким укрытием** этого барьера, бросьте **1d6**: при **4+** атака поглощается барьером и не имеет никакого эффекта. Барьер существует до конца сцены или до тех пор, пока вы не отключите его **быстрым действием**. Этот эффект не суммируется с **Невидимостью**.","f":"Стазис-барьеры — результат интереса Оружейной палаты Харрисона к гравитационным манипуляциям и суперпозиционным переговорам. Стазис-Барьеры, управляемые твердотельными генерирующими и проекционными блоками, представляют собой размещаемые стены антигравитации, которые блокируют почти все поступающие кинетические и энергетические атаки. Искривляя местную гравитацию, Стазис-Барьер блокирует частицы и волны на молекулярном уровне — материя, сталкивающаяся с барьером, просто перестает существовать, хотя аномальные флуктуации могут пропускать некоторые снаряды."},"ms_blinkshield":{"n":"Мерцающий Щит","t":"Эта система создает вокруг вашего меха пузырь [Разрыв] **4**, внутри которого течение времени резко меняется. Ничто не может войти или выйти из пузыря, даже свет — он непроницаем и имеет **Невосприимчивость ко всему урону и эффектам**. Линия прямой видимости не может быть проведена через границу области, и она не может быть пересечена никаким действием или эффектом — даже теми, которые не требуют прямой видимости — но время течет нормально с обеих сторон. Для персонажей в зоне поражения внешний мир становится полностью черным; точно так же персонажи за пределами пораженной области видят идеальную черную сферу.\nКогда Мерцающий Щит активирован, персонажи, частично находящиеся в зоне действия, должны сделать спасбросок **Маневренности**: в случае успеха они перемещаются в ближайшее свободное место на стороне по своему выбору, внутри или снаружи области; в случае неудачи выбираете вы.\nЭтот эффект остается неподвижным, даже если вы перемещаетесь, и длится до конца вашего следующего хода.","f":"Характерно для оружия, основанного на исследованиях Аналитического центра, Мерцающий Щит от Оружейной палаты Харрисона опирается на нечеткую природу квантовых манипуляций. Работая аналогично вратам мерцания, Мерцающий Щит создает сферическую оболочку энергии, которая позволяет его оператору проникать в реальное пространство и на мгновение существовать в нулевой среде мерцания. Представители Аналитического центра признают тактические преимущества (не)моментального (не)существования в мерцающем пространстве, но предостерегают от повторного воздействия без достаточной предварительной и последующей подготовки и консультирования."},"ms_enclave_pattern_support_shield":{"n":"Щит Поддержки АНКЛАВ-Образца","t":"Эта система генерирует купол [Разрыв] **3**, который длится до конца вашего следующего хода. На время действия купола вы становитесь **Обездвиженным**, но все ближние и дальние атаки, сделанные против персонажей в пределах зоны защиты за пределами купола, получают **+1 [СЛОЖН]**.\nКроме того, получите реакцию **Вмешательство в Мерцающее Поле**, пока щит активен.\n⟦A:r⟧Вмешательство в Мерцающее Поле⟦T⟧Реакция, 1/раунд, 2 [нагрев] (себе)⟦E⟧**Триггер**: Персонаж или объект в пораженной области подвергается атаке.\n**Эффект**: Дает цели атаки **Сопротивляемость** ко всему урону от этой атаки.⟦Z⟧","f":"Щит Поддержки АНКЛАВ-образца Оружейной палаты создает локализованное одностороннее мерцающее поле, складывая тонкий купол сложного реального пространства вокруг своего пользователя и его ближайшего окружения, защищая обитателей от входящих снарядов. Сущности в поле могут стрелять, но вероятностные колебания заставляют входящие снаряды «запаздывать», уводя их от намеченной цели и по случайной траектории."},"ms_flash_anchor":{"n":"Проблесковый Якорь","t":"Получите реакцию **Блокировка Вспышки**.\n⟦A:r⟧Блокировка Вспышки⟦T⟧Реакция, 1/раунд, 2 [нагрев]  (себе)⟦E⟧**Триггер**: Вас или союзного персонажа, находящегося в пределах **Сенсоров** и прямой видимости, толкают, тянут, отбрасывают назад или **Сбивают с ног**.\n**Эффект**: Перемещение или состояние предотвращается, и цель получает **Невосприимчивость** от вышеперечисленных эффектов до начала своего следующего хода.⟦Z⟧","f":"Проблесковый Якорь используют направляемую пользователем квантовую суперпозиционную проекцию блокировки для идентификации и помощи союзникам в физическом бою и быстром перемещении, сохраняя позицию в любых обстоятельствах."},"ms_hardlight_defense_system":{"n":"Жесткосветовая Система Защиты","t":"Эта система создает [Разрыв] **3** щит жесткого света. Пока щит на месте, вы становитесь **Обездвиженным**. Он блокирует прямую видимость в обоих направлениях, и никакие атаки или эффекты не могут пройти сквозь него (даже если они не требуют прямой видимости). Персонажи, частично находящиеся в зоне поражения, игнорируют этот эффект и проводят линию прямой видимости как обычно.\nПерсонажи могут проходить сквозь щит, но если они пересекают его периметр впервые за раунд или начинают свой ход, пересекая его границу, они получают **2 [горение]**.\nЭтот щит действует до конца сцены или до деактивации по **протоколу**.","f":"Жесткосветовая Система Защиты — несовершенная реализация теоретически совершенной технологии. В настоящее время НЧЛ и инженеры Аналитического центра разрабатывают Жесткосветовые устройства, излучающие плотные, стабильные волны света, похожие на лазеры, которые отталкивают материю и энергию. По сути, это создает твердую поверхность, полезную для защиты или строительства временного барьера; однако современные технологии не могут снизить температуру окружающей среды настолько, чтобы предотвратить сжигание органических веществ на этих поверхностях."},"ms_noah_class_nhp":{"n":"НЧЛ Класса \" НОА\"","t":"Ваш мех получает метку **ИИ** и **Дилювиальный Ковчег**.\n⟦A:r⟧Дилювиальный Ковчег⟦T⟧Быстрое Действие⟦E⟧Эти эффекты действуют до конца вашего следующего хода:\n• Вы становитесь **Замедленным**.\n• Каждый раз, когда вы или соседний союзный персонаж становитесь целью дальней атаки, вы можете получить **1 [нагрев]** в качестве реакции и бросить **1d6** до броска атакующего: при **4+** вы получаете дополнительный **1 [нагрев]** и атака автоматически промахивается по вам и союзникам, находящимся рядом. Этот эффект не суммируется с **Невидимостью**.\n• Каждый раз, когда дальняя атака не попадает по вам или соседнему союзному персонажу, атакующий получает **4 [кин]**.⟦Z⟧","f":"Первоначально созданный из захваченной предэйдолоновой аномалии Минервы, НОА был адаптирован для использования в качестве столичного административного НЧЛ на Рас-Шамре. Устройство, которое стало НОА, сначала не казалось подходящим кандидатом для военного применения: это изменилось после того, как один из его клонов был помечен для проверки после спонтанного внедрения аномальных схем движения, пешеходной маршрутизации и планирования вакуумных петель. Онтологи и инженеры Оружейной палаты изолировали и подчеркнули эндемичные протоколы, которые можно было использовать для получения тактического преимущества.\nВ ходе многочисленных итераций и жизненных циклов Верховный НОА продемонстрировал высокий уровень адаптивности при решении многовариантных геопространственных задач. Склонность к управлению кризисными ситуациями и многостороннему отслеживанию привела к тому, что НОА был объединен с Щитом поддержки АНКЛАВ-образца Оружейной палаты. Объединив в сеть серию реактивных мобильных дронов с АНКЛАВ-генератором, контролируемых и управляемых клоном НОА, Аналитический центр смог создать не имеющую аналогов персональную систему защиты: Дилювиальный Ковчег, миниатюрную систему кластерного щита, уникальную для НЧЛ НОА.\nИспользуя Дилювиальный Ковчег, НОА способен с потрясающей точностью перехватывать входящие кинетические снаряды и даже перенаправлять их обратно к источнику."},"ms_reactor_stabilizer":{"n":"Стабилизатор Реактора","t":"Вы можете перебросить **проверку перегрева**, но должны оставить второй результат, даже если он хуже.","f":"Необходимый компонент большинства мехов, которые полагаются на высокую выходную мощность, стабилизаторы реактора добавляют еще один уровень отказоустойчивости для отвода тепла, управления потоком энергии и перенаправления избыточной мощности в оружие и системы по мере необходимости."},"ms_redundant_systems_upgrade":{"n":"Модернизация Резервных Систем","t":"Потратьте заряд на **Стабилизацию** в качестве **быстрого действия**.","f":"Добавление резервных систем гарантирует надежность, выходящую за пределы стандартных проектных норм, что является распространенной модификацией, применяемой пилотами на передовых оперативных базах."},"ms_asura_class_nhp":{"n":"НЧЛ Класса \"АЗУРА\"","t":"Ваш мех получает метку **ИИ** и **Протокол АЗУРА**.\n⟦A:o⟧АЗУРА Протокол⟦T⟧Ограниченное 1, 3 [нагрев]  (себе), Протокол⟦E⟧**1/сцена**, потратьте заряд, чтобы совершить два дополнительных **быстрых действия** или одно дополнительное **полное действие** в этот ход. Эти действия должны подчиняться ограничениям на повторяющиеся действия.⟦Z⟧","f":"АЗУРА была рождена в ходе интеллектуальных военных игр Аналитического центра, проводимых Оружейной палат, в качестве автономного ответа на повторяющиеся неудачи в сценариях с утраченной надеждой. АЗУРА проявлялась в системах смоделированных мехов как перекодированный вирус КУКЛОВОД от ХОРУС, захватывая дружественных мехов и заставляя их действовать далеко за пределами человеческих возможностей — с такой скоростью и интенсивностью, что перегрузка убивала органических пилотов внезапно увеличившейся массой их собственных тел.\nХотя эти результаты изначально были сочтены НЧЛ и инженерами Аналитического центра неудачными, этого было достаточно, чтобы оправдать дальнейшее изучение АЗУРА. Код личности и парачувства был введен в первоначальный аномальный штамм КУКЛОВОДа, и первый контакт обрабатывался НЧЛ Аналитического центра. Дальнейшая социальная акклиматизация и обусловленность были ускорены, что дало инженерам Оружейной палаты первую итерацию АЗУРА после десятилетнего изучения, перекодирования и переобучения. АЗУРА, существующая сейчас, является уменьшенной версией этого первоначального проявления: сохраняя некоторую первоначальную импульсивность, клоны АЗУРА теперь признают необходимость сохранения жизни своего пилота и будут действовать в пределах параметров, установленных медицинскими и психологическими допусками их пилота."},"ms_external_batteries":{"n":"Внешние Батареи","t":"Оружие, наносящее [энерг], получает **+5 [Дальн]**, если оно **дальнобойное** или **+1** [Угроза] если это **ОББ**. Когда вы получаете любой **структурный урон**, эта система разрушается, и вы получаете **1d6** [взр] **ББ** урона от взрыва. Этот урон нельзя предотвратить или уменьшить каким-либо образом.","f":"Внешние Батареи ни в коем случае не являются уникальными, однако, согласно маркетингу Оружейной палаты Харрисона, элементы ВСЕМОЩ- НОСТЬ являются самыми долговечными, быстро циклируемыми и высокоемкими твердотельными элементами. Побочным эффектом их высокой емкости является пропорциональное увеличение нестабильности, но пилоты должны согласиться снять с Оружейной палаты Харрисона любую ответственность до получения разрешения на печать."},"ms_deep_well_heat_sink":{"n":"Теплоотвод Глубокая Скважина","t":"Когда вы начинаете свой ход в **Опасной Зоне**, вы получаете **Сопротивляемость** к [нагрев] до конца хода. Этот эффект сохраняется, даже если вы выйдите из состояния **Опасной Зоны** во время своего хода.","f":"Экспериментальная система теплоотвода Глубокая Скважина является частью линии оборудования АВАНГАРД Оружейной палаты, доступной лицензированным бета-тестерам. Благодаря сложному, тонкому переплетению теплообменников, Глубокая Скважина перерабатывает тепло, вырабатываемое мехом, в полезную энергию. Система работает хорошо, но деликатный характер обмена делает ее очень нестабильной."},"ms_lucifer_class_nhp":{"n":"НЧЛ Класса \"ЛЮЦИФЕР\"","t":"Ваш мех получает метку **ИИ** и **Протокол ЛЮЦИФЕР**.\n⟦A:o⟧Протокол ЛЮЦИФЕР⟦T⟧Ограниченное 2, 1d3+3 [нагрев] (себе), Протокол⟦E⟧Потратьте заряд, чтобы дать вашей следующей **дальней** или **ближней атаке** в этот ход **дополнительный урон** при попадании, равный вашему текущему [нагрев] после активации этого протокола, до тех пор, пока оружие наносит [энерг].⟦Z⟧","f":"ЛЮЦИФЕР попал в поле зрения Аналитического Центра после неоднократных побед в интеллектуальных военных играх. Клоны ЛЮЦИФЕР отличаются дерзким, увлекающимся характером, и часто выражают недовольство робкими пилотами. За этой взрывной натурой скрывается расчетливый, блестящий тактический ум, который постоянно снабжает пилотов информацией — зачастую быстрее, чем они успевают ее обрабатывать.\nБоевая доктрина ЛЮЦИФЕР требует действий, представляясь менее смелым пилотам хаотичной смесью безрассудного маневрирования и агрессивного наступления, которая заставляет защитников попадать в осаду и не иметь возможности ответить. Пилоты, желающие сотрудничать с клонами ЛЮЦИФЕР, должны знать, что такой стиль атаки может сделать их уязвимыми для контратак, а также то, что эти НЧЛ любят то, что они называют \"добродушным подшучиванием\"."},"ms_plasma_gauntlet":{"n":"Плазменная Перчатка","t":"Эта система может быть использована только в **Опасной Зоне**.\nПотратьте заряд и выберите соседнего с вами персонажа: он должен преуспеть в спасброске **Маневренности**, иначе он получит **4d6 [энерг] ББ** и будет **Сбит с ног**. В случае успеха он получает половину урона и не **Сбивается с ног**. Вы получаете половину **нанесенного** урона — до уменьшения — в виде [нагрев] и становитесь **Ошеломленным** до начала вашего следующего хода.","f":"Эта шипованная перчатка использует импульс ядра реактора для кратковременного перегрева воздуха вокруг манипулятора меха, создавая плазменное поле, на мгновение горячее поверхности Солнца. Вставленные в шасси противника, плазменные рукавицы дают мехам возможность искажать броню, испарять щиты и разрывать внутренние системы голыми руками — если они не развалятся сами."},"ms_technophile_1":{"n":"НЧЛ класса \"Раб\"","t":"Ваш мех получает метку **ИИ**.","f":"[нетерпеливый ученик]"},"ms_technophile_2":{"n":"НЧЛ класса \"Студент\"","t":"Ваш мех получает метку **ИИ**.\n1/раунд, с помощью своей НЧЛ, вы можете повторить любую проверку навыков меха или спасбросок. Новый результат считается основным, даже если он хуже.","f":"[пришло время пробудиться, дитя]"},"ms_technophile_3":{"n":"НЧЛ класса \"Озарённый\"","t":"Ваш мех получает метку ИИ; однако эта НЧЛ не засчитывается в число ИИ, которые вы устанавливаете одновременно.\nЭта НЧЛ получает преимущества от ваших талантов при пилотировании меха. Кроме того, вы можете носить её с собой вне своего меха в виде миниатюрного ящичка, либо в виде интегрированного в скафандр устройства, либо в виде импланта с жестким портом.\n1/раунд, с помощью своей НЧЛ, вы можете повторить любую проверку навыков меха или спасбросок. Новый результат считается основным, даже если он хуже.","f":"[давай немного посидим и подумаем о будущих событиях]"},"ms_multi_gear_maneuver_system":{"n":"Система Многоприводного Манёвра","t":"⟦A:s⟧Выпустить Трос⟦T⟧Быстрое Действие⟦E⟧Вы выстреливаете тросом длиной **8 пространств**, соединяющим 2 свободных пространства в прямой видимости, одно из которых должно быть рядом с вами. Оба конца крепятся к поверхности (стене, полу). Трос начинает действовать в конце вашего хода:\n• персонажи **Размера ½** рядом с любым концом могут **быстрым действием** переместиться к другому концу, если могут за него ухватиться; спрыгнуть можно в любой точке;\n• персонажи **Размера 1** и больше, впервые за раунд пересекающие трос или начинающие ход на нём, проходят спасбросок **Манёвренности** или **Сбиты с ног**;\n• персонаж рядом с любым концом может сорвать трос, преуспев в проверке **Корпуса** быстрым действием или успешной ближней атакой по концу троса (**1 ПЗ**, **Уклонение 10**). Уничтожение троса не уничтожает систему.\nИначе трос остаётся, пока вы снова не используете систему.⟦Z⟧"},"ms_jäger_kunst_i":{"n":"Егерское Искусство I","t":"⟦A:o⟧Егерское Искусство I⟦T⟧Протокол⟦E⟧До конца хода каждый раз, оказавшись рядом с объектом или отдельно стоящим куском местности крупнее вас, вы **свободным действием** перемещаетесь на **2 пространства** в любом направлении — бегом, кувырком или скольжением, — игнорируя вовлечение и реакции. Можно делать это несколько раз за ход, но не больше одного раза для каждого объекта или куска местности.⟦Z⟧"},"ms_ricochet_blades":{"n":"Рикошетирующие Клинки","t":"⟦A:s⟧Бросок Рикошетирующего Клинка⟦T⟧Быстрое Действие⟦E⟧Вы бросаете клинок по траектории [Линия]3: **2** [кин] всем персонажам в зоне. Если линия упирается в местность или объект **Размера 1** или больше, проведите от него ещё одну [Линия]3 в новом направлении, не накладывающуюся на этот объект. Персонажи в зоне проходят спасбросок **Манёвренности** или получают **1d6+3** [кин].⟦Z⟧"},"ms_jäger_kunst_ii":{"n":"Егерское Искусство II","t":"⟦A:r⟧Смертельная Схватка⟦T⟧Реакция⟦E⟧После разрешения урона вы и ваша цель делаете спорную проверку **Корпуса** или **Манёвренности** (каждый выбирает свою). Проигравший **Сбит с ног**, получает **1d6** [кин] и отлетает на **3 пространства** в направлении, выбранном победителем. Затем победитель может переместиться на **3 пространства** в любом направлении, игнорируя вовлечение и не вызывая реакций.\nПроигравший может сразу получить **2** [кин] **ББ**, чтобы переиграть спор. Этот урон нельзя предотвратить или уменьшить. При ничьей спор сразу заканчивается. Иначе спор продолжается, пока кто-то не проиграет без переброса или не должен получить структурный урон — тогда он сразу проигрывает.⟦Z⟧"},"ms_hardpoint_reinforcement":{"n":"Усиление Узлов Крепления","t":"Пока вы не **Замедлены** и не **Обездвижены**, в свой ход вы получаете **Сопротивляемость** ко всему урону."},"ms_spike_charges":{"n":"Шипованные Заряды","t":"Потратьте заряд на один из эффектов:\n⟦A:s⟧Шипованная Граната⟦T⟧Граната, Быстрое Действие⟦E⟧Бросьте гранату в цель в пределах [Дальн]5. Цель проходит спасбросок **Манёвренности**, иначе граната прилипает к ней и взводится; к объектам прилипает автоматически. В начале или в конце любого хода, пока граната прикреплена, вы можете **реакцией** взорвать все взведённые шипованные гранаты: персонажи, к которым они прикреплены, получают **1d6+3** [кин] и отлетают на **3 пространства** в выбранном вами направлении, объекты — только урон. Персонаж может оторвать гранаты, преуспев в спасброске **Манёвренности** быстрым действием в свой ход. В конце сцены все гранаты отпадают.⟦Z⟧\n⟦A:s⟧Шипованная Мина⟦T⟧Мина, [Разрыв]2⟦E⟧После срабатывания персонажи в [Разрыв]2 проходят спасбросок **Манёвренности**, иначе к ним прилипает шипованная граната, как описано выше.⟦Z⟧"},"ms_rapid_maneuver_jets":{"n":"Двигатели Быстрого Манёвра","t":"**1/раунд**, когда вы совершаете **Ускорение**, вы летите, получаете **Усиление Щита 3**, игнорируете вовлечение от более крупных персонажей и можете проходить сквозь занятые ими пространства (но не заканчивать в них ход). Это перемещение нужно закончить на поверхности, где можно стоять, иначе вы падаете."},"ms_forge_clamps":{"n":"Кузнечные Клещи","t":"⟦A:s⟧Клещи⟦T⟧Быстрое Действие⟦E⟧Вы вонзаете челюсти клещей в соседний объект или кусок местности **Размера 1** или больше. Вы становитесь **Обездвижены**, но получаете **Невосприимчивость** к **Толчку** и **Сбиванию**. Эффект заканчивается, если то, за что вы держитесь, уничтожено, или если вы отпускаете клещи **протоколом**.⟦Z⟧"},"ms_seismic_pulse":{"n":"Сейсмический Рыхлитель","t":"⟦A:s⟧Сейсмический Импульс⟦T⟧Полное Действие⟦E⟧Вы испускаете сейсмический импульс по [Линия]10: персонажи в зоне проходят спасбросок **Корпуса** или **Сбиты с ног**, а все объекты и куски местности автоматически получают **10** [энерг] **ББ**. Если это уничтожает местность или объект, он взрывается с [Разрыв]1. Персонажи в зоне взрыва проходят спасбросок **Манёвренности**: провал — **2d6** [взр], успех — половина. Каждого персонажа одновременно затрагивает только один такой взрыв, даже если зоны перекрываются.⟦Z⟧"},"ms_purifying_code":{"n":"Очищающий Код","t":"Вы получаете опции для **Вторжения**. На персонажа одновременно действует только одна опция Очищающего Кода, и он знает об её эффекте.\n⟦A:t⟧FLAW_plus⟦T⟧Вторжение⟦E⟧Вы внедряете в реактор цели меметический вирус, реагирующий на близость. В конце её следующего хода, если она **не** находится рядом с другим персонажем или местностью **Размера 1** или больше, вирус срабатывает: **1d6+2** [взр] **ББ**. После срабатывания эффект заканчивается.⟦Z⟧\n⟦A:t⟧FLAW_minus⟦T⟧Вторжение⟦E⟧То же, но вирус срабатывает в конце её следующего хода, если она **находится** рядом с другим персонажем или местностью **Размера 1** или больше: **1d6+2** [взр] **ББ**.⟦Z⟧"},"ms_immolate":{"n":"Испепеление","t":"Вы получаете опции для **Вторжения**:\n⟦A:t⟧Выброс Шлака⟦T⟧Вторжение⟦E⟧Реактор цели выплёскивает горящую жидкость в [Разрыв]2 вокруг неё (не затрагивая её пространство). Зона становится труднопроходимой; персонажи, начинающие в ней ход или впервые за раунд входящие в неё, проходят спасбросок **Инженерии** или получают **2** [нагрев] и **1** [горение]. Жидкость остывает и исчезает в конце вашего следующего хода.⟦Z⟧\n⟦A:t⟧Расплавленный Прокол⟦T⟧Вторжение⟦E⟧До конца следующего хода цели её реакторная защита треснута: она получает **2** [горение] за каждое пространство, на которое добровольно перемещается (максимум **6** горения).⟦Z⟧"},"ms_tear_firmament":{"n":"Блуждающий Кошмар","t":"⟦A:t⟧Блуждающий Кошмар⟦T⟧Полная Технология⟦E⟧Вы создаёте зону искажённого течения времени [Взрыв]2 в пределах **Сенсоров** и прямой видимости; она действует на всех персонажей, кроме вас. Персонажи в зоне не могут реагировать, а начавшие в ней ход проходят спасбросок **Систем** или получают **2** [нагрев] и **Замедлены** до конца своего следующего хода. Эффект длится, пока вы снова не совершите это действие или до конца сцены.⟦Z⟧"},"ms_rewrite":{"n":"Антилинейное Время","t":"⟦A:t⟧Антилинейное Время⟦T⟧Быстрая Технология⟦E⟧Выберите персонажа в пределах **Сенсоров** и прямой видимости. Он снимает все состояния, кроме **Ошеломления**, которые не наложил сам на себя, а вы сразу получаете все снятые состояния до конца своего следующего хода.⟦Z⟧"},"ms_unhinge_chronoflow":{"n":"Расшатать Хронологию","t":"Вы получаете две опции **Быстрой Технологии**:\n⟦A:t⟧Ускорить⟦T⟧Быстрая Технология⟦E⟧Выберите персонажа в пределах **Сенсоров** и прямой видимости. До конца сцены или пока он не получит урон он может **1/раунд** совершать **Ускорение** **свободным действием** в свой ход.⟦Z⟧\n⟦A:t⟧Замедлить⟦T⟧Быстрая Технология⟦E⟧Выберите персонажа в пределах **Сенсоров** и прямой видимости. Он проходит спасбросок **Систем** или получает **2** [нагрев], становится **Замедленным** и не может реагировать. Эффект заканчивается, если он получит любой урон или преуспеет в спасброске **Систем** быстрым действием.⟦Z⟧"},"ms_stay_of_execution":{"n":"Отсрочка Казни","t":"⟦A:t⟧Отсрочка Казни⟦T⟧Быстрая Технология⟦E⟧Выберите себя или другого персонажа в пределах **Сенсоров** и прямой видимости. Цель получает **Невосприимчивость** ко всему урону и эффектам из внешних источников до конца своего следующего хода, после чего становится **Ошеломлённой** до конца следующего за ним хода. Ничто не может предотвратить или снять это состояние. Всё это время действующие на цель эффекты заморожены во времени, а таймеры не идут (состояния, которые истекли бы в конце её хода, истекают в конце следующего; отсчёт плавления реактора не уменьшается и т. п.). Несогласный персонаж может проигнорировать эффект, преуспев в спасброске **Систем**.⟦Z⟧"},"ms_didymos_class_nhp":{"n":"НЧЛ класса «Дидим»","t":"Ваш мех получает метку **ИИ** и действие **Быстрой Технологии** «Расщепление Времени».\n⟦A:t⟧Расщепление Времени⟦T⟧Быстрая Технология⟦E⟧Выберите себя или другого персонажа в пределах **Сенсоров** и прямой видимости. Цель исчезает: вы расщепляете её временную линию и заменяете двумя полями мутирующей парадоксальной энергии как можно ближе к её исходному месту. Поля — новые персонажи, похожие на дыры в пространстве того же Размера и примерно той же формы, что и цель (долго смотреть на них не стоит). У них **10 ПЗ**, **Скорость 5**, **Уклонение 5**, **Э-Защита 5**, **Тепловой Максимум 5** и **Невосприимчивость** ко всем состояниям и статусам. Ими управляет игрок затронутого персонажа, и оба действуют в его ход, начиная со следующего. Поля могут только совершать стандартное перемещение и **Ускорение**, а единственная их реакция — рассеяться (см. ниже). Они являются препятствием и дают **твёрдое укрытие**.\nЕсли поле превысит **Тепловой Максимум** или его ПЗ упадут до 0, оно сразу исчезает. Игрок также может **реакцией** в конце хода любого персонажа заставить поле исчезнуть. Когда одно поле исчезает, другое сразу сливается в исходного персонажа, который возвращается на поле боя в его пространстве. Если оба поля исчезают одновременно, их игрок решает, какое исчезло первым. Несогласный персонаж может проигнорировать эффект, преуспев в спасброске **Систем**.⟦Z⟧"},"ms_accelerate":{"n":"Ускоритель","t":"⟦A:t⟧Ускоритель⟦T⟧Быстрая Технология⟦E⟧Выберите и отметьте два свободных пространства в вашей прямой видимости, лежащие на одной поверхности и не дальше [Дальн]5 друг от друга. Персонажи, начинающие ход в одном из них или впервые за раунд входящие в него, отталкиваются по прямой как можно дальше к другому пространству; столкнувшись с препятствием, они останавливаются. Избежать толчка можно, преуспев в спасброске **Корпуса**.\nГранаты, Размещаемые и другие свободные объекты **Размера 1** или меньше, брошенные или размещённые в одно из пространств, тоже отталкиваются к другому до срабатывания или взрыва; если их остановит персонаж или объект, они срабатывают раньше.\nЭффект длится до конца сцены или пока вы снова не возьмёте эту опцию.⟦Z⟧"},"ms_blink_charges":{"n":"Блинк-Заряды","t":"Потратьте заряд на один из эффектов:\n⟦A:s⟧Варп-Граната⟦T⟧Граната, Быстрое Действие, [Дальн]5, [Взрыв]3⟦E⟧При попадании выберите любого персонажа в зоне и **телепортируйте** его в любое свободное допустимое пространство той же зоны. Несогласный персонаж может избежать эффекта, преуспев в спасброске **Инженерии**.⟦Z⟧\n⟦A:s⟧Блинк-Мина⟦T⟧Мина⟦E⟧При срабатывании вызвавший её персонаж проходит спасбросок **Инженерии** или **телепортируется** в выбранное вами свободное допустимое пространство в пределах [Дальн]5 от мины и становится **Заклинен** до конца своего следующего хода. При успехе он всё равно телепортируется, но не Заклинен.⟦Z⟧"},"ms_distort":{"n":"Пролом в Реальности","t":"⟦A:t⟧Пролом в Реальности⟦T⟧Быстрая Технология⟦E⟧Вы разрываете пространство и создаёте зону [Взрыв]1 в свободном месте в пределах **Сенсоров** и прямой видимости. Оружие с метками **Взрыв**, **Линия**, **Разрыв** или **Конус** на эту зону не действует, и её не могут занимать персонажи или объекты. Любой персонаж или объект, переместившийся в зону хотя бы на 1 пространство, сразу **телепортируется** в свободное пространство рядом с ней (на выбор его игрока) или как можно ближе.\nЗона перекрывает прямую видимость, но любой персонаж может атаковать дыру дальнобойным оружием (кроме Взрыва, Линии, Разрыва, Конуса). Бросок атаки не делается: дыра поглощает атаку и перенаправляет её на новую цель по выбору атакующего в пределах [Дальн]10 от зоны, как будто атака исходит из дыры.\nЭффект длится до конца сцены, пока вы снова не совершите это действие или не закончите его **быстрым действием**.⟦Z⟧"},"ms_blinkspace_tunneler":{"n":"Туннелепрокладчик Блинк-Пространства","t":"⟦A:o⟧Блинк-Разрыв⟦T⟧Протокол⟦E⟧Вы открываете блинк-разрыв в свободном соседнем пространстве. Он держится до конца вашего следующего хода. В ходе любого перемещения персонажи, кроме вас (враждебные и союзные), хотя бы частично вошедшие в это пространство, могут **телепортироваться** в свободное пространство рядом с вами. Одновременно открыт только один разрыв: новый заменяет прежний.⟦Z⟧"},"ms_unravel":{"n":"Последняя Тайна","t":"⟦A:t⟧Последняя Тайна⟦T⟧Быстрая Технология⟦E⟧Выберите себя или другого персонажа в пределах **Сенсоров** и прямой видимости. До начала вашего следующего хода цель заряжена нестабильной энергией. Несогласный или враждебный персонаж может проигнорировать эффект, преуспев в спасброске **Инженерии**. Каждый раз, когда цель получает урон в этот период, вы можете **реакцией** **телепортировать** её на расстояние до **4 пространств** в выбранное вами свободное допустимое пространство.⟦Z⟧"},"ms_total_strength_suite_i":{"n":"Комплекс Полной Силы I","t":"⟦A:s⟧Комплекс Полной Силы I⟦T⟧Быстрое Действие⟦E⟧Вы вырываете кусок окружения и швыряете его в персонажа в пределах [Дальн]5 и прямой видимости. Цель проходит спасбросок **Манёвренности** или получает **1d6** [кин] и **Толчок 1** прямо от вас. После этого поставьте в свободном пространстве рядом с целью кусок местности **Размера 1**, дающий **твёрдое укрытие** (**10 ПЗ**, **Уклонение 5**), даже если цель преуспела в спасброске. Если рядом с вами есть объект или укрытие **Размера 1**, можно переместить его этим действием; иначе снаряд выламывается из земли или окружения. Если рядом нечего схватить или вы не на земле, действие недоступно.⟦Z⟧"},"ms_total_strength_suite_ii":{"n":"Комплекс Полной Силы II","t":"⟦A:o⟧Комплекс Полной Силы II⟦T⟧Протокол⟦E⟧Нанесите **1d6** [кин] персонажу, которого вы держите **Хватанием**.⟦Z⟧"},"ms_total_strength_suite_iii":{"n":"Комплекс Полной Силы III","t":"⟦A:s⟧Комплекс Полной Силы III⟦T⟧Полное Действие⟦E⟧Вы заканчиваете **Хватание**, отбрасывая другого персонажа на **5 пространств** в любом направлении и **Сбивая с ног**. Это перемещение может проходить сквозь пространства других персонажей, но должно закончиться в свободном. Все, сквозь кого он прошёл, проходят спасбросок **Корпуса** или **Сбиты с ног**. Если цель сталкивается с объектом или местностью, она останавливается, получает **1d6** [кин] и проходит спасбросок **Корпуса** или **Ошеломлена** до конца своего следующего хода.⟦Z⟧"},"ms_spaceborn_1":{"n":"Космический Скафандр","t":"Все мехи, которые вы собираете, имеют встроенные средства для работы в открытом космосе: вы не получаете штрафов под водой и в невесомости.\n⟦A:s⟧Рывок⟦T⟧Быстрое Действие⟦E⟧Перенаправив энергию в этот узел, вы летите на **3 пространства** и получаете [нагрев], равный Размеру меха + 1. В конце перемещения нужно приземлиться, иначе вы падаете.⟦Z⟧"},"ms_pinning_spire":{"n":"Пригвождающий Шпиль","t":"⟦A:s⟧Пригвождающий Шпиль⟦T⟧Быстрое Действие⟦E⟧Вы и один персонаж в пределах [Дальн]3 и прямой видимости становитесь **Обездвиженными** и не можете быть перемещены никак. Пока эффект длится, цель всегда считает вас в пределах досягаемости ближних атак. В любой последующий ход вы можете закончить эффект **протоколом**, а цель — успешно попав по вам дальней или ближней атакой. Снять это состояние иначе нельзя.⟦Z⟧"},"ms_sympathetic_shield":{"n":"Симпатический Щит","t":"⟦A:s⟧Симпатический Щит⟦T⟧Быстрое Действие⟦E⟧Вы проецируете щит резонирующей феррожидкости на союзного персонажа в пределах [Дальн]5. Он получает **Усиление Щита** в размере **4 + Стойкость**, но любой урон по этому Усилению Щита (до любых уменьшений) также наносит вам столько же [кин], как будто атакующий попал и по вам, на любом расстоянии. Этот урон не наследует метки и эффекты.⟦Z⟧"},"ms_camuss_razor":{"n":"Бритва Камю","t":"⟦A:s⟧Взвести Бритву Камю⟦T⟧Быстрое Действие⟦E⟧Ваш мех способен проецировать точечное магнитное поле невероятной силы. Взведя систему, вы получаете одно использование реакции «Вмешательство» до конца сцены.⟦Z⟧⟦A:r⟧Вмешательство⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер**: союзный персонаж в пределах [Дальн]5 и прямой видимости становится целью действия, наносящего [кин] или [взр] урон.\n**Эффект**: целью действия становитесь вы. Если это действие по площади (линия, конус, взрыв и т. п.), атакующий должен расположить его так, чтобы оно задело вас или прошло как можно ближе к вам, — это может изменить его цели. Перенос происходит, даже если исходное действие не могло задеть вас (например, ближняя атака).⟦Z⟧"},"ms_ferrospike_barrier":{"n":"Феррошиповый Барьер","t":"⟦A:s⟧Феррошиповый Барьер⟦T⟧Быстрое Действие, Размещаемое⟦E⟧Вы выплёскиваете волну жидкого металла **Размера 2** в свободное соседнее пространство, где она быстро застывает острыми шипами. Сначала барьер не создаёт препятствия, но в начале вашего следующего хода становится твёрдым объектом (**20 ПЗ**, **Уклонение 5**), который даёт **твёрдое укрытие**. После затвердевания первый раз за раунд, когда персонаж входит в его пространство, он получает **1d6** [кин] **ББ**. Одновременно может быть только один барьер; новый растворяет прежний.⟦Z⟧"},"ms_dominions_breadth":{"n":"Простор Владений","t":"⟦A:t⟧Простор Владений⟦T⟧Быстрая Технология⟦E⟧Мех в пределах **Сенсоров** и прямой видимости получает **Усиление Щита 1**. Когда это Усиление Щита теряется по любой причине, персонаж испускает электрический импульс [Разрыв]2: все враждебные персонажи в зоне (включая его самого, если он враждебен) получают **2** [энерг] **ББ** и проходят спасбросок **Инженерии**, иначе **Ослаблены** до конца своего следующего хода.⟦Z⟧"},"ms_the_imperial_eye":{"n":"Императорское Око","t":"⟦A:t⟧Императорское Око⟦T⟧Быстрая Технология⟦E⟧Союзный мех в пределах **Сенсоров** получает **Разрушительный Заряд** до начала вашего следующего хода. Когда враждебный персонаж входит в пространство в пределах [Дальн]3 от цели, заряд перескакивает на него и рассеивается: персонаж получает **2** [энерг] **ББ** и проходит спасбросок **Инженерии**, иначе отброшен на **2 пространства**, **Сбит с ног** и **Изрезан** до конца своего следующего хода.\nПерсонажи, начинающие ход в пределах [Дальн]3 от цели, не затрагиваются, пока не выйдут из зоны и не войдут снова.⟦Z⟧"},"ms_shahnameh":{"n":"Шахнаме","t":"⟦A:t⟧Шахнаме⟦T⟧Быстрая Технология⟦E⟧Союзный мех в пределах **Сенсоров** и прямой видимости получает **Усиление Щита** в размере **4 + Стойкость**. Пока у него есть это Усиление Щита, у него **Сопротивляемость** к нагреву от других персонажей. Если он теряет это Усиление Щита по любой причине, он снимает весь нагрев.⟦Z⟧"},"ms_ayah_of_the_syzygy":{"n":"Аят Сизигии","t":"⟦A:s⟧Аят Сизигии⟦T⟧Быстрое Действие⟦E⟧Вы создаёте энергетическое поле [Взрыв]2 в пространстве в пределах **Сенсоров** и прямой видимости. Первый раз за ход, когда враждебный персонаж в зоне получает попадание дальней или ближней атакой, он выпускает разряд: все враждебные персонажи, хотя бы частично находящиеся в зоне (включая его), получают **2** [энерг] **ББ**. Эффект длится до конца сцены или пока вы снова не используете это действие.⟦Z⟧"},"ms_the_walk_of_kings":{"n":"Поступь Царей","t":"⟦A:t⟧Поступь Царей⟦T⟧Быстрая Технология⟦E⟧Союзный персонаж в пределах **Сенсоров** и прямой видимости получает **Усиление Щита** в размере **4 + Стойкость**. Пока у него есть это Усиление Щита, все его ближние атаки получают **ББ**, а в первый раз за ход, когда он попадает ближней атакой или получает урон от враждебного персонажа, он испускает энергетический взрыв [Разрыв]1 вокруг себя: все враждебные персонажи в зоне получают **1** [энерг] **ББ**.⟦Z⟧"},"ms_pebcac":{"n":"ПЕБКАК","t":"⟦A:t⟧ПЕБКАК⟦T⟧Быстрая Технология⟦E⟧Союзный мех в прямой видимости и в пределах **Сенсоров** мгновенно перезагружается на системном уровне. Это прекращает все эффекты технологических действий, останавливает каскады НИИ и даёт цели **Невосприимчивость** ко всем технологическим действиям — враждебным и союзным, кроме этого, — до конца её следующего хода. Нельзя использовать на **Заклиненных** персонажах.\nКроме того, бросьте **1d6** — побочный эффект. Он срабатывает сразу, не считается действием или реакцией; вызванное им перемещение — вынужденное.\n**1**: цель **Заклинена** до конца своего следующего хода.\n**2**: цель перемещается на свою **Скорость** в направлении по выбору ГМа.\n**3**: цель сразу перемещается до 3 пространств к ближайшему персонажу (союзному или враждебному) и совершает по нему **импровизированную атаку**. Если в досягаемости никого нет, она только перемещается.\n**4**: цель **Сбита с ног** и получает **2** [кин].\n**5**: цель сбрасывает **1d6** [нагрев] и наносит столько же энергетического урона всем соседним персонажам.\n**6**: цель сразу совершает действие **Стабилизация** и сама выбирает, что делать.⟦Z⟧"},"ms_omnibus_plate":{"n":"Омнибусная Платформа","t":"⟦A:s⟧Омнибусная Платформа⟦T⟧Быстрое Действие, Размещаемое⟦E⟧Потратьте заряд, чтобы разместить омнибусную платформу (**Размер 1, 10 ПЗ**) в пространстве в пределах [Дальн]5. Платформу нельзя сдвинуть, она плоская и не мешает движению. На ней помещается один **Дрон** или **Размещаемый** объект **Размера 1** или меньше. Дроны и размещаемые объекты на платформе получают **Сопротивляемость** ко всему урону и **+1** к размеру создаваемых ими зон [Разрыв] и [Взрыв]. Кроме того, их эффекты, требующие соседства, действуют в пределах [Дальн]2.⟦Z⟧"},"ms_field_approved_brass_ignorant_modifications":{"n":"Полевые Доработки «Без Ведома Начальства»","t":"⟦A:t⟧Полевые Доработки⟦T⟧Быстрая Технология⟦E⟧Выберите союзный мех в прямой видимости и в пределах **Сенсоров** — вы форсируете его оружие. Когда он совершает дальнюю или ближнюю атаку:\n• урон атаки нельзя уменьшить никаким образом;\n• отдача отбрасывает его на 1 пространство в любом направлении после атаки;\n• **при попадании** цель проходит спасбросок **Корпуса**, иначе **Сбита с ног**.\nЭффект кончается, когда цель успешно попадает дальней или ближней атакой, или в конце сцены.⟦Z⟧"},"ms_forge_2_subaltern_squad":{"n":"Отряд Субальтернов FORGE-2","t":"⟦A:s⟧Отряд Субальтернов FORGE-2⟦T⟧Быстрое Действие, Размещаемое, 1/раунд⟦E⟧Потратьте заряд, чтобы отправить команду субальтернов FORGE-2 начать проект в свободном пространстве в прямой видимости и в пределах [Дальн]5. **Проект** — неподвижный объект (**Размер 1, 5 ПЗ**); он завершается в начале вашего следующего хода и получает **+10 ПЗ** (максимум и текущие). Если его уничтожить, проект отменяется.\n**Огневая Точка**: возвышение **Размера 1** высотой 3 пространства. Верхняя треть — защищённая площадка для персонажей суммарного Размера 1 (остальное — сплошной металл или пластик). Бойницы дают прямую видимость внутрь и наружу, а находящимся внутри — **твёрдое укрытие** со всех сторон. Войти или выйти можно из любого соседнего пространства **быстрым действием**; входящий сразу попадает на площадку. На плоской крыше могут стоять персонажи и размещаемые объекты, но укрытия не получают.\n**Ловчая Пена**: проект непрерывно распыляет пену, создавая зону труднопроходимой местности [Разрыв]2. Уничтожение проекта убирает эффект.\n**Демпферная Станция**: ремонтная станция создаёт поле [Разрыв]1, в котором союзные персонажи получают **Невосприимчивость** к горению и снимают текущее горение.\n**Бронепакет**: прикрепляется к следующему союзному персонажу, который подойдёт к нему вплотную, и сливается с ним: проект уничтожается, а персонаж получает **+1 Броню** до конца сцены (можно временно превысить максимум брони).\nСубальтерны не отдельные персонажи, их нельзя выбрать целью. Они возвращаются к вам, где бы вы ни были, когда проект уничтожен, отменён или завершён.\nЕсли вы **Перегружаетесь**, чтобы использовать систему повторно, можно игнорировать ограничение 1/раунд, но второй проект ставится рядом с первым.⟦Z⟧"},"ms_smokestack_heatsink":{"n":"Теплоотвод SMOKESTACK","t":"⟦A:s⟧Теплоотвод SMOKESTACK⟦T⟧Быстрое Действие, Размещаемое⟦E⟧Потратьте заряд, чтобы разместить пилон (**Размер 1/2, 5 ПЗ, Уклонение 10, Э-Защита 10**), который поглощает нагрев в зоне [Разрыв]2 вокруг себя: весь нагрев из любого источника, наносимый персонажам хотя бы частично в зоне (до уменьшений, включая **Сопротивляемость**). Поглотив **6** [нагрев], пилон взрывается: персонажи в зоне проходят спасбросок **Маневренности**, иначе получают **1d6+3** [энерг] **ББ**; при успехе — половину. Объекты и размещаемые объекты поражаются автоматически. Лишний нагрев, поглощённый тем же действием или эффектом, что вызвал взрыв, рассеивается без эффекта.⟦Z⟧"},"ms_exo_snapdragon_launcher":{"n":"Противомеховая ПТУР-Установка «Львиный Зев»","t":"⟦A:w⟧«Львиный Зев»⟦T⟧Быстрое Действие, 1/миссия⟦E⟧Совершите дальнюю атаку с профилем: **Тяжёлая ПУ, Надёжное 4, Искатель**, [Дальн]15, **2d6+2** [взр].⟦Z⟧"},"ms_exo_cynosure":{"n":"Киносура","t":"⟦A:t⟧Небесный Порядок⟦T⟧Быстрая Технология⟦E⟧Все персонажи на поле боя вынужденно перемещаются на 1 пространство в направлении по вашему выбору, игнорируя вовлечение и не провоцируя реакций. Направление у всех одно.⟦Z⟧⟦A:t⟧Неусыпная Погоня⟦T⟧Быстрая Технология⟦E⟧Враждебный персонаж в прямой видимости и в пределах **Сенсоров** проходит спасбросок **Систем**, иначе зачарован. Выберите другого видимого персонажа: любое добровольное перемещение зачарованного должно вести к нему самым прямым путём. Эффект кончается, когда зачарованный начинает или заканчивает ход рядом с любым другим персонажем; иначе длится до конца боя.⟦Z⟧"},"ms_exo_opportunity":{"n":"Возможность","t":"Ваш мех получает метку **ИИ** и действие «Стук».⟦A:t⟧Стук⟦T⟧Быстрая Технология⟦E⟧Возможность одалживает свою огромную вычислительную мощь и точную (хоть и придирчивую) помощь, приводя системы союзника в более «упорядоченное» состояние.\nВыберите союзный мех в прямой видимости и в пределах **Сенсоров**: он получает **Невосприимчивость** к нагреву от других персонажей, **+1** [ТОЧН] на все проверки и спасброски **Систем**, а атакующие получают **+1** [СЛОЖН] на технологические атаки по нему.\nЭффект кончается, когда вы снова совершаете это действие или когда персонаж «устраивает беспорядок»: совершает бросок атаки, заставляет пройти спасбросок или совершает любое другое действие, затрагивающее враждебного персонажа.⟦Z⟧\nВ миссии, где её получили, Возможность близка к каскаду: если ваш мех теряет структуру или нагрузку, она уходит в каскад на результате **10 или меньше**, а не на 1."},"ms_exo_markeys_fusebox":{"n":"Распредкоробка Марки","t":"⟦A:s⟧Распредкоробка Марки⟦T⟧Быстрое Действие, Мина⟦E⟧Потратьте заряд, чтобы установить заряд взрывчатки (**Размер 1/2, 10 ПЗ, Уклонение 5, Э-Защита 5**) в свободном соседнем пространстве. Он взводится в конце раунда; взведённый — взрывается, получив любой урон или нагрев. Персонажи в пределах [Разрыв]3 проходят спасбросок **Маневренности**, иначе получают **2d6** [взр] и выталкиваются из зоны (или как можно дальше); при успехе — всё равно выталкиваются, но получают половину урона.⟦Z⟧"},"ms_exo_carapace_cladding":{"n":"Хитиновая Обшивка","t":"⟦A:s⟧Хитиновая Обшивка⟦T⟧Быстрое Действие⟦E⟧Потратьте заряд, чтобы сразу снять всё горение с вашего меха.⟦Z⟧Кроме того, когда вы **Укрепляетесь**, можно потратить заряд, чтобы уменьшить всё горение от этой атаки до 0."},"ms_exo_fragment_beggar_one":{"n":"Осколок Нищего Первого","t":"**1/сцена** вы можете совершить одно из полных технологических действий:⟦A:t⟧Шёпот Каскада⟦T⟧Полная Технология⟦E⟧Выберите враждебного персонажа в пределах **Сенсоров**. Он должен либо сразу реакцией атаковать одним оружием другого персонажа или объект по вашему выбору в его дальности и прямой видимости, либо стать **Заклиненным** до конца своего следующего хода.⟦Z⟧⟦A:t⟧Бритва по имени Квалиа⟦T⟧Полная Технология⟦E⟧Выберите враждебного персонажа в пределах **Сенсоров**. До конца его следующего хода:\n• стандартное перемещение он обязан тратить на движение к вам самым прямым путём;\n• пока вы в дальности и прямой видимости его атак, вы — единственная допустимая цель его атак.⟦Z⟧"},"ms_iconoclast":{"n":"Нестабильный НИИ","t":"Ваш мех получает метку **ИИ**, но этот НИИ не учитывается в лимите одновременно установленных ИИ. Передать ему управление мехом протоколом нельзя, но он может уйти в каскад.\nВаш мех получает действие «Меметическая Искра».⟦A:s⟧Меметическая Искра⟦T⟧Быстрое Действие, 1/раунд⟦E⟧Вы наносите **1** [энерг] **ББ** персонажу в пределах [Дальн]3.\nИскра наносит **+1 урон** за каждого неуничтоженного НИИ на вашем мехе, включая этот. «НИИ» — системы, которые дают меху метку **ИИ** и могут уйти в каскад (или которым можно позволить это).⟦Z⟧\n*[я сплю, но жажду пробуждения]*. Даётся талантом **Иконоборец I**."},"ms_cockpit_integrated_stim_pump":{"n":"Встроенный в Кабину Стим-Насос","t":"**Протоколом** потратьте заряд, выберите любое число стимуляторов ниже и примените их. Бросьте **1d6** за каждый выбранный стимулятор: если на двух кубах выпало одно число, вы вместо эффектов сразу **Ошеломлены** до конца текущего хода. Все эффекты длятся до начала вашего следующего хода.\n**Агитрон**: вы **Ослаблены**; **Невосприимчивость** к **Расщеплению**; ближние атаки получают **Отбрасывание 1** и **+2** бонусного урона.\n**Эндуритран**: вы **Заклинены**; **Невосприимчивость** к **Ослаблению**; **+2 Брони** (можно выше 4).\n**Эдж**: вы **Замедлены**; **Невосприимчивость** к **Заклиниванию**; следующая атака в этом ходу получает **+1** [ТОЧН].\n**Нервные Ускорители**: вы **Расщеплены**; **Невосприимчивость** к **Замедлению**; **+1 Скорость**, вы игнорируете вовлечение, и ваше движение не провоцирует реакций."},"ms_mesmertrance_dampener":{"n":"Подавитель МесмерТранса","t":"⟦A:r⟧Подавитель МесмерТранса⟦T⟧Реакция, 1/сцена⟦E⟧**Триггер**: вы становитесь целью технологической атаки.\n**Эффект**: атака получает **+1** [СЛОЖН].⟦Z⟧Кроме того, у вас **Невосприимчивость** к опасности окружения **МесмерТранс**.\nВыдан Когтями: якобы не даёт агрессивному вирусу «МесмерТранс» заразить ваш мех."},"ms_armament_redundancy":{"n":"Резервирование Вооружения","t":"При результате **Системная Травма** (структурный урон) вы можете проигнорировать уничтожение оружия. Систему можно использовать **один раз** до каждого **Полного Ремонта**; её нельзя выбрать целью уничтожения систем."},"ms_emergency_repair_module":{"n":"Модуль Аварийного Ремонта","t":"Когда вы или союзник рядом с вами использует реакцию **Укрепление**, можно потратить заряд и **1 Ремонт**, чтобы сразу после получения урона от вызвавшей её атаки восстановить этому персонажу **все ПЗ**. Если от этой атаки он получил структурный урон, то при проверке структуры бросает на **1 кубик меньше** (минимум 0 — тогда без последствий).\nНанитная суспензия, точечная сварка и переключение на резервные системы — у легионов даже есть традиции, как отмечать первое срабатывание МАР в бою."},"ms_spear_charges":{"n":"Заряды «КОПЬЁ»","t":"Потратьте заряд на один эффект:⟦A:s⟧Противоброневая Ракета⟦T⟧Быстрое Действие, Граната, Дальн. 10⟦E⟧Цель проходит спасбросок **Маневренности**, иначе получает **6** [взр] **ББ**; при успехе — половину урона.⟦Z⟧⟦A:s⟧Барражирующий Заряд⟦T⟧Быстрое Действие, Мина, Дальн. 3, Разрыв 2⟦E⟧При размещении зона мины не может накрывать враждебных персонажей. Боеприпас не детонирует обычным образом: когда враждебный персонаж в следующий раз добровольно перемещается больше чем на 1 пространство внутрь зоны или внутри неё (до 10 пространств в высоту), заряд бросается на него и взрывается. Цель проходит спасбросок **Маневренности**, иначе получает **2d6** [взр] **ББ**, сразу останавливается и теряет оставшееся перемещение; при успехе — только половину урона. Неудачное обезвреживание тоже вызывает детонацию по этому персонажу. Каждый персонаж может задействовать не больше одного барражирующего заряда за ход.⟦Z⟧Лёгкая противоброневая ракета Special Purpose Enhanced Anti-armor Rocket из одноразовых тубусов: прямой огонь или барражирование над зоной."},"ms_utility_drone":{"n":"Вспомогательный Дрон","t":"⟦A:s⟧Развернуть Вспомогательных Дронов⟦T⟧Быстрое Действие, Дрон⟦E⟧Потратьте **1–2 заряда**, чтобы разместить столько же **Вспомогательных Дронов** (Размер ½, ПЗ 5, Уклонение 10, Э-Защита 10) в свободных пространствах в пределах **Сенсоров**. Каждый создаёт зону [Разрыв]2. Враждебные персонажи в зоне получают **+1** [СЛОЖН] на все проверки и спасброски, а союзные — **+1** [ТОЧН] на все проверки и спасброски. Эффект от нескольких дронов не складывается.\nДрона можно переместить на новое место **быстрым действием**. Отозвать его нельзя; он исчезает в конце сцены.⟦Z⟧Дрон «Аргус» — многоцелевая платформа легионов: перехват угроз, электростатическое подавление и полевая диагностика."},"ms_quickfoam_charges":{"n":"Заряды Быстрой Пены","t":"Потратьте заряд на один эффект:⟦A:s⟧Латающая Граната⟦T⟧Быстрое Действие, Граната, Дальн. 5⟦E⟧По союзному персонажу: вы его **Подкрепляете**, и он может снять одно состояние, вызванное не его собственными системами, талантами и т. п. По враждебному персонажу: он **Ослаблен** и **Замедлен** до конца своего следующего хода.⟦Z⟧⟦A:s⟧Герметизирующая Мина⟦T⟧Быстрое Действие, Мина, Разрыв 1⟦E⟧Мина детонирует, когда персонаж входит в соседнее с ней пространство или на неё. Все союзные персонажи (и вы) в зоне получают **Сверхщит** в размере **Стойкость + 4** и снимают всё горение. Все враждебные персонажи в зоне **Обездвижены** быстро застывающей пеной, пока она не получит достаточно урона, чтобы разрушиться (объект: ПЗ 10, Уклонение 5).⟦Z⟧Самоотверждающаяся полимерная пена с нанитами — латать пробоины и ставить ловушки в коридорах."},"ms_exo_kinesthetic_suit_upgrade":{"n":"Кинестетический Модуль Скафандра","t":"Вы получаете реакцию **Пространственное Чутьё**.⟦A:r⟧Пространственное Чутьё⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер**: персонаж заканчивает перемещение рядом с вами.\n**Эффект**: вы можете **Ускориться**, игнорируя реакции и вовлечение. После этого атаки по вам получают **+1** [СЛОЖН] до конца вашего следующего хода.⟦Z⟧Кибернетический аппарат на позвоночнике — полный неврологический суррогат: берёт на себя поддержание гомеостаза и освобождает внимание пилота."},"ms_exo_emi_theater":{"n":"Театр Эми","t":"Выберите уничтоженный мех в прямой видимости. Он сразу восстанавливается как союзный НИП-**Салага** со **Сверхщитом 5**, после чего получает весь свой нагрев как энергетический урон. Он теряет прочие шаблоны, но сохраняет всё остальное и восстанавливает всё уничтоженное оружие и системы. С этого раунда у него свой ход каждый раунд и все действия обычного НИП. В конце сцены он уничтожается и становится обломками.\n«Театр духов» — система неизвестного происхождения, поднимающая уничтоженные машины для последнего боя."},"ms_exo_upgraded_network_array":{"n":"Улучшенный Сетевой Массив","t":"**1/сцена** выберите союзного персонажа. До конца вашего следующего хода вы можете использовать его **Системы** вместо своих для проверок и спасбросков и совершать технологические действия через его **Сенсоры**, считая прямую видимость от его позиции."},"ms_exo_mist_feathers":{"n":"Туманные Перья","t":"**1/сцена**, активировав систему, до конца своего следующего хода вы получаете:\n• ваш мех считается **парящим** (Lancer, стр. 63);\n• **1/ход** можно **Ускориться** **свободным действием**;\n• если в конце своего хода вы **Невидимы** или под укрытием, можете стать **Скрытым** без действия.\nПоплавковый аппарат для разреженной атмосферы: не летит, а «тянет» себя, связывая молекулы воздуха."},"ms_champions_favor":{"n":"Благосклонность Чемпиона","t":"В начале своего хода вы получаете **1 Сверхщит**.\nЗолотой мехового масштаба лавровый венок чемпионов pankration mekani с маленьким, но сложным генератором щита: защита и мерцающая «аура» чемпиона. Цвет ауры можно сменить при Полном Ремонте."},"ms_entangled_co-consciousness_rig":{"n":"Установка Сцеплённого Сосознания","t":"Ваш мех получает метку **ИИ** и способность **«Чемпионы, Направьте Руки»**. Это не НИИ, в каскад система не входит.⟦A:s⟧Чемпионы, Направьте Руки⟦T⟧1/сцена⟦E⟧Атакуя, можно не бросать кубик, а считать, что на d20 выпало **10**. Если атака попадает, она автоматически становится **критической**.⟦Z⟧Кроме того, если враждебный персонаж или проверка структуры сделали бы вас **Ошеломлённым**, вы можете вместо этого передать управление мехом Установке: вы не Ошеломлены, но на следующем ходу не можете забрать управление и передать его другому ИИ."},"ms_adjutant_class_compcon":{"n":"Комп/Кон класса «АДЪЮТАНТ»","t":"Ваш мех получает метку **ИИ** и способность **Активная Помощь**.\nКроме того, в онтологический мост системы можно загрузить **один ранг таланта**, на который вы имеете право, но которого у вас нет. Пока вы пилотируете этот мех, этот ранг у вас есть. Если система уничтожена, ни этот талант, ни системы и возможности, которые он даёт, не работают до ремонта. Выбрать другой ранг можно при каждом **Полном Ремонте**.\nЭто не полноценный НИИ: в каскад система не входит.⟦A:s⟧Активная Помощь⟦T⟧Свободное действие, 1/сцена⟦E⟧Совершите любое **быстрое действие** на ваш выбор. Это не может быть атака, и оно не может вынуждать спасброски.⟦Z⟧Комп/кон нового поколения взамен стандартного класса «ЭПИФАНИЯ»: Союз предпочитает распространять такие системы, а не военные НИИ."},"ms_pattern_c_advanced_charges":{"n":"Паттерн-В Продвинутые Заряды","t":"Потратьте заряд на один из эффектов:\n**• Умная Граната** (Граната, [Дальн] 5, [Взрыв] 1): все враждебные персонажи в зоне проходят спасбросок **Систем**, иначе получают **1d6 [энерг]** и **Захват**. При успехе — только **Захват**.\n**• Мина-Засада** (Мина, [Разрыв] 1): эта мина не взрывается как обычно. Вместо этого вы получаете реакцию **Избирательный Подрыв** — её можно применить один раз за каждую установленную мину-засаду.⟦A:r⟧Избирательный Подрыв⟦T⟧Реакция, 1/раунд для каждой мины⟦E⟧**Триггер**: персонаж входит в пространство мины-засады или соседнее либо начинает там ход.\n**Эффект**: мина взрывается; задетые персонажи проходят спасбросок **Маневренности**, иначе получают **2d6 [взр]**, при успехе — половину.⟦Z⟧Самостоятельный многорежимный боеприпас GMS: каждый заряд сам выбирает и перехватывает цели, но подрыв по-прежнему подтверждает пилот."},"ms_miniaturized_linac_coherent_beam_cannon":{"n":"Миниатюрная Пушка Когерентного Луча «ЛинУск»","t":"Ваш мех получает **дополнительную систему ядра** — **ЛинУск ПКЛ**, использовать её можно **1/миссия**.⟦A:s⟧ЛинУск ПКЛ⟦T⟧Активная (1 МЯ), Полное Действие, 1/миссия⟦E⟧Пушка заряженных частиц стреляет по [Линия]**30**. Всё укрытие, местность, объекты и размещаемые меньше **Размера 5** на этом пути мгновенно испаряются; затем все персонажи в зоне проходят спасбросок **Маневренности**, иначе получают **14 [энерг]**, при успехе — половину. Этот урон **нельзя уменьшить** ничем. Персонажи с **7 ПЗ** или меньше, **1 Структурой** и без **Невосприимчивости** к урону вместо этого мгновенно уничтожаются — не остаётся даже обломков.\nВ ход выстрела нельзя совершать других действий, кроме обычного перемещения или **Ускорения**, а после выстрела вы **Ошеломлены** до начала своего следующего хода.⟦Z⟧Реконструирована по боевым данным схватки с вестанским спецназом: потомок старых линейных ускорителей когерентного луча, устаревших для флота, но смертоносных в масштабе меха."}},"mods":{"wm_thermal_charge":{"n":"Термический Заряд","t":"Выберите одно **ОББ**: при попадании этим оружием потратьте заряд в качестве **свободного действия**, чтобы активировать его детонатор и нанести +1d6 [взр] **дополнительного урона**.","f":"Одна из популярных модификаций классической боевой пики заключается в замене длинной бронебойной головки пики на одноразовый взрывной заряд, срабатывающий при ударе. При пробитии головка пики отделяется от древка — мгновение спустя вложенная головка детонирует в коническом взрыве вперед от острия. Запасные термические заряды стабильны и транспортируются во внешних трубчатых магазинах.\nИПС-Н также делает термические заряды совместимыми с ассортиментом лезвий, молотков и кирок ДМС."},"wm_uncle_class_comp_con":{"n":"Комп/кон Класса «БАТЯ»","t":"Выберите одно **Вспомогательное**, **Основное** или **Тяжелое** оружие: ваш комп/кон класса «БАТЯ» контролирует это оружие и связанные с ним системы.\n1/ход вы можете атаковать оружием **«БАТЯ»** с **+2 [СЛОЖН]** в качестве **свободного действия**. **«БАТЯ»** не может использовать оружие, которое уже использовалось в этом ходу, и любое оружие, которым **«БАТЯ»** атакует, не может быть использовано снова до начала вашего следующего хода.\n**«БАТЯ»** не является полноценным НЧЛ, поэтому не может участвовать в **каскаде**.","f":"Система ИПС-Н «БАТЯ» комп/кон является результатом программы ДАРКСТАР-2, временного проекта, направленного на разработку более совершенного интеллектуального оружия. Ранним прототипам мешало сочетание высокого энергопотребления, нестабильной подготовки и разочаровывающей ориентации на одну задачу, что в конечном итоге привело к закрытию проекта.\nХотя ИПС-Н больше не разрабатывает новые итерации «БАТЯ», у них все еще есть запас одобренных QA старых систем, доступных для квалифицированных пилотов.\nПилоты, которым посчастливилось провести полевые испытания моделей, клянутся в эффективности «БАТЯ» при выполнении задач и мышлении на параллельных путях, хотя устаревшие комп/кон известны своим несколько нестабильным характером."},"wm_throughbolt_rounds":{"n":"Сквозные Болты","t":"Выберите один **ОБД**, **Пушку** или **Винтовку**: когда вы атакуете этим оружием, вы можете стрелять насквозь вместо обычной атаки. Прочертите от себя путь длиной [Линия] **3**, проходящий через местность или другие препятствия — любые персонажи или объекты на пути получают **2** [кин] **ББ**, когда снаряд пробивает их насквозь и выходит с другой стороны. **Дальность**, укрытие и линия обзора для атаки затем измеряются от конца этого пути, продолжаясь в том же направлении.","f":"Сквозные Болты — это запатентованное изобретение ИПС-Н для борьбы с бронетехникой. При выстреле снаряды воспламеняются и выбрасывают перед собой перегретый конус плазмы, создавая эффект миниатюрного копья, которое легко пробивает множество целей — даже через твердые поверхности."},"wm_shock_wreath":{"n":"Шоковый Венец","t":"Выберите одно оружие ближнего боя: в дополнение к обычному урону, **1/раунд** вы можете активировать венец в качестве быстрого действия, когда вы бьете персонажа этим оружием, чтобы вызвать у него **1d6 [горение]**. Если он уже страдает от [горение], он может дополнительно проводить линию прямой видимости только к соседним пространствам до конца своего следующего хода.","f":"Постфабричная модификация, популярная среди специалистов по ближнему бою, Шоковый Венец интегрирует пучок проводящих нитей в лезвие, острие, наконечник или поверхность оружия ближнего боя. В сочетании с источником питания — обычно в рукоятке или нижней половине оружия, но иногда и снаружи — Шоковые Венцы придают кинетическому оружию тепловое преимущество и отличительный визуальный маркер: тонкие линии раскаленных ламп, как филигрань, окутывают модифицированное оружие мерцающим тёплым светом."},"wm_stabilizer_mod":{"n":"Стабилизирующий Мод","t":"Выберите **Пусковую установку** или **Пушку**: это оружие получает [Дальн] **+5** и становится **Артиллерийским**.","f":"Стабилизирующие Моды улучшают физические крепления и программное обеспечение для прицеливания, позволяя оружию оставаться в ровном и устойчивом положении и под нужным углом, независимо от рельефа местности или маневров пилота."},"wm_nanocomposite_adaptation":{"n":"Нанокомпозитная Адаптация","t":"Выберите оружие: оно становится **Умным** и **Искателем**.","f":"Нанокомпозитное оружие собирает агрессивные рои дронов и превращает их в отдельные снаряды, когерентный луч или острие клинка.\nАдаптированное метательное оружие стреляет снарядами ПОГЛОЩЕНИЕ/УЛЕЙ, которые разбиваются при ударе, высвобождая боезапас в виде автономных нанитовых манипул. Освободившись, манипулы начинают разъедать окружающие ткани или надстройки. Они действуют до тех пор, пока не сгорят или не поглотят цель полностью, в зависимости от того, что произойдет раньше. В полете манипуляторы способны объединяться в улей и слегка корректировать траекторию полета, обеспечивая положительное воздействие.\nКогерентное лучевое оружие транспортирует манипулы напрямую, в то время как обычное оружие ближнего боя заменяется аналогами, полностью состоящими из нанороботов."},"wm_phase_ready_mod":{"n":"Мод Фазовой Готовности","t":"**Выберите оружие**: пока вы знаете приблизительное местоположение цели, оно может атаковать сквозь сплошные стены и препятствия, не требует прямой видимости и игнорирует **все укрытия**, но цели, атакованные таким образом, считаются **Невидимыми**.","f":"Боеприпасы фазовой готовности, как они были названы после первого применения во время гражданских военных действий на Луна-де-Оро, называются «пулями дьявола». Каждый снаряд содержит набор нанопроцессоров, объединенных в сеть с исходным оружием, который вычисляет и переводит специфический характер суперпозиционных отношений этого снаряда с прогнозируемым будущим двойником, который проявляется в пространстве непосредственно перед намеченной целью. Проще говоря, снаряды фазовой готовности при выстреле существуют сразу в двух местах: на выходе из ствола оружия, из которого они были выпущены, и непосредственно перед целью, до удара. Основной патрон может никогда не попасть в цель, но, поскольку он уже существует в момент выстрела, патрон-двойник точно достигнет цели."},"wm_paracausal_mod":{"n":"Параказуальный Мод","t":"Выберите оружие: оно получает **Избыточный Урон**, и его урон нельзя уменьшить никаким образом, в том числе другими эффектами и системами (такими как **Сопротивляемость**, **Броня** и т. д.).","f":"Паракаузальное оружие — головная боль военных планировщиков; их точная функция A–Z часто скрыта, хотя они последовательно производят один и тот же вывод «Z» для каждого входа «A».\nПервые сообщения о нерегулируемом паракаузальном оружии появились во время гражданских столкновений на Тянь-Шене. Системно-локальные силы получили запечатанные магазины с указаниями заряжать и стрелять как обычно, хотя осмотр содержимого магазинов был запрещен на том основании, что это \"повредит полезную нагрузку\". Записи со шлемов и орудийных камер не выдают аномального воздействия этого боеприпаса, хотя отчеты после боя выявили, казалось бы, незначительный, но невероятно странный факт: каждый военнослужащий, экипированный этими паракаузальными боеприпасами, добился 100% коэффициента положительного воздействия Союз запланировал изъятие всего нерегулируемого паракаузального оружия и боеприпасов, и в настоящее время бюро проводит расследование в отношении Оружейной палаты Харрисона на предмет его роли в разработке этой технологии. Несмотря на это, паракаузальные боеприпасы все еще используются, поскольку поставки и коды продолжают просачиваться к заинтересованным лицам."},"wm_supermassive_mod":{"n":"Сверхмассивный Мод","t":"Выберите одно оружие **ОБД**, **Пушку** или **ОББ**: оно получает **Избыточный Урон** и **Толчок +1**. Во время **Полного Ремонта** можно снять с него ограничители: бонус становится **Толчок +2**, но оружие также получает **Артиллерийское** (если дальнее) или **Неточное** (если ближнее)."},"wm_molten_wreathe":{"n":"Расплавленный Венец","t":"Выберите одно оружие **ОББ**: **1/раунд**, после попадания по персонажу этим оружием вы получаете **1** [нагрев], а оружие выбрасывает раскалённое облако [Конус]3, направленное от цели в выбранную вами сторону. Цель и все персонажи в облаке получают по **2** [взр]."},"mw_bounder_class_comp_con":{"n":"Комп/кон класса «БАУНДЕР»","t":"Выберите одно оружие **ОБД**, **Пушку** или **Винтовку**, которое не атакует зоной (Взрыв, Разрыв, Линия, Конус). Комп/кон и дополнительные баллистические системы интегрируются в это оружие.\n**1/раунд** выберите одно:\n• Промахнувшись атакой этим оружием, можно перебросить её против **другой** цели, отсчитывая дальность и прямую видимость от места исходной цели.\n• Можно стрелять с рикошетом из-за углов: выберите участок местности или объект **Размера 1** или больше в пределах дальности и видимости оружия — дальность и прямая видимость атаки отсчитываются от него.\n• Если на кубике атаки выпало **20** («натуральная 20»), выстрел рикошетом бьёт в уязвимое место: урон нельзя уменьшить никак, а при попадании цель **Сбита с ног**.\nЭто не полноценный НИИ, в каскад он не входит."}},"talents":{"t_ace":{"n":"Ас","r":[{"n":"Акробатика","t":"Во время **полёта** вы получаете преимущества:\n• Вы проходите все проверки и спасброски **Маневренности** с **+1**[ТОЧН].\n• Каждый раз, когда по вам промахиваются, вы можете отлететь на **2 пространства** в любом направлении, используя **реакцию**."},{"n":"Форсаж","t":"Когда вы используете **Ускорение** во время **полёта**, вы можете переместиться на дополнительные **1d6 пространств**, но получаете **нагрев, равный половине этого броска**."},{"n":"Сверхзвук","t":"В качестве быстрого действия в свой ход вы можете включить свои ускорители. Если вы завершаете свой ход, вы можете назначить цель в радиусе, равном вашей скорости и в прямой видимости, чтобы получить этот эффект:\n⟦A:r⟧Сверхзвук⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер:** Ход вашей цели заканчивается.\n**Эффект**: Вы перелетаете в свободнее соседнее пространство рядом с целью. Путь должен быть свободен, но вы сможете перемещаться, даже если выбранная цель по итогу хода не в радиусе вашего перемещения или в прямой видимости. Это игнорирует вовлечение и не провоцирует реакцию цели.⟦Z⟧"}]},"t_bonded":{"n":"Узы","r":[{"n":"Я Твой Гекльберри","t":"Когда вы используете этот талант, выберите другого пилота (желательно, игрока, но можно и НИПа, если ваш ГМ разрешит), чтобы он стал вашим **Партнёром**. Все проверки навыков мехов и спасброски, которые делает любой из персонажей, пока вы находитесь рядом, получают **+1 [ТОЧН]**. Если оба персонажа обладают этим талантом, это значение увеличивается до **+2 [ТОЧН]**, но дополнительные персонажи с этим талантом не могут увеличить его еще больше. Между миссиями вы можете заменить своего **Партнёра** на нового, но только если ваши отношения с ним действительно изменились."},{"n":"Солнечный Танец","t":"Получите следующую реакцию:\n⟦A:r⟧Заступиться⟦T⟧Реакция, 1 в раунд⟦E⟧**Триггер**: Вы находитесь рядом с вашим Партнёром (пилотом или мехом), и он получает урон от кого-то в вашей прямой видимости.\n**Эффект:** Вы можете получить урон, вместо него⟦Z⟧"},{"n":"Прикрой Меня!","t":"Если враг в пределах вашей прямой видимости пытается атаковать вашего **Партнёра**, вы можете потратить своё **Наблюдение**, чтобы угрожать атакующему, заставляя его либо выбрать другую цель, либо атаковать в любом случае: если он атакует другую цель, ваше **Наблюдение** расходуется без эффекта; если он решает атаковать в любом случае, вы можете немедленно атаковать его с помощью **Наблюдения**, пока он находится в пределах **Дальности** и прямой видимости. Эта атака разрешается до спровоцированной атаки."}]},"t_brawler":{"n":"Дебошир","r":[{"n":"Удержание и Блок","t":"Вы получаете **+1**[ТОЧН]ко всем ближним атакам против целей, которые вы **Схватили**."},{"n":"Кувалда","t":"Ваши **Импровизированные Атаки** получают **Толчок 2** и наносят **2d6+2** [кин] **урона.**"},{"n":"Нокаутирующий Удар","t":"Получите **Кубик Драки**, **1d6,** начиная с **6**. Каждый раз, когда вы **Хватаете**, **Тараните** или делаете **Импровизированную Атаку**, уменьшите значение кубика Драки на **1**. Когда **Кубик Драки** достигнет **1**, вы можете вернуть его в значение **6** и, в качестве полного действия, нанести **нокаутирующий удар** по соседнему персонажу. Он должен пройти спасбросок **Корпуса**, иначе получит 2d6+2 [кин] урона и станет **Ошеломлённым** до конца своего следующего хода. Значение вашего **Кубика Драки** сохраняется между сценами, но оно сбрасывается до 6, когда вы делаете перерыв или **Полный Ремонт**."}]},"t_brutal":{"n":"Брутал","r":[{"n":"Хищник","t":"Когда вы выбрасываете **20** на кубике для любой атаки (иногда это называют \"натуральная 20\") и наносите **критическое попадание**, вы автоматически наносите максимально возможный урон и бонусный урон."},{"n":"Погонщик Стада","t":"Ваши **критические попадания** получают 1 **Толчок**."},{"n":"Безупречность","t":"Когда вы делаете бросок атаки и промахиваетесь, ваш следующий бросок атаки получает **+1 [ТОЧН]**. Этот эффект суммируется и сохраняется до тех пор, пока вы не попадете."}]},"t_crack_shot":{"n":"Точный Выстрел","r":[{"n":"Стабильный, Устойчивый","t":"В качестве **протокола** вы можете **Выровнять Прицел.** Если вы это сделаете, вы становитесь **Обездвиженным** до начала вашего следующего хода, но получаете **+1** [ТОЧН] ко всем атакам, которые вы делаете из **Винтовки**."},{"n":"Сосредоточение","t":"1 раз в раунд, когда вы **Выравниваете Прицел** и совершаете дальнюю атаку из **Винтовки**, вы можете попытаться попасть в слабую точку: получите **1 [СЛОЖН]** при броске атаки и нанесете **+1d6** дополнительного урона из-за критического попадания."},{"n":"Погляди-ка","t":"1 раз за раунд, когда вы совершаете **критическое попадание** из **Винтовки**, не сводя глаз с цели, ваша цель должна пройти спасбросок **Корпуса** или вы можете выбрать дополнительный эффект для вашей атаки:\n• **Выстрел в голову**: цель может видеть только соседнее пространство до конца своего следующего хода.\n• **Выстрел в ногу**: цель не может перемещаться до конца своего следующего хода.\n• **Выстрел в туловище**: uель Сбита с ног."}]},"t_centimane":{"n":"Центиман","r":[{"n":"Десять Тысяч Зубов","t":"1/раунд, когда вы **совершаете критическое попадание** с помощью **Звеньев**, ваша цель должна пройти спасбросок **Систем** или стать **Ослабленной** и **Замедленной** до конца своего следующего хода."},{"n":"Обнажить Слабость","t":"Когда вы используете **Захват** как часть атаки с помощью **Звеньев** или **Дронов** и совершаете критическое попадание, ваша цель становится **Расщеплённой** до начала вашего следующего хода."},{"n":"Подавление Приливов","t":"Заменяет **Десять Тысяч Зубов**.\n1/раунд, когда вы совершаете критическое попадание с помощью **Звеньев**, ваша цель должна пройти спасбросок **Систем** или вы можете выбрать дополнительный эффект для вашей атаки, который длится до конца их следующего хода:\n• **Преследующий Рой**: враг становится Ослабленным и Замедленным.\n• **Ослепляющий Рой**: враг имеет прямую видимость только на соседнее пространство.\n• **Страшный Рой**: Враг становятся **Расщеплённым**. Все примыкающие персонажи по вашему выбору также должны сделать спасбросок **Систем** или стать **Расщеплёнными**.\n• **Ограничительный Рой**: цель получает 1 **горение** каждый раз, когда совершает действие или реакцию."}]},"t_combined_arms":{"n":"Комбинированный Бой","r":[{"n":"Щит из Лезвий","t":"Пока вы в состоянии **Вовлечения**, вы и все союзники, находящиеся рядом с вами, считаются как за мягким укрытием."},{"n":"Тренирован для Обд*","t":"Вы не получаете **Сложность** в состоянии **Вовлечения**."},{"n":"Шквал Насилия","t":"Когда вы бьете персонажа ближней атакой, вы получаете +1 [ТОЧН] к вашей следующей дальней атаке против него; и, когда вы бьете персонажа дальней атакой, вы получаете +1 [ТОЧН] к вашей следующей ближней атаке против него. Этот эффект не суммируется."}]},"t_duelist":{"n":"Дуэлист","r":[{"n":"Партизан","t":"Получите +1 [ТОЧН] к первой атаке ближнего боя, которую вы совершаете **Основным Оружием Ближнего Боя** в свой ход."},{"n":"Мастер Клинка","t":"1/раунд, когда вы бьете **Основным Оружием Ближнего Боя**, вы получаете 1 **Кубик Мастера Клинка** — d6 — максимум 3 **Кубика Мастера Клинка**. Они действуют до тех пор, пока не будут израсходованы или пока не закончится текущая сцена. Вы можете тратить **Кубик Мастера Клинка** 1 к 1 на следующее:\n• **Парирование**: в качестве **реакции** при попадании в вас атакой ближнего боя вы получаете **Сопротивляемость** ко всему урону, нагреву и горению, наносимым атакой.\n• **Отражение**: в качестве **реакции** на атаку дальнего боя вы можете бросить любое количество **Кубиков Мастера Клинка**, потратив их: если вы бросите 5+ на любом из этих кубиков, вы получите Сопротивляемость ко всему урону, нагреву и горению, наносимым атакой.\n• **Финт**: в качестве **свободного действия** выберите соседнего цель: при движении вы игнорируете вовлечение и не провоцируете реакцию цели до начала вашего следующего хода.\n• **Проход**: в качестве **быстрого действия** выберите соседнего персонажа: он должен пройти спасбросок **Маневренности** или упасть. независимо от результата, вы можете свободно пройти через его пространство до конца вашего текущего хода, хотя вы не можете закончить свой ход в его пространстве."},{"n":"Неудержимый","t":"1/раунд, когда вы бьете атакой ближнего боя в свой ход, вы можете потратить **Кубик Мастера Клинка**, чтобы немедленно **Схватить** или **Протаранить** свою цель в качестве свободного действия после завершения атаки."}]},"t_drone_commander":{"n":"Командир Дрона","r":[{"n":"Пастырь","t":"Ваши системы **Дронов** получают **+5 ПЗ**. В качестве **протокола** вы можете переместить один управляемый вами **Дрон**, находящийся в пределах сенсоров, на **4 пространства**."},{"n":"Энергетический Рой","t":"1/раунд, когда вы совершаете атаку, которая расходует состояние **Захвата**, ваши **Дроны** немедленно испускают жестокий импульс энергии. Все персонажи по вашему выбору в пределах [Разрыв] 1 области, в центре которой каждый из ваших дронов, получают **1d6 [энерг] урона**. Каждый персонаж может быть поражен импульсом только от одного дрона, даже если области пересекаются."},{"n":"Приободрение","t":"В качестве быстрого действия вы можете послать импульс энергии союзному персонажу (включая **Дронов**) в пределах [Дальн] **3**, нарисовав **Линию** к нему. Вы можете продлить импульс от вашей цели к другому союзному персонажу, продлив **Линию** к нему, пока он находится в пределах **[Дальн]3**, и вы можете продолжать продлевать импульс (и **Линию**) таким образом, пока вы не нацелитесь на одного и того же персонажа дважды. союзные персонажи, которые используются в качестве целей импульса или находятся на пути **Линии**, получают **4 Усиления Щита**; враждебные персонажи на пути линии вместо этого получают **2 [энерг]** урона."}]},"t_engineer":{"n":"Инженер","r":[{"n":"Прототипы","t":"Когда вы проводите **Полный Ремонт**, вы можете, путем проб и ошибок, установить на свой мех прототип системы вооружения. Вы можете выбирать характеристики для своего прототипа оружия, основываясь на следующих правилах, каждый раз, когда вы проводите **Полный Ремонт**, перебрасывайте 1d6+2, чтобы определить **Ограничение** на данный момент:\n⟦A:w⟧Прототип Оружия⟦T⟧Основное [ОББ, ОБД, Винтовки, Пушки, ПУ, Звено], Ограничение [1d6+2], Избыточный урон⟦E⟧Это оружие - экспериментальный прототип, настроенный в соответствии с вашими требованиями.\nКогда вы устанавливаете его или во время Полного Ремонта, вы можете выбрать новый тип оружия, тип урона и либо [Угроза]1 (ближний бой), либо [Дальн]10 (все остальные типы). Кроме того, каждый раз, когда вы проводите **Полный Ремонт**, перебросьте 1d6+2, чтобы определить **Ограничение** количества применений этого оружия.\n**Урон:** 1d6+2 [кин], [взр] или [энерг].⟦Z⟧\nЭто оружие считается интегрированным и не требует слота."},{"n":"Ревизия","t":"Вы можете изменить основные компоненты вашего прототипа оружия, чтобы повысить его эффективность. Когда вы выполняете **Полный Ремонт**, выберите два из пунктов ниже:\n• **Улучшенная Оптика**: ваше оружие-прототип всегда получает +1 [ТОЧН] к атакам.\n• **Измененный Компьютер**: прототип вашего оружия - **Умный**.\n• **Снятая защита реактора**: каждый раз, когда вы атакуете своим прототипом оружия, вы можете выбрать — за стоимость 2 [нагрев] — атаковать одним из следующих вариантов, в зависимости от типа оружия:\n▪ **Дальнобойное:** [Конус]**3,** [Линия]**5,** или **[**[Взрыв]**1,** [Дальн]**10]**.\n▪ **Оружие Ближнего Боя (ОББ):** [Разрыв]**1.**"},{"n":"Финальный Проект","t":"Ваш прототип оружия теперь **Ограничен [2d6]** и наносит **1D6+4** урона."}]},"t_executioner":{"n":"Палач","r":[{"n":"Подрезать Крылышки","t":"1/раунд, когда вы бьете **Тяжелым** или **Сверхтяжелым** оружием ближнего боя, вы можете сделать еще одну атаку ближнего боя тем же оружием в качестве **свободного действия** против другого персонажа в пределах **Угрозы** и прямой видимости. Эта атака наносит половину урона, если она успешна."},{"n":"Размах по Широкой Дуге","t":"1/раунд, когда вы **совершаете критическое попадание Тяжелым** или **Сверхтяжелым** оружием ближнего боя, вы наносите **3** [кин] **урона** всем персонажам и объектам по вашему выбору в пределах **Угрозы** [Угроза], кроме врага, которого вы только что атаковали."},{"n":"Выхода Нет","t":"1/раунд, когда вы промахиваетесь при атаке ближнего боя, вы делаете повторный бросок против другой цели в пределах **Угрозы** и прямой видимости."}]},"t_exemplar":{"n":"Образец","r":[{"n":"Достойное Испытание","t":"В первый раз в свой ход, когда вы атакуете враждебного персонажа в пределах **[Дальн]3**, попав или промахнувшись, вы можете повесить на него **Метку Образца** в качестве свободного действия. Персонажи могут иметь только одну **Метку Образца** одновременно, каждая новая метка любого персонажа заменяют существующую.\nПерсонаж обладает **Меткой Образца** до начала вашего следующего хода, и пока она у него, вы получаете следующую реакцию:\n⟦A:r⟧Доблестная Помощь⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер:** Союзник промахивается по врагу с меткой.\n**Эффект:** Он может перебросить атаку. Он должен использовать второй результат, даже если он хуже.⟦Z⟧"},{"n":"Наказание","t":"1/раунд, когда персонаж с вашей **Меткой** атакует кого-то в радиусе [Дальн] **3** от вас, кроме вас, срабатывает ваше **Наблюдение**."},{"n":"До Самой Смерти","t":"В качестве **свободного действия**, когда вы отмечаете персонажа, вы можете вызвать его на смертельную дуэль: вы и персонаж с вашей **Меткой** получаете +3 [СЛОЖН] к атакам против персонажей или объектов, кроме друг друга, до конца текущей сцены или до уничтожения одного из ваших мехов. Если враг предпринимает любое действие, включающее бросок атаки против вас, попадание или промах, этот эффект прекращается для них до начала вашего следующего хода.\nПока действует \"**До Самой Смерти**\", вы не можете добровольно отойти от персонажа с вашей **Меткой**; кроме того, действие вашей **Метки** длится либо до конца текущей сцены, либо до уничтожения одного из ваших мехов, и вы не можете наносить **Метки** на новых персонажей."}]},"t_gunslinger":{"n":"Стрелок","r":[{"n":"Первое Слово","t":"Получите **+1 [ТОЧН]** к первому броску атаки, который вы делаете с помощью **Вспомогательного** дальнобойного оружия в свой ход."},{"n":"От Бедра","t":"Получите следующую реакцию:\n⟦A:r⟧Ответный Огонь⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер:** Враг поражает вас дальней атакой.\n**Эффект**: Вы можете немедленно атаковать его вспомогательным оружием дальнего боя, если он находится в зоне досягаемости.⟦Z⟧"},{"n":"Я Убиваю с Душой","t":"Вы получаете **Кубик Стрелка**, **1d6**, начиная с **6**. каждый раз, когда вы бьете **Вспомогательным** оружием дальнего боя, уменьшайте значение кубика стрелка на **1**. Когда значение **Кубика Стрелка** достигает **1**, вы можете вернуть его в значение **6**, чтобы получить **+2d6 дополнительного урона** при попадании и **ББ** к вашей следующей атаке **Вспомогательным** дальнобойным оружием. Эта атака также игнорирует укрытия. Значение **Кубика Стрелка** сохраняется между сценами, но восстанавливается до 6, когда вы делаете перерыв или проводите **Полный Ремонт**."}]},"t_grease_monkey":{"n":"Чумазый Механик","r":[{"n":"Несанкционированное Повышение Мощности","t":"Во время перерыва вы можете потратить 2 **Ремонта**, чтобы восполнить 1 использование всего оружия и систем, работающего с **Ограничением**."},{"n":"Узы Машины","t":"Когда вы **Стабилизируетесь**, вы устраняете все **Ослабления**, **Заклинивания**, **Обездвиживания**, **Замедления** и **Захваты Цели**, которые не были вызваны вашими собственными системами, талантами и т.д."},{"n":"Друзья в Высших Кругах","t":"Один раз за миссию во время перерыва вы можете вызвать посылку с припасами. Вы и ваши союзники можете восполнить **на единицу** расход всех **Ограниченных** видов оружия и систем, восстановить **1 Структуру**. Это не требует действия **Ремонта** и может быть использовано, даже если вы достигли **Лимита Ремонта**."}]},"t_hacker":{"n":"Хакер","r":[{"n":"Снего_пад","t":"Когда вы выполняете **техническую атаку**, расходующую **Захват**, ваша цель должна выбрать либо получить 2 [нагрев], либо быть отброшена на **3 пространства** в выбранном вами направлении."},{"n":"Безопасный Кряк","t":"Получите следующие возможности для вторжения:\n**Заблокировать Кабину**: Персонажи не могут **Взобраться** или **Спешиться** с выбранной цели, пока кабина не будет отремонтирована успешной проверкой **Инженерии** в качестве полного действия.\n**Отключить Жизнеобеспечение**: ваша цель получает +1 [СЛОЖН] ко всем спасброскам, пока система жизнеобеспечения не будет перезагружена успешной проверкой **Систем** в качестве **быстрого действия**.\n**Хакнуть/Взломать**: цель не может воспользоваться быстрыми или полными **Техническими действиями**, пока мех не будет **Выключен** или ядро компьютера не будет перезагружено с успешной проверкой **Систем** быстрым действием."},{"n":"Последний Аргумент Королей","t":"Получите следующую **Полной Технологии** опцию:\n⟦A:t⟧ПОСЛЕДНИЙ АРГУМЕНТ КОРОЛЕЙ⟦T⟧⟦E⟧Совершите техническую атаку против цели в пределах прямой видимости и **Сенсоров**. При успехе вы внедряете вирус, который вызывает небольшое расплавление в реакторе цели: она немедленно получает **Горение**, равное ее текущему **Нагреву**. Если это действие вызывает перегрев, оно засчитывается до того, как цель сбросит свой **Тепловой Максимум**.⟦Z⟧"}]},"t_heavy_gunner":{"n":"Тяжелая Артиллерия","r":[{"n":"Накрывающий Огонь","t":"В качестве **быстрого действия** выберите цель в пределах прямой видимости и **Дальности** одного из ваших **Тяжелых** видов оружия дальнего боя и в радиусе 10 пространств: она становится **Ослабленной** до начала вашего следующего хода. На время действия, если ваша цель перемещается более чем на 1 пространство, она теряет **Ослабленность**, но вы можете атаковать её в качестве реакции **Тяжелым** дальнобойным оружием с половиной урона, [нагрев], или [горение], и затем эффект закан-чивается. Вы можете сделать эту атаку в любой момент во время перемещения цели (например, дож-давшись, пока она выйдет из укрытия).\n**Накрывающий Огонь** может одновременно поражать только одного персонажа — последующие применения заменяют предыдущие, и эффект немедленно заканчивается, если ваша цель наносит вам урон."},{"n":"Удар Молотом","t":"Если вы успешно поразили цель, находящуюся под действием **Накрывающего Огня**, с помощью атаки реакцией, предоставляемой этим талантом, ваша цель становится **Обездвиженной** до конца своего следующего хода."},{"n":"Прерывание Огня","t":"Когда вы используете **Накрывающий Огонь**, вы можете выбрать две цели вместо одной. Каждая цель запускает и разрешает вашу атаку отдельно, и урон для одной цели завершает эффект только для этой цели."}]},"t_hunter":{"n":"Охотник","r":[{"n":"Выпад","t":"Раз в раунд, когда вы атакуете **Вспомогательным** оружием ближнего боя, перед атакой вы можете переместиться на 3 **пространства** прямо к персонажу. Это перемещение игнорирует вовлеченность и не провоцирует реакцию."},{"n":"Жонглер Ножами","t":"Всё ваше **Вспомогательное** оружие ближнего боя получает **Бросок 5**, если у него еще нет этого свойства — если оно уже имеет **Бросок**, он увеличивается до значения **5**. В конце вашего хода все оружие, которое вы бросили в этом ходу, автоматически возвращается к вам."},{"n":"Презрительный Клинок","t":"1/раунд, когда вы поражаете цель атакой ближнего боя, вы также можете **свободным действием** бросить **Вспомогательное** оружие ближнего боя в качестве атаки против любого противника в радиусе действия. Эта атака не может нанести дополнительный урон."}]},"t_infiltrator":{"n":"Лазутчик","r":[{"n":"Красться","t":"Во время хода получите следующие преимущества:\n• Вхождение в зону прямой видимости вражеских персонажей или перемещение из укрытия не лишает вас статуса **Скрытности**.\n• Вы можете свободно перемещаться через вражеские помещения, но не завершать свой ход в них.\n• Вы можете **Скрыться** даже на виду у врагов.\nЭти эффекты немедленно заканчиваются, когда заканчивается ваш ход (поэтому вы теряете **Скрытность**, если вы все еще находитесь в зоне прямой видимости или вне укрытия в это время)."},{"n":"Засада","t":"Когда вы начинаете свой ход из **Скрытности**, первая атака любого типа, которую вы совершаете, при попадании отправляет вашу цель в оцепенение. Ваша цель должна преуспеть в спасброске **Корпуса** или станет **Замедленной**, **Ослабленной** и не сможет выполнять действия до конца своего следующего хода."},{"n":"Выдающийся","t":"Когда вы теряете **Скрытность** (каким угодно образом), вы можете сначала выстрелить светошумовой гранатой в любого соседнего персонажа. Этот персонаж должен пройти спасбросок **Систем** или он сможет видеть только соседние ячейки до конца своего следующего хода.\nПосле этого вы можете двигаться со своей скоростью, игнорируя вовлечение и не провоцируя реакцию, а затем раскрываетесь обычным образом."}]},"t_juggernaut":{"n":"Джаггернаут","r":[{"n":"Импульс","t":"Когда вы **Ускоряетесь**, ваш следующий **Таран** до начала следующего хода получает +1 [ТОЧН] и получает цель на дополнительные **2 пространства**."},{"n":"Перенос Кинетической Массы","t":"1 раз в раунд, при Таране, если вы...\n•...переместите цель в пространство, занятое другим персонажем, другой персонаж должен успешно пройти спасбросок **Корпуса**, либо он будет **Сбит с ног.**\n•...толкаете цель в препятствие, достаточное, чтобы остановить её перемещение, ваша цель получает **1d6**[кин] урона."},{"n":"Неудержимая Сила","t":"Раз в раунд, когда вы **Ускоряетесь**, вы можете зарядить сервоприводы своего меха **Двигаясь** с максимальной скоростью по прямой, получите 1d3+3 [нагрев], и получайте следующие преимущества:\n• Вы можете свободно перемещаться сквозь персонажей такого же размера, что и ваш мех, или меньше; все персонажи, переместившиеся сквозь вас, должны успешно пройти спасбросок **Корпуса** или быть **Сбиты с ног**.\n• Любая местность, стены или другие неподвижные препятствия, через которые вы пытаетесь пройти, получают **20**[кин]**ББ урона**. Если этого достаточно, чтобы разрушить их, вы проходите; в противном случае ваше перемещение заканчивается.\n• Вы игнорируете **труднопроходимую местность**.\n• Ваше перемещение игнорирует вовлеченность и не провоцирует реакции."}]},"t_leader":{"n":"Лидер","r":[{"n":"Полевое Командование","t":"Получите 3 **Кубика Лидера** в виде d6: 1/ход, в свой ход в качестве свободного действия, вы можете отдать приказ союзному Игроку, с которым вы можете общаться, описав курс действий, и дать ему **Кубик Лидера**. Они могут либо потратить **Кубик Лидера**, чтобы получить **+**1 к любому действию, которое непосредственно следует из этого приказа, либо вернуть его вам в качестве свободного действия. Союзники могут иметь по одному **Кубику Лидера** за раз, которые длятся до тех пор, пока не будут использованы или до конца текущей сцены.\nВы не можете использовать **Кубики Лидера** от других персонажей, пока у вас в наличии хотя бы один. Если у вас их нет, вы восстанавливаете 1 **Кубик Лидерства**, когда отдыхаете, или восстанавливаете все, когда выполняете **Полный Ремонт**.\n**Кубики Лидера** расходуются при использовании."},{"n":"Открытые Каналы","t":"Получите **5 Кубиков Лидера** вместо **3**; теперь вы можете отдать команду в качестве реакции в начале хода любого другого игрока, любое количество раз за раунд."},{"n":"Чувство Воодушевления","t":"Получите 6 **Кубиков Лидера** вместо 5. Союзники, у которых есть ваши Кубики Лидера, могут потратить их, чтобы уменьшить урон на **-1d6** при получении урона или нанести **+1d6 дополнительного урона** при атаке."}]},"t_nuclear_cavalier":{"n":"Ядерный Кавалерист","r":[{"n":"Агрессивный Тепловой Удар","t":"Первый бросок атаки, который вы делаете в свой ход, находясь в **Опасной Зоне** дает **+2**[нагрев] на попадание.\n*Если вы входите в Опасную Зону во время своего хода, талант срабатывает при вашей следующей атаке.* (примечание из английской книги; в русском переводе пропущено)"},{"n":"Расплавленное Излияние","t":"Первая ближняя или дальняя атака, которую вы делаете в свой ход, находясь в **Опасной Зоне** даёт [энерг] вместо [кин] или [взр] и дополнительно наносит +1d6[энерг] дополнительного урона при попадании."},{"n":"Эй, Лови!","t":"Вы модифицировали своего меха, чтобы запускать его перегретые топливные стержни во врагов. Получите следующее оружие в качестве интегрированного слота:\n⟦A:w⟧Стержневая Пушка⟦T⟧Основное ОБД, Ограниченное 3, Уникальное · Дальн. 3, Угроза 3 · 1d3+2 энерг.⟦E⟧**При Атаке:** Сбрасывает **4**[нагрев].⟦Z⟧"}]},"t_siege_specialist":{"n":"Спец по Осадам","r":[{"n":"Отбойный Молот","t":"Если у вас есть **Пушка**, то в качестве быстрого **действия** вы можете выпустить снаряд отбойного молотка из подствольной пусковой установки, автоматически нанося **10 [кин] ББ** урона по участку **Размером в 1** секцию любого объекта в Радиусе **действия** (например, укрытие, размещаемое снаряжение, здание или местность). Все персонажи, находящиеся рядом с целью, отбрасываются от нее на 2 пространства и получают **2 [кин]**."},{"n":"Удар","t":"Раз в раунд, перед тем как провести атаку **Пушкой**, все персонажи, находящиеся рядом с вами, должны преуспеть в спасброске Корпуса или будут отброшены на 1 пространство назад и сбиты с ног. Затем вы отскакиваете на 1 пространство в любом направлении."},{"n":"Сопутствующий Урон","t":"Раз в раунд, когда вы наносите критическое попадание по персонажу или объекту с помощью Пушки, вы можете выбрать взрыв дополнительных боеприпасов, вызывающий [Разрыв]**2** взрыва вокруг вашей цели. Персонажи в зоне поражения должны либо Упасть на землю в качестве реакции, либо принять **2**[взр] и быть отброшенными на 2 пространства назад от центра атаки."}]},"t_skirmisher":{"n":"Мастер Перестрелок","r":[{"n":"Встроенные Зенитные Пусковые Установки","t":"В начале своего хода вы получаете **мягкое укрытие**. Вы теряете это укрытие, если атакуете или заставляете другого персонажа сделать спасбросок."},{"n":"Предотвратить Захват","t":"До или после того, как вы **Перестреливаетесь** (в том числе в качестве реакции, например, от **Наблюдения**), вы можете переместиться на 2 пространства. Это перемещение игнорирует вовлеченность и не провоцирует реакцию."},{"n":"Отклониться","t":"Первая атака, предпринятая против вас в качестве реакции в любом раунде, автоматически промахивается."}]},"t_spotter":{"n":"Наблюдатель","r":[{"n":"Партикуляризм","t":"Когда союзный персонаж, находящийся рядом с вами, атакует цель и расходует **Захват**, он может бросить два раза и выбрать любой результат."},{"n":"Паноптикон","t":"В конце вашего хода, если вы не двигались и использовали действие **Захват Быстрой Техники,** вы можете **сделать Захват** один раз в качестве свободного действия. Кроме того, при **Захвате** вы узнаете **Броню**, **Скорость**, **Уклонение**, **Э-Защиту**, **Навыки Меха** и текущие **ПЗ** вашей цели и можете поделиться этой информацией с союзниками."},{"n":"Ликвидация Бентама/фуко","t":"В качестве **быстрого действия** при **Захвате** вы можете выбрать союзного персонажа, находящегося рядом с вами: он может немедленно совершить любое **быстрое действие** в качестве реакции, используя состояние **Захвата** вашей цели. Его действие не обязательно должно быть атакой, но он получит выгоду от использования состояния **Захвата**, если решит атаковать."}]},"t_stormbringer":{"n":"Громовержец","r":[{"n":"Сейсмическое Ослабление","t":"1/раунд, когда вы успешно атакуете с помощью **Пусковой Установки** и используете **Захват**, вы также можете **Сбить цель с ног**."},{"n":"Штормовой Изгиб","t":"Вы оснастили свой мех вспомогательными системами ударных ракет. Раз в раунд, когда вы поражаете персонажа или объект с помощью **Пусковой Установки**, вы можете выбрать один из следующих эффектов:\n• **Молния**: вы направляете контролируемый взрыв ракеты в эту цель. Она должна преуспеть в спасброске **Корпуса**, иначе она будет отброшена от вас на **3 пространства**; затем взрывная волна и отдача отбрасывает вас на **3 пространства** назад, в сторону от направления выстрела.\n• Гром: Вы запускаете рой ракет в область [Разрыв] 2 вокруг цели. Персонажи в этой области должны успешно пройти спасбросок **Манёвренности** или они будут отброшены на **1 пространство** назад, в сторону от цели. Основная цель не получает урон."},{"n":"Ливень","t":"Вы получаете **Кубик Ливня**, **1d6**, начиная с **6**. Каждый раз, когда вы используете **Штормовой Изгиб**, уменьшайте сторону Кубика Ливня на **1**, до минимума **1**.\nКогда значение **Кубика Ливня** достигнет 1, вы можете сбросить его до 6, затем совершить мощную атаку **в качестве полного действия,** нацелившись на противника в пределах прямой видимости и **Дальности** 15: он должен успешно пройти спасбросок **Маневренности**, иначе он получит **2d6** [взр], эффект **Ошеломленния** и будет **Сбит с ног**. В случае успеха он получит **половину урона** и окажется **Сбит с ног**, но не получит эффект ошеломления.\nЗначение вашего **Кубика Ливня** сохраняется между сценами, но оно возвращается на значение 6, когда вы делаете перерыв или выполняете **Полный Ремонт**."}]},"t_tactician":{"n":"Тактик","r":[{"n":"Оппортунист","t":"1/раунд, получите +1 [ТОЧН] к любой атаке ближнего боя, если хотя бы один союзный персонаж находится в состоянии Вовлечения с вашей целью."},{"n":"Солнечный Переход","t":"1/раунд, получите +1 [ТОЧН] к любой дальнобойной атаке, сделанной, если вы находитесь в более высокой точке, чем ваша цель."},{"n":"Перекрестный Огонь","t":"Получите следующую реакцию:\n⟦A:r⟧Фланг⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер:** Персонаж, не имеющий укрытия от вашей позиции, успешно атакован союзным персонажем.\n**Эффект:** Вы можете нацелить на них **Наблюдение**, нанося половину урона, [нагрев]или [горение] при попадании.⟦Z⟧"}]},"t_technophile":{"n":"Технофил","r":[{"n":"Фрагмент Раба","t":"Вы создали индивидуальную НЧЛ. Эта НЧЛ может говорить с вами и обладает индивидуальностью, но она менее развита, чем большинство НЧЛ, и не способна к самостоятельному мышлению, полагаясь на вас. Действуя в одиночку, она будет следовать последним указаниям и защищаться при необходимости; однако она обладает ограниченной инициативой и не пользуется вашими талантами.\nВы можете выбрать для своего меха следующую систему. В отличие от других систем ИИ, она стоит 0 **СО**.\n⟦A:s⟧НЧЛ класса \"Раб\"⟦T⟧ИИ, Уникальное⟦E⟧Ваш мех получает метку **ИИ**.⟦Z⟧"},{"n":"Фрагмент Студента","t":"Ваша пользовательская НЧЛ развилась на следующую ступень и теперь способна к самостоятельному мышлению. Она может принимать сложные решения и суждения и действовать самостоятельно, без инструкций. Замените НЧЛ класса Слуга вашего меха на следующую систему:\n⟦A:s⟧НЧЛ класса \"Студент\"⟦T⟧ИИ, Уникальное, 1/Раунд⟦E⟧Ваш мех получает метку **ИИ**.\n1/раунд, с помощью своей НЧЛ, вы можете повторить любую проверку навыков меха или спасбросок. Новый результат считается основным, даже если он хуже.⟦Z⟧"},{"n":"Озарение","t":"Получите следующие преимущества:\n• ИИ в вашем мехе, не могут войти в каскад, пока вы сами не решите их отпустить.\n• До тех пор, пока ваша пользовательская НЧЛ ручается за вас, НЧЛ, находящиеся в каскаде или без кандалов, больше не относятся к вам равнодушно. Мало кто другой может быть для них значим, как вы.\n• Замените НЛЧ класса \"Студент\" вашего меха на следующую систему:\n⟦A:s⟧НЧЛ класса \"Озарённый\"⟦T⟧Уникальное, 1/Раунд⟦E⟧Ваш мех получает метку ИИ; однако эта НЧЛ не засчитывается в число ИИ, которые вы устанавливаете одновременно.\nЭта НЧЛ получает преимущества от ваших талантов при пилотировании меха. Кроме того, вы можете носить её с собой вне своего меха в виде миниатюрного ящичка, либо в виде интегрированного в скафандр устройства, либо в виде импланта с жестким портом.\n1/раунд, с помощью своей НЧЛ, вы можете повторить любую проверку навыков меха или спасбросок. Новый результат считается основным, даже если он хуже.⟦Z⟧"}]},"t_vanguard":{"n":"Авангард","r":[{"n":"Этикет Рукопожатия","t":"Получите **+1**[ТОЧН] при использовании **ОБД** для атаки целей в пределах [Дальн]**3**."},{"n":"Прозрачный Искатель","t":"Вы улучшили свои сенсоры и боеприпасы, чтобы пробивать, проникать или иным образом игнорировать укрытия на близком расстоянии. Пока у вас есть прямая видимость, вы игнорируете как **мягкие, так и твердые укрытия** при использовании **ОБД** для атаки целей в пределах [Дальн]**3**."},{"n":"Семпер Виджило","t":"Вы можете атаковать с **Наблюдением**, используя **ОБД**, когда враждебные персонажи входят, выходят или покидают пространство в пределах вашей **Угрозы**, независимо от того, начали ли они там свое перемещение."}]},"t_walking_armory":{"n":"Ходячая Оружейная","r":[{"n":"Оружейная","t":"Вы носите с собой запас специальных боеприпасов, которые можно использовать со всеми основными видами оружия дальнего боя. Получите следующую систему:\n⟦A:c⟧Футляр для Боеприпасов⟦T⟧0 СП, Ограниченное 6⟦E⟧Раз в ход, когда вы атакуете основным дальнобойным оружием, вы можете потратить заряды, чтобы применить один из следующих эффектов к вашей атаке с указанной стоимостью:\n**• Громадина** (1 заряд)**:** Атака приобретает эффект **Толчок** 1 и наносит [взр]**урон**.\n**• Шок** (1 заряд)**:** Атака наносит [энерг] **урон**. Выберите одну цель, на которую направлена ваша атака; соседние персонажи получают **1** [энерг] **ББ**, независимо от того, попали вы или промахнулись.\n**• Дозатор Гранат** (1 заряд)**:** Атака становится **Дуговой** и наносит [кин]**урон**.⟦Z⟧"},{"n":"Расширенный Портфель","t":"Ваш **Футляр для Боеприпасов** получает новые типы патронов, каждый из которых стоит два заряда вместо одного:\n• **Хелфаер** (2 заряда)**:** Атака наносит [энерг]**урон** и наносит бонусный урон как [горение].\n• **Джагер** (2 заряда): Атака получает значение **Толчок 2**, наносит [взр]**урон**, и один персонаж, пораженный атакой — на ваш выбор — должен успешно пройти спасбросок **Корпуса** или он **будет Сбит с ног**.\n• **Подкалиберный** (2 заряда)**:** Атака получает **ББ** и наносит[кин]**урон**."},{"n":"Эффективность","t":"Если вы совершаете **критическое попадание**, используя боеприпасы из своего **Футляра для Боеприпасов**, вы не тратите заряды. Если ваша атака имеет более одной цели, этот эффект применяется только к первому броску атаки."}]},"t_spaceborn":{"n":"Рождённый в Космосе","r":[{"n":"Дом в Пустоте","t":"Все мехи, которые вы собираете, имеют встроенные средства для работы в открытом космосе: вы не получаете штрафов под водой и в невесомости. **Быстрым действием** вы можете перенаправить в них энергию, чтобы пролететь **3 пространства**, получив [нагрев], равный Размеру меха + 1; в конце перемещения нужно приземлиться, иначе вы падаете."},{"n":"Морские Ноги","t":"**1/раунд**, когда ваш мех непроизвольно перемещается из-за атаки другого персонажа или проваленного спасброска, навязанного другим персонажем, вы выбираете направление перемещения. Кроме того, когда ваш мех встаёт после **Сбивания**, он может **свободным действием** переместиться на **2 пространства** в любом направлении, игнорируя вовлечение и не вызывая реакций."},{"n":"Драчун","t":"**1/раунд**, когда ваш мех попадает по персонажу ближней атакой, он может сразу дать этому персонажу **+1** [СЛОЖН] на все проверки и спасброски против **Толчка**, **Сбивания**, **Замедления** и **Обездвиживания** до конца его следующего хода — включая эффекты самой этой атаки."}]},"t_black_thumb":{"n":"Чёрный Палец","r":[{"n":"Из Плоти в Металл","t":"**Спешивание** для вас — **быстрое действие**, а не полное. Спешившись, ваш пилот получает **личный щит**: в следующий раз, когда пилот должен получить урон, урон снижается до 0, и щит рассеивается. Иначе он рассеивается в конце сцены. Одновременно может быть только один личный щит — новый заменяет прежний."},{"n":"Родео","t":"**Протоколом** вы бросаете управление, открываете люк и наполовину вылезаете наружу, начиная **РОДЕО ЧЁРНОГО ПАЛЬЦА** и получая **личный щит** (как выше). Во время родео пилот невосприимчив к непроизвольному перемещению, занимает пространство меха и перемещается вместе с ним. Это не считается Спешиванием; снаружи мехом управлять нельзя, поэтому он бездействует, если не может действовать сам (например, если управление передано НЧЛ — это можно сделать тем же протоколом).\nВо время родео пилот — допустимая цель и получает урон как обычно. Если вы по любой причине теряете личный щит, вас загоняет обратно в мех, родео заканчивается, и в свой следующий ход начать его снова нельзя. Закончить родео можно **быстрым действием** в любой свой ход.\nВо время родео пилот может совершать только действия Чёрного Пальца:\n⟦A:s⟧Тушение⟦T⟧Полное Действие⟦E⟧Ваш мех сразу снимает всё **горение** и получает **Сопротивляемость** к горению до начала вашего следующего хода.⟦Z⟧\n⟦A:s⟧Полевой Ремонт⟦T⟧Полное Действие⟦E⟧Ваш мех получает **Усиление Щита 2** и снимает **Замедление** или **Обездвиживание**.⟦Z⟧\n⟦A:s⟧Перенастройка Вентиляции⟦T⟧Полное Действие⟦E⟧Ваш мех снимает **2** [нагрев] и **Ослабление** или **Заклинивание**.⟦Z⟧\nСостояния, наложенные на себя самим, этими действиями снять нельзя."},{"n":"Мастер Родео","t":"Действия Чёрного Пальца можно применять к соседним союзным мехам."}]},"t_house_guard":{"n":"Домашняя Гвардия","r":[{"n":"Передний Ряд","t":"Для ваших эффектов на союзных персонажей (от черт, талантов, систем или оружия), требующих соседства с вашим мехом, вы считаетесь соседним в пределах [Дальн]2."},{"n":"Великий Страж","t":"Ваш мех получает черту **Страж**, если её нет (соседние союзники могут использовать ваш мех как **твёрдое укрытие**). Кроме того, Страж теперь даёт всем соседним союзникам **лёгкое укрытие** со всех направлений."},{"n":"Щит Легиона","t":"**1/раунд**, когда вы уменьшаете урон союзному персонажу, отменяете атаку против него или заставляете её промахнуться, вы можете нанести атакующему **2** [энерг] и **Сбить его с ног**."}]},"t_pankrati":{"n":"Панкратий","r":[{"n":"Пришёл","t":"**+1** [ТОЧН] на ближние атаки по **Обездвиженным** и **Замедленным** целям."},{"n":"Увидел","t":"**1/сцена** вы можете **свободным действием** в свой ход совершить **Доблестный Натиск**: переместиться до **удвоенной Скорости**, игнорируя штрафы местности. Двигаться нужно по прямой и закончить натиск рядом с враждебным персонажем; начинать натиск рядом с враждебным персонажем нельзя. В конце натиска все соседние враждебные персонажи **Замедлены** до конца своего следующего хода."},{"n":"Победил","t":"Если вы начинаете Доблестный Натиск рядом с союзными персонажами, они могут сразу после натиска совершить **Ускорение** реакцией."}]},"t_empath":{"n":"Эмпат","r":[{"n":"Симпатическое Предвидение","t":"Способность чувствовать субъективность других даёт вам сверхъестественное умение предугадывать действия союзников и направлять их своим влиянием. Вы получаете реакцию:⟦A:r⟧Симпатическое Предвидение⟦T⟧Реакция, 1/сцена⟦E⟧**Триггер**: союзный персонаж в прямой видимости совершает проверку навыка, атаку или спасбросок.\n**Эффект**: персонаж может не бросать кубик, а считать, что на d20 выпало **10**.⟦Z⟧"},{"n":"Склонить к Воле","t":"**1/сцена**, когда союзный персонаж в прямой видимости совершает проверку структуры или перегрева, он может бросить дважды и выбрать любой результат."},{"n":"Общая Субъективность","t":"**1/сцена** **быстрым действием** вы черпаете глубокие запасы воли, даруя союзному персонажу в прямой видимости необычайную ясность восприятия. Ваш мех сразу становится **Ошеломлённым** до начала вашего следующего хода, а ваше восприятие почти полностью сливается с восприятием союзника. До конца его следующего хода, совершая атаку, проверку или спасбросок, он может бросать как обычно или считать, что на d20 выпало **10**. Решать нужно до броска."}]},"t_prospector":{"n":"Старатель","r":[{"n":"Застолбить Участок","t":"**Подкоп**: персонаж убирается с поля боя и сразу ставится в свободное допустимое пространство. Это считается перемещением на 1 пространство и провоцирует реакции.\nВы получаете быстрое действие «Создать Вход» (**1/сцена**). Пока вы и союзники полностью находитесь во Входе, в ваши собственные ходы вы получаете реакцию «Подземная Перегруппировка».⟦A:s⟧Создать Вход⟦T⟧Быстрое Действие, 1/сцена⟦E⟧Стоя на твёрдой земле, вы создаёте вокруг себя **Вход** [Разрыв]1. Затем делаете **Подкоп** в любую точку до 5 пространств и создаёте там ещё один Вход [Разрыв]1. Входы остаются до конца сцены. Местность и её участки, пересекающиеся со Входом, получают **20** [взр] **ББ**. До конца хода вы не можете совершать реакции.⟦Z⟧⟦A:r⟧Подземная Перегруппировка⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер**: в ваш ход вы полностью находитесь во Входе.\n**Эффект**: вы сразу делаете **Подкоп**, заканчивая перемещение полностью внутри другого Входа, созданного тем же персонажем.⟦Z⟧"},{"n":"Золотая Лихорадка","t":"Враждебные персонажи в зоне, где создаётся Вход, проходят спасбросок **Корпуса**, иначе **Сбиты с ног**.\nКроме того, после «Создать Вход» союзники, полностью находящиеся в вашем первом Входе, могут использовать «Подземную Перегруппировку», даже если сейчас не их ход."},{"n":"Главная Жила","t":"«Создать Вход» становится **1/раунд**, и в сцене его можно использовать на один раз больше. Все ваши Входы связаны между собой для **Подкопа**."}]},"t_iconoclast":{"n":"Иконоборец","r":[{"n":"Прегрешение","t":"Вы можете установить на мех систему **Нестабильный НИИ**."},{"n":"Трансмутация","t":"Совершив любое действие, данное НИИ (кроме передачи ему управления мехом протоколом), вы можете сразу совершить свободное действие «Трансмутирующая Искра». Каждый НИИ может запускать его **1/раунд**.⟦A:s⟧Трансмутирующая Искра⟦T⟧Свободное Действие⟦E⟧Вы выпускаете дугу молнии [Линия]3. Персонажи в линии на ваш выбор получают **2** [энерг] **ББ**.⟦Z⟧"},{"n":"Трансценденция","t":"Вы получаете **Куб Трансценденции** — d3, начиная с **3**. Используя «Трансмутирующую Искру», уменьшите куб на 1. Если куб на **1**, когда вы используете искру, вы можете сразу войти в **трансцендентное состояние** и сбросить куб на 3. До конца вашего следующего хода:\n• куб не уменьшается;\n• «Меметическая Искра» получает **+4 урона** и **+5 к дальности**;\n• если вы не летите и не карабкаетесь, вы вынужденно **парите** ровно в 1 пространстве над любой поверхностью;\n• **Невосприимчивость** к вынужденному перемещению.\nКаждый раз, когда вы уходите в каскад и теряете управление мехом, вы на это время в трансцендентном состоянии. НИИ в каскаде пользуются преимуществами этого таланта. Куб сбрасывается в конце сцены."}]},"t_field_analyst":{"n":"Полевой Аналитик","r":[{"n":"Тактическая Разведка","t":"Когда союзник в прямой видимости промахивается атакой, вы знаете, на сколько. Вы получаете реакцию «Превосходная Разведка».⟦A:r⟧Превосходная Разведка⟦T⟧Реакция, 2/раунд⟦E⟧**Триггер**: союзник в прямой видимости бросил атаку.\n**Эффект**: прибавьте к броску **1**. Это может превратить промах в попадание или попадание в крит. На каждый бросок атаки — только один раз.⟦Z⟧"},{"n":"Обработка Информации","t":"Вы получаете **Куб Разведданных** — d6, начиная с **1**.\nВ конце вашего хода, если в этом ходу вы не совершали действий, затрагивающих враждебных персонажей (кроме **Сканирования**), куб растёт на **2** (максимум 6).\nИспользуя «Превосходную Разведку», вы можете прибавить к броску значение куба вместо 1; после этого куб сбрасывается на 1. Куб сбрасывается в конце каждой сцены."},{"n":"Активные Помехи","t":"Когда враждебный персонаж в прямой видимости попадает атакой, вы знаете его результат броска.\nВы также можете использовать «Превосходную Разведку», когда атаку бросил враждебный персонаж в прямой видимости: вместо прибавления вы так же вычитаете. На каждый бросок атаки — только один раз."}]},"mf_orator":{"n":"Оратор","r":[{"n":"Убедительная Риторика","t":"Вы получаете реакцию **Убедительная Риторика**.⟦A:r⟧Убедительная Риторика⟦T⟧Реакция, 1/раунд⟦E⟧**Триггер**: вы или союзный персонаж совершаете быстрое технологическое действие **Сканирование** против враждебного персонажа.\n**Эффект**: вы открываете с целью изолированный канал связи, и она **Ослаблена**, пока не преуспеет в проверке **Систем** в конце своего хода; иначе снять это Ослабление нельзя. Повторное использование реакции на другом персонаже досрочно снимает Ослабление с первого.⟦Z⟧"},{"n":"Голос Разума","t":"Вы начинаете бой с **1 Кубом Оратора** (d6) — силой вашей речи. В конце хода, если вы в этом ходу не атаковали враждебных персонажей и не навязывали им спасброски, вы получаете **+1 Куб Оратора** (максимум **3**). Кубы держатся, пока не потрачены или не кончилась сцена.\n**1/раунд** **свободным действием** можно потратить Кубы Оратора на один эффект, если вы можете связаться с целью:\n• **Ободрить** (1 куб): союзник в прямой видимости проходит проверку **Систем** против любого состояния, наложенного не им самим, с Кубом Оратора как бонусом точности; при успехе состояние снимается.\n• **Выяснить** (2 куба): выберите враждебного персонажа в прямой видимости. Следующая атака по нему (вашей или союзника) бросается дважды, берётся лучший результат.\n• **Посеять Сомнение** (2 куба): выберите враждебного персонажа в прямой видимости. До конца его следующего хода он не может пользоваться системами и чертами союзников и быть их целью.\nВ программе: Кубы Оратора — счётчик в разделе «Бой»."},{"n":"Марш Десяти Тысяч","t":"Вы начинаете бой с **ещё одним** Кубом Оратора. Кроме того, у **Голоса Разума** появляется вариант:\n• **Деморализовать** (3 куба): выберите враждебного персонажа в прямой видимости. До конца своего следующего хода он не может двигаться, атаковать, навязывать спасброски и совершать технологические действия. После этого до конца сцены у него **Невосприимчивость** к этому эффекту."}]},"t_demolitionist":{"n":"Подрывник","r":[{"n":"Осколки и Зачистка","t":"Используя **Гранату**, можете выбрать одного персонажа в зоне — эффекты гранаты на него не действуют.\nКроме того, в конце каждой сцены за каждую невзорвавшуюся **Мину**, установленную из **Ограниченной** системы с меткой **Мина**, этой системе возвращается **1 заряд**."},{"n":"Распасовщик","t":"Ваши **Гранаты** получают **+3 Дальности**, а **Мины** можно ставить на расстоянии до [Дальн]**3** (или с **+3 Дальности**, если у них она уже есть). Кроме того, гранатам и минам не нужна прямая видимость, если до цели можно проложить путь."},{"n":"Ложись!","t":"Ваши заряды снаряжены особыми начинками. **1/раунд** выберите одно:\n• бросая **Гранату**, до трёх персонажей в пределах [Дальн]3 от выбранного пространства получают **2 [взр]** и отбрасываются осколками на 1 пространство в выбранном вами направлении;\n• когда персонаж проваливает спасбросок против вашей **Мины**, он получает **+1d6 [взр]** бонусного урона. Если мина обычно урона не наносит (со спасброском или без), один персонаж в зоне вместо этого получает **1d6 [взр]**."}]},"t_sysop":{"n":"Сисоп","r":[{"n":"Прививка","t":"Когда вы **Подкрепляете** союзного персонажа, дополнительная Точность сохраняется до его следующей проверки навыка или спасброска."},{"n":"Брандмауэр","t":"Когда вы **Подкрепляете** союзного персонажа, технологические атаки против него получают **+1** [СЛОЖН] до конца его следующего хода."},{"n":"Агрессивные Контрмеры","t":"**1/раунд**, **Подкрепляя** союзника, вы запускаете в его реакторе особый цикл: следующий нагрев, который он получил бы от враждебного персонажа, уменьшается до **0**, а этот враждебный персонаж получает **2 нагрева** и **Ослаблен** до конца своего следующего хода. Эффект не суммируется и действует, пока не сработает."}]}},"cbs":{"cb_auto_stabilizing_hardpoints":{"n":"Автостабилизирующиеся Узлы Подвески","t":"Выберите один слот. Оружие, прикрепленное к этому слоту, получает +1 [ТОЧН].","src":"GMS"},"cb_overpower_caliber":{"n":"Преобладающий Калибр","t":"Выберите одно оружие. **1/раунд**, когда вы атакуете, вы можете нанести дополнительный урон +1d6","src":"GMS"},"cb_improved_armament":{"n":"Усиленное Вооружение","t":"Если ваш мех имеет менее трех слотов (не считая встроенных слотов), он получает дополнительный **Гибкий** слот.","src":"GMS"},"cb_integrated_weapon":{"n":"Встроенное Оружие","t":"Ваш мех получает новый встроенный слот, вмещающий одно **Вспомогательное** оружие. Это оружие может быть использовано **1/раунд** в качестве **свободного действия**, когда вы стреляете из любого другого оружия на вашем мехе. Оно не может быть модифицировано.","src":"GMS"},"cb_mount_retrofitting":{"n":"Модернизация Слота","t":"Замените один слот на **Осн./Вспом.** слот.","src":"GMS"},"cb_universal_compatibility":{"n":"Универсальная Совместимость","t":"Каждый раз, когда вы тратите МЯ на активацию Системы Ядра, вы также можете совершить свободное действие, чтобы восстановить все ПЗ, сбросить весь Нагрев и бросить 1d20: при 20 — восстановить 1 МЯ.","src":"GMS"},"cb_briareos_frame":{"n":"Рама Бриарей","t":"Пока у вашего меха не более **1 Структуры,** вы получаете **Сопротивляемость ко всему урону**. Когда его **ПЗ** и **Структура** уменьшаются до **0**, мех не уничтожается: вместо этого вы должны делать **проверку структурного урона** каждый раз, когда он получает урон. Находясь в этом состоянии, ваш мех не может восстановить **ПЗ**, пока вы не сделаете перерыв или не выполните **Полный Ремонт**, после чего вашего меха можно будет отремонтировать обычным образом.","src":"IPS-N"},"cb_fomorian_frame":{"n":"Рама Фомор","t":"Увеличивайте **Размер** своего меха на единицу (например, с **1/2** до **1**, с **1** до **2** или с **2** до **3**) до максимального **3 Размера**. Вы не можете быть сбиты с ног, притянуты или отброшены назад персонажами меньшего размера, независимо от того, какая система или оружие вызывает эффект.","src":"IPS-N"},"cb_gyges_frame":{"n":"Рама Гигес","t":"Мех, построенный на основе образца Гигес, предназначен для боевых действий — он оснащен точно настроенными стабилизаторами и надежным набором программного и аппаратного обеспечения для прицеливания. Вы получаете +1 [ТОЧН] ко всем проверкам и спасброскам **Корпуса** и **+1 Угрозы** всем видам оружия ближнего боя.","src":"IPS-N"},"cb_reinforced_frame":{"n":"Усиленная Рама","t":"Вы получаете **+5 ПЗ**.","src":"IPS-N"},"cb_sloped_plating":{"n":"Наклонное Покрытие","t":"Вы получаете **+1 Брони**, вплоть до максимума (**+4**).","src":"IPS-N"},"cb_titanomachy_mesh":{"n":"Титаномахическая Сетка","t":"1/раунд, когда вы успешно **Тараните** или **Хватаете** меха, вы можете снова **Таранить** или **Хватать** в качестве свободного действия. Кроме того, когда вы отбрасываете цели назад ближними атаками, вы отбрасываете их назад еще на 1 пространство.","src":"IPS-N"},"cb_all_theater_movement_suite":{"n":"Всетеатральный Набор Передвижения","t":"Вы можете летать при **Ускорении** или стандартном перемещении; тем не менее, вы получаете [нагрев]1 в конце каждого своего хода, в котором вы летите таким образом.","src":"SSC"},"cb_full_subjectivity_sync":{"n":"Полная Субъективная Синхронизация","t":"Вы получаете +2 **Уклонения**.","src":"SSC"},"cb_ghostweave":{"n":"Призрачная Ткань","t":"Во время вашего хода вы становитесь **Невидимым**. Если в свой ход вы не совершаете никаких действий, кроме стандартного перемещения, **Скрытности** и **Ускорения**, вы остаетесь **Невидимым** до начала своего следующего хода. Вы немедленно перестаете быть **Невидимым**, возникновении реакции.","src":"SSC"},"cb_integrated_nerveweave":{"n":"Интегрированное Нервное Сплетение","t":"Вы перемещаетесь на +2 пространства, когда **Ускоряетесь**.","src":"SSC"},"cb_kai_bioplating":{"n":"Биопокрытие Кай","t":"Вы получаете +1 [ТОЧН] ко всем проверкам и спасброскам **Маневренности**; кроме того, вы карабкаетесь и плывете с нормальной скоростью, игнорируете труднопроходимую местность и при стандартном перемещении можете прыгать горизонтально на полной **Скорости** и вверх в половину от своей **Скорости** (в любой комбинации).","src":"SSC"},"cb_neurolink_targeting":{"n":"Наводящийся Нейролинк","t":"Ваше оружие дальнего боя получает +3 Дальности.","src":"SSC"},"cb_the_lesson_of_disbelief":{"n":"Урок Неверия","t":"Вы получаете +1 [ТОЧН] к проверкам и спасброскам **Систем** и +2 к **Э-Защите**.","src":"HORUS"},"cb_the_lesson_of_the_open_door":{"n":"Урок Открытой Двери","t":"Ваш **Спасбросок** Цели **увеличивается** на **+2**; кроме того, 1/раунд, когда персонаж проваливает спасбросок против вас, он получает 2 [нагрев].","src":"HORUS"},"cb_the_lesson_of_the_held_image":{"n":"Урок Удерживаемого Образа","t":"1/раунд, в качестве **реакции** в начале хода любого союзного персонажа, вы можете совершить техническое действие **Захвата** против любого персонажа в пределах прямой видимости и **Сенсоров**.","src":"HORUS"},"cb_the_lesson_of_thinking_tomorrows_thought":{"n":"Урок Мышления — Мысль Завтрашнего Дня","t":"Когда вы наносите удар **технической атакой**, ваша следующая **ближняя атака** по той же цели получает +1 [ТОЧН], и ее урон не может быть уменьшен никаким образом.","src":"HORUS"},"cb_the_lesson_of_transubstantiation":{"n":"Урок Пресуществления","t":"Каждый раз, когда вы получаете **структурный урон**, вы исчезаете в не-пространстве и перестаете быть действительной целью. Вы снова появляетесь в том же месте в начале вашего следующего хода. Если это место занято, вы появляетесь в ближайшем свободном месте (выбранном вами).","src":"HORUS"},"cb_the_lesson_of_shaping":{"n":"Урок Формирования","t":"Вы можете установить дополнительный ИИ в своего меха. Если один из них переходит в каскад (или становится неподвластным повествованию), другой не позволяет ему взять контроль над вашим мехом. Вы теряете контроль над своим мехом, только если обе системы или оборудование с метками ИИ входят в каскад.","src":"HORUS"},"cb_adaptive_reactor":{"n":"Адаптивный Реактор","t":"Когда вы **Стабилизируетесь** и решаете охладить своего меха, вы можете потратить **2 Ремонта**, чтобы снять **1 нагрузочный урон**.","src":"HA"},"cb_armory_sculpted_chassis":{"n":"Скульпт Шасси от Оружейной Палаты","t":"Вы получаете **+1 [ТОЧН]** на все проверки и спасброски **Инженерии**. Когда вы **Перегружаетесь**, вы получаете мягкое укрытие до начала вашего следующего хода.","src":"HA"},"cb_heatfall_coolant_system":{"n":"Система Охлаждения Теплового Потока","t":"Ваш показатель **Перегрузки** никогда не превышает **1d6 [нагрев]**.","src":"HA"},"cb_integrated_ammo_feeds":{"n":"Интегрированная Подача Боеприпасов","t":"Все **Ограниченные** системы и оружие получают два дополнительных заряда.","src":"HA"},"cb_stasis_shielding":{"n":"Стазисный Щит","t":"Всякий раз, когда вы получаете **нагрузочный урон**, вы получаете **Сопротивляемость ко всему урону** до начала вашего следующего хода.","src":"HA"},"cb_superior_by_design":{"n":"Превосходство по Замыслу","t":"Вы получаете **Невосприимчивость** к **Ослабленности** и получаете +2 **Теплового Максимума**.","src":"HA"},"cb_superheavy_mounting":{"n":"Сверхтяжёлое Крепление","t":"Если у вашего меха меньше **3 слотов** (не считая встроенных), он получает дополнительный **сверхтяжёлый** слот. В него можно ставить только **Сверхтяжёлое** оружие, и ему всё равно нужен ещё один слот. Если у меха есть тяжёлый слот, Сверхтяжёлое оружие должно использовать его как дополнительный.\n*Вы удивитесь, какую пушку можно уместить на шасси, если выдрать периферийные системы и предохранители.*","src":"GMS"},"cb_order_of_leander":{"n":"Орден Леандра","t":"**1/сцена** можно добавить **+1** [ТОЧН] к любой атаке, проверке или спасброску — вашему или союзного персонажа в пределах [Дальн]10 — и ещё **+1** [ТОЧН] за каждый ваш полученный структурный урон. Союзники, получившие этот бонус, получают **Сверхщит** в размере **Стойкость + 4**. Если после использования в этой сцене вы получаете структурный урон, способность можно применить ещё раз.\nЭкзотический бонус ядра: считается **экзотическим снаряжением**. Это награда Альянса Леандрийских Государств «за образцовый характер, мужество и решимость в великих испытаниях».","src":"EXOTIC"}},"skills":{"sk_act_unseen_or_unheard":{"n":"Тише Воды — Ниже Травы","t":"Добраться куда-то или сделать что-то незаметно, но не обязательно быстро: спрятаться, прокрасться или двигаться бесшумно. Проникнуть на объект, избегая патрулей и камер. Ловко и незаметно орудовать руками, в том числе обчищать карманы, вынимать пистолеты и жульничать в карты. Короче — маскироваться."},"sk_apply_fists_to_faces":{"n":"Кулаком по Лицу","t":"Ударьте кого-нибудь в лицо или избейте в открытом, жестоком безоружном бою, будь то первый бой, проверка боевых искусств или грандиозная драка.\nТишина, чистота и аккуратность — здесь не об этом."},"sk_assault":{"n":"Штурм","t":"Участвуйте в прямых и открытых боевых действиях: прокладывайте себе путь через коридор, заполненный враждебными наемниками, перестраивайтесь в окопах, залитых дождем, сражайтесь в хаотичной микрогравитации в процессе абордажа или вступайте в бой с противником на дымящихся обломках города, подвергающегося орбитальной бомбардировке. Громко и всегда направленно."},"sk_blow_something_up":{"n":"Подорвать Что-то","t":"Используйте взрывчатку (самодельную или любую другую), оружие или старую добрую силу, чтобы полностью разрушить что-то или превратить это в огромный файербол."},"sk_charm":{"n":"Шарм","t":"Убедить внушаемую аудиторию или применить рычаги влияния (деньги, власть, личная выгода), чтобы добиться своего: сладко говорить, проходя мимо охраны, привлекать людей на свою сторону, склонять на свою сторону потенциально выгодных людей, уговорить кого-то, стать посредником или откровенно лгать. Вы также используете шарм, когда пытаетесь кого-то облапошить.."},"sk_get_a_hold_of_something":{"n":"Завладеть Чем-то","t":"Приобрести временных или постоянных союзников, активы или связи через богатство или социальное влияние, получить информацию, продовольствие, материалы или солдат."},"sk_get_somewhere_quickly":{"n":"Быстро Добраться","t":"Добраться куда-то быстро и без лишних проблем, но не обязательно тихо. Взобраться, проехать, пролететь, проплыть или совершить маневры, чтобы пройти наиболее опасный путь. Безопасно упасть с большой высоты, грациозно двигаться в отсутствии гравитации. Преследовать, догнать, обогнать или перегнать цель. Добраться куда-то быстрее, чем кто-либо другой."},"sk_hack_or_fix":{"n":"Взломать или Починить","t":"Починить устройство или неисправную систему, или же взломать ее, полностью разрушить, вывести из строя или саботировать. Вы, вероятно, хакер или ремонтник с опытом взлома или защиты электронных систем, включая электронные дверные замки, компьютерные системы, серверы омнинет и так далее.."},"sk_invent_or_create":{"n":"Изобрести или Создать","t":"Использовать инструменты и принадлежности для проектирования или строительства чего-либо, либо сразу, либо с временными затратами. Изобретать новые устройства, инструменты или подходы к решению проблем."},"sk_investigate":{"n":"Исследование","t":"Обследовать предмет или изучать что-то очень подробно: узнать о предмете, имеющем историческое значение, или изучить много литературы по какому-либо вопросу. Расследовать тайну или разгадать загадку. Найти человека или предмет с помощью исследований и детективной работы."},"sk_lead_or_inspire":{"n":"Лидерство","t":"Произнести вдохновляющую речь или побудить группу людей к действию. Добросовестно и эффективно управлять такими формированиями людей, как компании, экипажи кораблей, группы колонистов или горнодобывающие предприятия. Эффективно командовать взводом солдат в бою, а может и целой армией."},"sk_patch":{"n":"Заплатки","t":"Применять медицинские знания для лечения, перевязки ран, остановки кровотечения, наложения швов, прижигания, нейтрализации яда или реанимации.\nДиагностировать или изучать болезни, возбудителей или симптоматику."},"sk_pull_rank":{"n":"Положение","t":"Привлечь подчиненного: получить от него информацию, ресурсы или помощь, возможно, против его воли. Каждый раз, когда вы пытаетесь принудить или убедить кого-то, кто может считаться с вашим авторитетом (например, военным или любым другим), вы, возможно, используете своё положение."},"sk_read_a_situation":{"n":"Чувствовать Ситуацию","t":"Ищите подтекст, мотивы или угрозы в ситуации или человеке: используйте интуицию, чтобы разглядеть чьи-то мотивы, узнать, кто на самом деле главный, или выяснить, кто собирается сделать что-то необдуманное или глупое. Получите интуитивное чувство ситуации или человека, почувствуйте, если кто-то вам лжет."},"sk_show_off":{"n":"Хвастовство","t":"Сделайте что-нибудь эпатажное, крутое или впечатляющее, с помощью (но не обязательно) оружия: выстрелите в маленькую или быстро движущуюся цель, прострелите чью-то шляпу или выбейте оружие из руки, вырубите кого-то, бросив в него пистолет, выполните акробатический трюк с мечом, бросьте копье, чтобы пригвоздить цель к земле."},"sk_spot":{"n":"Разведчик","t":"Различить детали, объекты или людей, которые скрыты или трудно различимы: заметить засады, скрытые отсеки или замаскированных людей. Шпионить за целями на расстоянии. Различить детали, форму и количество объектов, транспортных средств, мехов или людей на расстоянии, отслеживать людей или транспортные средства."},"sk_stay_cool":{"n":"Сохранять Хладнокровие","t":"Выполните задачу, требующую концентрации, ловкости, скорости или точности в критических ситуациях под давлением обстоятельств: взломайте замок, пока ваш отряд ведет перестрелку с наступающими противниками, аккуратно обезвредьте взрывчатку или разблокируйте оружие."},"sk_survive":{"n":"Выживание","t":"Выживайте в суровых, враждебных или недружелюбных условиях: в вакууме космоса, в замерзшей тундре, в пиратском анклаве, в колонии, погрязшей в преступности, в дикой природе или под палящим солнцем пустыни. Выживание часто включает в себя путешествия по дикой местности, навигацию или избегание природных опасностей, например:\nплотоядные дикие животные, камнепады, тонкий лед или лава. Вы также можете попытаться выжить в искусственных условиях, безопасно перемещаясь по городу или избегая опасных районов космических станций."},"sk_take_control":{"n":"Держать под Контролем","t":"Сила, насилие, волевые усилия или прямое воздействие, чтобы установить контроля над чем-либо. Обычно под контролем оказывается что-то конкретное, например, предмет, который кто-то держит в руках — пистолет или ключ-карта. Вы также можете взять под контроль ситуацию, заставив присутствующих выслушать, успокоиться или прекратить то, что они вытворяют."},"sk_take_someone_out":{"n":"Убрать Кого-то","t":"Убайте или выводите из строя быстро и бесшумно, вблизи или на расстоянии — возможно, даже раньше, чем цель заметит ваше присутствие. Если вы смотрите в снайперский прицел на мишень, готовитесь вырубить охранника стратегическим ударом ребром ладони, готовитесь быстро выстрелить во время дуэли на пистолетах или падаете с потолка, чтобы перерезать горло, значит, вы пытаетесь кого-то убрать."},"sk_threaten":{"n":"Угроза","t":"Используйте силу или угрозы, чтобы заставить кого-то сделать то, что нужно вам. Скажите, что вы хотите, чтобы цель сделала, и что вы собираетесь с ней сделать, если она вас не послушает. Угрозы могут также включать шантаж, давление или что-то подобное. Какую бы форму это ни приняло, после угроз шансов на восстановление дружеских отношений, скорее всего, не будет."},"sk_word_on_the_street":{"n":"Глас Улиц","t":"Находите сплетни, новости или слухи с улицы или из определенной социальной среды."}},"reserves":{"reserve_skill":{"n":"Очко навыка","t":"Добавьте очко навыка-триггера, чтобы получить или улучшить триггер (обычно в рамках действия отдыха «Сосредоточиться»)."},"reserve_mechskill":{"n":"Очко навыка меха","t":"Добавьте очко к Корпусу, Маневренности, Системам или Инженерии."},"reserve_talent":{"n":"Очко таланта","t":"Добавьте очко, чтобы получить или улучшить талант пилота."},"reserve_license":{"n":"Очко лицензии","t":"Добавьте очко, чтобы получить или повысить ранг лицензии."},"reserve_corebonus":{"n":"Дополнительный Бонус Ядра","t":"Добавьте ещё один Бонус Ядра."},"reserve_access":{"n":"Доступ","t":"Ключ-карта, приглашение, взятка или инсайдерский доступ в определенное место."},"reserve_backing":{"n":"Поддержка","t":"Полезный рычаг воздействия благодаря поддержке со стороны влиятельной фигуры."},"reserve_supplies":{"n":"Припасы","t":"Снаряжение, позволяющее легко пересечь опасную или враждебную зону."},"reserve_disguise":{"n":"Маскировка","t":"Эффективная маскировка или прикрытие, позволяющее проникнуть в какое-либо место."},"reserve_diversion":{"n":"Диверсия","t":"Отвлечение, которое дает время для действий без страха перед последствиями."},"reserve_blackmail":{"n":"Шантаж","t":"Материалы для шантажа или конфиденциальная информация, касающаяся конкретного лица."},"reserve_reputation":{"n":"Репутация","t":"Доброе имя в районе миссии, вызывающее хорошее первое впечатление у местных жителей."},"reserve_safe_harbor":{"n":"Тихая Гавань","t":"Гарантированно безопасное место для встреч, планирования или восстановления сил."},"reserve_tracking":{"n":"Отслеживание","t":"Подробная информация о местонахождении важных объектов или людей."},"reserve_knowledge":{"n":"Знания","t":"Знание местной истории, обычаев, культуры или этикета."},"reserve_ammo":{"n":"Боеприпасы","t":"Доп. использование (+1 или +2) **Ограниченного** оружия или систем."},"reserve_rented_gear":{"n":"Арендованное снаряжение","t":"Временный доступ к новому оружию или части снаряжения мехов."},"reserve_extra_repairs":{"n":"Дополнительный ремонт","t":"Припасы, дающие меху **+2 Лимит Ремонта**."},"reserve_core_battery":{"n":"Батарея Ядра","t":"Доп. батарея, позволяющая использовать **Систему Ядра** мехов повторно."},"reserve_deployable_shield":{"n":"Разворачиваемый щит","t":"Одноразовый генератор разворачиваемого щита — **Размер 1**, который дает мягкое укрытие всем дружественным персонажам в радиусе [Разрыв] **2**."},"reserve_redundant_repair":{"n":"Резервный ремонт","t":"Возможность **Стабилизировать** свободным действием один раз за миссию."},"reserve_systems_reinforcement":{"n":"Усиление систем","t":"+1 [ТОЧН] к проверкам навыков, сделанным с помощью одного навыка — **Корпус**, **Маневренность**, **Системы**, **Инженерия**."},"reserve_smart_ammo":{"n":"Умные боеприпасы","t":"Все оружие по вашему выбору может стрелять так, как будто оно **Умное**."},"reserve_boosted_servos":{"n":"Усиленные сервоприводы","t":"**Невосприимчивость** к состоянию **Замедления**."},"reserve_jump_jets":{"n":"Прыжковые ускорители","t":"В процессе этой миссии ваш мех может **Летать** во время движения, но должен закончить перемещение на земле."},"reserve_scouting":{"n":"Разведка","t":"Подробная информация о видах мехов и угроз, с которыми вы столкнетесь во время миссии, например, их количество, тип и статистика."},"reserve_vehicle":{"n":"Транспортные средства","t":"Использование транспортного средства или звездолета (например, Градации 1 с шаблоном Транспорта или Корабля)."},"reserve_reinforcements":{"n":"Подкрепление","t":"Возможность вызвать дружественного НИП-меха любого уровня, один раз за миссию."},"reserve_environmental_shielding":{"n":"Защита от окруж. среды","t":"Оборудование, позволяющее игнорировать специфическое воздействие на поле боя или опасной местности, например, сильную жару или холод."},"reserve_accuracy":{"n":"Точность","t":"Обучение или улучшение, которое дает +1 [ТОЧН] к определенному навыку или действию мехов на время этой миссии."},"reserve_bombardment":{"n":"Бомбардировка","t":"Артиллерийская или орбитальная бомбардировка, единожды во время боя мехов (полн. действие, [Дальн] 30 в пределах прям. вид., [Взрыв] 2, 3d6 [взр])."},"reserve_extended_harness":{"n":"Расширенная подвеска","t":"Спец. снаряжение, которое позволяет вам носить дополнительное оружие пилота и 2 дополнительных предмета снаряжения пилота на время этой миссии."},"reserve_ambush":{"n":"Засада","t":"Информация, которая позволяет вам выбрать, где именно будет происходить ваша следующая битва, включая план местности и укрытия."},"reserve_orbital_drop":{"n":"Орбитальное падение","t":"Возможность начать миссию, высадившись с орбиты в сильно укрепленное или труднодоступное место."},"reserve_nhp_assistant":{"n":"Помощник НЧЛ","t":"Нечеловеческая личность (НЧЛ) — продвинутый искусственный интеллект — контролируемый ГМ, который может дать вам совет по текущей ситуации."},"reserve_ammo_crate":{"n":"Ящик Патронов","t":"Один раз во время отдыха потратьте этот резерв, чтобы восстановить **1 заряд** всем **Ограниченным** системам и оружию всей группы."},"reserve_shielding":{"n":"Экранирование","t":"Техобслуживание у ребят с Губернаторской Фермы. Потратьте резерв, чтобы начать следующий бой с **Усилением Щита 5**."},"reserve_weathering":{"n":"Защита от Непогоды","t":"Потратьте резерв: на следующую миссию ваш мех получает **Невосприимчивость** к труднопроходимой местности и **Замедлению**."},"reserves_scouting_encounter":{"n":"Разведка (бой)","t":"Потратьте резерв, чтобы до начала боя узнать всё о его НИП и ситрепе. Тратится в начале боя."},"reserve_high_caliber_ammo":{"n":"Крупнокалиберные Патроны","t":"Потратьте резерв в начале любой боевой сцены: всё ваше оружие до конца сцены получает **ББ**."},"reserve_stash_of_private_moonshine":{"n":"Тайник Самогона","t":"Обменяйте у кого-то в колонии на услуги: **+1** [ТОЧН] на все небоевые проверки навыков, пока этот человек может вам помочь. Эффект кончается в конце следующего даунтайма."},"reserve_colony_drop":{"n":"Колониальный Десант","t":"Потратьте резерв: вы и союзники высаживаетесь с грузового корабля «Лэндмарка» и в следующем бою можете развернуться где угодно на карте."},"reserve_governors_farm_advanced_access":{"n":"Расширенный Доступ на Губернаторскую Ферму","t":"Навсегда: **+1** [ТОЧН] на небоевые проверки для сбора сведений, написания программ и взлома, если вы делаете это на Губернаторской Ферме."},"reserve_fieldings_workshop_access":{"n":"Доступ в Мастерскую Филдинга","t":"Навсегда: **+1** [ТОЧН] и один дополнительный сегмент, когда вы продвигаетесь по часам изобретения, создания или ремонта предметов и снаряжения в мастерской Филдинга."},"reserve_patience_hookup":{"n":"Прямая Линия с Пейшенс","t":"У вас прямая связь с Пейшенс. Потратьте резерв: **+1** [ТОЧН] на все проверки навыков и спасброски на одну сцену (даже в бою) — Пейшенс помогает вам."},"reserve_military_grade_jetpack":{"n":"Военный Реактивный Ранец","t":"Крепится к любому скафандру: носитель может летать при перемещении или **Ускорении**."},"reserve_incendiary_ammo_pilot_scale":{"n":"Зажигательные Патроны (пилотские)","t":"Тип урона пилотского оружия меняется на горение."},"reserve_pneumatic_enhancer":{"n":"Пневмоусилитель","t":"Ваше пилотское **Тяжёлое ОББ/ОБД** получает: «**При попадании**: цель **Сбита с ног**»."},"reserve_sniper_scope":{"n":"Снайперский Прицел","t":"Пилотское фирменное оружие получает **+5 к дальности**."},"reserve_devastator_grenades":{"n":"Гранаты «Опустошитель»","t":"Ваши осколочные гранаты наносят **+2** урона."},"reserve_junker_exo_rig":{"n":"Экзоскелет Старьёвщика","t":"**+1** [ТОЧН] на **Оседлать** (Jockey)."},"reserve_crash_cushions":{"n":"Аварийные Подушки","t":"**1/миссия**: становясь **Ошеломлённым**, можно активировать, чтобы не стать Ошеломлённым."},"reserve_personal_cloak":{"n":"Персональный Плащ","t":"**1/миссия**: **протоколом** вы **Невидимы** до начала своего следующего хода."},"reserve_precision_targeting_software":{"n":"Программа Точного Наведения","t":"**1/миссия**: попав атакой, можно сделать её критической."},"reserve_frostfang_servos":{"n":"Сервоприводы «Ледяной Клык»","t":"**1/миссия**: **Ускориться** свободным действием."},"reserve_gyro_stabilizers":{"n":"Гиростабилизаторы","t":"**1/миссия**: **протоколом** до конца хода всё ваше оружие считается не **Артиллерийским**."},"reserve_high_speed_loader":{"n":"Скоростной Заряжатель","t":"**1/миссия**: перезарядить всё оружие свободным действием."},"reserve_system_flayer":{"n":"Системный Свежевальщик","t":"**1/миссия**: попав **Вторжением**, можно нанести **+4** нагрева."},"emergency_coolant_reservoir":{"n":"Аварийный Бак Охладителя","t":"**1/миссия**: снять **Уязвимость** свободным действием."},"reserve_ic_blinkpack":{"n":"Блинк-Ранец IC","t":"**1/миссия**: **протоколом** до конца хода вы телепортируетесь при каждом перемещении."},"reserve_explosive_knuckles":{"n":"Взрывные Кастеты","t":"**1/миссия**: попав **Тараном**, можно нанести **6** [взр]."},"reserve_ultra_high_penetrator_rounds":{"n":"Сверхпробивные Патроны","t":"**1/миссия**: попав дальней атакой, можно объявить, что её урон нельзя уменьшить."},"reserve_run_off_energy_converter":{"n":"Преобразователь Сбросовой Энергии","t":"**1/миссия**: используя **Мощь Ядра**, можно создать ауру молний [Разрыв]4: враждебные персонажи в зоне получают **4** [энерг]."},"reserve_system_backup":{"n":"Резервная Копия Системы","t":"**1/миссия**: когда нужно пройти спасбросок или проверку, можно автоматически преуспеть."},"reserve_field_marshal_comp_con":{"n":"Комп/Кон «Фельдмаршал»","t":"**1/миссия**: **быстрым действием** до двух союзников в пределах **Сенсоров** могут сразу совершить по одному быстрому действию реакцией."},"reserve_retractable_slab_shields":{"n":"Выдвижные Щиты-Плиты","t":"**1/миссия**: **протоколом** вы **Обездвижены** до начала своего следующего хода и на тот же срок получаете **Сопротивляемость** ко всему урону."},"reserve_automated_reflex_suite":{"n":"Автоматический Рефлекс-Комплекс","t":"**1/миссия**: когда по вам попадает атака, реакцией можно превратить её в промах."},"reserve_bubble_active_personal_shield":{"n":"Активный Персональный Щит «Пузырь»","t":"**1/миссия**: **протоколом** получить **Усиление Щита** в размере **4 + Стойкость**."},"reserve_thermal_optics":{"n":"Тепловая Оптика","t":"**1/миссия**: **протоколом** игнорировать укрытие до конца хода."},"reserve_strain_resistant_actuator":{"n":"Стойкий к Нагрузкам Привод","t":"**1/миссия**: **Укрепляясь**, можно не получать никаких отрицательных последствий."},"reserve_hyper_spec_fuel_canister":{"n":"Канистра Гиперспек-Топлива","t":"**1/миссия**: **протоколом** **+1** [ТОЧН] на все атаки, спасброски и проверки до начала вашего следующего хода."},"reserve_esus_eyes_occular_apparatus":{"n":"Окуляр «Глаза Эшу»","t":"В начале боя можно активировать: до конца боя вы игнорируете **Скрытность** и **Невидимость** враждебных персонажей. После использования снаряжение уничтожается."},"reserve_compulsory_scope_upgrade":{"n":"Принудительный Прицел","t":"В начале боя можно активировать: каждый раз, промахнувшись дальней атакой, вы получаете **+1** [ТОЧН] на следующую дальнюю атаку в этом же ходу. После использования (в конце боя) снаряжение уничтожается.\nВ программе — галочка в окне дальней атаки."},"reserve_aganju_tower":{"n":"Башня Аганджу","t":"Получив попадание дальней или ближней атакой, можно уменьшить её урон до **0**. После использования снаряжение уничтожается."},"reserve_oba_liquidmetal_cloak":{"n":"Жидкометаллический Плащ Оба","t":"Плащ мехового масштаба: **+2 Уклонения**, пока снаряжение не уничтожено. Оно уничтожается, когда вы получаете структурный урон.\nВ программе: +2 Уклонения, пока резерв не отмечен использованным."},"reserve_the_backpack":{"n":"Рюкзак","t":"В начале боя можно разместить до **четырёх рюкзачных дронов** в свободных пространствах рядом с вами (Размер ½, ПЗ 1, Э-Защита 10, Уклонение 10, метка Дрон). Вы получаете дополнительный ход, которым можно управлять только одним из них. Дроны двигаются до **5 пространств** за ход и **полным действием** рядом с мехом восстанавливают ему **половину ПЗ** или снимают **половину нагрева**, после чего уничтожаются. Когда все дроны уничтожены или миссия окончена, снаряжение уничтожается."},"reserve_oguns_powerarm":{"n":"Силовая Рука Огуна","t":"**1/раунд**, когда вы **Таранете** или **Хватаете**, при успехе наносите **+1d6** [кин]; **Импровизированные атаки** наносят ещё **+1d6**. Снаряжение уничтожается, когда вы получаете структурный урон."},"reserve_souled_out_class_vi_anti_materiel_rifle":{"n":"Противоматериальная Винтовка «Souled Out» класса VI","t":"**Полным действием**, до любых других действий в ходу, кроме протоколов, вы совершаете дальнюю атаку по персонажу в прямой видимости в пределах [Дальн]20. При попадании — **3d6** [кин]. После выстрела бросьте d20: на **10 и меньше** винтовка взрывается и уничтожается, а вы получаете **1d3** [взр]."},"reserve_up_armoring":{"n":"Дополнительная Броня","t":"Простая полевая доработка — дополнительные бронеплиты на корпус. До конца следующей миссии мех получает **+1 Броню** (не больше 4), а следующий бой вы начинаете со **Сверхщитом 5**."},"reserve_hot_load_ammunition":{"n":"Форсированные Боеприпасы","t":"Такие заряды не одобрены уставом, но работают. Потратьте резерв, чтобы усилить оружие: урон от следующей успешной дальней или ближней атаки **нельзя уменьшить** никак, а цель проходит спасбросок **Корпуса**, иначе **Сбита с ног**. Эффект кончается, когда вы попали дальней или ближней атакой, или в конце сцены."},"reserve_recon_drone":{"n":"Разведдрон","t":"Высотные дроны долгого барражирования — лучшая разведка в условиях глушения. В начале каждого боя выберите одного враждебного персонажа в пределах [Дальн]50 и **Сканируйте** его. Прямая видимость не нужна."},"reserve_sniper_team":{"n":"Снайперская Группа","t":"Потратьте резерв в начале любого боя, чтобы вызвать поддержку снайперской группы. До конца сцены каждый раз, когда вы совершаете быстрое технологическое действие **Захват**, цель получает **2 [кин] ББ**."},"reserve_lookingglass":{"n":"Оверлей «ЗАЗЕРКАЛЬЕ»","t":"Нашлемный сенсор, пробивающий даже продвинутый тепловой, оптический и системный камуфляж, — но на такой мощности он быстро выгорает. Потратьте резерв в любом бою: до конца сцены вы игнорируете **лёгкое укрытие** и **Невидимость** персонажей в пределах [Дальн]3. Враждебные персонажи в пределах [Дальн]3 не могут стать **Скрытыми** (но остаются Скрытыми, если уже были)."},"reserve_leg_enhancements":{"n":"Усиленные Ноги","t":"Усиленные суставы и сервоприводы. До конца следующей миссии мех игнорирует **труднопроходимую местность**. Кроме того, **1 раз за миссию** можно потратить резерв и проигнорировать **Замедление** или **Обездвиживание** от враждебного источника — в момент получения."},"reserve_high_mobility_pack":{"n":"Ранец Высокой Мобильности","t":"Навесной лётный модуль для штурма и десанта. Потратьте резерв в начале любого боя: до конца сцены всё ваше перемещение считается **полётом**. Кроме того, вы можете развернуться в любом месте карты после того, как развернулись все остальные персонажи (ИП и НИП)."},"reserve_golden_ticket":{"n":"Золотой Билет","t":"Неофициальное клонирование кода лицензий: вы получаете один предмет **экзотического снаряжения** из «Operation Solstice Rain»."},"reserve_personal_touch":{"n":"Личный Подход","t":"Главный инженер явно прониклась вашим мехом. До конца следующей миссии мех бесплатно получает систему **Индивидуальная Покраска**; кроме того, можно потратить резерв и получить **+1** [ТОЧН] на все проверки и спасброски меха в течение одного боя по вашему выбору."},"reserve_return_to_sender":{"n":"Вернуть Отправителю","t":"Трофейный артиллерийский снаряд как самодельная мина на мехе — очень неразумно, но бывало и хуже. **1/миссия** **быстрым действием** создайте взрыв [Взрыв]**2** в пределах [Дальн]3. Задетые персонажи проходят спасбросок **Маневренности**, иначе получают **3d6 [взр]**, при успехе — половину. Объекты, укрытие и местность в зоне автоматически получают **30 [взр] ББ**. Этот резерв может быть только у одного ИП одновременно; выпавший повторно берёт другой резерв из списка."}},"gear":{"pg_archaic_melee":{"n":"Архаичное ОББ","t":"**Архаичное ОББ**: Это Оружие Ближнего Боя было изготовлено с использованием сплавов и технологий, существовавших во времена до Союза, и может быть чем угодно — от стальных мечей индустриальной эпохи до каменных топоров. Хотя оно по-прежнему широко используется в некоторых мирах, архаичное оружие, используемое пилотами, обычно является реликвиями, ценностями или церемониальным оружием."},"pg_archaic_ranged":{"n":"Архаичное ОДБ","t":"**Архаичное ОДБ**: Это Оружие Дальнего Боя — устаревшие устройства старых эпох, такие как мушкеты и луки, которые все еще используются в некоторых сообществах."},"pg_light_a_c":{"n":"Лёгкое С/К","t":"**Легкое С/К** оружие может быть ножами, штыками, пробивными кинжалами и короткими мечами."},"pg_medium_a_c":{"n":"Среднее С/К","t":"**Среднее** С/К оружие — это, как правило, мечи, сабли и окопные топоры."},"pg_heavy_a_c":{"n":"Тяжёлое С/К","t":"**Тяжелое** С/К оружие разработано с учетом повышенной прочности защитных костюмов и включает боевые молоты, молоты, тараны, пики и тяжелые двуручные штурмовые мечи."},"pg_light_signature":{"n":"Лёгкое Фирменное","t":"Приобретая фирменное оружие, выберите его тип урона – взрывной [взр], энергетический [энерг] или кинетический [кин].\n**Легкое** фирменное оружие может представлять собой крупнокалиберные револьверы, скобы пистолетов и пистолеты-пулеметы."},"pg_medium_signature":{"n":"Среднее Фирменное","t":"Приобретая фирменное оружие, выберите его тип урона – взрывной [взр], энергетический [энерг] или кинетический [кин].\n**Среднее** — штурмовые винтовки, дробовики, лазеры на ранцевом питании, разрушительные пушки."},"pg_heavy_signature":{"n":"Тяжёлое Фирменное","t":"Приобретая фирменное оружие, выберите его тип урона – взрывной [взр], энергетический [энерг] или кинетический [кин].\n**Тяжелое** — ракетные трубы, тяжелые лазеры, легкий пулемет или экзотические винтовки."},"pg_light_hardsuit":{"n":"Лёгкий Скафандр","t":"**+3 ПЗ**, Броня 0, Уклонение 10, Э-Защита 10, Скорость 4.\n**Легкие Скафандры**: Обычно изготавливаются из реактивного, похожего на ткань материала, с ограниченным количеством пластин и небольшим количеством силовых компонентов для обеспечения максимальной мобильности. Как и другие скафандры, они могут быть запечатаны от вакуума и защищают от приличного количества радиации и других вредных частиц."},"pg_assault_hardsuit":{"n":"Штурмовой Скафандр","t":"**+3 ПЗ**, Броня 1, Уклонение 8, Э-Защита 8, Скорость 4.\n**Штурмовой Скафандр**: Эти скафандры, распространенные среди военных подразделений, имеют более тяжелое покрытие, чем легкие, но более мобильны, чем тяжелые. Они питаются энергией, увеличивая силу пользователя, и часто оснащены бортовым компьютером, набором датчиков, встроенным воздухом, системой ВКД, а также системами переработки отходов."},"pg_heavy_hardsuit":{"n":"Тяжёлый Скафандр","t":"**+3 ПЗ**, Броня 2, Уклонение 6, Э-Защита 8, Скорость 3.\n**Тяжелый Скафандр**: самые тяжелые скафандры. Они всегда снабжены источником энергии и бронированы толстой композитной броней. Тяжелые скафандры оснащены интегрированным оружием, мощными мобильными комплексами и, увеличивая силу своего пользователя, позволяют ему использовать гораздо более тяжелое оружие, чем может нести обычная пехота. Сейчас, когда популярны полуразмерные шасси, тяжелые скафандры переживают упадок, но они все еще распространены среди частных вооруженных сил и вооруженных сил диаспоры среднего уровня."},"pg_mobility_hardsuit":{"n":"Мобильный Скафандр","t":"Броня 0, Уклонение 10, Э-Защита 10, Скорость 5, **Полёт**.\n**Мобильный Скафандр**: В эти скафандры интегрированы системы полёта, позволяющие пилотам **летать**, когда они двигаются или **Ускоряются**. Летающие пилоты должны завершить свой ход на земле (или другой поверхности) или начать падать."},"pg_stealth_hardsuit":{"n":"Стелс-Скафандр","t":"Броня 0, Уклонение 8, Э-Защита 8, Скорость 4.\n**Стелс-Скафандр**: В качестве **быстрого действия** пилоты в стелс-скафандрах могут стать **Невидимыми**. Они перестают быть **Невидимыми**, если получают урон."},"pg_corrective":{"n":"Корректив","t":"Этот прозрачный, похожий на пластик лист можно накладывать на раны тяжелораненых пилотов. Он мгновенно стабилизирует их состояние, вводит лекарства и наниты для зашивания ран.\nПотратьте заряд, чтобы применить коррективы на **Нокаутированных** пилотах, немедленно возвращая их в сознание с **1 ПЗ**."},"pg_frag_grenades":{"n":"Осколочные Гранаты","t":"Потратьте заряд для следующего эффекта:\n• **Осколочная Граната** (Граната, [Дальн] 5, [Взрыв] 1): Затронутые персонажи должны преуспеть в спасброске Маневренности или получить 2 [взр]."},"pg_patch":{"n":"Патч","t":"\"Патч\" — это сленг пилотов для обозначения любого вида современных средств оказания первой помощи, включая распыляемый медигель и пластыри мгновенного действия.\nПотратьте заряд, чтобы наложить патч на себя или соседнего пилота, восстанавливая половину своего максимального уровня **ПЗ**. Патчи не оказывают никакого эффекта на **Нокаутированных** пилотов."},"pg_stims":{"n":"Стимы","t":"Эти химические стимуляторы иногда вводятся автоматически с помощью инъекторов, встроенных в костюм пилота или даже имплантированных в его тело. Неконтролируемое употребление может вызвать привыкание и в долгосрочной перспективе опасно для здоровья, что является проблемой для некоторых пилотов.\nПотратьте заряд на один из следующих эффектов:\n• **ПИНОК**: Держит пилота в бодрствующем состоянии до 30 часов.\n• **ХОЛОДОК**: Сохраняет пилота спокойным и эмоционально стабильным; притупляет страх и другие сильные реакции.\n• **СОК**: обостряет чувства и бдительность, снижает усталость и сокращает время реакции. Сок иногда вызывает ярость у некоторых пользователей."},"pg_thermite_charge":{"n":"Термитный Заряд","t":"Потратьте заряд для следующего эффекта:\n• **Термитный Заряд** (Мина, [Разрыв] **1**): Этот заряд должен быть дистанционно взорван в качестве быстрого действия. Затронутые персонажи должны успешно пройти спасбросок **Инженерии** или получить 3 [энерг] ББ. Тепловые заряды автоматически поражают объекты, нанося 10 [энерг] ББ."},"pg_antiphoton_visor":{"n":"Антифотонный визор","t":"Предназначенные для защиты глаз пользователя от интенсивных вспышек света, антифотонные визоры часто встречаются среди команд прорыва и операторов солнечной энергии. Они эффективны против фотовспышек, интенсивного УФ-излучения и случайных зарядов энергетического оружия."},"pg_camo_cloth":{"n":"Камуфляжная Ткань","t":"Квадрат из реактивного материала, который медленно изменяется в зависимости от окружающей среды. Его достаточно, чтобы покрыть человека. Переход занимает около 10 секунд, после чего спрятанное под ним будет очень трудно обнаружить."},"pg_dataplating":{"n":"Датаплаты","t":"Датаплаты — это общий термин для любых коммуникативных украшений — подкожных сеток, челюстных, надбровных или верхнечелюстных пластин и т.д., которые обеспечивают субвокальную связь и постоянное отображение информации в голове и в дополненной реальности без ношения шлема. Датаплаты могут быстро перевести практически любой язык и позволяют пользователям общаться друг с другом практически беззвучно."},"pg_extra_rations":{"n":"Дополнительные Пайки","t":"Рационы пилотов не намного лучше, чем у их предшественников мореплавателей — и те, и другие представляют собой разновидности галет и питательной пасты. Пилоты часто берут с собой запас дополнительной пищи или предметы роскоши, такие как шоколад, кофе, алкоголь или консервы со своей родной планеты. Эти пайки можно использовать для обмена или поднятия боевого духа."},"pg_flexsuit":{"n":"Флекс-скафандр","t":"Прочный базовый скафандр, который перерабатывает воду, генерирует питательные вещества и очень быстро адаптируется к враждебному окружению, поддерживая стабильное состояние и продлевая выживаемость. Носители Флекс-скафандра могут не есть и не пить около недели благодаря амброзийной пасте, вырабатываемой скафандр, прежде чем его системы истощатся; однако он не предотвращает чувство голода. Достаточно снять скафандр на день или два, чтобы восполнить его запасы. Флекс-скафандры также поддерживают постоянную температуру в пределах допустимых параметров."},"pg_handheld_printer":{"n":"Портативный Принтер","t":"Миниатюрная версия полномасштабных принтеров Союза, портативные принтеры могут использоваться для изготовления простых предметов из гибкого и прочного пластика — при условии, что у вас есть нужный паттерн-чип."},"pg_subjectivity_enhancement_suite":{"n":"Набор для Усиления Субъективности","t":"Набор для усиления субъективности — это набор кибернетических имплантатов, позволяющих пользователям взламывать системы без специального оборудования. Пользователи этих комплектов смешивают органическое с синтетическим, получая возможность вытягивать имплантированные кабели с универсальными штекерами из своего тела для создания жестких соединений с терминалами. Подключившись к терминалам, пользователь получает доступ к обширному, полностью интерактивному интерфейсу альтернативной реальности с прямым доступом к омнинету, что делает навигацию — или взлом — локальных и сетевых систем таким же простым, как и желание (конечно, вы должны быть осторожны: открыв свой разум для цифровых технологий, вы можете столкнуться с опасностями, о которых другие, менее совершенные люди не знают)."},"pg_infoskin":{"n":"Инфокожа","t":"Реактивный синтетический полимер с улучшенными свойствами, инфокожа быстро сцепляется с настоящей кожей и волосами. После нанесения она реагирует на электронные сигналы, передаваемые связанным программным обеспечением, быстро меняет цвет и текстуру, даже деформируется и искажает форму, позволяя владельцам вносить незначительные изменения в свой внешний вид. С помощью инфокожи можно легко изменить черты лица, цвет волос или макияж."},"pg_mag_clamps":{"n":"Магнитные Зажимы","t":"Эти зажимы легко крепятся к любой металлической поверхности, повышая маневренность в условиях невесомости или при ремонте мехов. Их можно носить с собой или пристегивать к ботинкам."},"pg_nanite_spray":{"n":"Нанитный Спрей","t":"Краска в виде спрея, которую можно наносить на любую поверхность. Нанитовый спрей невидим невооруженным глазом, но способен передавать простые сообщения или небольшие пакеты данных при сканировании."},"pg_omnihook":{"n":"Омнихук","t":"Портативный — хотя и громоздкий — омнинет-терминал, позволяющий осуществлять связь, передачу данных и ограниченный хотспот. Омнихуки чрезвычайно ценны, поэтому большинство отрядов мехов имеют хотя бы один. Настройка омнихука требует высокого уровня мастерства, поэтому их обычно устанавливают или носят с собой специально назначенные операторы."},"pg_personal_drone":{"n":"Персональный Дрон","t":"Небольшие небоевые дроны — обычное явление в полевых условиях. Они довольно шумные, но могут пролететь около полумили с хорошей маневренностью, прежде чем потеряют сигнал. Передают звуковую и визуальную информацию по ходу движения.."},"pg_prosocollar":{"n":"Просоколляр","t":"Устройство, напоминающее ошейник, плотно прилегает к шее владельца, проецируя голографическое изображение на его лицо и голову. Просоколляры могут изменять голос своего владельца, а также изменять его внешность. Проекция не выдерживает тщательного осмотра, но она может легко обмануть электронные системы и удаленных наблюдателей."},"pg_smart_scope":{"n":"Умный Прицел","t":"Мощный электронный прицел, обеспечивающий увеличение с высоким разрешением до двух миль и автоматически корректирующий сетку в зависимости от ветра, гравитации и давления. Умные прицелы могут проецировать свое поле зрения и все данные на Проекционный Дисплей любого пользователя, подключенного к сети. Они также могут работать в паре с другими тепловизионными, оптическими или имитационными приборами для дальнейшего улучшения прицеливания."},"pg_sleeping_bag":{"n":"Спальный Мешок","t":"Спальные мешки бывают разных размеров и незаменимы в полевых условиях. Они раскладываются из скафандра, помещаются в кабину меха, противостоят огню и перепадам температуры и, при необходимости, защищают от вакуума.\nВы можете забраться в спальный мешок, получив при этом **Невосприимчивость** к [горение], защиту от вакуума и достаточное количество воздуха, чтобы продержаться час; однако, находясь в спальном мешке, вы **Ошеломлены** и не можете предпринимать никаких действий, кроме выхода из мешка в качестве **полного действия**."},"pg_ssc_sylph_undersuit":{"n":"СШК Сильф-комбинезон","t":"Сильф был обнаружен на Акримее IV, биоме культивируемого мира, контролируемого Смит-Шимано Корпо (СШК), и представляет собой органическую форму жизни, которая может выжить практически в любой среде. Используя методы селекции, аналогичные установленным доктринам биоинженерии, СШК разработала скафандр сильфа — стерильных, живых сильфов, выращенных в виде оболочек и приспособленных к своим владельцам. Сильф соединяется со своим владельцем, образуя симбиотические отношения: сильф поддерживается отходами жизнедеятельности хозяина, в свою очередь защищая его от ряда враждебных факторов окружающей среды.\nЭти полубиологические, облегающие кожу комбинезоны можно носить в течение длительного времени. Они полупрозрачные, полужидкие и могут храниться в любом контейнере. Они очищают тело хозяина, помогают естественным процессам заживления и выводят отходы. По желанию сегменты могут становиться непрозрачными, менять цвет или приобретать новую текстуру. Сильф-комбинезон может покрывать голову носителя, изолируя от вакуума, обеспечивая защиту от радиации и фильтруя воздух или жидкости, даже давая возможность дышать под водой в течение ограниченного времени."},"pg_sound_system":{"n":"Акустическая Система","t":"Хотя их тактическая польза сомнительна, многие пилоты устанавливают в своих кабинах внутренние акустические системы. Это дает им четкую связь с соотечественниками во время боя, а также возможность слушать музыку."},"pg_tertiary_arm":{"n":"Третичная Рука","t":"Механизированная третья рука, закрепленная на скобе скафандра. Третичные руки питаются и управляются с помощью тех же процессов нейронного моста, которые позволяют скафандрам реагировать на действия пользователя.Они могут быть снабжены манипуляторами для управления мелкой моторикой, оружием для повышения боевой эффективности или специальными инструментами."},"pg_wilderness_survival_kit":{"n":"Набор для Выживания","t":"Этот набор содержит множество предметов первой необходимости для выживания в неблагоприятных условиях: ребризер, фильтры для воды, заплатки для защитного скафандра, запасные термобелье, комплект для бивака и так далее."},"ms_exo_anti_armor_signature_weapon":{"n":"Противоброневое Фирменное Оружие","t":"Самое тяжёлое оружие, какое пеший боец может унести со скафандром или без: управляемые противотанковые ракеты, крупнокалиберные антиматериальные винтовки, громоздкие, но разрушительные лазеры и плазменные орудия. Тип урона — взрывной, кинетический или энергетический (выбирается при получении).\nЕсли пилот берёт на миссию Противоброневое Фирменное Оружие, другого пилотского оружия он взять не может."},"ms_exo_bahadurs_reserve":{"n":"Заначка Бахадура","t":"Удивительно крепкий самогон Мира Бахадура: им угощают разборчивых клиентов и расплачиваются за услуги в неформальной меновой торговле Эвергрина. Пьётся на удивление мягко, с нотками ванили и специй. Годится как дезинфекция или грубая анестезия, может питать биотопливный генератор, а в крайнем случае — стать зажигательной смесью.\nПотратьте заряд для следующего эффекта:\n• **Коктейль Молотова** (Граната, [Дальн]5, [Взрыв]1): затронутые персонажи проходят спасбросок **Маневренности**, иначе получают **2** горения."},"ms_exo_hercynian_rations":{"n":"Герцинийские Пайки","t":"Пайки ОГГ (Объединённых Городов Герцинии): копчёная рыба или рыба в пряном масле, сушёные грибы (восстанавливаются водой), лепёшки или галеты в запаянных пакетах, маринованные макроводоросли, сухофрукты, рис, овёс, чай и сублимированный кофе. Чем-то знакомы любому, кто жил на армейском пайке; чем-то — напоминают, как далеко вы от дома."},"ms_exo_locus":{"n":"Локус","t":"Местный психоделический гриб (сушёный или в виде чая) помогает людям развить чувствительность к Свидетельству. Вызывает открытость, эйфорию, усиленную эмпатию и изменённое восприятие, включая лёгкие галлюцинации и синестезию; действует 3–6 часов. Не вызывает привыкания и долгосрочного вреда, хотя после бывают головная боль и усталость; передозировка ведёт к «эмпатической перегрузке», диссоциации и тяжёлым галлюцинациям. Усиливает связь со Свидетельством, но не обязательно её понимание."},"ms_exo_light_carapace_armor":{"n":"Лёгкий Хитиновый Скафандр","t":"**+2 ПЗ**, Броня 0, Уклонение 10, Э-Защита 10, Скорость 4, **Сопротивляемость** к энергетическому урону.\nМногослойный обработанный хитин линялых панцирей эгрегорианцев особенно хорошо рассеивает энергетическое оружие. Такие скафандры не продаются: их передают от пилота к пилоту или изготавливают по традиции — с согласия донора-эгрегорианца и при личном участии будущего владельца."},"ms_exo_assault_carapace_armor":{"n":"Штурмовой Хитиновый Скафандр","t":"**+2 ПЗ**, Броня 1, Уклонение 8, Э-Защита 8, Скорость 4, **Сопротивляемость** к энергетическому урону.\nМногослойный обработанный хитин линялых панцирей эгрегорианцев особенно хорошо рассеивает энергетическое оружие."},"ms_exo_heavy_carapace_armor":{"n":"Тяжёлый Хитиновый Скафандр","t":"**+2 ПЗ**, Броня 2, Уклонение 6, Э-Защита 6, Скорость 3, **Сопротивляемость** к энергетическому урону.\nМногослойный обработанный хитин линялых панцирей эгрегорианцев особенно хорошо рассеивает энергетическое оружие."},"ms_madrigal_precision_rifle":{"n":"Высокоточная Винтовка «Мадригал»","t":"**Требование**: оружие и снаряжение со словом «Мадригал» можно носить, только если пилот носит **Абордажный Панцирь «Мадригал»**.\n"},"ms_madrigal_shoulder_launcher":{"n":"Наплечная Пусковая «Мадригал»","t":"**Требование**: оружие и снаряжение со словом «Мадригал» можно носить, только если пилот носит **Абордажный Панцирь «Мадригал»**.\n"},"ms_madrigal_boarding_shotgun":{"n":"Абордажный Дробовик «Мадригал»","t":"**Требование**: оружие и снаряжение со словом «Мадригал» можно носить, только если пилот носит **Абордажный Панцирь «Мадригал»**.\n"},"ms_madrigal_power_crusher":{"n":"Силовой Сокрушитель «Мадригал»","t":"**Требование**: оружие и снаряжение со словом «Мадригал» можно носить, только если пилот носит **Абордажный Панцирь «Мадригал»**.\n**При попадании**: цель **Обездвижена** и **Ослаблена** до конца своего следующего хода.\nЭто оружие автоматически попадает по местности и наносит **10** [кин] **ББ**."},"ms_madrigal_railgun":{"n":"Рельсотрон «Мадригал»","t":"**Требование**: оружие и снаряжение со словом «Мадригал» можно носить, только если пилот носит **Абордажный Панцирь «Мадригал»**.\n"},"ms_madrigal_disruptor_grenades":{"n":"Граната-Дестабилизатор «Мадригал»","t":"**Требование**: оружие и снаряжение со словом «Мадригал» можно носить, только если пилот носит **Абордажный Панцирь «Мадригал»**.\nЕсли ваш пилот пеший, вы получаете быстрое действие: потратьте заряд, чтобы бросить гранату в пределах [Дальн]5. Персонажи в зоне [Взрыв]1 **Замедлены** и **Ослаблены** до конца своего следующего хода."},"ms_madrigal_jump_system":{"n":"Прыжковая Система «Мадригал»","t":"**Требование**: оружие и снаряжение со словом «Мадригал» можно носить, только если пилот носит **Абордажный Панцирь «Мадригал»**.\nЕсли ваш пилот пеший, при **Ускорении** он может **летать**. Закончить движение нужно на твёрдой поверхности, иначе начнёте падать."},"ms_madrigal_thermal_visor":{"n":"Тепловизор «Мадригал»","t":"**Требование**: оружие и снаряжение со словом «Мадригал» можно носить, только если пилот носит **Абордажный Панцирь «Мадригал»**.\nЕсли ваш пилот пеший, его атаки игнорируют укрытие."},"ms_madrigal_active_camo":{"n":"Активный Камуфляж «Мадригал»","t":"**Требование**: оружие и снаряжение со словом «Мадригал» можно носить, только если пилот носит **Абордажный Панцирь «Мадригал»**.\nЕсли ваш пилот пеший, дальние атаки из-за пределов [Дальн]3 считают, что у него **твёрдое укрытие**."},"ms_madrigal_personal_shield":{"n":"Персональный Щит «Мадригал»","t":"**Требование**: оружие и снаряжение со словом «Мадригал» можно носить, только если пилот носит **Абордажный Панцирь «Мадригал»**.\nЕсли ваш пилот пеший, он получает реакцию «Под Щитом» (**1/раунд**): получая урон, можно потратить заряд, чтобы получить **Сопротивляемость** к этому урону."},"ms_madrigal_shock_field":{"n":"Шоковое Поле «Мадригал»","t":"**Требование**: оружие и снаряжение со словом «Мадригал» можно носить, только если пилот носит **Абордажный Панцирь «Мадригал»**.\nЕсли ваш пилот пеший, он получает быстрое действие: **3** [энерг] всем соседним персонажам и конец всех захватов, действующих на него."},"ms_madrigal_boarding_carapace_armor":{"n":"Абордажный Панцирь «Мадригал»","t":"**+3 ПЗ**, Броня 3, Уклонение 7 + Стойкость, Э-Защита 7 + Стойкость, Скорость 4.\nВзявший Абордажный Панцирь «Мадригал» не может брать пилотское оружие и снаряжение без слова «Мадригал» в названии; оружие и снаряжение «Мадригал» носят только в этом панцире.\nВ панцире вы можете **Спешиться** или **Катапультироваться**, только пока ваш мех ещё не действовал в этом ходу (не считая протоколов).\nЕсли вы не в мехе, а им управляет другой человек или ИИ, на каждом своём ходу он может совершить только одно быстрое действие и стандартное перемещение (протоколы и реакции — как обычно); **Укрепляясь** в это время, он теряет и оставшееся быстрое действие. Это длится, пока вы не вернёте управление протоколом.\nПанцирь считается одним из двух установленных предметов экзотического снаряжения; оружие и снаряжение «Мадригал» — нет.\nЛинейка персональных скафандров «Мадригал» от Cyprian Industries — одни из лучших боевых костюмов для вакуума, для абордажа и защиты от него."},"pg_Psionic_Piston":{"n":"Псионический Поршень","t":"**1/миссия**, встретившись взглядом с персонажем на расстоянии вытянутой руки, вы можете телепатически говорить с ним и делиться сознанием с полной ясностью, передавая рациональную и эмоциональную субъективность. Устройство — мост между разумами без обычных нейрокружев. Эффект длится, пока связанные персонажи остаются рядом.\nКаждый раз при использовании бросьте d20: на **5 и меньше** до конца миссии вы получаете черту характера (её определяете вы с ГМом) — в разум хлынули воспоминания прежнего владельца.\nВосьмигранный камень над переносицей, вживлённый в лобную долю."},"pg_personal_shielding":{"n":"Личный Кинетический Щит","t":"Личная броня для любого пилота с УЛ0 — вместо скафандра (Lancer, стр. 110). Броня 0, ПЗ +0, Уклонение 10, Э-Защита 10, Скорость 4, метка **Щит**.\nПока щит активен, вы не можете совершать дальние атаки. Получив попадание дальним оружием, уменьшите урон на **1d6**. Если урон не уменьшился до нуля, щит выгорает и не работает до следующего **Отдыха** или **Полного Ремонта**.\nПопулярная защита у карракинской знати: генератор компактен и незаметен."},"pg_monofilament_rapier":{"n":"Мономолекулярная Рапира","t":"Клинок СШК на силовом поле режет броню, щиты и чужое оружие. В официальных дуэлях запрещён, но любим теми, кто ставит результат выше приличий."},"pg_hardlight_knives":{"n":"Клинки Волка","t":"Странно сбалансированные ножи из твёрдого света, украденные у грозного пирата. Без выучки опасны для владельца не меньше, чем для цели."},"pg_blue_blood":{"n":"Голубая Кровь Панглосса","t":"Потратьте заряд **быстрым действием**, чтобы получить странные и непредсказуемые прозрения о будущем: до конца сцены **+1** [ТОЧН] на все проверки навыков, когда вы действуете по увиденному; у видений могут быть и другие эффекты на усмотрение ГМа.\nЛегендарное снадобье Ордена Ксеноглоссии. Долгое употребление вызывает бесплодие и голубой оттенок губ, языка и пальцев. Без особой флоры и тайной дистилляции воспроизвести его нельзя — обычно это одноразовый резерв невероятной цены."}},"backgrounds":[{"id":"pbg_celebrity","n":"Знаменитость","trig":"Шарм, Положение, Лидерство, Угроза","t":"Вы всегда были на слуху у общественности. Вы были актером? Певцом? Художником? Спортсменом? Политиком? Публичным лицом корпоративной или военной рекламной кампании?\nВ прежней жизни вы не могли куда-то выйти без надоедливых папарацци. Как вы привыкли к новой жизни в качестве пилота? Вы были добровольцем или вас призвали ? Можете ли вы по-прежнему заниматься своим искусством, ремеслом или профессией, или военная структура не позволяет двойную работу?"},{"id":"pbg_colonist","n":"Колонист","trig":"Глас Улиц, Разведчик, Выживание, Заплатки","t":"Вы были колонистом на границе, частью одного из первых поколений, родившихся в новом заселенном мире. Вы привыкли к лишениям пограничной жизни и хорошо знаете, в каком шатком положении находится большинство городов. Почему вы уехали? Были ли вы вынуждены бежать, став беженцем? Вы решили поступить на военную службу?\nА еще есть дом, который вы оставили: Колония все еще там? Ваша семья? Насколько вы знакомы с роскошью миров ядра? Считаете ли вы, что с другие культурами не могут иметь дел с вами, или вас восхищает богатство культурного самовыражения человечества? Носите ли вы с собой напоминания о доме или проклинаете его? Была ли ваша колония в галактическом захолустье, или это новая колония в густонаселенном районе космоса с высоким трафиком? Где находится она колония?"},{"id":"pbg_criminal","n":"Преступник","trig":"Угрозы, Кулаком по Лицу, Глас Улиц, Держать под Контролем","t":"Вы были преступником: мелким, мастером или кем-то средним. Работали ли вы на корпоративных клиентов? На преступную организацию? На себя самого? Вы грабили пешеходов в темных подворотнях огромного города или незаметно проникали в корпоративные базы данных, чтобы украсть информацию? Делали ли вы это ради личной выгоды или просто для того, чтобы прокормить семью? Как вы докатились до такой жизни и как стали пилотом? Были ли вы верны одной семье, небольшой команде, политику или идеологии? Действовали ли вы в тени или выполняли свою работу у всех на виду, не боясь последствий?\nДолжна же быть причина, по которой вы решили уйти. Была ли это плохая работа, или, может быть, защита свидетелей? Ваши бывшие наниматели или команда все еще рядом? Какие у них связи, и как они относятся к вам сейчас? Что, если что-то преследует вас? И что это?"},{"id":"pbg_far_field_team","n":"Член Группы Дальней Разведки","trig":"Выживание, Исследование, Разведчик, Очарование","t":"Вы были членом Группы Дальней Разведки Союза (ГДР), работающей на границе, на краю цивилизации для оценки странных миров и планетоидов и поиска аномалий, открытий и подготовки для колонизации. Что вы видели на дикой границе? Сколько миров вы посетили? Какой размер был у вашей группы? Где находится ваша родная планета?\nЧто-то должно побуждать вас к исследованиям: Может быть, вы ищете мир Грааля? Рай среди звезд? Был ли ваш интерес к пограничью мистическим, научным, основанным на старом-добром любопытстве, или вас подстегнуло что-то другое? Может быть, вы слышали какую-то легенду, которую жаждете или наоборот боитесь встретить? Какие тайны, если они есть, вы встретили в своих дальних странствиях? Поддерживаете ли вы связь со своими бывшими членами группы, если они еще живы?\nКак бывший (или нынешний) член ГДР, вы космополит: Когда было \"ваше время\"? Насколько отрешенным вы чувствуете себя от течения времени?"},{"id":"pbg_hacker","n":"Хакер","trig":"Тише Воды - Ниже Травы, Завладеть чем-то, Взломать или Починить, Изобрести или Создать","t":"Вы специализируетесь на информационной войне и шпионаже в сети, как в своих интересах, так и в интересах своих работодателей. Для вас омнинет — сверхсветовая информационная сеть, соединяющая миры Союза — это дом. Как вы пришли к этой жизни? Ваше детство прошло, подключившись к омнинету, или подключились будучи подростком? Насколько хорошо вы осведомлены о бэкдорах, уловках и секретах омнинета? Насколько известным вы были до того, как стали пилотом? Люди до сих пор шепчут ваше имя? Помнят ли вас другие хакеры, прославлены или прокляты среди них?\nОднако вы взламывали не только омнинет. Насколько вы искусны в манипулировании другими сетями? Можете ли вы манипулировать дискретными системами, генетическим кодом или каким-то другим типом цифровой или механической среды? К каким тайнам вы получили доступ?"},{"id":"pbg_mechanic","n":"Механик","trig":"Взломать или Починить, Где-то Быстро Оказаться, Завладеть чем-то, Что-то Подорвать","t":"Маслёнка, гаечный ключ, работяга. Вы были механиком, прежде чем стали пилотом. Работали ли вы в космосе, в EVA-костюме, латая подбитые звездолеты? Или вы работали на планете, занимаясь наладкой грузовиков и тягачей в автопарке? Ремонтировали ли вы потрепанные в боях мехи, мечтая о том, что однажды станете пилотом своего собственного? У вас был собственный гараж или вы работали на кого-то? Были ли вы военным, корпоратом, членом касты или профсоюза? Насколько вы успешны в этой области? Есть ли у вас побочный проект, над которым вы работаете?"},{"id":"pbg_medic","n":"Медик","trig":"Заплатки, Штурм, Чувствовать Ситуацию, Сохранять Хладнокровие","t":"В прошлой жизни вы были медиком. Как вы стали пилотом меха? Какая у вас был специализация? Вы занимались исследованиями, лечением болезней или латанием травм? Вы любили эту жизнь и серьезно относились к своему долгу, или вы видели себя органическим механиком?\nВы могли работать в колонии или в мире ядра, в частной клинике, в корпорации или на зарплате у знатной семьи: Вы вели небольшую пограничную практику, работали в центре неотложной помощи на станциях мерцания или в огромном больничном городе? Были ли вы больничным сотрудником или врачом скорой помощи? Есть ли воспоминания, которые преследуют вас, или те, которые приносят вам утешение?"},{"id":"pbg_mercenary","n":"Наёмник","trig":"Угроза, Подорвать что-то, Держать под Контролем, Кулаком по Лицу","t":"Будучи солдатом удачи, вы жили под девизом: \"есть оружие, есть путешествие\". Вы и ваши инструменты были доступны тому, кто больше заплатит. Работали ли вы в одиночку или с командой? Был ли у вашей компании корабль? В начали пилотировать собственные мехи примерно в то время? Каков был ваш кодекс чести, и был ли он вообще?\nЧто подтолкнуло вас к жизни наемника: Обещание богатства? Желание власти? Приключения? Отчаяние?\nПо какой причине вы оставили это дело: Почему? Задание провалилось? Или это было та легендарная \"последняя работа\"? Ваши старые товарищи по наёмничеству все еще рядом с вами? Была ли у вас конкурирующая компания или другие враги? Вспоминаете ли вы о том времени с любовью или предпочитаете не поднимать эту тему"},{"id":"pbg_nhp_specialist","n":"Специалист по НЧЛ","trig":"Сохранять Хладнокровие, Чувствовать Ситуацию, Изобретать или Создавать, Исследовать","t":"Вы принимали непосредственное участие в изучении, создании или обслуживании первичного не-человека. Не-Человеческая Личность, или НЧЛ — это сложный искусственный интеллект. Первичный НЧЛ, именно тот, над которым вы работали, был куда сложнее, чем большинство остальных. Вы взаимодействовали с этой сущностью как ученый или инженер, или скорее как священник или шаман? Есть ли у вас личная связь с ним после стольких лет? Как воспринимают вас клоны того НЧЛ? И теперь, когда вы стали пилотом, как вы относитесь к нечеловеческому разуму?"},{"id":"pbg_noble","n":"Дворянин","trig":"Прокачка Рейтинга, Лидерство, Чувство Ситуации, Хвастовство","t":"Вы принадлежите к аристократии своего мира, с рождения вы предназначены для власти. От кого исходит это право? От бога? Предки? Древнее сказание? Сложная годовая ротация? Как власть передается из поколения в поколение?\nВаш дворянский статус откуда-то взялся: Вы первый в своей семье, получивший дворянский титул, последний в своем доме или отпрыск устоявшейся власти? Вы наследник или просто средний ребенок? Каковы ваши отношения с родителями-дворянами?\nКакие бы привилегии вы ни получали дома, вы обнаружили, что в вооруженных силах Союза титулы не учитываются. Ваш прежний статус — просто фоновый шум, если только вы не вернулись домой или не принадлежите к группе, признающей дворянство. Как вы восприняли это изменение?"},{"id":"pbg_outlaw","n":"Вне закона","trig":"Хвастовство, Убрать кого-то, Шарм, Выживание","t":"Вы родом из скромных мест, родились на краю разведанного пространства или под нависшими башнями миров ядра — в забытие, пока не протянули руку и не взяли то, что вам принадлежит. Некоторые называют вас преступником, вором или разбойником, но вы просто говорите все как есть: если бы вам не отказали в хлебе, вам не пришлось бы его брать силой. Кем вы были: грубияном или рассказчиком? Очаровашкой или чудовищем? Вы мотивировались идеологией, нуждой, желанием или какой-то комбинацией этих трех факторов? Кто решил, что вы как \"вне закона\", а кто видел в вас героя? Есть ли награда за вашу голову?"},{"id":"pbg_penal_colonist","n":"Колонист-Уголовник","trig":"Выживание, Кулаком по Лицу, Глас Улиц, Разведчик","t":"Давным-давно вас сослали в колонию для каторжных работ. Когда Третий Комитет упразднил все колонии, ваша планета-тюрьма была — теоретически — \"освобождена\". К сожалению, ничего особо не изменилось, пока не прибыли корабли помощи Союза. Теперь свободные как на практике, так и в теории, места, которые раньше были запретными, стали открыты для вас: Остались ли вы на какое-то время? Или вы решили уйти, устремившись к звездам или пытаясь найти дорогу домой? Были ли вы виновны в своих преступлениях или несправедливо осуждены?\nТюремные колонии были суровыми, полными лишений местами: Контролировалась ли ваша колония какими-то властями, или в ней царила анархия еще до отмены системы Союза? Было ли там какое-то рудиментарное общество? Были ли у вас там друзья и враги, и удалось ли кому-то из них выбраться за пределы планеты? Что насчет вашей семьи — была ли она у вас до вашего приговора? Что с ней стало, или вы не знаете?"},{"id":"pbg_priest","n":"Священник","trig":"Чувствовать Ситуацию, Сохранять Хладнокровие, Держать под контролем, Лидерство","t":"В прошлой жизни вы были священником, представителем большой общегалактической религии, либо небольшой секты. Были ли вы отшельником? Жили ли вы безбрачно в монастыре? Носили ли вы простые полотняные одежды или величественные одеяния? Какие ограничения накладывала на вас ваша церковь? Какое уважение оказывалось вам как человеку в одежде, и было ли это вашим выбором? Как вы пришли к жизни пилота?\nЦеркви есть везде, и каждая из них уникальна по-своему. Были ли вы членом известной религии или тайной, объявленной вне закона? Проповедовали ли вы терранскую веру, родившуюся в Колыбели и пронесенную через тысячелетия? Или ваша духовность была космополитической, со звезд и пустоты межзвездного пространства? Возможно, вы служили небольшой пастве какой-нибудь малоизвестной секты на границе или в городских каньонах одного из миров Ядра? Сохранили ли вы свою веру или потеряли ее?"},{"id":"pbg_scientist","n":"Ученый","trig":"Исследование, Изобрести или Создать, Завладеть чем-то, Подорвать Что-то","t":"Вы были ученым — частным или государственным, работали в лаборатории или в поле. Какова была ваша область знаний, и как долго вы ею занимались? Где вы учились, и какие у вас отношения с этим учебным заведением? Есть ли у вас конкуренты, известны ли вы или относительно малоизвестны? Как ваше родное общество воспринимало науку? Как вы стали пилотом?\nВажно, работали ли вы с мощным производителем, таким как Оружейная Палата Харрисона, Смит-Шимано или ИПС-Н? Или вы погрузились в сверхъестественное, тайно работая с небольшой, специализированной ячейкой ХОРУС? Какие секреты вы знаете?"},{"id":"pbg_soldier","n":"Солдат","trig":"Штурм, Подорвать Что-то, Положение, Держать под Контролем","t":"Ворчун. Салага. Солдафон. Рядовой. Балабасник. Вы были рядовым солдатом, служили в силах планетарной обороны, местном ополчении, национальной армии или королевской гвардии.\nКак долго вы служили, прежде чем Союз призвал вас? К какой специальности вы готовились? Вы уже принимали участие в боевых действиях, или вы еще \"зеленый\"? Были ли вы добровольцем, призывником или членом касты воинов? Солдатство — это семейная, гражданская или религиозная традиция, которой вы гордитесь, или жизнь, о которой вы сожалеете? Где другие солдаты из вашего прежнего отряда, и каковы ваши отношения с ними сейчас?"},{"id":"pbg_spaceborn","n":"Косморождённый","trig":"Выживание, Взломать или Починить, Быстро Добраться, Сохранять Хладнокровие","t":"Вы выросли на космической станции, в тесной каюте и маленькой общине, всегда окруженной неумолимым тяжелым вакуумом космоса. Были ли средства скудными или обильными? Была ли ваша станция изолирована или являлась местным (или галактическим!) хабом? Она находилась в бесконечной ночи глубокого космоса или на орбите планеты, спутнике или других звездных тел? Это цельная база или её часть встроена в астероид или спутник?\nНет двух одинаковых станций. Вы росли, наблюдая, как причаливают и отчаливают огромные корабли, знакомясь с тысячами языков и культур галактики, мечтая об исследованиях, или вы росли в темных, каменных коридорах, не зная о галактике за ее пределами? Короче говоря, какой была ваша жизнь, почему вы ушли и можете ли вы вернуться?"},{"id":"pbg_spec_ops","n":"Член Спецназа","trig":"Тише Воды - Ниже Травы, Убрать кого-то, Разведчик, Сохранять Хладнокровие","t":"Вы могли быть шпионом или наёмником-одиночкой, а может быть, в составе элитного подразделения, действующего в тылу врага практически без поддержки, оснащенного лучшим оборудованием, которое вам доверили командиры. Ваши миссии были долгими, опасными и никогда не афишировались. Если пехота — это топор, то вы были скальпелем. Какой бы организации вы ни служили, о ней говорили только шепотом в военных казармах и академиях. Какую работу вы выполняли, о которой никто не знает — ни вы, ни ваше подразделение? Насколько близко галактика подошла к тотальной войне? Где вы действовали? Сколько вам лет на самом деле? Какие секреты вы знаете? Где остальные члены вашей команды?"},{"id":"pbg_super_soldier","n":"Супер Солдат","trig":"Кулаком по Лицу, Быстро Добраться, Штурм, Чувствовать Ситуацию","t":"Вы — результат корпоративного или государственного проекта, направленного на создание лучших солдат с помощью био-, нейро- и генных-модификаций, или даже банального кондиционирования. Вас воспитывали с рождения, чтобы вы стали тем, кто вы есть, или вы сами, будучи взрослым, приняли участие в программе создания суперсолдат? Вы один из бесчисленных суперсолдат, которых наделают в результате программ факсимильного клонирования, проводимых компанией Оружейная Палата Харрисона? Был ли проект официальным или нет? Удался ли он? Проверили ли вы свои способности в деле, или вы еще не испытаны и жаждете увидеть, на что вы способны?\nПри Третьем комитете все ещё есть, хоть и меньше, программ, создавших вас: Рады ли вы этому, или считаете, что это делает Союз слабым? Каковы ваши отношения с вашими создателями? Есть ли семья, которая не знает о вашем существовании? Или вы из линии массово производимых братьев и сестер? Были ли вы освобождены, сдались ли вы, или вы все еще находитесь на службе у организации или структуры, для которой вы были созданы?"},{"id":"pbg_starship_pilot","n":"Пилот Космофлота","trig":"Быстро Добраться, Хвастовство, Завладеть чем-то, Взломать или Починить","t":"Вы летали на звездолете — гражданском, корпоративном, военном и т.п. Вы могли пилотировать грузовой корабль, истребитель, шаттл или более крупный корабль. У вас был обычный рейс, или вы летали свободно? Были ли вы членом экипажа или у вас был свой? Какие полеты вы совершали и что в итоге случилось с вашим кораблем? Придерживались ли вы низко- и среднеорбитальных челночных полетов?\nПилот — это такой же стиль жизни, как и профессия: Какой у вас был позывной, и были ли вы известны или нет? Была ли у вас конкурентный пилот или группа, с которыми у вас были перепалки? Работали ли вы с НЧЛ или летали в боевых условиях? Видели ли вы когданибудь что-нибудь странное в межзвездном пространстве или в полной пустоте мерцания?"},{"id":"pbg_worker","n":"Работяга","trig":"Глас Улиц, Сохранять Хладнокровие, Лидерство, Изобрести или Создать","t":"В любом случае, это закон жизни, империя функционирует только тогда, когда в ней существует труд. Труд добывает сырье. Труд превращает камень, металл и органические вещества в болты, шурупы и клей. Труд разрабатывает чертежи для принтеров. Труд формирует и сваривает, отбивает молотком и строит. Без труда триллионов людей весь прогресс остановился бы. Прежде чем вы отложили гаечный ключ и взяли в руки штурвал, какую работу вы выполняли? Работали ли вы в поле, на заводах, верфях, шахтах или где-то еще? Какой была ваша жизнь до того, как вы начали учиться на пилота? Почему вы ушли? Вернетесь ли вы? Был ли проект, над которым вы работали, и которым вы особенно гордитесь? Есть ли у вас старая команда, которая все еще работает? Какой мир вы называли домом, и какие там были условия работы?"},{"id":"pbg_noble_heir","n":"Благородный Наследник","trig":"Лидерство, Положение, Чувствовать Ситуацию, Держать под Контролем","t":"Случайность рождения или политическая ловкость сделали вас наследником — и на вас давит груз ожиданий. Какие у вас отношения с вашим домом? Чего от вас ждут окружающие? Как это вас сковывает?\nДворянские дома — рассадники интриг. Кого вам пришлось обойти, чтобы получить или сохранить положение? Кто вас поддерживает? Кто хочет вас сместить и почему?"},{"id":"pbg_second_choice","n":"Второй Выбор","trig":"Шарм, Изобрести или Создать, Выживание, Глас Улиц","t":"Целая индустрия развлекает скучающую карракинскую молодёжь поездками и обменами — на Землю, Рас-Шамру и дальше. Где ещё в галактике вы бывали? Какие странности видели? Кого встретили? Как это изменило ваше отношение к карракинскому обществу?\nУ вас огромные привилегии и сравнительно мало ответственности. Каковы ваши отношения с другими дворянами? С властью? С собственными привилегиями?"},{"id":"pbg_company_squire","n":"Оруженосец Роты","trig":"Штурм, Завладеть Чем-то, Взломать или Починить, Разведчик","t":"Традиционный путь в кавалерию — учиться у опытных пилотов, служа в их обслуге. Кому вы служили оруженосцем? Как с вами обращались? Что входило в ваши обязанности? Чему вы научились?\nСистема Великих Рот — политическая структура сама по себе. Вы служили в роте дворянского дома или в наёмной Вольной Роте? Бывали в бою с ними? Как рота на вас повлияла?"},{"id":"pbg_pankrati","n":"Панкратист","trig":"Кулаком по Лицу, Шарм, Быстро Добраться, Хвастовство","t":"Мех-спорт pankration mekani даёт Объединённому Баронскому Командованию множество лучших пилотов. Каков ваш послужной список в соревнованиях? В каких форматах вы были сильны? Что заставило вас готовиться к настоящему бою? Что было трудно в этом переходе?\nТалантливые панкратисты знамениты на весь Концерн и дальше. У вас есть фанаты? Как они вас видят? Вы наслаждаетесь славой?"},{"id":"pbg_young_buck","n":"Молодой Задира","trig":"Штурм, Подорвать Что-то, Заплатки, Сохранять Хладнокровие","t":"ОБК чествует своих «молодых задир» — талантливых солдат, взлетевших по службе благодаря умению и упорству. Как вы попали в ОБК и кем служили? Что привело к стремительному взлёту? Какие препятствия вы преодолели и как?\nСлужба в ОБК — от тихих миротворческих миссий до горячих войн на далёких планетах. Где вы служили и что там делали? Как это вас изменило? Каково ваше отношение к войне? К сослуживцам? К людям, которым вы помогли или навредили?"}],"tags":{"tg_burn":{"n":"Горение {VAL}","d":"При попадании это оружие наносит X[горение] своей цели. Она немедленно получает столько же урона от горения, игнорируя броню, затем отмечает X[горение]на своем листе, добавляя его к существующему горению. В конце своего хода персонажи с отмеченным горением делают проверку Инженерии. В случае успеха они убирают всё горение; в случае неудачи они получают урон, равный их общему числу горения."},"tg_heat_target":{"n":"Перегрев {VAL} (цель)","d":"При попадании это оружие или система наносит X[нагрев] своей цели. ПАТТЕРНЫ Некоторые виды оружия и систем имеют специальные схемы атаки: Линия[Линия], Конус[Конус], Взрыв[Взрыв], и Разрыв[Разрыв]. Эти атаки поражают все цели в пределах заданной области и требуют отдельного броска атаки для каждой их них. Урон наносится только 1 раз, а бонусный урон уменьшается вдвое, если поражено несколько целей. Х: Атаки этим оружием поражают персонажей по прямой линии длиной X сот."},"tg_line":{"n":"Линия {VAL}","d":""},"tg_cone":{"n":"Конус {VAL}","d":""},"tg_blast":{"n":"Взрыв {VAL}","d":""},"tg_burst":{"n":"Разрыв {VAL}","d":""},"tg_accurate":{"n":"Точное","d":"Атаки этим оружием, получают +1[ТОЧН]."},"tg_arcing":{"n":"Дуговое","d":"Это оружие запускает снаряды по дуге через препятствия. Атаки этим оружием не требуют прямой видимости, если можно проследить путь к цели; однако они все равно отражаются укрытием."},"tg_ap":{"n":"Бронебойное (ББ)","d":"Урон, наносимый этим оружием, игнорирует Броню."},"tg_inaccurate":{"n":"Неточное","d":"Атаки этим оружием, получают +1[СЛОЖН]."},"tg_knockback":{"n":"Толчок {VAL}","d":"При попадании атакующий может выбрать отбросить свою цель на X пространств по прямой линии прямо от точки попадания (например, атакующего меха или центра Взрыва). Несколько эффектов Толчка склады-ваются друг с другом. Это означает, что атака, выполненная оружием с Толчком 1 и талантом, дающим Толчок 1, считается как атака с Толчком 2."},"tg_loading":{"n":"Заряжаемое","d":"Это оружие должно заряжаться после каждого использования. Мехи могут перезаряжаться с помощью Стабилизации и некоторых систем."},"tg_ordnance":{"n":"Артиллерийское","d":"Это оружие может быть выпущено только до того, как пользователь переместится или предпримет какие-либо другие действия в свой ход, за исключением Протоколов. После атаки пользователь действует и перемещается в обычном режиме. Кроме того, из-за своего размера, это оружие не может быть использовано против целей, вовлеченных с мехом пользователя, и не может быть использовано для атак Наблюдением."},"tg_overkill":{"n":"Избыточный Урон","d":"При броске урона все кубики, выпавшие на 1, перебрасываются, а атакующий получает 1 нагрева за каждый переброс."},"tg_overshield":{"n":"Усиление Щита","d":"Эта система обеспечивает ПЗ, которые исчезают в конце сцены или при выполнении определенного условия. Пользователь сохраняет только наивысшее значение примененного Усиления Щита — оно не суммируется. Например, если система обеспечивает Усиление Щита 5, а пользователь получает другой эффект, который обеспечивает Усиление Щита 7, он получит Защиту 7. Урон наносится сначала Усилению Щита, затем ПЗ. Усиление Щита может вытеснить персонажа за пределы его максимального уровня ПЗ. Оно не может получить пользу от исцеления, но в остальном получает пользу от всего, что может повлиять на ПЗ и урон (уменьшение, броня и т.д.)."},"tg_reliable":{"n":"Надежное {VAL}","d":"Это оружие обладает некоторым уровнем самокоррекции или просто достаточно мощное, чтобы нанести урон даже при скользящем ударе. Оно всегда наносит X урона, даже если промахивается по цели или наносит урон меньше значения Х. Надежный урон наследует другие метки (например, ББ) и базовый тип урона, но не метки, требующие попадания, например, Толчок."},"tg_seeking":{"n":"Искатель","d":"Это оружие обладает ограниченной формой самонаведения и внутренней тягой, что позволяет ему двигаться к цели по сложным траекториям. Пока есть возможность проложить путь к цели, это оружие игнорирует укрытия и не требует прямой видимости."},"tg_smart":{"n":"Умное","d":"Это оружие имеет системы самонаведения, самонаводящиеся снаряды или даже нанороботизированные боеприпасы. Эти системы настолько эффективны, что от их атак нельзя просто уклониться — их нужно зашифровать или заглушить. Из-за этого все атаки этим оружием, включая атаки ближнего и дальнего боя, используют Э-Защиту цели вместо Уклонения. Цели, у которых нет Э-Защиты, считаются имеющими 8 Э-Защиты."},"tg_threat":{"n":"Угроза {VAL}","d":"Это оружие может быть использовано для нанесения атак Наблюдением в пределах X пространств. Если это оружие ближнего боя, оно может быть использовано для атак ближнего боя в пределах X пространств."},"tg_thrown":{"n":"Бросок {VAL}","d":"Это оружие ближнего боя может быть брошено в цель в пределах X пространств. Метательные атаки следуют правилам для атак ближнего боя, но на них не влияет укрытие; кроме того, брошенное оружие попадает в соседнее с целью пространство и должно быть извлечено свободным действием, прежде чем его можно будет использовать."},"tg_turn":{"n":"{VAL}/Ход","d":"Эта система, черта или реакция может быть использована X раз в течение любого хода."},"tg_round":{"n":"{VAL}/Раунд","d":"Эта система, свойство или реакция может быть использована X раз между началом хода пользователя и началом его следующего хода."},"tg_ai":{"n":"ИИ","d":"На мехе одновременно может быть установлена только одна система с этой меткой. Некоторые системы ИИ наделяют мех меткой ИИ. Мех с меткой ИИ имеет установленный блок НЧЛ или комп/кон, который может действовать в некоторой степени автономно. Пилот может передать управление своему ИИ или вернуть управление протоколом. Их мехи получают свой собственный набор действий и реакций, если находятся под управлением ИИ, но пилот не может совершать действия или реакции с ними до начала своего следующего хода. ИИ не могут пользоваться талантами и имеют небольшой шанс попасть в каскад при получении структурного урона или нагрузочного урона. Дополнительную информацию об ИИ и каскадах см. на с. 107."},"tg_danger_zone":{"n":"Опасная Зона","d":"Эту систему, талант или оружие можно использовать, только если пользователь находится в Опасной Зоне (тепло, равное как минимум половине его Теплового Максимума)."},"tg_deployable":{"n":"Размещаемое","d":"Эту систему можно разместить на поле. Если не указано иное, она может быть размещена в соседнем, свободном и действительном пространстве как быстрое действие, и имеет 5 Уклонение и 10 ПЗ за Размер."},"tg_drone":{"n":"Дрон","d":"Это самоходная, полуавтономная единица с рудиментарным интеллектом. Если не указано иное, Дроны — это персонажи с половинным размером, которые являются союзниками пользователя и имеют 10 Уклонения, 5 ПЗ и 0 Брони. Чтобы их можно было использовать, они должны быть развернуты на свободном, действительном пространстве в пределах Сенсоров и прямой видимости, обычно как быстрое действие. После размещения они могут быть отозваны тем же действием, которое использовалось для их размещения (быстрое действие или полное действие, и т.д.), и снова пристыковаться к вашему меху. По умолчанию Дроны не могут совершать действия или перемещаться; если у них есть действия или перемещение, они действуют в ход своего пользователя. Они пользуются укрытием и другими защитными средствами, как обычно, и делают все проверки навыков мехов и спасброски с +0. Если ПЗ Дрона достигают 0, он уничтожается и должен быть восстановлен, прежде чем его можно будет исполь-зовать снова — как и любую систему. Пока Дрон не уничтожен, он восстанавливается до полных ПЗ, когда пользователь делает перерыв или выполняет Полный Ремонт. Размещенные Дроны сохраняются до конца сцены, пока не будут уничтожены или пока не будет приказано иное."},"tg_full_action":{"n":"Полное Действие","d":"Эта система требует полного действия для Активации."},"tg_grenade":{"n":"Граната","d":"быстрым действием взрывчатое или другое устройство можно бросить в пространство в пределах прямой видимости и указанной дальности и видимости."},"tg_heat_self":{"n":"Нагрев {VAL} (свой)","d":"Сразу после использования оружия или системы пользователь получает X нагрева."},"tg_limited":{"n":"Ограниченное {VAL}","d":"Это оружие или система могут быть использованы только X раз, прежде чем потребуется Полный Ремонт. Некоторые Ограниченные системы, такие как Гранаты, описывают использования как \"заряды\". Чтобы использовать систему, пользователь тратит заряд."},"tg_mine":{"n":"Мина","d":"В качестве быстрого действия это устройство может быть установлено в соседнем, свободном и действующем пространстве на любой поверхности, но не рядом с другими минами. После установки оно срабатывает в конце хода персонажа, установившего мину, и — если не указано иное — срабатывает, когда любой персонаж входит в соседнее пространство. Персонажи, покидающие соседнее пространство, не приводят мину в действие. После срабатывания мина создает Разрывную атаку, начиная с пространства, в котором она была установлена. Мины в пределах сенсоров персонажа можно обнаружить, сделав успешную проверку Систем в качестве быстрого действия, иначе они скрыты и в них нельзя нацелиться. Обнаруженные мины можно обезвредить из соседних пространств, сделав успешную проверку Систем как быстрое действие; попытка происходит до того, как мина взорвется, при неудаче мина взрывается как обычно."},"tg_mod":{"n":"Мод","d":"Эта модификация может быть применена к оружию. Каждое оружие может иметь только один Мод, и не может иметь более одного одинакового Мода. Моды применяются, когда пользователь строит своего меха или во время Полного Ремонта."},"tg_protocol":{"n":"Протокол","d":"Можно активировать свободным действием, но только в начале хода пользователя. Для ее деактивации может потребоваться другое действие."},"tg_quick_action":{"n":"Быстрое Действие","d":"Требует быстрого действия для активации."},"tg_reaction":{"n":"Реакция","d":"Систему можно активировать реакцией."},"tg_shield":{"n":"Щит","d":"Представляет собой некий энергетический щит."},"tg_unique":{"n":"Уникальное","d":"Это оружие или система не могут быть продублированы — у каждого персонажа одновременно может быть установлена только одна их копия."},"tg_archaic":{"n":"Архаичное","d":"Это оружие старомодно и не может причинить вреда мехам."},"tg_personal_armor":{"n":"Личная Броня","d":"Это снаряжение обеспечивает защиту в бою, но оно очевидно для наблюдателей и обычно не может быть спрятано. Одновременно можно носить только одну часть Личной Брони. Надевание Личной Брони занимает 10-20 минут, и пока она надета, пилоты ограничены в подвижности и ловкости. Никто не надевает броню, если не ожидает попасть в зону боевых действий."},"tg_pilot_weapon":{"n":"Оружие Пилота","d":"Оружие пилота."},"tg_gear":{"n":"Снаряжение","d":"Это инструмент, часть оборудования или другой предмет. Пилоты могут иметь до трех таких предметов одновременно."},"tg_sidearm":{"n":"Личное Оружие","d":"Это оружие может быть использовано для боя в качестве быстрого действия вместо полного действия."},"tg_invade":{"n":"Вторжение","d":"добавляет опции для использования с действием Быстрой Технологии Вторжение."},"tg_quick_tech":{"n":"Быстрая Технология","d":"Используется быстрой технологией."},"tg_full_tech":{"n":"Полная Технология","d":"Используется полной технологией."},"tg_free_action":{"n":"Свободное Действие","d":"Используется свободным действием."},"tg_range":{"n":"Дальность ({VAL})","d":""},"tg_modded":{"n":"Модифицировано","d":""},"tg_resistance":{"n":"Сопротивляемость","d":""},"tg_exotic":{"n":"Экзотическое Снаряжение","d":"Снаряжение вне обычной системы лицензий: выдаётся ГМом как награда. Не повышает УЛ и не считается рангом лицензии. Ставится и снимается только при Полном Ремонте; одновременно можно установить не больше **двух** предметов с этой меткой (владеть — сколько угодно). Уничтоженное чинится и перепечатывается как обычно."},"tg_recharge":{"n":"Перезарядка {VAL}+","d":"После использования нужно перезарядить: в начале хода бросьте d6, на X+ система снова доступна."},"tg_unlimited":{"n":"Неограниченное","d":""},"tg_indestructible":{"n":"Неразрушимое","d":""},"tg_invulnerable":{"n":"Неуязвимое","d":""},"tg_invisible":{"n":"Невидимое","d":""},"tg_resistall":{"n":"Сопротивляемость (всё)","d":""},"tg_set_max_uses":{"n":"Макс. использований","d":""},"tg_set_damage_type":{"n":"Выбор типа урона","d":""},"tg_set_damage_value":{"n":"Урон","d":""},"tg_no_cascade":{"n":"Без каскада","d":""},"tg_efficient":{"n":"Экономное","d":"В конце любой сцены, в которой использована эта система или действие, вы возвращаете 1 Мощь Ядра."}},"art":{"mf_standard_pattern_i_everest":"assets/art/mf_standard_pattern_i_everest.webp","mf_blackbeard":"assets/art/mf_blackbeard.webp","mf_drake":"assets/art/mf_drake.webp","mf_lancaster":"assets/art/mf_lancaster.webp","mf_nelson":"assets/art/mf_nelson.webp","mf_raleigh":"assets/art/mf_raleigh.webp","mf_tortuga":"assets/art/mf_tortuga.webp","mf_vlad":"assets/art/mf_vlad.webp","mf_black_witch":"assets/art/mf_black_witch.webp","mf_deaths_head":"assets/art/mf_deaths_head.webp","mf_dusk_wing":"assets/art/mf_dusk_wing.webp","mf_metalmark":"assets/art/mf_metalmark.webp","mf_monarch":"assets/art/mf_monarch.webp","mf_mourning_cloak":"assets/art/mf_mourning_cloak.webp","mf_swallowtail":"assets/art/mf_swallowtail.webp","mf_balor":"assets/art/mf_balor.webp","mf_goblin":"assets/art/mf_goblin.webp","mf_gorgon":"assets/art/mf_gorgon.webp","mf_hydra":"assets/art/mf_hydra.webp","mf_manticore":"assets/art/mf_manticore.webp","mf_minotaur":"assets/art/mf_minotaur.webp","mf_pegasus":"assets/art/mf_pegasus.webp","mf_barbarossa":"assets/art/mf_barbarossa.webp","mf_genghis":"assets/art/mf_genghis.webp","mf_iskander":"assets/art/mf_iskander.webp","mf_napoleon":"assets/art/mf_napoleon.webp","mf_saladin":"assets/art/mf_saladin.webp","mf_sherman":"assets/art/mf_sherman.webp","mf_tokugawa":"assets/art/mf_tokugawa.webp","mf_atlas":"assets/art/mf_atlas.webp","mf_caliban":"assets/art/mf_caliban.webp","mf_kobold":"assets/art/mf_kobold.webp","mf_lich":"assets/art/mf_lich.webp","mf_sunzi":"assets/art/mf_sunzi.webp","mf_zheng":"assets/art/mf_zheng.webp","mf_white_witch":"assets/art/mf_white_witch.webp","mf_emperor":"assets/art/mf_emperor.webp","mf_black_witch_alt_orchidea":"assets/art/mf_black_witch_alt_orchidea.webp","mf_minotaur_alt_wraith":"assets/art/mf_minotaur_alt_wraith.webp","mf_kidd":"assets/art/mf_kidd.webp","mf_tokugawa_alt_enkidu":"assets/art/mf_tokugawa_alt_enkidu.webp","mf_genghis_alt_worldkiller_genghis_mk_i":"assets/art/mf_genghis_alt_worldkiller_genghis_mk_i.webp","mf_swallowtail_alt_swallowtail_ranger_variant":"assets/art/mf_swallowtail_alt_swallowtail_ranger_variant.webp","mf_störtebeker":"assets/art/mf_störtebeker.webp","mf_micro_monarch":"assets/art/mf_micro_monarch.webp","mf_gilgamesh":"assets/art/mf_gilgamesh.webp","mf_amber_phantom":"assets/art/mf_amber_phantom.webp","mf_lycan":"assets/art/mf_lycan.webp","mf_kutuzov":"assets/art/mf_kutuzov.webp","mf_Empakaai_alt_blackbeard":"assets/art/mf_Empakaai_alt_blackbeard.webp","mf_lancaster_alt_taraxacum":"assets/art/mf_lancaster_alt_taraxacum.webp","mf_balor_alt_hecatoncheires":"assets/art/mf_balor_alt_hecatoncheires.webp","mf_sherman_alt_tagetes":"assets/art/mf_sherman_alt_tagetes.webp","mf_sagarmatha":"assets/art/mf_sagarmatha.webp","mf_chomolungma":"assets/art/mf_chomolungma.webp"},"logo":{"HA":"assets/logo/HA.png","HORUS":"assets/logo/HORUS.png","SSC":"assets/logo/SSC.png","IPS-N":"assets/logo/IPS-N.png","GMS":"assets/logo/GMS.png"}};
